-- Spawn storage: event log, command queue, read views.
--
-- Times are Unix epoch milliseconds in bigint, so no client date library is
-- needed. Every newly inserted event gets its id under one transaction-level
-- advisory lock: it makes "id order equals commit order" true, which lets a
-- global reader store its last position and never skip an event. A committed
-- idempotent repeat can be read without joining a contended lock queue.

-- A connection whose search_path names a schema that does not exist yet
-- (an isolated test run) gets it created, so everything below lands there.
do $$
declare
    v_first text := trim(both ' "' from split_part(current_setting('search_path'), ',', 1));
begin
    if current_schema() is null and v_first <> '' and v_first not like '%$user%' then
        execute format('create schema if not exists %I', v_first);
    end if;
end
$$;

create or replace function spawn_now_ms() returns bigint
language sql volatile as $$
    select (extract(epoch from clock_timestamp()) * 1000)::bigint
$$;

-- The restricted logins are roles, and roles belong to the whole cluster:
-- each database gets its own, named after it (`spawn_supervisor_<db>`), so
-- two installs on one cluster neither share privileges nor set each other's
-- passwords. Schemas of one database (test cases) share them.
-- `p_base` is `spawn_supervisor`, `spawn_reader` or `spawn_human`; a name that would not
-- fit, or a database name outside [a-z0-9_], gets a hash instead.
create or replace function spawn_login_role(p_base text) returns text
language sql stable as $$
    select case when x.d ~ '^[a-z0-9_]+$' and length(p_base) + 1 + length(x.d) <= 63
                then p_base || '_' || x.d
                else left(p_base || '_' || regexp_replace(lower(x.d), '[^a-z0-9_]+', '_', 'g'), 54)
                     || '_' || left(md5(x.d), 8) end
      from (select current_database()::text as d) x
$$;

-- The principal the session's login acts as: this database's restricted
-- logins act as `spawn_supervisor` and `spawn_reader`, the names grants,
-- commands and records carry, and `spawn_human` (the web page's typing,
-- `spawn_human_input`) as `human`, the principal `spawn submit --principal
-- human` names; the logins of the same names from before logins were per
-- database act as nobody (null); any other login as itself.
-- `session_user` survives SECURITY DEFINER, so this names the real caller.
create or replace function spawn_principal() returns text
language sql stable as $$
    select case
             when session_user::text = spawn_login_role('spawn_supervisor') then 'spawn_supervisor'
             when session_user::text = spawn_login_role('spawn_reader') then 'spawn_reader'
             when session_user::text = spawn_login_role('spawn_human') then 'human'
             when session_user::text in ('spawn_supervisor', 'spawn_reader', 'spawn_terminal')
                 then null
             else session_user::text end
$$;

create table if not exists spawn_events (
    id              bigint generated by default as identity primary key,
    agent_id        text   not null,
    session_id      text   not null,
    execution_id    text,
    source          text   not null,
    source_event_id text,
    kind            jsonb  not null,
    session_seq     bigint not null,
    recorded_at_ms  bigint not null,
    event_name      text generated always as (kind ->> 'name') stored
);

create unique index if not exists spawn_events_session_seq
    on spawn_events (session_id, session_seq);

create unique index if not exists spawn_events_source_key
    on spawn_events (session_id, source, source_event_id)
    where source_event_id is not null;

create index if not exists spawn_events_session_name
    on spawn_events (session_id, event_name, id);

-- One outcome of each kind per judging (gate v2, design-gate-survives-
-- restart.md D4): a gate may outlive the integrator that started it, and
-- the next one reaps it, so two integrators, or one after a crash between
-- its record and its cleanup, may record one gate's outcome again.
-- spawn_integrator_record returns the first instead; this index is the
-- store's own refusal of a second, whatever writes it. The kinds: one
-- verdict, and the `stale` after an `accepted` (the `task.aborted` a done
-- mission makes of it is that `stale`); one landing; one owner's outcome,
-- moved or refused. (An earlier draft of this index, never on live, had
-- another key under the name spawn_events_control_judging: dropped, so a
-- database that took it holds only this one.)
drop index if exists spawn_events_control_judging;
create unique index if not exists spawn_events_control_judging_outcome
    on spawn_events ((kind #>> '{detail,record,judging}'),
                     (case kind #>> '{detail,record,type}'
                          when 'task.gated' then
                              case when kind #>> '{detail,record,verdict}' = 'stale'
                                   then 'stale' else 'verdict' end
                          when 'task.aborted' then 'stale'
                          when 'source.push_refused' then 'source.moved'
                          else kind #>> '{detail,record,type}' end))
    where session_id = 'session_control' and kind #>> '{detail,record,judging}' is not null;

-- An agent's latest checkpoint, read by the integrator before it judges.
create index if not exists spawn_events_agent_name
    on spawn_events (agent_id, event_name, id);

-- The dashboard's reads (`spawn serve`; docs/view-architecture.md §8 has
-- the plans). A session's judgements by time: when its current state began
-- (the fleet board's `state_since_ms`) is the judgement after the latest one
-- of another state, found newest first instead of by reading them all.
create index if not exists spawn_events_observation_time
    on spawn_events (session_id, recorded_at_ms)
    where event_name = 'observation.recorded';

-- A tool call's end by its `tool_use_id`: `agent_open_tools` (a live
-- session's current tool) looks each start's end up instead of reading
-- every end of the session for every start.
create index if not exists spawn_events_tool_done
    on spawn_events (session_id, (kind -> 'detail' ->> 'tool_use_id'))
    where event_name in ('tool.completed', 'tool.failed');

-- Events of one kind in a window, across sessions: the fleet's health (the
-- last hour's tool calls and failures, the day's judgements and
-- executions) reads the window, not the whole log.
create index if not exists spawn_events_name_time
    on spawn_events (event_name, recorded_at_ms);

-- The message_not_taken alert reads one session's transcript after its typing,
-- ordered by time and event id so lines in the same millisecond stay ordered.
-- The partial index leaves every other event source out of that read.
create index if not exists spawn_events_claude_time
    on spawn_events (session_id, recorded_at_ms, id) where source = 'claude';

-- Projection: one row per session, written by `spawn_append` in the same
-- transaction as the event, so `agent_state`, `agent_status` and
-- `agent_freshness` read one row instead of folding the log. The log stays
-- the only truth: a row is the fold of its session's events, and any row
-- out of step with the log is folded again.
create table if not exists spawn_session_state (
    session_id           text   primary key,
    agent_id             text   not null,
    last_session_seq     bigint not null,
    last_event_id        bigint not null,
    last_event_at_ms     bigint not null,
    event_count          bigint not null,
    observation          jsonb,
    observation_seq      bigint,
    observation_event_id bigint,
    observation_at_ms    bigint
);

-- The session belongs to the agent of its first event, so a command another
-- agent submits into the session cannot move it out of its owner's grants.
create or replace function spawn_session_fold(p_session text) returns void
language sql as $$
    insert into spawn_session_state
    select f.session_id, a.agent_id, f.last_session_seq, f.last_event_id,
           f.last_event_at_ms, f.event_count,
           o.observation, o.session_seq, o.id, o.recorded_at_ms
    from (
        select e.session_id,
               max(e.session_seq) as last_session_seq, max(e.id) as last_event_id,
               max(e.recorded_at_ms) as last_event_at_ms, count(*) as event_count
        from spawn_events e
        -- The control stream belongs to no agent (§10.1).
        where e.session_id = p_session and p_session <> 'session_control'
        group by e.session_id
    ) f
    cross join lateral (
        select e.agent_id from spawn_events e
        where e.session_id = f.session_id
        order by e.session_seq limit 1
    ) a
    left join lateral (
        select e.kind -> 'detail' -> 'observation' as observation,
               e.session_seq, e.id, e.recorded_at_ms
        from spawn_events e
        where e.session_id = f.session_id and e.event_name = 'observation.recorded'
        order by e.session_seq desc
        limit 1
    ) o on true
    on conflict (session_id) do update set
        agent_id             = excluded.agent_id,
        last_session_seq     = excluded.last_session_seq,
        last_event_id        = excluded.last_event_id,
        last_event_at_ms     = excluded.last_event_at_ms,
        event_count          = excluded.event_count,
        observation          = excluded.observation,
        observation_seq      = excluded.observation_seq,
        observation_event_id = excluded.observation_event_id,
        observation_at_ms    = excluded.observation_at_ms;
$$;

-- Fold the sessions the projection is missing or behind on: a database from
-- before the projection, or events an older `spawn_append` wrote while this
-- migration ran. The append lock waits for those calls to commit; the
-- migration holds it until its own commit, after which the new body runs.
-- ponytail: this groups the whole log on every migration; keep a migration
-- version and run it once when init-db on a large log gets slow.
select pg_advisory_xact_lock(1399957335);
select spawn_session_fold(f.session_id)
from (select e.session_id, max(e.session_seq) as last_seq
      from spawn_events e group by e.session_id) f
left join spawn_session_state p on p.session_id = f.session_id
where p.last_session_seq is distinct from f.last_seq;

-- One session per agent, one agent per session: an agent and its session
-- are one entity, and `session_id` stays only as the log's column. The pair
-- is the one an append recorded first; `spawn_append_trusted` refuses every
-- other pairing. Keys, not only the append lock, hold it: two first writes
-- racing cannot both commit.
create table if not exists spawn_agent_sessions (
    agent_id   text primary key,
    session_id text not null unique
);

-- A log from before the table: its pairs, in the order they first appear.
-- A pairing that breaks the rule is reported, and the first pair of each
-- agent and session stands; the log is never changed.
do $$
declare
    v_pair record;
    v_broken text := '';
    v_count integer := 0;
begin
    if exists (select 1 from spawn_agent_sessions) or not exists (select 1 from spawn_events) then
        return;
    end if;
    for v_pair in
        select e.agent_id, e.session_id from spawn_events e
         group by e.agent_id, e.session_id
         order by min(e.id)
    loop
        insert into spawn_agent_sessions (agent_id, session_id)
        values (v_pair.agent_id, v_pair.session_id)
        on conflict do nothing;
        if not exists (select 1 from spawn_agent_sessions s
                        where s.agent_id = v_pair.agent_id and s.session_id = v_pair.session_id) then
            v_count := v_count + 1;
            if v_count <= 20 then
                v_broken := v_broken || format(' (%s, %s)', v_pair.agent_id, v_pair.session_id);
            end if;
        end if;
    end loop;
    if v_count > 0 then
        raise warning 'the log pairs % agents and sessions against one session per agent:%; '
                      'their first pairs stand and new writes of these pairs are refused',
                      v_count, v_broken;
    end if;
end
$$;

-- The writer. Only the owner reaches it: directly, or through SECURITY
-- DEFINER paths such as the `agent_commands` gateway, which must record
-- `command.accepted` with source `gateway` even when a restricted login
-- submitted the command. Restricted logins call `spawn_append` below.
-- The append lock, pg_advisory_xact_lock(1399957335), is copied outside
-- this file: the black-box scenarios rsi/scenarios/045.sh, 050.sh and
-- check-j05-operator.sh take it to insert events with their own
-- session_seq beside a running store. A change of the key must update them
-- too, or their inserts collide again with the store's appends.
create or replace function spawn_append_trusted(
    p_agent      text,
    p_session    text,
    p_execution  text,
    p_source     text,
    p_source_key text,
    p_kind       jsonb
) returns table (
    out_id       bigint,
    out_seq      bigint,
    out_at       bigint,
    out_inserted boolean
) language plpgsql security definer as $$
declare
    v_seq bigint;
    v_id  bigint;
    v_at  bigint;
    v_owned text;
    v_open text;
    v_open_id bigint;
    -- Only the Observer's judgement is the projected state.
    v_obs constant boolean := p_kind ->> 'name' = 'observation.recorded' and p_source = 'observer';
begin
    -- Keep the uncontended path free of an extra index read. Only a caller
    -- that would otherwise wait looks for a committed duplicate, which
    -- allocates no id and changes no state. A racing first write is not yet
    -- visible here; the caller takes the lock and finds that event below.
    if not pg_try_advisory_xact_lock(1399957335) then
        if p_source_key is not null then
            select e.id, e.session_seq, e.recorded_at_ms into v_id, v_seq, v_at
                from spawn_events e
                where e.session_id = p_session
                  and e.source = p_source
                  and e.source_event_id = p_source_key
                limit 1;
            if found then
                return query select v_id, v_seq, v_at, false;
                return;
            end if;
        end if;
        perform pg_advisory_xact_lock(1399957335);
    end if;

    if p_source_key is not null and exists (
        select 1 from spawn_events e
        where e.session_id = p_session
          and e.source = p_source
          and e.source_event_id = p_source_key
    ) then
        return query
            select e.id, e.session_seq, e.recorded_at_ms, false
            from spawn_events e
            where e.session_id = p_session
              and e.source = p_source
              and e.source_event_id = p_source_key
            limit 1;
        return;
    end if;

    -- The agent's session is the one recorded for it first.
    if not exists (select 1 from spawn_agent_sessions s
                    where s.agent_id = p_agent and s.session_id = p_session) then
        insert into spawn_agent_sessions (agent_id, session_id) values (p_agent, p_session)
            on conflict do nothing;
        select s.session_id into v_owned from spawn_agent_sessions s where s.agent_id = p_agent;
        if v_owned is distinct from p_session then
            raise exception 'agent % has session %, not %', p_agent, v_owned, p_session
                using errcode = '42501';
        end if;
        select s.agent_id into v_owned from spawn_agent_sessions s where s.session_id = p_session;
        if v_owned is distinct from p_agent then
            raise exception 'session % belongs to agent %, not %', p_session, v_owned, p_agent
                using errcode = '42501';
        end if;
    end if;

    -- One active execution per session, held here and not only in a
    -- Bridge's memory: a start is refused while the session's latest
    -- execution has no end the Bridge wrote (a runner's exit report is no
    -- end; a lost execution gets its end from the next tick).
    if p_kind ->> 'name' = 'execution.started' then
        select e.id, e.execution_id into v_open_id, v_open
          from spawn_events e
         where e.session_id = p_session and e.event_name = 'execution.started'
           and e.execution_id is not null
         order by e.id desc
         limit 1;
        if v_open is not null and not exists (
            select 1 from spawn_events x
             where x.session_id = p_session and x.event_name = 'execution.ended'
               and x.execution_id = v_open and x.source = 'bridge' and x.id > v_open_id
        ) then
            raise exception 'session % already runs execution %', p_session, v_open
                using errcode = '23P01';
        end if;
    end if;

    select coalesce(max(e.session_seq), 0) + 1 into v_seq
        from spawn_events e
        where e.session_id = p_session;

    v_at := spawn_now_ms();

    insert into spawn_events
        (agent_id, session_id, execution_id, source, source_event_id, kind, session_seq, recorded_at_ms)
    values
        (p_agent, p_session, p_execution, p_source, p_source_key, p_kind, v_seq, v_at)
    returning spawn_events.id into v_id;

    -- Guard: step the row only when it holds exactly the previous event.
    -- Any other row (missing, behind, ahead) is folded again from the log.
    update spawn_session_state p set
        last_session_seq     = v_seq,
        last_event_id        = v_id,
        last_event_at_ms     = greatest(p.last_event_at_ms, v_at),
        event_count          = p.event_count + 1,
        observation          = case when v_obs then p_kind -> 'detail' -> 'observation' else p.observation end,
        observation_seq      = case when v_obs then v_seq else p.observation_seq end,
        observation_event_id = case when v_obs then v_id else p.observation_event_id end,
        observation_at_ms    = case when v_obs then v_at else p.observation_at_ms end
    where p.session_id = p_session and p.last_session_seq = v_seq - 1;
    if not found then
        perform spawn_session_fold(p_session);
    end if;

    perform pg_notify('spawn_events', v_id::text);

    return query select v_id, v_seq, v_at, true;
end $$;

-- The entry point for every caller of the owner's login. No restricted login
-- writes events: engines report nothing themselves (the Bridge reads their
-- transcripts, screens and exit files), so a pane holds no login that could
-- forge a fact. The restricted logins are refused here as well as by the
-- grants. `session_user` survives SECURITY DEFINER, so it names the real
-- caller.
create or replace function spawn_append(
    p_agent      text,
    p_session    text,
    p_execution  text,
    p_source     text,
    p_source_key text,
    p_kind       jsonb
) returns table (
    out_id       bigint,
    out_seq      bigint,
    out_at       bigint,
    out_inserted boolean
) language plpgsql security definer as $$
begin
    if coalesce(spawn_principal() in ('spawn_supervisor', 'spawn_reader', 'human'), true) then
        raise exception '% may not write events', session_user using errcode = '42501';
    end if;
    return query
        select * from spawn_append_trusted(p_agent, p_session, p_execution, p_source, p_source_key, p_kind);
end $$;

create table if not exists spawn_commands (
    id              bigint generated by default as identity primary key,
    principal       text   not null,
    idempotency_key text   not null,
    agent_id        text   not null,
    session_id      text   not null,
    action          jsonb  not null,
    state           text   not null default 'pending',
    lease_worker    text,
    lease_attempt   integer not null default 0,
    lease_until_ms  bigint,
    succeeded       boolean,
    error           text,
    created_at_ms   bigint not null,
    finished_at_ms  bigint,
    unique (principal, idempotency_key)
);

create index if not exists spawn_commands_open
    on spawn_commands (session_id, id)
    where state <> 'finished';

-- A session's latest commands, finished or not: the fleet board's task.
create index if not exists spawn_commands_session
    on spawn_commands (session_id, id);

-- Commands that finished failed, since a time: the alert step's notice of a
-- failed command, found without reading the queue (docs/fleet-architecture.md
-- §3.4).
create index if not exists spawn_commands_failed
    on spawn_commands (finished_at_ms)
    where succeeded = false;

-- A session's commands by who sent them: the dispatcher's facts read one
-- session's dispatcher commands (what it already sent, its deliveries and
-- nudges, the tags the supervisor was told) on every pass, and these two
-- keys are what those reads need. Both are plain, so a read of one session
-- is a range scan of its own, never a scan of the table; a database made
-- before this pass gets them on its next `spawn init-db` (the upgrade
-- test's first shapes included).
create index if not exists spawn_commands_by_session
    on spawn_commands (session_id, principal, id);

-- A grant either lets a principal read an agent's views (`read`) or also
-- submit commands for it (`all`). `agent_id` is an id, `*`, or a prefix
-- pattern such as `agent_worker_*`, so the supervisor can command every worker
-- without being able to command itself.
create table if not exists spawn_grants (
    principal text not null,
    agent_id  text not null,
    scope     text not null default 'all',
    primary key (principal, agent_id)
);

-- Every start migrates in place: a table made by an earlier schema keeps its
-- rows and gets each column added since, here, after its `create table`.
-- tests/upgrade.rs builds the first shape of every table and checks that a
-- migration over it matches a fresh schema.
alter table spawn_grants add column if not exists scope text not null default 'all';


create or replace function spawn_grant_matches(p_pattern text, p_agent text)
returns boolean language sql immutable as $$
    select p_pattern = '*'
        or p_pattern = p_agent
        or (right(p_pattern, 1) = '*'
            and left(p_agent, length(p_pattern) - 1) = left(p_pattern, length(p_pattern) - 1))
$$;

create or replace function spawn_submit(
    p_principal text,
    p_key       text,
    p_agent     text,
    p_session   text,
    p_action    jsonb
) returns table (out_id bigint) language plpgsql as $$
declare
    v_id bigint;
begin
    -- The id is taken under the append lock, which is held to commit:
    -- commands commit in id order, the order `spawn_claim` relies on. Only a
    -- caller that would wait looks for an already committed key first; a
    -- first submission still in flight uses the conflict path below.
    if not pg_try_advisory_xact_lock(1399957335) then
        select c.id into v_id
            from spawn_commands c
            where c.principal = p_principal and c.idempotency_key = p_key;
        if v_id is not null then
            return query select v_id;
            return;
        end if;
        perform pg_advisory_xact_lock(1399957335);
    end if;
    insert into spawn_commands
        (principal, idempotency_key, agent_id, session_id, action, state, created_at_ms)
    values
        (p_principal, p_key, p_agent, p_session, p_action, 'pending', spawn_now_ms())
    on conflict (principal, idempotency_key) do nothing
    returning spawn_commands.id into v_id;

    if v_id is null then
        select c.id into v_id
            from spawn_commands c
            where c.principal = p_principal and c.idempotency_key = p_key;
        return query select v_id;
        return;
    end if;

    perform spawn_append_trusted(
        p_agent, p_session, null, 'gateway', 'cmd_' || v_id || ':accepted',
        jsonb_build_object('name', 'command.accepted',
                           'detail', jsonb_build_object('command_id', v_id)));

    return query select v_id;
end $$;

-- The first version returned no principal.
drop function if exists spawn_claim(text, bigint);
create or replace function spawn_claim(
    p_worker text,
    p_ttl_ms bigint
) returns table (
    out_id        bigint,
    out_attempt   integer,
    out_agent     text,
    out_session   text,
    out_action    jsonb,
    out_principal text
) language sql as $$
    -- One command per session at a time: nothing earlier in the session
    -- may be unfinished, but an input that waits for its turn (the Bridge
    -- recorded its `command.step` `waiting`, keyed `cmd_<id>:waiting`): it
    -- holds nothing behind it. A stop, a discard, a resume or a key behind
    -- it is handled at once, and an input behind it is claimed and kept behind it
    -- by the Bridge (typed after it, or refused while it waits). An
    -- unfinished input that does not wait still holds everything. "Earlier"
    -- is id order, which is commit order because `spawn_submit` takes its id
    -- under the append lock.
    with candidate as (
        select c.id
        from spawn_commands c
        where c.state <> 'finished'
          and (c.lease_until_ms is null or c.lease_until_ms <= spawn_now_ms())
          and not exists (
              select 1 from spawn_commands o
              where o.session_id = c.session_id
                and o.state <> 'finished'
                and o.id < c.id
                and not exists (
                    select 1 from spawn_events w
                    where w.session_id = o.session_id and w.source = 'bridge'
                      and w.source_event_id = 'cmd_' || o.id || ':waiting')
          )
        order by c.id
        for update skip locked
        limit 1
    )
    update spawn_commands c
    set lease_worker = p_worker,
        lease_attempt = c.lease_attempt + 1,
        lease_until_ms = spawn_now_ms() + p_ttl_ms
    from candidate
    where c.id = candidate.id
    returning c.id, c.lease_attempt, c.agent_id, c.session_id, c.action, c.principal;
$$;

-- Leave a claimed command unfinished and claimable again in `p_ms`: an
-- input that waits for its turn. A lease that is no longer this attempt's
-- changes nothing. Returns whether it released.
create or replace function spawn_release(
    p_command bigint,
    p_attempt integer,
    p_ms      bigint
) returns boolean language sql as $$
    update spawn_commands c
       set lease_until_ms = spawn_now_ms() + greatest(p_ms, 0)
     where c.id = p_command and c.state <> 'finished' and c.lease_attempt = p_attempt
    returning true;
$$;

create or replace function spawn_finish(
    p_command   bigint,
    p_attempt   integer,
    p_succeeded boolean,
    p_error     text
) returns text language plpgsql as $$
declare
    v_state   text;
    v_attempt integer;
    v_agent   text;
    v_session text;
begin
    select c.state, c.lease_attempt, c.agent_id, c.session_id
        into v_state, v_attempt, v_agent, v_session
        from spawn_commands c
        where c.id = p_command
        for update;

    if v_state is null then
        return 'missing';
    end if;
    if v_state = 'finished' then
        return 'already';
    end if;
    if v_attempt <> p_attempt then
        return 'stale';
    end if;

    update spawn_commands c
        set state = 'finished',
            succeeded = p_succeeded,
            error = p_error,
            finished_at_ms = spawn_now_ms()
        where c.id = p_command;

    perform spawn_append(
        v_agent, v_session, null, 'gateway', 'cmd_' || p_command || ':finished',
        jsonb_build_object('name', 'command.finished',
            'detail', jsonb_build_object(
                'command_id', p_command,
                'succeeded', p_succeeded,
                'error', p_error)));

    return 'done';
end $$;

create or replace view agent_commands as
select c.id, c.agent_id, c.session_id, c.idempotency_key, c.action, c.created_at_ms
from spawn_commands c;

create or replace function spawn_gateway_insert() returns trigger
language plpgsql security definer as $$
declare
    v_id bigint;
begin
    if not exists (
        select 1 from spawn_grants g
        where g.principal = spawn_principal()
          and g.scope = 'all'
          and spawn_grant_matches(g.agent_id, new.agent_id)
    ) then
        raise exception 'principal % has no grant for agent %', session_user, new.agent_id
            using errcode = '42501';
    end if;
    -- A session belongs to the agent that first used it: a grant for one
    -- agent must not reach another agent's session (the Bridge acts on the
    -- session, not the agent). This early answer names the pair; the append
    -- in `spawn_submit` is what holds it when two first submissions race.
    if exists (select 1 from spawn_agent_sessions s
                where s.session_id = new.session_id and s.agent_id <> new.agent_id) then
        raise exception 'session % belongs to another agent than %', new.session_id, new.agent_id
            using errcode = '42501';
    end if;
    if exists (select 1 from spawn_agent_sessions s
                where s.agent_id = new.agent_id and s.session_id <> new.session_id) then
        raise exception 'agent % has another session than %', new.agent_id, new.session_id
            using errcode = '42501';
    end if;

    select s.out_id into v_id
        from spawn_submit(spawn_principal(), new.idempotency_key, new.agent_id, new.session_id,
                          new.action) s;

    new.id := v_id;
    select c.created_at_ms into new.created_at_ms from spawn_commands c where c.id = v_id;
    return new;
end $$;

drop trigger if exists spawn_gateway_insert on agent_commands;
create trigger spawn_gateway_insert
    instead of insert on agent_commands
    for each row execute function spawn_gateway_insert();

create or replace view agent_state as
select
    p.session_id,
    p.agent_id,
    p.observation ->> 'state'      as state,
    p.observation ->> 'reason'     as reason,
    (p.observation ->> 'confidence')::float8 as confidence,
    (p.observation ->> 'based_on_seq')::bigint as based_on_seq,
    p.observation ->> 'judge'      as judge,
    p.observation_seq as session_seq,
    p.observation_at_ms as recorded_at_ms,
    p.observation_event_id as event_id,
    p.observation
from spawn_session_state p
where p.observation is not null;

create or replace view agent_timeline as
select
    e.session_id,
    e.session_seq,
    e.id,
    e.agent_id,
    e.execution_id,
    e.source,
    e.event_name,
    e.kind -> 'detail' as detail,
    e.recorded_at_ms
from spawn_events e
where e.source <> 'observer';

-- Judgements are read apart from the timeline: they describe the session
-- instead of being part of it.
create or replace view agent_judgements as
select
    e.session_id,
    e.session_seq,
    e.id as event_id,
    e.agent_id,
    e.kind -> 'detail' -> 'observation' ->> 'state'  as state,
    e.kind -> 'detail' -> 'observation' ->> 'reason' as reason,
    (e.kind -> 'detail' -> 'observation' ->> 'based_on_seq')::bigint as based_on_seq,
    e.kind -> 'detail' -> 'observation' as observation,
    e.recorded_at_ms
from spawn_events e
where e.event_name = 'observation.recorded';

create or replace view agent_tasks as
select
    c.id as command_id,
    c.agent_id,
    c.session_id,
    c.action ->> 'type' as action,
    c.state,
    c.lease_worker,
    c.lease_attempt,
    c.succeeded,
    c.error,
    c.created_at_ms,
    c.finished_at_ms,
    coalesce(c.action ->> 'prompt', c.action ->> 'text') as prompt,
    c.principal
from spawn_commands c;

create or replace view agent_executions as
select
    s.session_id,
    s.agent_id,
    s.execution_id,
    s.kind -> 'detail' ->> 'engine'    as engine,
    -- Always the execution's own terminal; records no longer name it.
    'spawn-' || s.execution_id         as terminal,
    s.kind -> 'detail' ->> 'workspace' as workspace,
    s.recorded_at_ms as started_at_ms,
    x.kind -> 'detail' ->> 'cause'     as cause,
    (x.kind -> 'detail' ->> 'exit_code')::integer as exit_code,
    x.recorded_at_ms as ended_at_ms,
    -- The execution ends only when the Bridge writes its own end event. An
    -- end from another source is an exit report of an old runner: runners
    -- now write SPAWN_EXIT_FILE, so only old executions have one.
    exists (
        select 1 from spawn_events r
        where r.event_name = 'execution.ended'
          and r.session_id = s.session_id
          and r.execution_id = s.execution_id
          and r.source <> 'bridge'
    ) as exit_reported,
    x.recorded_at_ms - s.recorded_at_ms as duration_ms,
    (s.kind -> 'detail' ->> 'command_id')::bigint as command_id,
    -- Columns added after the first are appended here, never inserted:
    -- `create or replace view` keeps every existing column in place, so a
    -- live database refuses a new one in the middle (42P16).
    -- The signal that killed the engine, when one did (the runner writes it
    -- beside the exit status; the Bridge records it). Null for an exit.
    (x.kind -> 'detail' ->> 'signal')::integer as signal,
    -- What the Bridge saw when no runner of its own ran the execution any
    -- more; null for an exit or a stop of a running engine.
    x.kind -> 'detail' ->> 'evidence' as evidence,
    -- What the engine was launched with, no secret in it (issue #79,
    -- `LaunchSummary`): the relay's scheme, host and port, the main and
    -- small models the inline settings pin, the engine's own Claude Code
    -- directory. Only these keys are read, whatever else a record holds;
    -- null for a start on Claude Code's own settings in `~/.claude`, and
    -- for records made before it was kept.
    case when jsonb_typeof(s.kind -> 'detail' -> 'launch') = 'object' then
        nullif(jsonb_strip_nulls(jsonb_build_object(
            'relay_url',   s.kind -> 'detail' -> 'launch' ->> 'relay_url',
            'model',       s.kind -> 'detail' -> 'launch' ->> 'model',
            'small_model', s.kind -> 'detail' -> 'launch' ->> 'small_model',
            'config_dir',  s.kind -> 'detail' -> 'launch' ->> 'config_dir')), '{}'::jsonb)
    end as launch
from spawn_events s
left join lateral (
    select e.kind, e.recorded_at_ms
    from spawn_events e
    where e.event_name = 'execution.ended'
      and e.session_id = s.session_id
      and e.execution_id = s.execution_id
      and e.source = 'bridge'
    order by e.id
    limit 1
) x on true
where s.event_name = 'execution.started';

create or replace view agent_artifacts as
select
    e.session_id,
    e.agent_id,
    e.execution_id,
    e.kind -> 'detail' -> 'artifact' ->> 'project'  as project,
    e.kind -> 'detail' -> 'artifact' ->> 'branch'   as branch,
    e.kind -> 'detail' -> 'artifact' ->> 'commit'   as commit_id,
    e.kind -> 'detail' ->> 'reason'                 as reason,
    e.session_seq,
    e.recorded_at_ms
from spawn_events e
where e.event_name = 'artifact.committed';

create or replace view agent_relations as
select
    e.session_id,
    e.agent_id,
    e.kind -> 'detail' ->> 'parent_session_id' as parent_session_id,
    e.recorded_at_ms
from spawn_events e
where e.event_name = 'session.linked';

-- One row per (session, ancestor). Depth 1 is the parent.
-- ponytail: the depth cap of 64 stops a link cycle; reject cycles at write
-- time if a deeper tree appears.
create or replace view agent_lineage as
with recursive parent as (
    select distinct on (r.session_id) r.session_id, r.agent_id, r.parent_session_id
    from agent_relations r
    order by r.session_id, r.recorded_at_ms desc
), chain (session_id, agent_id, ancestor_session_id, depth) as (
    select p.session_id, p.agent_id, p.parent_session_id, 1
    from parent p
    union all
    select c.session_id, c.agent_id, p.parent_session_id, c.depth + 1
    from chain c
    join parent p on p.session_id = c.ancestor_session_id
    where c.depth < 64
)
select session_id, agent_id, ancestor_session_id, depth from chain;

-- Events of one command: its gateway events and every event of the
-- execution it created.
create or replace view agent_task_events as
select
    coalesce((e.kind -> 'detail' ->> 'command_id')::bigint,
             (s.kind -> 'detail' ->> 'command_id')::bigint) as command_id,
    e.session_id,
    e.agent_id,
    e.session_seq,
    e.id as event_id,
    e.execution_id,
    e.event_name,
    e.recorded_at_ms
from spawn_events e
left join spawn_events s
    on s.event_name = 'execution.started'
   and s.session_id = e.session_id
   and s.execution_id = e.execution_id
where e.event_name in ('command.accepted', 'command.finished') or s.id is not null;

-- Tool calls started and not completed or failed, in executions the Bridge
-- has not ended.
create or replace view agent_open_tools as
select
    s.session_id,
    s.agent_id,
    s.execution_id,
    s.kind -> 'detail' ->> 'tool_use_id' as tool_use_id,
    s.kind -> 'detail' ->> 'tool_name'   as tool_name,
    s.session_seq,
    s.recorded_at_ms as started_at_ms
from spawn_events s
where s.event_name = 'tool.started'
  and not exists (
      select 1 from spawn_events c
      where c.session_id = s.session_id
        and c.event_name in ('tool.completed', 'tool.failed')
        and c.kind -> 'detail' ->> 'tool_use_id' = s.kind -> 'detail' ->> 'tool_use_id'
  )
  and not exists (
      select 1 from spawn_events x
      where x.session_id = s.session_id
        and x.event_name = 'execution.ended'
        and x.source = 'bridge'
        and x.execution_id = s.execution_id
  );

-- Background jobs (a Bash `run_in_background`, a Monitor, a background
-- Agent) an execution started and that have not ended, in executions the
-- Bridge has not ended: an execution's end closes its jobs, and a resume is
-- a new execution. The Bridge reads both records from the engine's
-- transcript (`job.started`, `job.ended`). An Agent can run again under its
-- id (resumed by a message), so a job is open when its latest start has no
-- later end: the row is that start, with no later start or end of the id.
create or replace view agent_open_jobs as
select
    s.session_id,
    s.agent_id,
    s.execution_id,
    s.id as event_id,
    s.kind -> 'detail' ->> 'job_id' as job_id,
    s.kind -> 'detail' ->> 'kind'   as job_kind,
    s.session_seq,
    s.recorded_at_ms as started_at_ms
from spawn_events s
where s.event_name = 'job.started'
  and not exists (
      select 1 from spawn_events e
      where e.session_id = s.session_id
        and e.event_name in ('job.started', 'job.ended')
        and e.kind -> 'detail' ->> 'job_id' = s.kind -> 'detail' ->> 'job_id'
        and e.session_seq > s.session_seq
  )
  and not exists (
      select 1 from spawn_events x
      where x.session_id = s.session_id
        and x.event_name = 'execution.ended'
        and x.source = 'bridge'
        and x.execution_id = s.execution_id
  );

-- Position of the log per session. This is not judgement lag; see
-- docs/view-architecture.md section 4.1.
create or replace view agent_freshness as
select p.session_id, p.agent_id, p.last_session_seq, p.last_event_id,
       p.last_event_at_ms, p.event_count
from spawn_session_state p;

-- One row per session: the latest judgement and the latest execution.
create or replace view agent_status as
select
    p.session_id,
    p.agent_id,
    p.observation ->> 'state'  as state,
    p.observation ->> 'reason' as reason,
    p.observation_seq,
    p.last_session_seq,
    p.last_event_at_ms,
    x.execution_id,
    x.engine,
    x.started_at_ms,
    x.ended_at_ms,
    x.exit_reported,
    x.execution_id is not null and x.ended_at_ms is null as live,
    -- Appended (42P16): the latest execution's launch summary.
    x.launch
from spawn_session_state p
left join lateral (
    select a.execution_id, a.engine, a.started_at_ms, a.ended_at_ms, a.exit_reported, a.launch
    from agent_executions a
    where a.session_id = p.session_id
    order by a.started_at_ms desc, a.execution_id desc
    limit 1
) x on true;

-- The raw tables, the projection and the views stay with the owner. Readers
-- go through the grant-filtered `spawn_read_*` functions below; the gateway
-- trigger runs as the owner and checks `session_user` against `spawn_grants`.
-- The revoke on the views also removes the public select of older schemas.
revoke all on spawn_events, spawn_commands, spawn_grants, spawn_session_state, spawn_agent_sessions
    from public;
revoke select on agent_state, agent_status, agent_timeline, agent_judgements, agent_tasks,
    agent_task_events, agent_executions, agent_artifacts, agent_relations,
    agent_lineage, agent_open_tools, agent_open_jobs, agent_freshness
    from public;
grant insert on agent_commands to public;
-- No select, not even of `id` (older schemas granted it for RETURNING):
-- that would list every command's id. A caller learns the id of the command
-- it made from `spawn_gateway_submit` below.
revoke select on agent_commands from public;
revoke select (id) on agent_commands from public;

-- Submit through the gateway and return the command made: a new one, or
-- the one an earlier call of this principal with this key made. The
-- trigger checks `session_user`'s grants, which SECURITY DEFINER keeps.
create or replace function spawn_gateway_submit(p_agent text, p_session text, p_key text,
                                                p_action jsonb)
returns bigint language sql security definer as $$
    insert into agent_commands (agent_id, session_id, idempotency_key, action)
    values (p_agent, p_session, p_key, p_action)
    returning id
$$;

revoke execute on function spawn_append(text, text, text, text, text, jsonb) from public;
revoke execute on function spawn_append_trusted(text, text, text, text, text, jsonb) from public;
revoke execute on function spawn_session_fold(text) from public;
revoke execute on function spawn_submit(text, text, text, text, jsonb) from public;
revoke execute on function spawn_claim(text, bigint) from public;
revoke execute on function spawn_release(bigint, integer, bigint) from public;
revoke execute on function spawn_finish(bigint, integer, boolean, text) from public;

-- A security definer function must not resolve names through the caller's
-- search_path, or a caller's temporary table could stand in for
-- `spawn_grants`. Pin the schema the migration runs in, temp schema last.
do $$
begin
    execute format(
        'alter function spawn_gateway_insert() set search_path = %I, pg_temp',
        current_schema()
    );
    execute format(
        'alter function spawn_gateway_submit(text, text, text, jsonb) set search_path = %I, pg_temp',
        current_schema()
    );
end
$$;

-- Grant-filtered readers: `spawn_read_<view>()` for the views that list
-- sessions, `spawn_read_<view>(session_id)` for per-session views. Each
-- returns the rows whose agent the caller's principal (spawn_principal)
-- holds a grant for, and every row to the owner (the role these functions
-- run as).
do $$
declare
    v_view text;
    v_filter constant text :=
        '(session_user = current_user or exists (select 1 from spawn_grants g'
        ' where g.principal = spawn_principal()'
        ' and spawn_grant_matches(g.agent_id, r.agent_id)))';
begin
    foreach v_view in array array['state', 'status', 'tasks', 'freshness'] loop
        execute format(
            'create or replace function spawn_read_%1$s() returns setof agent_%1$s'
            ' language sql stable security definer set search_path = %2$I, pg_temp'
            ' as $f$ select r.* from agent_%1$s r where %3$s $f$',
            v_view, current_schema(), v_filter);
    end loop;
    foreach v_view in array array['timeline', 'judgements'] loop
        execute format(
            'create or replace function spawn_read_%1$s(p_session text) returns setof agent_%1$s'
            ' language sql stable security definer set search_path = %2$I, pg_temp'
            ' as $f$ select r.* from agent_%1$s r where r.session_id = p_session and %3$s $f$',
            v_view, current_schema(), v_filter);
    end loop;
end
$$;

-- Readers nothing calls are not kept.
drop function if exists spawn_read_relations();
drop function if exists spawn_read_executions(text);
drop function if exists spawn_read_artifacts(text);
drop function if exists spawn_read_task_events(text);
drop function if exists spawn_read_lineage(text);
drop function if exists spawn_read_open_tools(text);

-- The retired RSI controller's tables. `spawn mission import-rsi` brought
-- each landed attempt into the control stream as a `legacy.imported` task
-- (created by `rsi`, its objective the attempt's task, created when the
-- attempt was); nothing else of theirs was imported. They are dropped only
-- when that loses nothing: every attempt has its record and no iteration or
-- controller state is left. Otherwise they stay, with a warning.
do $$
declare
    v_attempts bigint := 0;
    v_rest bigint := 0;
begin
    if to_regclass('rsi_attempts') is not null then
        select count(*) into v_attempts
          from rsi_attempts a
         where not exists (
             select 1 from spawn_events e
              cross join lateral (select e.kind -> 'detail' -> 'record' as r) x
              where e.session_id = 'session_control' and e.event_name = 'control.recorded'
                and x.r ->> 'type' = 'legacy.imported' and x.r ->> 'table' = 'mission_tasks'
                and x.r -> 'row' ->> 'created_by' = 'rsi'
                and (x.r -> 'row' ->> 'objective')::bigint = a.task_id
                and (x.r -> 'row' ->> 'created_at_ms')::bigint = a.created_at_ms);
    end if;
    if to_regclass('rsi_iterations') is not null then
        v_rest := v_rest + (select count(*) from rsi_iterations);
    end if;
    if to_regclass('rsi_state') is not null then
        v_rest := v_rest + (select count(*) from rsi_state);
    end if;
    if v_attempts = 0 and v_rest = 0 then
        drop table if exists rsi_attempts, rsi_iterations, rsi_state;
    else
        raise warning 'kept rsi_attempts, rsi_iterations and rsi_state: % attempts have no '
                      'imported record and % iteration or state rows were never imported; '
                      'dump them (pg_dump -t ''rsi_*'') and drop them to keep their history',
                      v_attempts, v_rest;
    end if;
end
$$;

-- `spawn_terminal`, a login for engine terminals to append their own
-- events, is unused: an existing one may not log in. Roles are the
-- cluster's, so a migration writes one only when it has to: migrations of
-- other databases run at the same time and would collide on the row.
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'spawn_terminal' and rolcanlogin) then
        alter role spawn_terminal nologin;
    end if;
end
$$;

-- The logins from before they were per database (`spawn_supervisor`,
-- `spawn_reader`, `spawn_terminal`, one per cluster) lose everything they
-- were granted here, and act as nobody (spawn_principal). They may still
-- log in, with a password an earlier install set (a fixed one, or one
-- derived from that install's owner password): another database on the
-- cluster may still use them, so only a human drops them.
do $$
declare
    v_role text;
begin
    foreach v_role in array array['spawn_supervisor', 'spawn_reader', 'spawn_terminal'] loop
        if exists (select 1 from pg_roles where rolname = v_role) then
            execute format('revoke all on all tables in schema %I from %I', current_schema(), v_role);
            execute format('revoke all on all sequences in schema %I from %I',
                           current_schema(), v_role);
            execute format('revoke all on all functions in schema %I from %I',
                           current_schema(), v_role);
            execute format('revoke all on schema %I from %I', current_schema(), v_role);
            -- The database's row is the cluster's: written only to take one.
            if exists (select 1 from pg_database d cross join lateral aclexplode(d.datacl) a
                        where d.datname = current_database()
                          and a.grantee = (select oid from pg_roles where rolname = v_role)) then
                execute format('revoke all on database %I from %I', current_database(), v_role);
            end if;
            if exists (select 1 from pg_roles where rolname = v_role and rolcanlogin) then
                raise warning 'role % from an earlier install can still log in; it has no access '
                              'here any more (this database''s logins are %): drop it once no '
                              'other database on the cluster uses it',
                              v_role, spawn_login_role(v_role);
            end if;
        end if;
    end loop;
end
$$;

-- A restricted login of this database: created without login (a migration
-- with the owner's password gives it one, PostgresStore::migrate), with a
-- random salt in its comment that its password derives from, and the right
-- to connect and to see the schema.
do $$
declare
    v_base text;
    v_role text;
begin
    foreach v_base in array array['spawn_supervisor', 'spawn_reader', 'spawn_human'] loop
        v_role := spawn_login_role(v_base);
        if not exists (select 1 from pg_roles where rolname = v_role) then
            execute format('create role %I nologin', v_role);
        end if;
        if coalesce(shobj_description((select oid from pg_roles where rolname = v_role),
                                      'pg_authid'), '') !~ '^spawn login salt [0-9a-f]{64}$' then
            execute format('comment on role %I is %L', v_role,
                           'spawn login salt '
                           || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''));
        end if;
        -- The database's row is the cluster's too: granted once.
        if not exists (select 1 from pg_database d cross join lateral aclexplode(d.datacl) a
                        where d.datname = current_database() and a.privilege_type = 'CONNECT'
                          and a.grantee = (select oid from pg_roles where rolname = v_role)) then
            execute format('grant connect on database %I to %I', current_database(), v_role);
        end if;
        execute format('grant usage on schema %I to %I', current_schema(), v_role);
    end loop;
end
$$;

-- A migration without the owner's password turns this database's logins
-- off (PostgresStore::migrate): their passwords derive from the owner's, so
-- none can be set, and one an earlier migration set must not outlive it.
create or replace function spawn_logins_off() returns void
language plpgsql as $$
declare
    v_role text;
begin
    foreach v_role in array array[spawn_login_role('spawn_supervisor'),
                                  spawn_login_role('spawn_reader'),
                                  spawn_login_role('spawn_human')] loop
        execute format('alter role %I with nologin password null', v_role);
    end loop;
    raise warning 'the database URL has no owner password: logins %, % and % are off (no login, '
                  'no password) until a migration with the owner''s password',
                  spawn_login_role('spawn_supervisor'), spawn_login_role('spawn_reader'),
                  spawn_login_role('spawn_human');
end $$;
revoke execute on function spawn_logins_off() from public;

-- The supervisor's terminal connects with its login. It reads the fleet
-- and submits commands through the `agent_commands` gateway, which records
-- `spawn_supervisor` as the principal and allows only the agents its grants
-- name; it decides missions through the checked mission functions. It
-- writes no events, claims or finishes no commands.
do $$
begin
    execute format('revoke execute on function spawn_append(text, text, text, text, text, jsonb) '
                   'from %I', spawn_login_role('spawn_supervisor'));
end
$$;

insert into spawn_grants (principal, agent_id, scope) values
    ('spawn_supervisor', '*', 'read'),
    ('spawn_supervisor', 'agent_worker_*', 'all')
on conflict (principal, agent_id) do nothing;

-- A person's idempotency key answers with its first command only for the
-- request that made it: the same session and the same action (GitHub #16
-- item 8). `spawn_submit` returns the command of `(principal, key)` whatever
-- session and action it was made for, so a key one session's input used,
-- sent again for another session or with other text, was answered with that
-- first command: the page read success and the second session got nothing.
-- `p_id` is the command `spawn_submit` returned (or the one found) for
-- `p_key`: returned when it is this request's, refused otherwise with
-- SQLSTATE 23505, which the page answers 409, and nothing is recorded. The
-- refusal names no session and no text: the `spawn_human` login reads
-- nothing. Checked after `spawn_submit`, under its lock, so two first uses
-- of one key that race are told apart too. No row changes: commands made
-- before this keep their keys and replay as before for their own request.
create or replace function spawn_human_replay(p_id bigint, p_key text, p_session text,
                                              p_action jsonb)
returns bigint language plpgsql as $$
begin
    if not exists (select 1 from spawn_commands c
                    where c.id = p_id and c.principal = 'human'
                      and c.session_id = p_session and c.action = p_action) then
        raise exception 'idempotency key % was already used for another input or key: send this one with a new key',
            quote_literal(p_key) using errcode = '23505';
    end if;
    return p_id;
end $$;

revoke execute on function spawn_human_replay(bigint, text, text, jsonb) from public;

-- A person's input from the web page (`spawn serve`, `POST
-- /api/session/<id>/input`): the command `spawn submit --principal human
-- --agent <the session's agent> --session <id> --key <key> --action
-- '{"type":"input","text":<text>}'` makes, through the same `spawn_submit`
-- with the same idempotency rule (a repeated key of `human` returns the
-- first command and makes none), for the same session and text only: the
-- key of another session's input, or of other text, is refused
-- (`spawn_human_replay`, SQLSTATE 23505). Like every input of a person it waits for
-- the session's turn (crates/spawn-core/src/bridge.rs). The agent is the one
-- the session belongs to (`spawn_agent_sessions`): the caller cannot pair a
-- session with another agent. Returns the command, or null when no agent
-- has used the session. An input needs a running engine (objective 040): a
-- session with no live execution (it never ran one, or its latest ended) is
-- refused here with the reason (SQLSTATE 55000, which the page answers 409),
-- and records no command, so the person learns at once that it went nowhere;
-- a repeated key returns its first command even if the session stopped
-- since. (`spawn submit` is unchanged: it records the command, and the
-- Bridge fails it with the same reason.) Only the `spawn_human` login may
-- call it, and it may
-- call nothing else: it reads nothing (no grant), appends no event, and
-- submits no other action and as no other principal. The text is what a
-- person types: not blank, at most 8192 bytes (serve.rs `MAX_INPUT_TEXT`),
-- and no control character but tab and line ends (an escape or a C1 control
-- would reach the engine's terminal as keys, not as text).
create or replace function spawn_human_input(p_session text, p_key text, p_text text)
returns bigint language plpgsql security definer as $$
declare
    v_agent text;
    v_action jsonb;
    v_first bigint;
begin
    if spawn_principal() is distinct from 'human' then
        raise exception '% may not type as a person (only the spawn_human login does)',
            session_user using errcode = '42501';
    end if;
    if coalesce(p_key, '') = '' or octet_length(p_key) > 256 or p_key ~ '[[:cntrl:]]' then
        raise exception 'an input needs an idempotency key of 1 to 256 bytes, no control character'
            using errcode = '22023';
    end if;
    if coalesce(btrim(p_text, E' \t\r\n'), '') = '' then
        raise exception 'an input needs text' using errcode = '22023';
    end if;
    if octet_length(p_text) > 8192 then
        raise exception 'an input is at most 8192 bytes, not %', octet_length(p_text)
            using errcode = '22023';
    end if;
    if p_text ~ '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f-\x9f]' then
        raise exception 'an input holds no control character but tab and line ends'
            using errcode = '22023';
    end if;
    select s.agent_id into v_agent from spawn_agent_sessions s where s.session_id = p_session;
    if v_agent is null then
        return null;
    end if;
    v_action := jsonb_build_object('type', 'input', 'text', p_text);
    -- A repeated key returns its first command even if the session stopped
    -- since (objective 040), for the same session and text only (#16 item 8).
    select c.id into v_first from spawn_commands c
     where c.principal = 'human' and c.idempotency_key = p_key;
    if v_first is not null then
        return spawn_human_replay(v_first, p_key, p_session, v_action);
    end if;
    if not exists (select 1 from agent_status a where a.session_id = p_session and a.live) then
        raise exception '% runs no execution: an input needs a running engine; resume the session',
            p_session using errcode = '55000';
    end if;
    return (select spawn_human_replay(s.out_id, p_key, p_session, v_action)
              from spawn_submit('human', p_key, v_agent, p_session, v_action) s);
end $$;

do $$
begin
    execute format('alter function spawn_human_input(text, text, text) set search_path = %I, pg_temp',
                   current_schema());
    execute 'revoke execute on function spawn_human_input(text, text, text) from public';
    execute format('grant execute on function spawn_human_input(text, text, text) to %I',
                   spawn_login_role('spawn_human'));
end
$$;

-- A person's key from the web page (`spawn serve`, `POST
-- /api/session/<id>/key`, backlog P1): the command `spawn submit --principal
-- human --agent <the session's agent> --session <id> --key <key> --action
-- '{"type":"key","key":<name>}'` makes, through the same `spawn_submit` with
-- the same idempotency rule, as its own action type and never text. The name
-- is one of the closed set (spawn-core's `NamedKey`): escape, up, down, left,
-- right, enter, y, n, and the digits of a numbered permission or selection
-- prompt, digit1 to digit9 (issue #91; the bare `1` to `9` name them
-- too, and the action stores the `digit<n>` name, so every stored key
-- parses). Returns the command, or null when no agent has used
-- the session. A key needs a running engine: a session with no live
-- execution is refused here with the reason (SQLSTATE 55000, which the page
-- answers 409), and records no command, since nothing reached an agent; a
-- repeated key returns its first command even if the session stopped since,
-- for the same session and name only (`spawn_human_replay`, SQLSTATE 23505
-- otherwise).
-- (The Bridge still fails, on the record, a key that loses the race against
-- the execution's end.) Only the `spawn_human` login may call it, beside
-- `spawn_human_input`.
create or replace function spawn_human_key(p_session text, p_key text, p_name text)
returns bigint language plpgsql security definer as $$
declare
    v_agent text;
    v_first bigint;
    v_action jsonb;
begin
    if spawn_principal() is distinct from 'human' then
        raise exception '% may not press keys as a person (only the spawn_human login does)',
            session_user using errcode = '42501';
    end if;
    if coalesce(p_key, '') = '' or octet_length(p_key) > 256 or p_key ~ '[[:cntrl:]]' then
        raise exception 'a key needs an idempotency key of 1 to 256 bytes, no control character'
            using errcode = '22023';
    end if;
    if p_name is null or (p_name not in ('escape', 'up', 'down', 'left', 'right', 'enter', 'y', 'n')
                          and p_name !~ '^(digit)?[1-9]$') then
        raise exception 'key % is not one of escape, up, down, left, right, enter, y, n, digit1 to digit9',
            coalesce(quote_literal(p_name), 'null') using errcode = '22023';
    end if;
    select s.agent_id into v_agent from spawn_agent_sessions s where s.session_id = p_session;
    if v_agent is null then
        return null;
    end if;
    select c.id into v_first from spawn_commands c
     where c.principal = 'human' and c.idempotency_key = p_key;
    v_action := jsonb_build_object('type', 'key', 'key',
                                   case when p_name ~ '^[1-9]$' then 'digit' || p_name
                                        else p_name end);
    if v_first is not null then
        return spawn_human_replay(v_first, p_key, p_session, v_action);
    end if;
    if not exists (select 1 from agent_status a where a.session_id = p_session and a.live) then
        raise exception '% runs no execution: a key needs a running engine; resume the session',
            p_session using errcode = '55000';
    end if;
    return (select spawn_human_replay(s.out_id, p_key, p_session, v_action)
              from spawn_submit('human', p_key, v_agent, p_session, v_action) s);
end $$;

do $$
begin
    execute format('alter function spawn_human_key(text, text, text) set search_path = %I, pg_temp',
                   current_schema());
    execute 'revoke execute on function spawn_human_key(text, text, text) from public';
    execute format('grant execute on function spawn_human_key(text, text, text) to %I',
                   spawn_login_role('spawn_human'));
end
$$;

-- A person's message to the supervisor from the web page's Master Control
-- (`spawn serve`, `POST /api/master/message`, issue #91 P1a). Unlike
-- `spawn_human_input` it never refuses a supervisor that runs no
-- execution: a message to a stopped or idle supervisor wakes it and is
-- delivered after the wake. Everything is a command `spawn submit
-- --principal human` could make, to `session_supervisor` and its agent
-- (`agent_supervisor` when it never ran), through the same `spawn_submit`,
-- in this order, so the Bridge runs them in this order (`spawn_claim`: one
-- command per session at a time, in id order):
--   restart, while it runs: `{"type":"stop"}` (key `<key>:stop`), which
--     ends it with a checkpoint; it then runs no execution;
--   steer, while it runs: `{"type":"key","key":"escape"}` (key
--     `<key>:steer`), which interrupts the turn at once (Esc keeps the
--     native session's context), so the input is read next;
--   whenever it runs no execution, or a stop or discard not finished yet
--     will end the one it runs (any mode): the wake (key `<key>:wake`),
--     `{"type":"resume"}` when a native session is bound to resume
--     (`session.native_started`), else `{"type":"start"}` with a short
--     prompt and no charter, on the `engine`, `model` and `model_label` of
--     the session's newest start (each only when that start names it;
--     engine `claude` when there is none, so a Claude session's wake is
--     unchanged): after a cold start the dispatcher types the
--     charter in at the supervisor's first idle prompt, as after any start
--     that gave none (crate dispatch, `charter`). No wake is made when a
--     start or resume is already in flight after every unfinished stop and
--     discard (the liveness rule's, or an earlier message's): its id is
--     the wake then. A wake is never older than a stop ahead of it, so the
--     stop never ends the execution the wake begins;
--   always the input `{"type":"input","text":<text>,"tags":[...]}` (key
--     `<key>`), which waits for the turn as every person's input does. Its
--     tags are `master:<mode>` first, then `master-stop:<id>`,
--     `master-steer:<id>` and `master-wake:<id>` of the commands this
--     message made or took as its wake: the record of what it did, which a
--     repeat of the request is answered from.
-- auto and queue are the plain input (auto-woken); the tag says which.
-- Idempotent: the key's input made, the same request (same text and mode)
-- returns exactly the commands the first call answered and makes none;
-- another request under the key is refused (SQLSTATE 23505, which the
-- page answers 409). A key whose derived keys (`<key>:stop`, `:steer`,
-- `:wake`) another request already used is refused the same way, before
-- anything is made, so a message never takes an earlier command for its
-- own. The key is 1 to 240 bytes (its derived keys stay within 256;
-- spawn-postgres `MAX_MASTER_KEY_BYTES`), the text what a person types as
-- for `spawn_human_input`, the mode one of auto, steer, queue, restart
-- (null: auto; spawn-postgres `MasterMessageMode`). Returns `{command_id,
-- wake_command_id, stop_command_id, steer_command_id, session_id, mode,
-- principal, woke, replayed}`, ids null where none was made. Only the
-- `spawn_human` login may call it.
create or replace function spawn_human_master_message(p_key text, p_text text, p_mode text)
returns jsonb language plpgsql security definer as $$
declare
    v_session constant text := 'session_supervisor';
    v_mode text := coalesce(p_mode, 'auto');
    v_agent text;
    v_action jsonb;
    v_first bigint;
    v_first_action jsonb;
    v_first_session text;
    v_live boolean;
    v_ahead bigint;
    v_stop bigint;
    v_steer bigint;
    v_wake bigint;
    v_wake_action jsonb;
    v_tags jsonb;
    v_input bigint;
begin
    if spawn_principal() is distinct from 'human' then
        raise exception '% may not write to the supervisor as a person (only the spawn_human login does)',
            session_user using errcode = '42501';
    end if;
    if coalesce(p_key, '') = '' or octet_length(p_key) > 240 or p_key ~ '[[:cntrl:]]' then
        raise exception 'a message needs an idempotency key of 1 to 240 bytes, no control character'
            using errcode = '22023';
    end if;
    if v_mode not in ('auto', 'steer', 'queue', 'restart') then
        raise exception 'mode % is not one of auto, steer, queue, restart', quote_literal(v_mode)
            using errcode = '22023';
    end if;
    if coalesce(btrim(p_text, E' \t\r\n'), '') = '' then
        raise exception 'a message needs text' using errcode = '22023';
    end if;
    if octet_length(p_text) > 8192 then
        raise exception 'a message is at most 8192 bytes, not %', octet_length(p_text)
            using errcode = '22023';
    end if;
    if p_text ~ '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f-\x9f]' then
        raise exception 'a message holds no control character but tab and line ends'
            using errcode = '22023';
    end if;
    -- One message at a time decides on the supervisor's state: the append
    -- lock spawn_submit takes, held to commit.
    perform pg_advisory_xact_lock(1399957335);
    select c.id, c.action, c.session_id into v_first, v_first_action, v_first_session
      from spawn_commands c
     where c.principal = 'human' and c.idempotency_key = p_key;
    if v_first is not null then
        -- The same request again: answered from the first call's record.
        if v_first_session is distinct from v_session
           or v_first_action ->> 'type' is distinct from 'input'
           or v_first_action ->> 'text' is distinct from p_text
           or v_first_action -> 'tags' ->> 0 is distinct from 'master:' || v_mode then
            raise exception 'idempotency key % was already used for another input or key: send this one with a new key',
                quote_literal(p_key) using errcode = '23505';
        end if;
        select max(substring(t from '^master-stop:([0-9]+)$')::bigint),
               max(substring(t from '^master-steer:([0-9]+)$')::bigint),
               max(substring(t from '^master-wake:([0-9]+)$')::bigint)
          into v_stop, v_steer, v_wake
          from jsonb_array_elements_text(coalesce(v_first_action -> 'tags', '[]'::jsonb)) t;
        return jsonb_build_object('command_id', v_first, 'wake_command_id', v_wake,
                                  'stop_command_id', v_stop, 'steer_command_id', v_steer,
                                  'session_id', v_session, 'mode', v_mode,
                                  'principal', 'human', 'woke', v_wake is not null,
                                  'replayed', true);
    end if;
    if exists (select 1 from spawn_commands c
                where c.principal = 'human'
                  and c.idempotency_key in (p_key || ':stop', p_key || ':steer', p_key || ':wake')) then
        raise exception 'idempotency key % derives keys another request already used (%:stop, :steer or :wake): send this one with a new key',
            quote_literal(p_key), p_key using errcode = '23505';
    end if;
    select s.agent_id into v_agent from spawn_agent_sessions s where s.session_id = v_session;
    v_agent := coalesce(v_agent, 'agent_supervisor');
    v_live := exists (select 1 from agent_status a where a.session_id = v_session and a.live);
    -- A stop or discard not finished yet ends the execution it runs: the
    -- message needs a wake after it.
    select max(c.id) into v_ahead from spawn_commands c
     where c.session_id = v_session and c.state <> 'finished'
       and c.action ->> 'type' in ('stop', 'discard');
    if v_ahead is not null then
        v_live := false;
    end if;
    if v_live and v_mode = 'restart' then
        select spawn_human_replay(s.out_id, p_key || ':stop', v_session,
                                  jsonb_build_object('type', 'stop')) into v_stop
          from spawn_submit('human', p_key || ':stop', v_agent, v_session,
                            jsonb_build_object('type', 'stop')) s;
        v_ahead := v_stop;
        v_live := false;
    elsif v_live and v_mode = 'steer' then
        select spawn_human_replay(s.out_id, p_key || ':steer', v_session,
                                  jsonb_build_object('type', 'key', 'key', 'escape')) into v_steer
          from spawn_submit('human', p_key || ':steer', v_agent, v_session,
                            jsonb_build_object('type', 'key', 'key', 'escape')) s;
    end if;
    if not v_live then
        -- A start or resume in flight after every stop ahead wakes it.
        select c.id into v_wake from spawn_commands c
         where c.session_id = v_session and c.state <> 'finished'
           and c.action ->> 'type' in ('start', 'resume')
           and c.id > coalesce(v_ahead, 0)
         order by c.id desc limit 1;
        if v_wake is null then
            v_wake_action := case
                when exists (select 1 from spawn_events e
                              where e.session_id = v_session
                                and e.event_name = 'session.native_started')
                then jsonb_build_object('type', 'resume')
                -- A cold start runs the engine, model profile and model label
                -- of the session's newest start (Claude Code when it has
                -- none); a key that start left out stays out, so a Claude
                -- session's wake is what it always was.
                else (select jsonb_strip_nulls(jsonb_build_object(
                          'type', 'start',
                          'engine', coalesce(n.action ->> 'engine', 'claude'),
                          'model', n.action -> 'model',
                          'model_label', n.action -> 'model_label',
                          'prompt', 'The owner wrote to you from the dashboard (Master '
                                    'Control) while you were stopped; the message follows '
                                    'as your next input. Read it, then go on with your work.'))
                        from (select 1) one
                        left join lateral (
                            select c.action from spawn_commands c
                             where c.session_id = v_session and c.action ->> 'type' = 'start'
                             order by c.id desc limit 1) n on true)
            end;
            select spawn_human_replay(s.out_id, p_key || ':wake', v_session, v_wake_action)
              into v_wake
              from spawn_submit('human', p_key || ':wake', v_agent, v_session, v_wake_action) s;
        end if;
    end if;
    v_tags := jsonb_build_array('master:' || v_mode);
    if v_stop is not null then
        v_tags := v_tags || to_jsonb('master-stop:' || v_stop);
    end if;
    if v_steer is not null then
        v_tags := v_tags || to_jsonb('master-steer:' || v_steer);
    end if;
    if v_wake is not null then
        v_tags := v_tags || to_jsonb('master-wake:' || v_wake);
    end if;
    v_action := jsonb_build_object('type', 'input', 'text', p_text, 'tags', v_tags);
    select spawn_human_replay(s.out_id, p_key, v_session, v_action) into v_input
      from spawn_submit('human', p_key, v_agent, v_session, v_action) s;
    return jsonb_build_object('command_id', v_input, 'wake_command_id', v_wake,
                              'stop_command_id', v_stop, 'steer_command_id', v_steer,
                              'session_id', v_session, 'mode', v_mode, 'principal', 'human',
                              'woke', v_wake is not null, 'replayed', false);
end $$;

do $$
begin
    execute format('alter function spawn_human_master_message(text, text, text) set search_path = %I, pg_temp',
                   current_schema());
    execute 'revoke execute on function spawn_human_master_message(text, text, text) from public';
    execute format('grant execute on function spawn_human_master_message(text, text, text) to %I',
                   spawn_login_role('spawn_human'));
end
$$;

-- Missions, tasks and residents (docs/fleet-architecture.md §3.2).
--
-- These tables are the fold of the control stream (§10.1 and
-- `spawn_control_apply` below), never written directly. Humans add missions
-- and approve residents; the supervisor decides tasks and reviews reports
-- through the checked functions; the dispatcher records deliveries and
-- reports as the owner.
create table if not exists mission_missions (
    id            bigint generated by default as identity primary key,
    text          text   not null,
    origin        text   not null,
    sources       jsonb  not null default '[]'::jsonb,
    state         text   not null default 'open'
                  check (state in ('open', 'active', 'done', 'dropped')),
    summary       text,
    created_at_ms bigint not null,
    updated_at_ms bigint not null,
    -- Landing (§10.3): a gate (a scenarios directory in the controller's
    -- checkout) lands the tasks' work on the source, after the supervisor's
    -- review (`review`) or on the gate alone (`gate`). `baseline` is where
    -- the last landing left the source's main; `halted` holds the reason a
    -- halt rule fired, until a human resumes the mission.
    gate            text,
    accept          text    not null default 'review' check (accept in ('review', 'gate')),
    budget          jsonb,
    baseline        text,
    halted          text,
    scenario_floor  integer not null default 0,
    gate_rejections integer not null default 0,
    gate_aborts     integer not null default 0,
    -- The gate's current run of `no_room` outcomes (TMPDIR short of room,
    -- scripts/disk.sh, or a check the integrator makes before a gate:
    -- disk, memory, the test database) on one task, `gate_room_task`: when the first and
    -- the latest were recorded, how many, and whether one of them escalated
    -- to the supervisor. No verdict on the work, so it counts toward no
    -- halt. A gate that judged (or aborted) ends the run, and so does its
    -- task leaving the gate (cancelled, aborted); a `no_room` on another
    -- task starts a new one.
    gate_room_task     bigint,
    gate_room_since_ms bigint,
    gate_room_last_ms  bigint,
    gate_room_waits    integer not null default 0,
    gate_room_escalated boolean not null default false,
    -- An objective mission (§10.4): `{"backlog": <dir>, "resident": <name>}`.
    objectives      jsonb,
    -- The gate's current run of `host_fault` outcomes (the gate failed
    -- because the host did: the test database), in a row across the
    -- mission: how many, the task the latest was about and when it is due to
    -- be judged again (the record's `due_ms`). No verdict on the work, so it
    -- counts toward no halt. `no_room` and `stale` leave the run; every
    -- other verdict, a landing and a resume end it.
    gate_host_faults integer not null default 0,
    gate_host_task   bigint,
    gate_host_due_ms bigint,
    -- The gate's current run of `host_fault` outcomes whose evidence is a
    -- base that disagreed with itself (objective 033: a scenario of the base
    -- exited 1 and then 0, before any candidate code ran), in a row across
    -- the mission: the record that makes it 3 carries `alert`, and every
    -- other one does not. No verdict on the work, so it counts toward no
    -- halt. `no_room` and `stale` leave the run; every other verdict
    -- (020's host faults included), a landing and a resume end it.
    gate_base_disagrees integer not null default 0,
    -- The objective of every rejection in the current run of
    -- `gate_rejections`, or null: no run, a rejection of another objective
    -- or of a task without one in it (design-halt-per-objective.md). A run
    -- of one objective's tasks yields that objective instead of halting the
    -- mission.
    gate_rejection_objective integer,
    -- The scenario file names (`*.sh`) the gate directory held at the
    -- gating that set `scenario_floor` (the latest `task.gated` at the floor
    -- since the last resume, its `scenario_names`), null without one.
    scenario_names jsonb,
    -- The halt the mission is in (null while it is not halted): its
    -- `mission.halted` record's event id and time, and `gone`, the scenarios
    -- a halt on the floor names (null for any other halt).
    halt_event      bigint,
    halt_at_ms      bigint,
    halt_gone       jsonb,
    -- The owner's pause the mission is in (`spawn mission pause`, objective
    -- 099; null while it is not paused): its `mission.paused` record's event
    -- id, time and reason. While it holds, no objective is assigned to the
    -- mission, nothing is delivered to its workers and its resident is
    -- stopped. A pause is not a halt: the two are independent.
    pause_event     bigint,
    pause_at_ms     bigint,
    pause_reason    text,
    -- The mission's latest `mission.unpaused` record (event id and time),
    -- null while it is paused or was never paused: the dispatcher resumes
    -- the workers the pause stopped once per unpause.
    unpause_event   bigint,
    unpause_at_ms   bigint
);

create table if not exists mission_residents (
    name          text   primary key check (name ~ '^[a-z][a-z0-9_]{0,30}$'),
    agent_id      text   not null unique,
    session_id    text   not null unique,
    charter       text   not null,
    state         text   not null default 'proposed'
                  check (state in ('proposed', 'approved', 'retired')),
    proposed_by   text   not null,
    approved_by   text,
    created_at_ms bigint not null,
    updated_at_ms bigint not null
);

create table if not exists mission_tasks (
    id            bigint generated by default as identity primary key,
    mission_id    bigint not null references mission_missions (id),
    kind          text   not null check (kind in ('resident', 'ephemeral')),
    agent_id      text   not null,
    session_id    text   not null,
    brief         text   not null,
    state         text   not null default 'assigned'
                  check (state in ('assigned', 'delivered', 'reported', 'revise',
                                   'accepted', 'cancelled', 'landing', 'landed')),
    revisions     integer not null default 0,
    review_note   text,
    command_id    bigint,
    report        text,
    created_by    text   not null,
    created_at_ms bigint not null,
    updated_at_ms bigint not null,
    -- Landing: the commit the gate judged and its base, the gate's log and
    -- metric, and, for an objective task, the objective and its scenario.
    base            text,
    candidate       text,
    gate_log        text,
    metric          text,
    objective       integer,
    scenario        text,
    delivered_at_ms bigint,
    -- The models the task's worker runs on (docs/fleet-architecture.md,
    -- "Engine models"): `default`, or `cheap` for simple, well-specified work.
    model           text   not null default 'default' check (model in ('default', 'cheap')),
    -- The owner's hold this landing task last waited behind (`task.held`,
    -- the `source.held` record's event id): its `land()` pushed nothing
    -- under it. Set only by `task.held`; the hold's end does not clear it.
    held_by         bigint,
    -- The task this one re-issues (its `task.assigned` names it): a first
    -- delivery spent without typing is cancelled and assigned again once,
    -- by the dispatcher (`spawn_task_reissue`); a re-issue is never
    -- re-issued again.
    reissue_of      bigint,
    -- The task this one continues (its `task.assigned` names it): the
    -- objective's task after one that went over its budget keeps that
    -- task's work (`task.over_budget`, docs/fleet-architecture.md §10.4).
    continues       bigint,
    -- The task this one takes over (its `task.assigned` names it): a
    -- delivered task moved to a fresh worker whose branch starts from the
    -- old worker's last checkpoint (`spawn_task_reassign`).
    reassign_of     bigint
);

-- Columns added since the first shape of these tables (see spawn_grants).
alter table mission_missions add column if not exists gate text;
alter table mission_missions add column if not exists accept text not null default 'review'
    check (accept in ('review', 'gate'));
alter table mission_missions add column if not exists budget jsonb;
alter table mission_missions add column if not exists baseline text;
alter table mission_missions add column if not exists halted text;
alter table mission_missions add column if not exists scenario_floor integer not null default 0;
alter table mission_missions add column if not exists gate_rejections integer not null default 0;
alter table mission_missions add column if not exists gate_aborts integer not null default 0;
alter table mission_missions add column if not exists gate_room_task bigint;
alter table mission_missions add column if not exists gate_room_since_ms bigint;
alter table mission_missions add column if not exists gate_room_last_ms bigint;
alter table mission_missions add column if not exists gate_room_waits integer not null default 0;
alter table mission_missions add column if not exists gate_room_escalated boolean not null default false;
alter table mission_missions add column if not exists objectives jsonb;
alter table mission_missions add column if not exists gate_host_faults integer not null default 0;
alter table mission_missions add column if not exists gate_host_task bigint;
alter table mission_missions add column if not exists gate_host_due_ms bigint;
alter table mission_missions add column if not exists gate_base_disagrees integer not null default 0;
alter table mission_missions add column if not exists gate_rejection_objective integer;
alter table mission_missions add column if not exists scenario_names jsonb;
alter table mission_missions add column if not exists halt_event bigint;
alter table mission_missions add column if not exists halt_at_ms bigint;
alter table mission_missions add column if not exists halt_gone jsonb;
alter table mission_missions add column if not exists pause_event bigint;
alter table mission_missions add column if not exists pause_at_ms bigint;
alter table mission_missions add column if not exists pause_reason text;
alter table mission_missions add column if not exists unpause_event bigint;
alter table mission_missions add column if not exists unpause_at_ms bigint;
-- A mission halted before its halt was folded: its latest `mission.halted`.
update mission_missions m
   set halt_event = h.id, halt_at_ms = h.recorded_at_ms,
       halt_gone = case when jsonb_typeof(h.r -> 'gone') = 'array' then h.r -> 'gone' end
  from (select distinct on (e.kind -> 'detail' -> 'record' ->> 'id')
               e.id, e.recorded_at_ms, e.kind -> 'detail' -> 'record' as r
          from spawn_events e
         where e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and e.kind -> 'detail' -> 'record' ->> 'type' = 'mission.halted'
         order by e.kind -> 'detail' -> 'record' ->> 'id', e.id desc) h
 where m.halted is not null and m.halt_event is null and h.r ->> 'id' = m.id::text;
alter table mission_tasks add column if not exists base text;
alter table mission_tasks add column if not exists candidate text;
alter table mission_tasks add column if not exists gate_log text;
alter table mission_tasks add column if not exists metric text;
alter table mission_tasks add column if not exists objective integer;
alter table mission_tasks add column if not exists scenario text;
alter table mission_tasks add column if not exists delivered_at_ms bigint;
-- Work stealing (objective 239): a resident's pool (null: none, it neither
-- takes nor gives a task), from its `resident.proposed`. The task's
-- columns of objective 239 come after the others (below), so a migrated
-- schema keeps a fresh one's column order.
alter table mission_residents add column if not exists pool text;
alter table mission_tasks add column if not exists model text not null default 'default'
    check (model in ('default', 'cheap'));
alter table mission_tasks add column if not exists held_by bigint;
alter table mission_tasks add column if not exists reissue_of bigint;
alter table mission_tasks add column if not exists continues bigint;
alter table mission_tasks add column if not exists reassign_of bigint;
-- The re-judge bound of a load-sensitive regression (sync/design-load-
-- sensitive-bound.md): the task's pushed commit (its branch head, never
-- the merge with main the gate runs) whose gate last said a regression is
-- load-sensitive (gate.sh's `load_sensitive`, recorded as a `host_fault`
-- with evidence `load_sensitive`), every scenario it named across those
-- judgings, and the pushed commit the second one parked (evidence
-- `load_sensitive_parked`): not judged again until a new commit is pushed
-- or a person's `task.released`.
alter table mission_tasks add column if not exists gate_load_sensitive_pushed text;
alter table mission_tasks add column if not exists gate_load_sensitive_scenarios jsonb;
alter table mission_tasks add column if not exists gate_parked_pushed text;
-- Work stealing (objective 239): a task pinned to its worker (`spawn task
-- assign --pin`), from its `task.assigned`; when it last moved (its
-- `task.stolen`), null if never.
alter table mission_tasks add column if not exists pinned boolean not null default false;
alter table mission_tasks add column if not exists stolen_at_ms bigint;
-- Agent grading (docs/agent-grading.md). `difficulty`: the rank the task
-- was assigned at (1 to 3: `l1` to `l3`, `l2` unless the assigner said).
-- `preset_id`: the graded preset it runs on (`grading_presets`; null:
-- assigned without the grading catalog); a `task.rerouted` (rework stepped
-- up to a stronger preset) moves it and `model`. `first_preset_id`: the
-- preset it was first assigned to, set once by its `task.assigned` (a
-- re-issue or reassign carries it) and never moved by a reroute: the
-- preset calibration counts the task for. `quality_rejections`: how many
-- times the task was sent back for its quality, a review's `revise` or a
-- gate's `rejected` (never a gate's `conflict` or `incompatible`, which
-- `revisions` also counts); a re-issue or reassign carries it. Rework
-- steps up and calibration scores first pass on it. Added here only, after
-- every other column, so a migrated table keeps a fresh one's column order.
alter table mission_tasks add column if not exists difficulty smallint not null default 2
    check (difficulty in (1, 2, 3));
alter table mission_tasks add column if not exists preset_id text;
alter table mission_tasks add column if not exists first_preset_id text;
alter table mission_tasks add column if not exists quality_rejections integer not null default 0;
alter table mission_tasks add column if not exists engine text;
alter table mission_tasks add column if not exists model_label text;

-- Agent grading: a grade or difficulty's rank from its wire name (`l1` to
-- `l3`), or from a bare rank (`1` to `3`) as a record might hold it; null
-- for anything else.
create or replace function spawn_grade_rank(p_grade text) returns smallint
language sql immutable as $$
    select case p_grade when 'l1' then 1 when 'l2' then 2 when 'l3' then 3
                        when '1' then 1 when '2' then 2 when '3' then 3 end::smallint
$$;
revoke execute on function spawn_grade_rank(text) from public;

-- The first task states had no landing: a check from then is replaced, once.
do $$
begin
    if not exists (select 1 from pg_constraint
                    where conrelid = 'mission_tasks'::regclass
                      and conname = 'mission_tasks_state_check'
                      and pg_get_constraintdef(oid) like '%''landed''%') then
        alter table mission_tasks drop constraint if exists mission_tasks_state_check;
        alter table mission_tasks add constraint mission_tasks_state_check
            check (state in ('assigned', 'delivered', 'reported', 'revise',
                             'accepted', 'cancelled', 'landing', 'landed'));
    end if;
end
$$;

create index if not exists mission_tasks_agent on mission_tasks (agent_id, id);

-- The grading catalog (docs/agent-grading.md): every graded preset a task
-- may be routed to, its cost rank, state and grades (1 to 3: `l1` to `l3`).
-- The fold of the `grading.recorded` events of the control session (agent
-- `agent_control`, source `control`), outside the control fold: written
-- only by `spawn_grading_apply` in the same transaction as its event
-- (`spawn_grading_record`), rebuilt from them by `spawn_grading_refold`,
-- and never read or cleared by `spawn_control_refold`. Not a
-- `ModelProfile`: `model_profile` is the one it maps to, and in phase 1
-- the only part of it a worker runs on; `engine_label` and `model_label`
-- are labels. `window_start_ms`: where its calibration window starts (the
-- last change of its calibrated or locked grade, or of its state to a
-- routed one); calibration reads only the tasks assigned since.
create table if not exists grading_presets (
    preset_id        text    primary key check (preset_id ~ '^[a-z0-9][a-z0-9_-]{0,63}$'),
    engine_label     text    not null,
    model_label      text    not null,
    model_profile    text    not null check (model_profile in ('default', 'cheap')),
    cost_rank        integer not null check (cost_rank >= 0),
    state            text    not null default 'unexamined'
                     check (state in ('unexamined', 'active', 'demoted', 'disabled')),
    onboarded_grade  smallint check (onboarded_grade in (1, 2, 3)),
    calibrated_grade smallint check (calibrated_grade in (1, 2, 3)),
    locked_grade     smallint check (locked_grade in (1, 2, 3)),
    window_start_ms  bigint  not null,
    created_at_ms    bigint  not null,
    updated_at_ms    bigint  not null,
    last_event       bigint  not null
);

-- Agent grading phase 2: the named execution profile a preset stands for
-- (`opus-max`, `local-qwen`, ...: any name of a preset id's shape but the
-- two model profiles' own), run on `model_profile`; null: its profile is
-- its `model_profile`, as in phase 1. Added here only, so a migrated
-- table keeps a fresh one's column order.
alter table grading_presets add column if not exists execution_profile text
    check (execution_profile ~ '^[a-z0-9][a-z0-9_-]{0,63}$'
           and execution_profile not in ('default', 'cheap'));

-- Calibration's window: the tasks first assigned to a preset, at one
-- difficulty, newest first (spawn-postgres grading.rs `OUTCOMES`).
create index if not exists mission_tasks_first_preset
    on mission_tasks (first_preset_id, difficulty, updated_at_ms)
    where first_preset_id is not null;

-- The owner's holds on mission sources (docs/fleet-architecture.md §10.3,
-- "Landing: the owner's hold"): the fold of `source.held` (keyed by source:
-- a source has at most one active hold, and a new one renews it) less the
-- `source.released` or `source.hold_expired` naming its hold. While a source
-- has a row here, no task lands on it: the integrator reads the row under
-- the landing lock before any push. `hold` is the `source.held` record's
-- event id, `main` the source's main when it was taken, `held_at_ms` its
-- record's time and `expires_ms` that time plus its bound, written into the
-- record by the store. Only a record ends a hold, never the clock.
create table if not exists mission_source_holds (
    source     text   primary key,
    hold       bigint not null,
    main       text   not null,
    by         text   not null,
    reason     text,
    held_at_ms bigint not null,
    expires_ms bigint not null
);

-- The objectives retired by hand (objective 210, GitHub #65): the fold of
-- `objective.retired` (`spawn objective retire`, through
-- spawn_objective_retire), keyed by mission and objective, the first record
-- winning. A retired objective is closed whatever its kind: no task of it
-- is assigned again. `caller` is the login that recorded it (`owner` or
-- `spawn_supervisor`), `event` the record's event id and `at_ms` its time.
create table if not exists mission_retired_objectives (
    mission_id bigint  not null,
    objective  integer not null,
    by         text    not null,
    reason     text    not null,
    caller     text    not null,
    event      bigint  not null,
    at_ms      bigint  not null,
    primary key (mission_id, objective)
);

-- A source whose main is red on a check (docs/fleet-architecture.md §10.3,
-- "Main is red"): the fold of the integrator's `source.main_red` records
-- (keyed by source: a red on a later main moves `main` on, keeping `since_ms`)
-- less the `source.main_green` that ends it. While a source has a row and its
-- main is still `main`, the integrator starts no gate on it but one probe per
-- interval (`source.main_probe`). `event` is the first red record's id,
-- `since_ms` its time, `red_ms` the latest red record's, `probed_ms` the
-- latest probe's; `failures` the latest red record's shared failures and
-- `tasks` the tasks whose gates found it, in order.
create table if not exists mission_source_reds (
    source    text   primary key,
    event     bigint not null,
    main      text   not null,
    scenario  text   not null,
    failures  jsonb  not null,
    since_ms  bigint not null,
    red_ms    bigint not null,
    probed_ms bigint,
    tasks     jsonb  not null default '[]'::jsonb
);

-- What went wrong, in the record (docs/fleet-architecture.md, "Alerts";
-- docs/storage.md, "Alerts"). One row per occurrence, keyed by the key its
-- `alert.fired` and `alert.cleared` records share: an alert fires once and
-- clears at most once, across loop restarts and two loops at once. A notice
-- is a `fired` that never clears. The loop writes the records
-- (`spawn_alert_record`, owner only); the table is their fold, so a
-- restarted loop reads its alerts back and fires nothing twice.
create table if not exists spawn_alerts (
    key              text    primary key,
    kind             text    not null,
    subject          text    not null,
    state            text    not null,
    notice           boolean not null default false,
    text             text,
    evidence         jsonb   not null default '{}'::jsonb,
    fired_event_id   bigint  not null,
    fired_at_ms      bigint  not null,
    cleared_event_id bigint,
    cleared_at_ms    bigint,
    cleared_evidence jsonb
);

create index if not exists spawn_alerts_time on spawn_alerts (fired_at_ms);

-- The owner's judgement of an alert (objective 092, `spawn alert judge`):
-- `right` (a real need, objective 148), `false`, `stale` or `duplicate`,
-- and when. An alert's outcome is its verdict when judged, `cleared` when
-- its condition cleared it, none while open (and for a notice). "Needs you
-- is right" (objective 148) is right over judged, of the needs fired in 7
-- days: a clearing is never evidence.
alter table spawn_alerts add column if not exists verdict text;
alter table spawn_alerts add column if not exists judged_at_ms bigint;

-- When each open agent_stuck alert's session was last scored (its latest
-- judgement carrying `stuck`): the alerts window's `scored_at_ms`, so a
-- score that stands while the judge is down shows its age. A view, read
-- with its owner's rights: a login that may read the alerts (the
-- supervisor's `spawn alerts`) reads it without any grant on spawn_events.
create or replace view spawn_alert_scores as
select a.key,
       (select max(e.recorded_at_ms) from spawn_events e
         where e.session_id = a.subject and e.event_name = 'observation.recorded'
           and e.kind -> 'detail' -> 'observation' ? 'stuck') as scored_at_ms
from spawn_alerts a
where a.kind = 'agent_stuck' and a.state = 'open';

-- What the fleet's model calls cost (objective 041; docs/fleet-architecture.md
-- §3.5): one row per assistant message (the engine's `message.id`), folded by
-- the loop's cost step (`spawn_cost_record`) from the Bridge's `model.usage`
-- events. A message counts once whatever repeats it (its lines, a copy, a
-- restarted loop's read): its largest usage, at its earliest line's time,
-- under its model, for the execution whose transcript first held it, that
-- execution's agent, the task the agent held at the message's time (its
-- latest task assigned at or before it; a message timed before any of them,
-- the latest assigned at or before the execution started; none: no task)
-- and that task's mission. `usd` is priced when the row is recorded, by the
-- rates `rates` names (US dollars per million tokens, SPAWN_MODEL_PRICES):
-- a later price leaves it as it is. Null: the model had no price, and its
-- tokens count as unpriced, never as $0.
create table if not exists spawn_cost_messages (
    message_id         text    primary key,
    execution_id       text    not null,
    agent_id           text    not null,
    session_id         text    not null,
    task_id            bigint,
    mission_id         bigint,
    model              text    not null,
    at_ms              bigint  not null,
    input_tokens       bigint  not null,
    output_tokens      bigint  not null,
    cache_write_tokens bigint  not null,
    cache_read_tokens  bigint  not null,
    usd                numeric,
    rates              jsonb,
    -- The newest `model.usage` event folded into the row, and its time: where
    -- the next fold starts reading (less a margin for a late commit).
    event_id           bigint  not null,
    event_at_ms        bigint  not null,
    recorded_at_ms     bigint  not null
);

create index if not exists spawn_cost_messages_time on spawn_cost_messages (at_ms);
create index if not exists spawn_cost_messages_mission on spawn_cost_messages (mission_id, at_ms);
create index if not exists spawn_cost_messages_event on spawn_cost_messages (event_at_ms);

-- One message's cost at `p_rates` (`{input, output, cache_write, cache_read}`,
-- US dollars per million tokens): each count times its rate over a million,
-- exact. Null when the model has no rates.
create or replace function spawn_cost_usd(p_rates jsonb, p_input bigint, p_output bigint,
                                          p_cache_write bigint, p_cache_read bigint)
returns numeric language sql immutable as $$
    select case when jsonb_typeof(p_rates) = 'object' then
        (p_input * (p_rates ->> 'input')::numeric
         + p_output * (p_rates ->> 'output')::numeric
         + p_cache_write * (p_rates ->> 'cache_write')::numeric
         + p_cache_read * (p_rates ->> 'cache_read')::numeric) / 1000000 end
$$;

-- The loop's cost step (owner only): fold the `model.usage` events not yet
-- folded into `spawn_cost_messages`, pricing each new message by `p_prices`
-- (`{<model>: {input, output, cache_write, cache_read}}`). It reads the
-- events from ten minutes before the newest one already folded, so an event
-- committed late is still read; one read again changes nothing (a message is
-- rewritten only by a larger usage, repriced then, or an earlier time).
-- Returns how many messages it recorded or changed.
create or replace function spawn_cost_record(p_prices jsonb)
returns integer language plpgsql security definer as $$
declare
    v_since bigint;
    v_count integer;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record costs', session_user using errcode = '42501';
    end if;
    if jsonb_typeof(p_prices) is distinct from 'object' then
        raise exception 'the prices are a JSON object, not %', p_prices;
    end if;
    -- The cost record's lock (cost coverage 1b): the engine folds and the
    -- sessions' record commit one after another on every connection, so a
    -- message is never taken by both sides at once.
    perform pg_advisory_xact_lock(1399957341);
    select coalesce(max(event_at_ms), 0) - 600000 into v_since from spawn_cost_messages;
    with fresh as (
        select e.id, e.recorded_at_ms, e.agent_id, e.session_id, e.execution_id,
               d ->> 'message_id' as message_id, d ->> 'model' as model,
               (d ->> 'at_ms')::bigint as at_ms,
               (d ->> 'input_tokens')::bigint as i, (d ->> 'output_tokens')::bigint as o,
               (d ->> 'cache_write_tokens')::bigint as w,
               (d ->> 'cache_read_tokens')::bigint as r
          from spawn_events e
         cross join lateral (select e.kind -> 'detail' as d offset 0) x
         where e.event_name = 'model.usage' and e.recorded_at_ms >= v_since
           and e.execution_id is not null and nullif(d ->> 'message_id', '') is not null
    ), messages as (
        -- The execution whose transcript held it first, its earliest line's
        -- time and model, its largest usage.
        select b.message_id, f.execution_id, f.agent_id, f.session_id, t.model, t.at_ms,
               b.i, b.o, b.w, b.r, g.event_id, g.event_at_ms
          from (select distinct on (message_id) message_id, i, o, w, r
                  from fresh order by message_id, i + o + w + r desc, id) b
          join (select distinct on (message_id) message_id, execution_id, agent_id, session_id
                  from fresh order by message_id, id) f using (message_id)
          join (select distinct on (message_id) message_id, model, at_ms
                  from fresh order by message_id, at_ms, id) t using (message_id)
          join (select message_id, max(id) as event_id, max(recorded_at_ms) as event_at_ms
                  from fresh group by message_id) g using (message_id)
    ), changed as (
        select m.*
          from messages m
          left join spawn_cost_messages c on c.message_id = m.message_id
         where c.message_id is null
            or m.i + m.o + m.w + m.r
               > c.input_tokens + c.output_tokens + c.cache_write_tokens + c.cache_read_tokens
            or m.at_ms < c.at_ms
    ), placed as (
        select m.*, t.task_id, k.mission_id, p_prices -> m.model as rates
          from changed m
         cross join lateral (
               select coalesce(
                   (select k.id from mission_tasks k
                     where k.agent_id = m.agent_id and k.created_at_ms <= m.at_ms
                     order by k.created_at_ms desc, k.id desc limit 1),
                   (select k.id from mission_tasks k
                     where k.agent_id = m.agent_id
                       and k.created_at_ms <= (
                           select min(s.recorded_at_ms) from spawn_events s
                            where s.session_id = m.session_id
                              and s.event_name = 'execution.started'
                              and s.execution_id = m.execution_id)
                     order by k.created_at_ms desc, k.id desc limit 1)) as task_id) t
          left join mission_tasks k on k.id = t.task_id
    ), upserted as (
    insert into spawn_cost_messages as c
        (message_id, execution_id, agent_id, session_id, task_id, mission_id, model, at_ms,
         input_tokens, output_tokens, cache_write_tokens, cache_read_tokens, usd, rates,
         event_id, event_at_ms, recorded_at_ms)
    select p.message_id, p.execution_id, p.agent_id, p.session_id, p.task_id, p.mission_id,
           p.model, p.at_ms, p.i, p.o, p.w, p.r,
           spawn_cost_usd(p.rates, p.i, p.o, p.w, p.r),
           p.rates, p.event_id, p.event_at_ms, spawn_now_ms()
      from placed p
    on conflict (message_id) do update set
        at_ms = least(c.at_ms, excluded.at_ms),
        event_id = greatest(c.event_id, excluded.event_id),
        event_at_ms = greatest(c.event_at_ms, excluded.event_at_ms),
        input_tokens = case when (excluded.input_tokens + excluded.output_tokens + excluded.cache_write_tokens
                 + excluded.cache_read_tokens
                 > c.input_tokens + c.output_tokens + c.cache_write_tokens + c.cache_read_tokens)
            then excluded.input_tokens else c.input_tokens end,
        output_tokens = case when (excluded.input_tokens + excluded.output_tokens + excluded.cache_write_tokens
                 + excluded.cache_read_tokens
                 > c.input_tokens + c.output_tokens + c.cache_write_tokens + c.cache_read_tokens)
            then excluded.output_tokens else c.output_tokens end,
        cache_write_tokens = case when (excluded.input_tokens + excluded.output_tokens + excluded.cache_write_tokens
                 + excluded.cache_read_tokens
                 > c.input_tokens + c.output_tokens + c.cache_write_tokens + c.cache_read_tokens)
            then excluded.cache_write_tokens else c.cache_write_tokens end,
        cache_read_tokens = case when (excluded.input_tokens + excluded.output_tokens + excluded.cache_write_tokens
                 + excluded.cache_read_tokens
                 > c.input_tokens + c.output_tokens + c.cache_write_tokens + c.cache_read_tokens)
            then excluded.cache_read_tokens else c.cache_read_tokens end,
        usd = case when (excluded.input_tokens + excluded.output_tokens + excluded.cache_write_tokens
                 + excluded.cache_read_tokens
                 > c.input_tokens + c.output_tokens + c.cache_write_tokens + c.cache_read_tokens)
            then excluded.usd else c.usd end,
        rates = case when (excluded.input_tokens + excluded.output_tokens + excluded.cache_write_tokens
                 + excluded.cache_read_tokens
                 > c.input_tokens + c.output_tokens + c.cache_write_tokens + c.cache_read_tokens)
            then excluded.rates else c.rates end,
        recorded_at_ms = case when (excluded.input_tokens + excluded.output_tokens + excluded.cache_write_tokens
                 + excluded.cache_read_tokens
                 > c.input_tokens + c.output_tokens + c.cache_write_tokens + c.cache_read_tokens)
            then excluded.recorded_at_ms else c.recorded_at_ms end
    returning c.message_id
    ), dropped as (
        -- A message an engine's record now holds is the engines' (cost
        -- coverage R2): the sessions' copy, counted first when their pass
        -- read the transcript before this fold, goes, so no message counts
        -- twice. Only this call's messages: an index lookup each.
        delete from spawn_cost_session_messages s
         where s.message_id in (select message_id from upserted)
        returning 1
    )
    select count(*) into v_count from upserted;
    return v_count;
end $$;

-- The transcript archive's part of the cost record (objective 048): the
-- messages of executions the cost step never read (they ended before 041,
-- or their `model.usage` events are gone) are counted from the archive
-- (`<root>/.transcripts/<agent>/<native>[.<n>].jsonl`) each time the loop
-- starts. Each archive file it counted, with its length and modification
-- time then: a file the same as it was is not read again.
create table if not exists spawn_cost_archive_files (
    agent_id      text   not null,
    file          text   not null,
    length        bigint not null,
    modified_ms   bigint not null,
    counted_at_ms bigint not null,
    primary key (agent_id, file)
);

-- The archive's messages into the cost record (owner only): `p_messages`,
-- `[{agent_id, message_id, model, at_ms, input, output, cache_write,
-- cache_read}]`, each message once (the caller folds its lines and copies
-- by 041's rules: its largest usage, its earliest line's time and model).
-- A message counts for the agent whose archive holds it, that agent's
-- execution running at its time (the latest started at or before it; a
-- message timed before all of them, the agent's first), the task the agent
-- held then (its latest task assigned at or before the message; a message
-- timed before any, the latest assigned at or before that execution
-- started; none: no task) and that task's mission, priced by `p_prices` as
-- `spawn_cost_record` prices. A message the record already holds keeps what
-- it holds; one of an agent with no execution is not counted. The row's
-- event mark is 0, so the cost step's fold still starts where it did.
-- Returns `{counted, unplaced}`: the messages it added, and those of
-- agents with no execution.
create or replace function spawn_cost_archive_record(p_prices jsonb, p_messages jsonb)
returns jsonb language plpgsql security definer as $$
declare
    v_counted bigint;
    v_unplaced bigint;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record costs', session_user using errcode = '42501';
    end if;
    if jsonb_typeof(p_prices) is distinct from 'object' then
        raise exception 'the prices are a JSON object, not %', p_prices;
    end if;
    if jsonb_typeof(p_messages) is distinct from 'array' then
        raise exception 'the messages are a JSON array, not %', p_messages;
    end if;
    -- The cost record's lock (cost coverage 1b): the engine folds and the
    -- sessions' record commit one after another on every connection, so a
    -- message is never taken by both sides at once.
    perform pg_advisory_xact_lock(1399957341);
    with given as (
        select distinct on (x.message_id) x.*
          from jsonb_to_recordset(p_messages)
               as x(agent_id text, message_id text, model text, at_ms bigint,
                    input bigint, output bigint, cache_write bigint, cache_read bigint)
         where nullif(x.message_id, '') is not null and nullif(x.agent_id, '') is not null
           and nullif(x.model, '') is not null and x.at_ms is not null
         order by x.message_id, x.at_ms
    ), placed as (
        select g.*, e.execution_id, e.session_id, e.started_at_ms
          from given g
         cross join lateral (
               select u.execution_id, u.session_id, u.started_at_ms
                 from ((select s.execution_id, s.session_id, s.recorded_at_ms as started_at_ms,
                               1 as rank
                          from spawn_events s
                         where s.agent_id = g.agent_id and s.event_name = 'execution.started'
                           and s.execution_id is not null and s.recorded_at_ms <= g.at_ms
                         order by s.recorded_at_ms desc, s.id desc limit 1)
                       union all
                       (select s.execution_id, s.session_id, s.recorded_at_ms, 2
                          from spawn_events s
                         where s.agent_id = g.agent_id and s.event_name = 'execution.started'
                           and s.execution_id is not null
                         order by s.recorded_at_ms, s.id limit 1)) u
                order by u.rank limit 1) e
    ), tasked as (
        select p.*, t.task_id, k.mission_id, p_prices -> p.model as rates
          from placed p
         cross join lateral (
               select coalesce(
                   (select k.id from mission_tasks k
                     where k.agent_id = p.agent_id and k.created_at_ms <= p.at_ms
                     order by k.created_at_ms desc, k.id desc limit 1),
                   (select k.id from mission_tasks k
                     where k.agent_id = p.agent_id and k.created_at_ms <= p.started_at_ms
                     order by k.created_at_ms desc, k.id desc limit 1)) as task_id) t
          left join mission_tasks k on k.id = t.task_id
    ), added as (
        insert into spawn_cost_messages
            (message_id, execution_id, agent_id, session_id, task_id, mission_id, model, at_ms,
             input_tokens, output_tokens, cache_write_tokens, cache_read_tokens, usd, rates,
             event_id, event_at_ms, recorded_at_ms)
        select t.message_id, t.execution_id, t.agent_id, t.session_id, t.task_id, t.mission_id,
               t.model, t.at_ms, coalesce(t.input, 0), coalesce(t.output, 0),
               coalesce(t.cache_write, 0), coalesce(t.cache_read, 0),
               spawn_cost_usd(t.rates, coalesce(t.input, 0), coalesce(t.output, 0),
                              coalesce(t.cache_write, 0), coalesce(t.cache_read, 0)),
               t.rates, 0, 0, spawn_now_ms()
          from tasked t
        on conflict (message_id) do nothing
        returning message_id
    ), dropped as (
        -- As in spawn_cost_record: the engines' record holds it now, so the
        -- sessions' copy goes (cost coverage R2).
        delete from spawn_cost_session_messages s
         where s.message_id in (select message_id from added)
        returning 1
    )
    select (select count(*) from added),
           (select count(*) from given) - (select count(*) from placed)
      into v_counted, v_unplaced;
    return jsonb_build_object('counted', v_counted, 'unplaced', v_unplaced);
end $$;


-- The other Claude Code sessions on this host (cost coverage, lead's scope
-- OK 2026-11-17 16:39): the people's and reviewers' sessions, whose model
-- calls no engine's `model.usage` event carries. Counted from Claude Code's
-- own transcripts (`~/.claude/projects/<project>/<session>.jsonl`, read
-- only, appended bytes only) and KEPT APART from `spawn_cost_messages`: no
-- engine figure (the window's total, a mission, dollars per landing, U3)
-- changes. One row per assistant message (`message.id`), by 041's rules:
-- its largest usage, at its earliest line's time, under that line's model;
-- priced when it is recorded. `project` is the project directory's name
-- alone (no other path, no message text, no tool input is stored).
create table if not exists spawn_cost_session_messages (
    message_id         text    primary key,
    project            text    not null,
    session_id         text    not null,
    model              text    not null,
    at_ms              bigint  not null,
    input_tokens       bigint  not null,
    output_tokens      bigint  not null,
    cache_write_tokens bigint  not null,
    cache_read_tokens  bigint  not null,
    usd                numeric,
    rates              jsonb,
    recorded_at_ms     bigint  not null
);

create index if not exists spawn_cost_session_messages_time on spawn_cost_session_messages (at_ms);

-- Each transcript file the sessions' count read, and how far: `file` is
-- `<project>/<session>.jsonl`, `offset_bytes` the end of its last whole
-- line read, with the file's inode, length and modification time then. The
-- next count reads from that offset only; a file whose inode changed or
-- that is now shorter than the offset is read from 0 once.
create table if not exists spawn_cost_session_files (
    file          text   primary key,
    inode         bigint not null,
    offset_bytes  bigint not null check (offset_bytes >= 0),
    length        bigint not null check (length >= 0),
    modified_ms   bigint not null,
    read_at_ms    bigint not null
);

-- The sessions' messages and how far their files were read, in one
-- transaction (owner only), so a mark never runs ahead of what it counted:
-- `p_messages` `[{project, session_id, message_id, model, at_ms, input,
-- output, cache_write, cache_read}]`, `p_files` `[{file, inode,
-- offset_bytes, length, modified_ms}]`. Lines of one message in one call are
-- folded by 041's rules: its largest usage, at its earliest line's time,
-- under that line's model, project and session. A message an engine's
-- record already holds (`spawn_cost_messages`) is not counted again, and a
-- copy of it held here goes; an engine fold that takes one later removes
-- it from here too, so no message counts twice. One already held
-- here keeps its model and takes a larger usage, repriced by `p_prices`
-- under that model; a smaller or equal usage never replaces it; an earlier
-- time moves its time and nothing else. A line without a message id,
-- project, session, model or time is not counted (`invalid`: the caller
-- decides what its mark then means). Returns `{counted, changed, engine,
-- invalid}`: messages added, held messages that grew or moved earlier,
-- messages left to the engines' record, lines not counted.
create or replace function spawn_cost_session_record(p_prices jsonb, p_messages jsonb,
                                                     p_files jsonb)
returns jsonb language plpgsql security definer as $$
declare
    v_counted bigint;
    v_changed bigint;
    v_engine bigint;
    v_invalid bigint;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record costs', session_user using errcode = '42501';
    end if;
    if jsonb_typeof(p_prices) is distinct from 'object' then
        raise exception 'the prices are a JSON object, not %', p_prices;
    end if;
    if jsonb_typeof(p_messages) is distinct from 'array'
       or jsonb_typeof(p_files) is distinct from 'array' then
        raise exception 'the messages and the files are JSON arrays';
    end if;
    -- The cost record's lock (cost coverage 1b): the engine folds and the
    -- sessions' record commit one after another on every connection, so a
    -- message is never taken by both sides at once.
    perform pg_advisory_xact_lock(1399957341);
    with lines as (
        select x.project, x.session_id, x.message_id, x.model, x.at_ms,
               coalesce(x.input, 0) as input, coalesce(x.output, 0) as output,
               coalesce(x.cache_write, 0) as cache_write, coalesce(x.cache_read, 0) as cache_read,
               coalesce(x.input, 0) + coalesce(x.output, 0) + coalesce(x.cache_write, 0)
                 + coalesce(x.cache_read, 0) as total
          from jsonb_to_recordset(p_messages)
               as x(project text, session_id text, message_id text, model text, at_ms bigint,
                    input bigint, output bigint, cache_write bigint, cache_read bigint)
         where nullif(x.message_id, '') is not null and nullif(x.project, '') is not null
           and nullif(x.session_id, '') is not null and nullif(x.model, '') is not null
           and x.at_ms is not null
    ), given as (
        -- 041's fold of one call's lines: the largest usage, and the
        -- earliest line's time, model, project and session.
        select t.message_id, t.project, t.session_id, t.model, t.at_ms,
               b.input, b.output, b.cache_write, b.cache_read, b.total
          from (select distinct on (message_id) message_id, project, session_id, model, at_ms
                  from lines order by message_id, at_ms, total desc) t
          join (select distinct on (message_id) message_id, input, output, cache_write,
                       cache_read, total
                  from lines order by message_id, total desc, at_ms) b using (message_id)
    ), engine as (
        select g.message_id from given g
         where exists (select 1 from spawn_cost_messages c where c.message_id = g.message_id)
    ), yielded as (
        -- Held here but in an engine's record now (a fold on another
        -- connection that raced this one): the engines' alone.
        delete from spawn_cost_session_messages s
         where s.message_id in (select message_id from engine)
        returning 1
    ), held as (
        select h.message_id, h.at_ms,
               h.input_tokens + h.output_tokens + h.cache_write_tokens + h.cache_read_tokens
                 as total
          from spawn_cost_session_messages h
         where h.message_id in (select message_id from given)
           and h.message_id not in (select message_id from engine)
    ), added as (
        insert into spawn_cost_session_messages
            (message_id, project, session_id, model, at_ms, input_tokens, output_tokens,
             cache_write_tokens, cache_read_tokens, usd, rates, recorded_at_ms)
        select g.message_id, g.project, g.session_id, g.model, g.at_ms,
               g.input, g.output, g.cache_write, g.cache_read,
               spawn_cost_usd(p_prices -> g.model, g.input, g.output, g.cache_write,
                              g.cache_read),
               p_prices -> g.model, spawn_now_ms()
          from given g
         where g.message_id not in (select message_id from engine)
           and g.message_id not in (select message_id from held)
        on conflict (message_id) do nothing
        returning 1
    ), grown as (
        -- A larger usage replaces the held one, priced under the held
        -- model; an earlier time moves the time alone.
        update spawn_cost_session_messages m
           set input_tokens = case when g.total > h.total then g.input else m.input_tokens end,
               output_tokens = case when g.total > h.total then g.output else m.output_tokens end,
               cache_write_tokens = case when g.total > h.total then g.cache_write
                                         else m.cache_write_tokens end,
               cache_read_tokens = case when g.total > h.total then g.cache_read
                                        else m.cache_read_tokens end,
               usd = case when g.total > h.total
                          then spawn_cost_usd(p_prices -> m.model, g.input, g.output,
                                              g.cache_write, g.cache_read)
                          else m.usd end,
               rates = case when g.total > h.total then p_prices -> m.model else m.rates end,
               at_ms = least(m.at_ms, g.at_ms),
               recorded_at_ms = spawn_now_ms()
          from given g join held h on h.message_id = g.message_id
         where m.message_id = g.message_id and (g.total > h.total or g.at_ms < h.at_ms)
        returning 1
    ), marked as (
        insert into spawn_cost_session_files
            (file, inode, offset_bytes, length, modified_ms, read_at_ms)
        select f.file, f.inode, f.offset_bytes, f.length, f.modified_ms, spawn_now_ms()
          from jsonb_to_recordset(p_files)
               as f(file text, inode bigint, offset_bytes bigint, length bigint,
                    modified_ms bigint)
         where nullif(f.file, '') is not null and f.inode is not null
           and f.offset_bytes is not null and f.length is not null and f.modified_ms is not null
        on conflict (file) do update
           set inode = excluded.inode, offset_bytes = excluded.offset_bytes,
               length = excluded.length, modified_ms = excluded.modified_ms,
               read_at_ms = excluded.read_at_ms
        returning 1
    )
    -- `marked` runs whether read or not (a data-modifying WITH always does).
    select (select count(*) from added), (select count(*) from grown),
           (select count(*) from engine),
           jsonb_array_length(p_messages) - (select count(*) from lines)
      into v_counted, v_changed, v_engine, v_invalid;
    return jsonb_build_object('counted', v_counted, 'changed', v_changed, 'engine', v_engine,
                              'invalid', v_invalid);
end $$;

-- Who may call the mission functions: the owner (humans' CLI, the
-- controller) and the supervisor's login; not the reader's, and not the web
-- page's typing login (`human`, which may only call `spawn_human_input`,
-- `spawn_human_key`, `spawn_human_task`, `spawn_human_resume` and
-- `spawn_human_master_message`).
create or replace function spawn_mission_caller() returns text
language sql stable as $$
    select case when x.p is null or x.p in ('spawn_reader', 'human') then null
                -- The node gateway's login (spawn-node v1) calls only its
                -- four spawn_node_gw_* functions, and is nobody here.
                when x.p = spawn_login_role('spawn_node_gateway') then null
                when x.p = 'spawn_supervisor' then 'spawn_supervisor'
                else 'owner' end
      from (select spawn_principal() as p) x
$$;

-- The commit map of a history rewrite (objective 173). The owner rewrites
-- the history of a source (git filter-repo: every changed commit gets a new
-- id) while the event log keeps the old ids, so every reader that compares
-- a recorded id with git reads it through the map: `spawn commit-map load`
-- loads filter-repo's commit-map once (`spawn_commit_map_load`, owner only),
-- and `spawn_commit_now` reads a recorded id as the commit it is now. `old`
-- is the commit before the rewrite, `new` the one after it (null: the
-- rewrite dropped it). The map is never changed: a statement trigger
-- refuses every update, delete and truncate, and a load is either the
-- first or exactly the pairs loaded already.
create table if not exists spawn_commit_map (
    old text collate "C" primary key check (old ~ '^[0-9a-f]{40}$'),
    new text collate "C" check (new ~ '^[0-9a-f]{40}$')
);
revoke all on spawn_commit_map from public;
-- Byte order, not the database's locale (objective 190): the ids are hex,
-- and comparing them through the locale (strcoll) was most of a lookup's
-- cost. A map made before is altered once; its rows stay as they are.
do $$
begin
    if exists (select 1 from pg_attribute a
                where a.attrelid = 'spawn_commit_map'::regclass and a.attname in ('old', 'new')
                  and a.attcollation <> (select oid from pg_collation where collname = 'C'
                                                                        and collnamespace = 'pg_catalog'::regnamespace)) then
        alter table spawn_commit_map alter column old type text collate "C",
                                     alter column new type text collate "C";
    end if;
end
$$;

create or replace function spawn_commit_map_unchanged() returns trigger
language plpgsql as $$
begin
    raise exception 'the commit map is never changed (objective 173): % refused', lower(tg_op)
        using errcode = '42501';
end $$;
drop trigger if exists spawn_commit_map_unchanged on spawn_commit_map;
create trigger spawn_commit_map_unchanged
    before update or delete or truncate on spawn_commit_map
    for each statement execute function spawn_commit_map_unchanged();
revoke execute on function spawn_commit_map_unchanged() from public;

-- A recorded commit id as the commit it is now: the map's `new` for an id
-- the map names (any case; null for a dropped commit), otherwise the id
-- itself. Null stays null. Every reader and fold that compares a recorded
-- id (a baseline, a base, a request's commit, a move's from and to) reads
-- it through this, both sides alike.
--
-- Fast (objective 190): SECURITY DEFINER with a SET clause cost about
-- 5.5 us a call on live. It is plpgsql run with the caller's rights and
-- no SET clause, its plan kept per session; the map is named with this
-- schema when it is made, so no caller's search_path reads another table.
-- `spawn_commit_now_rows` is the same translation as an SQL set-returning
-- function, which PostgreSQL inlines into a caller that joins it LATERAL
-- (an index scan on the map per row, no call): the polled readers use it.
-- (A scalar SQL function with a subquery is never inlined.) The callers
-- read the map with their own rights: the owner, and the restricted logins
-- granted SELECT on it. The map stays insert-once and owner-only: only
-- `spawn_commit_map_load` writes it.
do $$
begin
    execute format($f$
create or replace function spawn_commit_now(p_commit text) returns text
language plpgsql stable as $b$
declare
    v_known boolean;
    v_new text;
begin
    select true, m.new into v_known, v_new from %1$I.spawn_commit_map m where m.old = lower(p_commit);
    return case when v_known then v_new else p_commit end;
end
$b$
$f$, current_schema());
    execute format($f$
create or replace function spawn_commit_now_rows(p_commit text) returns table (now text)
language sql stable as $b$
    select case when count(*) = 0 then p_commit else max(m.new) end
      from %1$I.spawn_commit_map m
     where m.old = lower(p_commit)
$b$
$f$, current_schema());
    -- Not public's (the gateway's ACL holds no store reader): the restricted
    -- logins read recorded commits through them as the owner does.
    execute 'revoke execute on function spawn_commit_now(text) from public';
    execute 'revoke execute on function spawn_commit_now_rows(text) from public';
    execute format('grant execute on function spawn_commit_now(text), spawn_commit_now_rows(text) to %I, %I',
                   spawn_login_role('spawn_supervisor'), spawn_login_role('spawn_reader'));
    execute format('grant select on spawn_commit_map to %I, %I',
                   spawn_login_role('spawn_supervisor'), spawn_login_role('spawn_reader'));
end
$$;

-- Load filter-repo's commit map (owner only): `p_pairs` a non-empty array
-- of `[old, new]` pairs, each old 40 hex characters, each new 40 hex or null
-- (a dropped commit), no old twice. On an empty map it inserts them and
-- returns how many; given exactly the pairs loaded already it returns that
-- count and changes nothing; any other map is refused: a map is loaded once
-- and never changed. The table is locked, so two loads never both insert.
create or replace function spawn_commit_map_load(p_pairs jsonb) returns integer
language plpgsql security definer as $$
declare
    v_loaded integer;
    v_given integer;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner loads the commit map' using errcode = '42501';
    end if;
    if jsonb_typeof(p_pairs) is distinct from 'array' or jsonb_array_length(p_pairs) = 0 then
        raise exception 'a commit map is a non-empty array of [old, new] pairs';
    end if;
    if exists (select 1 from jsonb_array_elements(p_pairs) p
                where jsonb_typeof(p) is distinct from 'array'
                   or jsonb_array_length(p) <> 2
                   or jsonb_typeof(p -> 0) is distinct from 'string'
                   or lower(p ->> 0) !~ '^[0-9a-f]{40}$'
                   or (jsonb_typeof(p -> 1) is distinct from 'null'
                       and (jsonb_typeof(p -> 1) is distinct from 'string'
                            or lower(p ->> 1) !~ '^[0-9a-f]{40}$'))) then
        raise exception 'a commit map pair is [old, new]: old 40 hex characters, new 40 hex characters or null (a dropped commit)';
    end if;
    if (select count(distinct lower(p ->> 0)) from jsonb_array_elements(p_pairs) p)
       <> jsonb_array_length(p_pairs) then
        raise exception 'a commit map names each old commit once';
    end if;
    lock table spawn_commit_map in exclusive mode;
    v_given := jsonb_array_length(p_pairs);
    select count(*) into v_loaded from spawn_commit_map;
    if v_loaded = 0 then
        insert into spawn_commit_map (old, new)
        select lower(p ->> 0), lower(p ->> 1) from jsonb_array_elements(p_pairs) p;
        return v_given;
    end if;
    if v_loaded = v_given
       and not exists (select 1 from jsonb_array_elements(p_pairs) p
                        where not exists (select 1 from spawn_commit_map m
                                           where m.old = lower(p ->> 0)
                                             and m.new is not distinct from lower(p ->> 1))) then
        return v_loaded;
    end if;
    raise exception 'a different commit map is loaded (% pairs): a map is loaded once and never changed',
                    v_loaded;
end $$;
do $$
begin
    execute format('alter function spawn_commit_map_load(jsonb) set search_path = %I, pg_temp',
                   current_schema());
    execute 'revoke execute on function spawn_commit_map_load(jsonb) from public';
end
$$;

-- Closure: whether a task may be in `p_state`, given its mission's state,
-- whether the mission has a gate, and its resident's state (null for an
-- ephemeral worker). The one rule that closing a mission, retiring a
-- resident, the integrator's selection (the `GATED` query) and every task
-- transition follow:
-- - a closed state (cancelled, landed, accepted without a gate) always holds;
-- - an open mission's task, with a worker that is not retired, may be in any;
-- - a done mission with a gate takes in the work already handed out, and
--   asks nothing new of a worker: delivered (its report still comes),
--   reported (judged by the gate or reviewed), accepted and landing;
-- - a retired resident's work goes on only where it needs nothing more from
--   the worker: accepted and landing, for a mission with a gate that is not
--   dropped;
-- - a dropped mission's work goes on in no state.
-- Anything else is cancelled when the mission closes or the resident
-- retires, and no transition moves a task into it.
create or replace function spawn_task_may_continue(p_state text, p_mission_state text,
                                                   p_gated boolean, p_resident_state text)
returns boolean language sql immutable as $$
    select p_state in ('cancelled', 'landed')
        or (p_state = 'accepted' and not p_gated)
        or (p_mission_state in ('open', 'active') and p_resident_state is distinct from 'retired')
        or (p_gated and p_mission_state <> 'dropped' and p_state in ('accepted', 'landing'))
        or (p_gated and p_mission_state = 'done' and p_state in ('delivered', 'reported')
            and p_resident_state is distinct from 'retired')
$$;

-- Whether task `p_task` may move to `p_to` under the closure rule: its
-- current state and `p_to` both hold. False for a task that does not exist.
create or replace function spawn_task_may_move(p_task bigint, p_to text)
returns boolean language sql stable as $$
    select coalesce((
        select spawn_task_may_continue(k.state, m.state, m.gate is not null, r.state)
               and spawn_task_may_continue(p_to, m.state, m.gate is not null, r.state)
          from mission_tasks k
          join mission_missions m on m.id = k.mission_id
          left join mission_residents r on r.agent_id = k.agent_id
         where k.id = p_task), false)
$$;

-- The control stream (docs/fleet-architecture.md §10.1). Every change to a
-- mission, task or resident is one `control.recorded` event of session
-- `session_control`; the `mission_*` tables are its fold, written only by
-- `spawn_control_apply`, in the same transaction as the event. The checked
-- functions below validate against the tables, then record. Applying a
-- record never validates: the log is the truth, and replaying it must give
-- the same tables. `p_at` is the record's time and `p_event` its event's id
-- (a hold is named by its `source.held` event).
drop function if exists spawn_control_apply(jsonb, bigint);
create or replace function spawn_control_apply(p_record jsonb, p_at bigint, p_event bigint)
returns void language plpgsql as $$
declare
    v_type text := p_record ->> 'type';
    v_id bigint := (p_record ->> 'id')::bigint;
    v_accepted boolean;
    v_verdict text;
    v_mission bigint;
    v_accept text;
begin
    case v_type
    when 'mission.added' then
        insert into mission_missions (id, text, origin, sources, created_at_ms, updated_at_ms)
        values (v_id, p_record ->> 'text', p_record ->> 'origin',
                coalesce(p_record -> 'sources', '[]'::jsonb), p_at, p_at);
    when 'mission.closed' then
        update mission_missions set state = p_record ->> 'state', summary = p_record ->> 'summary',
                                    updated_at_ms = p_at
         where id = v_id;
        -- Its work that the closure rule does not let go on is dropped.
        update mission_tasks k set state = 'cancelled', updated_at_ms = p_at
          from mission_missions m
         where m.id = k.mission_id and k.mission_id = v_id
           and not spawn_task_may_continue(k.state, m.state, m.gate is not null,
                   (select r.state from mission_residents r where r.agent_id = k.agent_id));
    when 'task.assigned' then
        insert into mission_tasks (id, mission_id, kind, agent_id, session_id, brief,
                                   created_by, objective, scenario, model, reissue_of,
                                   continues, reassign_of, pinned, difficulty, preset_id,
                                   first_preset_id, quality_rejections, engine, model_label,
                                   created_at_ms, updated_at_ms)
        values (v_id, (p_record ->> 'mission_id')::bigint, p_record ->> 'kind',
                p_record ->> 'agent_id', p_record ->> 'session_id', p_record ->> 'brief',
                p_record ->> 'created_by', (p_record ->> 'objective')::integer,
                p_record ->> 'scenario', coalesce(p_record ->> 'model', 'default'),
                (p_record ->> 'reissue_of')::bigint, (p_record ->> 'continues')::bigint,
                (p_record ->> 'reassign_of')::bigint,
                coalesce((p_record ->> 'pinned')::boolean, false),
                -- Agent grading: a record from before it, or assigned
                -- without the catalog, names none of these (`l2`, no
                -- preset, no rejection). A re-issue or reassign names
                -- `first_preset_id` when it is not its `preset_id`, and
                -- the rejections it carries.
                coalesce(spawn_grade_rank(p_record ->> 'difficulty'), 2),
                p_record ->> 'preset_id',
                coalesce(p_record ->> 'first_preset_id', p_record ->> 'preset_id'),
                coalesce((p_record ->> 'quality_rejections')::integer, 0),
                p_record ->> 'engine',
                p_record ->> 'model_label',
                p_at, p_at);
        update mission_missions set state = 'active', updated_at_ms = p_at
         where id = (p_record ->> 'mission_id')::bigint and state = 'open';
    when 'mission.configured' then
        update mission_missions set gate = p_record ->> 'gate', accept = p_record ->> 'accept',
                                    budget = p_record -> 'budget',
                                    objectives = p_record -> 'objectives', updated_at_ms = p_at
         where id = v_id;
    when 'mission.halted' then
        -- The halt the mission is in: this record, and the scenarios it
        -- names gone (a halt on the scenario floor).
        update mission_missions set halted = p_record ->> 'reason', halt_event = p_event,
                                    halt_at_ms = p_at,
                                    halt_gone = case when jsonb_typeof(p_record -> 'gone') = 'array'
                                                     then p_record -> 'gone' end,
                                    updated_at_ms = p_at
         where id = v_id;
    when 'mission.resumed' then
        -- The next gate records the source's main as the new baseline, and
        -- the scenario count as the new floor: a human who resumes has seen
        -- the scenarios as they are (only the owner changes them).
        -- The owner's resume and a person's from the page
        -- (`spawn_human_resume`, `by` human, naming its `halt`) fold alike.
        update mission_missions set halted = null, baseline = null, gate_rejections = 0,
                                    gate_aborts = 0, scenario_floor = 0, scenario_names = null,
                                    halt_event = null, halt_at_ms = null, halt_gone = null,
                                    gate_room_task = null,
                                    gate_room_since_ms = null,
                                    gate_room_last_ms = null, gate_room_waits = 0,
                                    gate_room_escalated = false, gate_host_faults = 0,
                                    gate_host_task = null, gate_host_due_ms = null,
                                    gate_base_disagrees = 0, gate_rejection_objective = null,
                                    updated_at_ms = p_at
         where id = v_id;
    when 'mission.paused' then
        -- The owner holds the mission (`spawn_mission_pause`): the pause it
        -- is in is this record. Its halt, if any, stays as it is.
        update mission_missions set pause_event = p_event, pause_at_ms = p_at,
                                    pause_reason = p_record ->> 'reason',
                                    unpause_event = null, unpause_at_ms = null,
                                    updated_at_ms = p_at
         where id = v_id;
    when 'mission.unpaused' then
        -- The owner's resume of a paused mission: it clears the pause alone
        -- (a halt stays, for a second resume).
        update mission_missions set pause_event = null, pause_at_ms = null, pause_reason = null,
                                    unpause_event = p_event, unpause_at_ms = p_at,
                                    updated_at_ms = p_at
         where id = v_id;
    when 'source.moved' then
        -- The owner moved a source's main on purpose: a deploy behind
        -- Spawn's back (`spawn mission moved`), forward from where the last
        -- landing left it, or the integrator's landing of the owner's
        -- request (`spawn mission push`; the record names the `request`):
        -- the missions on that source take the new main as their baseline
        -- instead of halting at the next pass. The record names them (never
        -- a halted one, unless its halt was this very move: `clear`); a
        -- record from before it did moved every mission on the source at
        -- that baseline.
        -- The integrator's landing of an owner's request (it names the
        -- `request`) is the owner changing the scenario set, as a resume is
        -- (P28): the missions it moves take the scenarios as they are after
        -- it, so the floor starts again (0, no names) and their next gate sets
        -- it. The floor guards against a task's candidate deleting its judge:
        -- an owner's retirement of scenarios is not one, and halted every
        -- mission on the source at its next pass. A task judging does not
        -- start on a main ahead of its controller (P22's controller_behind),
        -- so the next gate counts the deployed scenarios. A move with no
        -- request (`spawn mission moved`) keeps the floor.
        update mission_missions set baseline = p_record ->> 'to', updated_at_ms = p_at,
                                    scenario_floor = case when p_record ? 'request' then 0
                                                          else scenario_floor end,
                                    scenario_names = case when p_record ? 'request' then null
                                                          else scenario_names end
         where sources ->> 0 = p_record ->> 'source'
           -- Both read through the commit map (objective 173): a baseline
           -- recorded before a history rewrite is the commit it is now.
           and spawn_commit_now(baseline) = spawn_commit_now(p_record ->> 'from')
           and (p_record -> 'missions' is null
                or id in (select m::bigint
                            from jsonb_array_elements_text(p_record -> 'missions') m));
        -- The `clear` list: missions whose only halt was the integrator's
        -- reading of this very move (main away from their baseline with no
        -- record). The owner's record is that explanation, so they are not
        -- halted any more and are judged again at the next pass.
        update mission_missions set halted = null, halt_event = null, halt_at_ms = null,
                                    halt_gone = null, updated_at_ms = p_at
         where jsonb_typeof(p_record -> 'clear') = 'array'
           and id in (select m::bigint
                        from jsonb_array_elements_text(p_record -> 'clear') m);
        -- An owner's landing also names the missions on the source with no
        -- baseline yet (new, or resumed), not halted: they take the new main
        -- as their first baseline, so a gate of theirs that was judging
        -- against the old main when it landed does not leave them at it.
        update mission_missions set baseline = p_record ->> 'to', updated_at_ms = p_at,
                                    scenario_floor = 0, scenario_names = null
         where sources ->> 0 = p_record ->> 'source' and baseline is null
           and jsonb_typeof(p_record -> 'without_baseline') = 'array'
           and id in (select m::bigint
                        from jsonb_array_elements_text(p_record -> 'without_baseline') m);
    when 'source.held' then
        -- The owner holds landings on a source (spawn_source_hold): the
        -- source's active hold is this one. A hold on a source already held
        -- renews it: the previous one ends here, with no record of its own.
        insert into mission_source_holds (source, hold, main, by, reason, held_at_ms, expires_ms)
        values (p_record ->> 'source', p_event, p_record ->> 'main', p_record ->> 'by',
                p_record ->> 'reason', p_at, (p_record ->> 'expires_ms')::bigint)
        on conflict (source) do update
           set hold = excluded.hold, main = excluded.main, by = excluded.by,
               reason = excluded.reason, held_at_ms = excluded.held_at_ms,
               expires_ms = excluded.expires_ms;
    when 'source.released', 'source.hold_expired' then
        -- The record that ends a hold: only the one naming the active hold.
        delete from mission_source_holds
         where source = p_record ->> 'source' and hold = (p_record ->> 'hold')::bigint;
    when 'source.main_red' then
        -- Main of a source is red on a check (the integrator, after a gate
        -- found it failing twice on the base with the same tests): the first
        -- record starts the row, a later one (another task's gate, or a later
        -- main red the same way) moves `main` and `failures` on and keeps
        -- `since_ms` and `event`.
        insert into mission_source_reds (source, event, main, scenario, failures, since_ms,
                                         red_ms, tasks)
        values (p_record ->> 'source', p_event, p_record ->> 'main', p_record ->> 'scenario',
                p_record -> 'failures', p_at, p_at,
                jsonb_build_array((p_record ->> 'task')::bigint))
        on conflict (source) do update
           set main = excluded.main, scenario = excluded.scenario,
               failures = excluded.failures, red_ms = excluded.red_ms,
               tasks = mission_source_reds.tasks || excluded.tasks;
    when 'source.main_probe' then
        -- A gate on the red main anyway, so a candidate that fixes it is
        -- judged: the next probe is due an interval after this one.
        update mission_source_reds set probed_ms = p_at where source = p_record ->> 'source';
    when 'source.main_green' then
        -- The red check passed on main's base (a probe's, or a later main's): green.
        delete from mission_source_reds where source = p_record ->> 'source';
    when 'task.rerouted' then
        -- Agent grading's rework step-up (docs/agent-grading.md,
        -- `spawn_task_reroute`): a task sent back runs its next revision on
        -- the stronger preset the record names, on that preset's model.
        -- `first_preset_id` stays: calibration counts the task for the
        -- preset it was first assigned to.
        update mission_tasks set preset_id = p_record ->> 'preset_id',
                                 model = p_record ->> 'model'
         where id = v_id;
    when 'task.held' then
        -- A landing that pushed nothing: its source is held. It stays
        -- `landing`, waiting behind that hold.
        update mission_tasks set held_by = (p_record ->> 'hold')::bigint where id = v_id;
    when 'task.delivered' then
        update mission_tasks set state = 'delivered', command_id = (p_record ->> 'command_id')::bigint,
                                 delivered_at_ms = p_at, updated_at_ms = p_at
         where id = v_id;
    when 'task.gated' then
        v_verdict := p_record ->> 'verdict';
        -- A verdict names the revision of the report it judged; one on
        -- another revision (or a task gone) moves nothing. A record from
        -- before it named none applies as it did.
        select k.mission_id, m.accept into v_mission, v_accept
          from mission_tasks k join mission_missions m on m.id = k.mission_id
         where k.id = v_id
           and (p_record ->> 'revision' is null
                or k.revisions = (p_record ->> 'revision')::integer);
        if v_mission is null then
            return;
        end if;
        update mission_tasks
           set state = case v_verdict
                         when 'accepted' then 'landing'
                         when 'rejected' then 'revise'
                         when 'conflict' then 'revise'
                         -- `incompatible`: the head passes the gate alone and
                         -- fails only merged with main (the integrator judged
                         -- both): sent back like `conflict`, never counted as
                         -- a rejection (docs/fleet-architecture.md §10.3).
                         when 'incompatible' then 'revise'
                         when 'stale' then case when v_accept = 'gate' then 'reported' else 'accepted' end
                         else state end,
               base = coalesce(p_record ->> 'base', base),
               candidate = case when v_verdict = 'accepted' then p_record ->> 'candidate'
                                when v_verdict in ('aborted', 'no_room', 'host_fault')
                                     then candidate end,
               gate_log = coalesce(p_record ->> 'log', gate_log),
               metric = case when v_verdict = 'accepted' then p_record ->> 'metric' else metric end,
               review_note = case when v_verdict in ('rejected', 'conflict', 'incompatible') then p_record ->> 'note'
                                  else review_note end,
               revisions = revisions + case when v_verdict in ('rejected', 'conflict', 'incompatible') then 1 else 0 end,
               -- Agent grading: only a quality rejection, never a conflict
               -- or an incompatible head (docs/agent-grading.md).
               quality_rejections = quality_rejections
                                    + case when v_verdict = 'rejected' then 1 else 0 end,
               -- The load-sensitive bound: set by its two evidences, kept
               -- by `no_room` and `stale` (no judging), cleared by every
               -- other verdict on the task (a released task's next gate
               -- starts the count again).
               gate_load_sensitive_pushed = case
                   when v_verdict in ('no_room', 'stale') then gate_load_sensitive_pushed
                   when v_verdict = 'host_fault'
                        and p_record ->> 'evidence' in ('load_sensitive', 'load_sensitive_parked')
                       then p_record ->> 'pushed' end,
               gate_load_sensitive_scenarios = case
                   when v_verdict in ('no_room', 'stale') then gate_load_sensitive_scenarios
                   when v_verdict = 'host_fault'
                        and p_record ->> 'evidence' in ('load_sensitive', 'load_sensitive_parked')
                        and jsonb_typeof(p_record -> 'sensitive') = 'array'
                       then p_record -> 'sensitive' end,
               gate_parked_pushed = case
                   when v_verdict in ('no_room', 'stale') then gate_parked_pushed
                   when v_verdict = 'host_fault'
                        and p_record ->> 'evidence' = 'load_sensitive_parked'
                       then p_record ->> 'pushed' end,
               updated_at_ms = p_at
         where id = v_id;
        update mission_missions
           set baseline = coalesce(baseline, p_record ->> 'base'),
               gate_rejections = case v_verdict when 'rejected' then gate_rejections + 1
                                                when 'accepted' then 0 else gate_rejections end,
               -- The run's objective: the first rejection's task's, kept
               -- while every later one is a task of the same objective, null
               -- once one is not (null stays null for the run).
               gate_rejection_objective = case
                   when v_verdict = 'rejected' and gate_rejections = 0
                       then (select k.objective from mission_tasks k where k.id = v_id)
                   when v_verdict = 'rejected'
                       then case when gate_rejection_objective
                                      = (select k.objective from mission_tasks k where k.id = v_id)
                                 then gate_rejection_objective end
                   when v_verdict = 'accepted' then null
                   else gate_rejection_objective end,
               -- `no_room`: no room to judge (TMPDIR's free space, the
               -- host's memory or the test database, measured before the
               -- gate or by the gate's own floor), a fact about the host,
               -- not the work. It moves neither count.
               -- `host_fault`: the gate failed because the host did (the
               -- test database): neither count grows nor resets.
               gate_aborts = case v_verdict when 'aborted' then gate_aborts + 1
                                            when 'stale' then gate_aborts
                                            when 'no_room' then gate_aborts
                                            when 'host_fault' then gate_aborts
                                            else 0 end,
               -- The mission's host faults in a row: a landing or a real
               -- verdict ends the run; `no_room` and `stale` leave it. The
               -- task waits until the record's `due_ms`.
               -- A red main (evidence `main_red`) is no host fault of the run:
               -- it leaves the run as it was, as `no_room` does; the
               -- source's red holds the gates instead of a backoff.
               -- A task parked by the load-sensitive bound ends the run:
               -- it is not judged again, so nothing waits behind it.
               gate_host_faults = case when v_verdict = 'host_fault'
                                            and p_record ->> 'evidence' = 'main_red'
                                           then gate_host_faults
                                       when v_verdict = 'host_fault'
                                            and p_record ->> 'evidence' = 'load_sensitive_parked'
                                           then 0
                                       when v_verdict = 'host_fault' then gate_host_faults + 1
                                       when v_verdict in ('no_room', 'stale') then gate_host_faults
                                       else 0 end,
               gate_host_task = case when v_verdict = 'host_fault'
                                          and p_record ->> 'evidence' = 'main_red'
                                         then gate_host_task
                                     when v_verdict = 'host_fault'
                                          and p_record ->> 'evidence' = 'load_sensitive_parked'
                                         then null
                                     when v_verdict = 'host_fault' then v_id
                                     when v_verdict in ('no_room', 'stale') then gate_host_task end,
               gate_host_due_ms = case when v_verdict = 'host_fault'
                                            and p_record ->> 'evidence' = 'main_red'
                                           then gate_host_due_ms
                                       when v_verdict = 'host_fault'
                                            and p_record ->> 'evidence' = 'load_sensitive_parked'
                                           then null
                                       when v_verdict = 'host_fault'
                                           then (p_record ->> 'due_ms')::bigint
                                       when v_verdict in ('no_room', 'stale')
                                           then gate_host_due_ms end,
               -- The mission's base disagreements in a row (objective 033):
               -- + 1 on a host fault with that evidence, kept by `no_room`
               -- and `stale`, ended by every other verdict (020's host faults
               -- included), a landing and a resume. The record that makes it
               -- 3 carries `alert`.
               gate_base_disagrees = case
                   when v_verdict = 'host_fault'
                        and p_record ->> 'evidence' = 'base_disagrees'
                       then gate_base_disagrees + 1
                   when v_verdict = 'host_fault' and p_record ->> 'evidence' = 'main_red'
                       then gate_base_disagrees
                   when v_verdict in ('no_room', 'stale') then gate_base_disagrees
                   else 0 end,
               -- The run is this task's: a `no_room` on another task starts
               -- a new one (no inherited backoff or age).
               gate_room_task = case v_verdict when 'no_room' then v_id
                                               when 'stale' then gate_room_task end,
               gate_room_since_ms = case when v_verdict = 'no_room' and gate_room_task = v_id
                                              then coalesce(gate_room_since_ms, p_at)
                                         when v_verdict = 'no_room' then p_at
                                         when v_verdict = 'stale' then gate_room_since_ms end,
               gate_room_last_ms = case v_verdict when 'no_room' then p_at
                                                  when 'stale' then gate_room_last_ms end,
               gate_room_waits = case when v_verdict = 'no_room' and gate_room_task = v_id
                                           then gate_room_waits + 1
                                      when v_verdict = 'no_room' then 1
                                      when v_verdict = 'stale' then gate_room_waits else 0 end,
               gate_room_escalated = case when v_verdict = 'no_room' and gate_room_task = v_id
                                               then gate_room_escalated
                                                    or coalesce((p_record ->> 'escalate')::boolean, false)
                                          when v_verdict = 'no_room'
                                               then coalesce((p_record ->> 'escalate')::boolean, false)
                                          when v_verdict = 'stale' then gate_room_escalated
                                          else false end,
               -- The floor rises only from a gating on the mission's baseline
               -- (P28, rev-e F1): one in flight across an owner's landing ends
               -- on the old main (`stale`, or any verdict) with the old
               -- controller's count, and must not raise the floor the landing
               -- started again. A `stale` one on the baseline counts as before.
               scenario_floor = case
                   when baseline is null
                        or spawn_commit_now(baseline) = spawn_commit_now(p_record ->> 'base')
                       then greatest(scenario_floor,
                                     coalesce((p_record ->> 'scenarios')::integer, 0))
                   else scenario_floor end,
               -- The names of the gating that set the floor: the latest at
               -- it (one at the floor with other names replaces them).
               scenario_names = case
                   when (baseline is null
                         or spawn_commit_now(baseline) = spawn_commit_now(p_record ->> 'base'))
                        and p_record ? 'scenarios'
                        and (p_record ->> 'scenarios')::integer >= scenario_floor
                        and (p_record ->> 'scenarios')::integer > 0
                       then case when jsonb_typeof(p_record -> 'scenario_names') = 'array'
                                 then p_record -> 'scenario_names' end
                   else scenario_names end,
               updated_at_ms = p_at
         where id = v_mission;
    when 'task.landed' then
        -- A task that ends leaves the load-sensitive bound (rev-e F2): no
        -- board line, no release, for a task no gate judges again.
        update mission_tasks set state = 'landed',
                                 gate_load_sensitive_pushed = null,
                                 gate_load_sensitive_scenarios = null, gate_parked_pushed = null,
                                 updated_at_ms = p_at
         where id = v_id;
        -- A landing ends its mission's run of host faults, and its run of
        -- bases that disagreed with themselves.
        update mission_missions set gate_host_faults = 0, gate_host_task = null,
                                    gate_host_due_ms = null, gate_base_disagrees = 0
         where id = (select mission_id from mission_tasks where id = v_id);
        -- Every mission on the same source sees the same main: the landing
        -- moves its own mission's baseline, and those of the other missions
        -- it names (spawn_integrator_record: the ones whose baseline was its
        -- `from`, not halted). A record from before it named them moved
        -- every mission on the source that had a baseline.
        update mission_missions m set baseline = p_record ->> 'to', updated_at_ms = p_at
          from mission_missions own join mission_tasks k on k.mission_id = own.id
         where k.id = v_id
           and (m.id = own.id
                or (p_record -> 'missions' is null
                    and m.baseline is not null and m.sources ->> 0 = own.sources ->> 0)
                or m.id in (select x::bigint
                              from jsonb_array_elements_text(p_record -> 'missions') x));
    when 'task.aborted' then
        -- Over budget: the work is dropped, and it counts toward the abort halt.
        update mission_tasks set state = 'cancelled', review_note = p_record ->> 'reason',
                                 gate_load_sensitive_pushed = null,
                                 gate_load_sensitive_scenarios = null, gate_parked_pushed = null,
                                 updated_at_ms = p_at
         where id = v_id;
        update mission_missions set gate_aborts = gate_aborts + 1, updated_at_ms = p_at
         where id = (select mission_id from mission_tasks where id = v_id);
        -- A task that leaves the gate ends its run of `no_room`.
        update mission_missions set gate_room_task = null, gate_room_since_ms = null,
                                    gate_room_last_ms = null, gate_room_waits = 0,
                                    gate_room_escalated = false, updated_at_ms = p_at
         where gate_room_task = v_id;
    when 'task.over_budget' then
        -- Over budget: the task is bigger than its budget, not a failed
        -- gate. Its work is kept on its branch and its objective's next
        -- task continues it (`task.assigned` naming `continues`), so the
        -- task leaves flight and counts toward no halt: the mission's
        -- gate_aborts and gate_rejections stay as they were
        -- (docs/fleet-architecture.md §10.4).
        update mission_tasks set state = 'cancelled', review_note = p_record ->> 'reason',
                                 gate_load_sensitive_pushed = null,
                                 gate_load_sensitive_scenarios = null, gate_parked_pushed = null,
                                 updated_at_ms = p_at
         where id = v_id;
        -- A task that leaves the gate ends its run of `no_room`.
        update mission_missions set gate_room_task = null, gate_room_since_ms = null,
                                    gate_room_last_ms = null, gate_room_waits = 0,
                                    gate_room_escalated = false, updated_at_ms = p_at
         where gate_room_task = v_id;
    when 'task.reported' then
        update mission_tasks set state = 'reported', report = p_record ->> 'report',
                                 updated_at_ms = p_at
         where id = v_id;
    when 'task.reviewed' then
        v_accepted := (p_record ->> 'accepted')::boolean;
        -- A review names the revision of the report it judged; one on another
        -- revision moves nothing (a record from before it named none applies).
        update mission_tasks
           set state = case when v_accepted then 'accepted' else 'revise' end,
               review_note = case when v_accepted then review_note else p_record ->> 'note' end,
               revisions = revisions + case when v_accepted then 0 else 1 end,
               quality_rejections = quality_rejections + case when v_accepted then 0 else 1 end,
               updated_at_ms = p_at
         where id = v_id
           and (p_record ->> 'revision' is null
                or revisions = (p_record ->> 'revision')::integer);
    when 'task.released' then
        -- A person releases a task the load-sensitive bound parked
        -- (`spawn task release`): its next gate judges it, and the count
        -- starts again. Only its own columns move.
        update mission_tasks set gate_load_sensitive_pushed = null,
                                 gate_load_sensitive_scenarios = null,
                                 gate_parked_pushed = null, updated_at_ms = p_at
         where id = v_id;
    when 'task.cancelled' then
        -- `by` names who cancelled (spawn_task_cancel_by), read by the
        -- scorecard, not by the fold.
        update mission_tasks set state = 'cancelled',
                                 gate_load_sensitive_pushed = null,
                                 gate_load_sensitive_scenarios = null, gate_parked_pushed = null,
                                 updated_at_ms = p_at
         where id = v_id;
        -- A cancel of a task of the objective every rejection of the
        -- mission's run was ends that run, whoever cancels it: a yield
        -- (either rule's: three rejections of one objective, or its failed
        -- attempts), the owner's cancel, or the objective solved on the base.
        -- The objective's work is set aside, so the next rejection starts a
        -- run of its own and is not mixed with a run whose objective is gone.
        update mission_missions m set gate_rejections = 0, gate_rejection_objective = null,
                                      updated_at_ms = p_at
          from mission_tasks k
         where k.id = v_id and m.id = k.mission_id
           and m.gate_rejection_objective = k.objective;
        -- A task that leaves the gate ends its run of `no_room`.
        update mission_missions set gate_room_task = null, gate_room_since_ms = null,
                                    gate_room_last_ms = null, gate_room_waits = 0,
                                    gate_room_escalated = false, updated_at_ms = p_at
         where gate_room_task = v_id;
    when 'task.stolen' then
        -- A queued task moved, unstarted, to an idle resident of its pool
        -- (objective 239, spawn_task_steal): its worker is the taker now.
        update mission_tasks set session_id = p_record ->> 'to_session',
                                 agent_id = p_record ->> 'to_agent', stolen_at_ms = p_at,
                                 updated_at_ms = p_at
         where id = v_id;
    when 'resident.proposed' then
        insert into mission_residents (name, agent_id, session_id, charter, proposed_by,
                                       pool, created_at_ms, updated_at_ms)
        values (p_record ->> 'name', 'agent_resident_' || (p_record ->> 'name'),
                'session_resident_' || (p_record ->> 'name'), p_record ->> 'charter',
                p_record ->> 'proposed_by', p_record ->> 'pool', p_at, p_at)
        on conflict (name) do update
           set charter = excluded.charter, pool = excluded.pool, updated_at_ms = p_at;
    when 'resident.approved' then
        update mission_residents set state = 'approved', approved_by = 'human', updated_at_ms = p_at
         where name = p_record ->> 'name';
    when 'resident.retired' then
        update mission_residents set state = 'retired', updated_at_ms = p_at
         where name = p_record ->> 'name';
        -- Its work that the closure rule does not let go on is dropped.
        update mission_tasks k set state = 'cancelled', updated_at_ms = p_at
          from mission_missions m, mission_residents r
         where m.id = k.mission_id and r.agent_id = k.agent_id
           and r.name = p_record ->> 'name'
           and not spawn_task_may_continue(k.state, m.state, m.gate is not null, r.state);
    when 'host.disk' then
        -- A fact about this host's free disk (spawn loop, crate disk.rs):
        -- read from the log, folded into no table.
        null;
    when 'host.storage' then
        -- A sample of what the transcript archive and Claude Code's own
        -- transcripts hold (spawn loop, crate storage.rs): read from the
        -- log by `/api/fleet`'s storage figures, folded into no table.
        null;
    when 'host.core_lines' then
        -- An hourly sample of every Core lines figure that has a value
        -- (spawn loop, crate core_lines_sample.rs, objective 090): read from
        -- the log by `/api/core-lines`' 7-day trends, folded into no table.
        null;
    when 'host.storage_bytes' then
        -- A daily reading of the real bytes on disk of each storage source,
        -- each extent counted once (spawn loop, crate storage_bytes.rs,
        -- objective 180): read from the log, folded into no table.
        null;
    when 'host.judge' then
        -- The model judge's calls began failing (`down`) or answered again
        -- (`up`): one record per crossing (spawn loop, crate judge_watch.rs),
        -- read from the log by the alert step, folded into no table.
        null;
    when 'alert.fired' then
        -- An alert's one occurrence (spawn loop, crate alerts.rs): one row
        -- per key, and a second `fired` for it is refused (also by
        -- `spawn_alert_record`, the writer). A notice never clears.
        if exists (select 1 from spawn_alerts where key = p_record ->> 'key') then
            raise exception 'alert % was already fired', p_record ->> 'key';
        end if;
        insert into spawn_alerts (key, kind, subject, state, notice, text, evidence,
                                  fired_event_id, fired_at_ms)
        values (p_record ->> 'key', p_record ->> 'kind', p_record ->> 'subject',
                case when coalesce((p_record ->> 'notice')::boolean, false)
                     then 'notice' else 'open' end,
                coalesce((p_record ->> 'notice')::boolean, false),
                p_record ->> 'text', coalesce(p_record -> 'evidence', '{}'::jsonb),
                p_event, p_at);
    when 'deploy.finished' then
        -- How a deploy of the live system ended (deploy/deploy.sh, through
        -- spawn_deploy_record): read by the alert step (`deploy_failed`),
        -- folded into no table.
        null;
    when 'objective.verified' then
        -- A look at the running product after an objective landed (`spawn
        -- verify`, through spawn_verification_record, objective 133): read
        -- by `spawn verify list` and /api/verifications, folded into no table.
        null;
    when 'backup.dumped', 'backup.bundled', 'backup.verified', 'backup.stored',
         'backup.drilled.transcripts', 'backup.drilled.missions',
         'backup.drilled.controllers', 'backup.drilled.sync' then
        -- What `spawn backup` did (crate backup.rs; `backup.stored`: a
        -- `spawn store put` run, its manifest's key): read from the log by the
        -- next run, folded into no table. What a copy holds is in its record
        -- (its events, watermark and sha256), so the drill compares a
        -- restore with the record and not with the live database
        -- (docs/storage.md, "Where state lives").
        null;
    when 'alert.judged' then
        -- The owner's verdict on an alert (`spawn alert judge`, objective
        -- 092): `right` (objective 148), `false`, `stale` or `duplicate`,
        -- once, never on a notice. `right` changes nothing else: an open
        -- alert stays open (its condition clears it later, and it keeps its
        -- verdict), a cleared one keeps its clearing. Every other verdict
        -- clears an open alert (cleared evidence {judged}); a cleared one
        -- keeps its cleared evidence and gains the verdict.
        if p_record ->> 'verdict' is null
           or p_record ->> 'verdict' not in ('right', 'false', 'stale', 'duplicate') then
            raise exception 'an alert verdict is right, false, stale or duplicate: %', p_record;
        end if;
        if not exists (select 1 from spawn_alerts
                        where key = p_record ->> 'key' and not notice and verdict is null) then
            raise exception 'alert % cannot be judged: no such alert, a notice, or judged already',
                            p_record ->> 'key';
        end if;
        if p_record ->> 'verdict' = 'right' then
            update spawn_alerts
               set verdict = 'right', judged_at_ms = p_at
             where key = p_record ->> 'key';
        else
            update spawn_alerts
               set verdict = p_record ->> 'verdict', judged_at_ms = p_at,
                   state = 'cleared',
                   cleared_event_id = coalesce(cleared_event_id, p_event),
                   cleared_at_ms = coalesce(cleared_at_ms, p_at),
                   cleared_evidence = coalesce(cleared_evidence,
                                               jsonb_build_object('judged', p_record ->> 'verdict'))
             where key = p_record ->> 'key';
        end if;
    when 'alert.updated' then
        -- An open alert's text and evidence as its condition is now
        -- (objective 219: `unverified_landings` says the count of the
        -- current reading). Only those two change: its fire, state and
        -- verdict stay. Checked by spawn_alert_record before it is written;
        -- a row that is not the open alert of that kind and subject is left
        -- as it is.
        update spawn_alerts
           set text = p_record ->> 'text',
               evidence = coalesce(p_record -> 'evidence', '{}'::jsonb)
         where key = p_record ->> 'key' and state = 'open' and not notice
           and kind = p_record ->> 'kind' and subject = p_record ->> 'subject';
    when 'alert.cleared' then
        -- What cleared an alert, once: the row must be open (a notice never
        -- clears, and a cleared alert is cleared at most once).
        if not exists (select 1 from spawn_alerts
                        where key = p_record ->> 'key' and state = 'open') then
            raise exception 'alert % is not open: nothing to clear', p_record ->> 'key';
        end if;
        update spawn_alerts
           set state = 'cleared', cleared_event_id = p_event, cleared_at_ms = p_at,
               cleared_evidence = coalesce(p_record -> 'evidence', '{}'::jsonb)
         where key = p_record ->> 'key';
    when 'host.messages_marked' then
        -- The first `spawn loop` whose Bridge types each message's marker
        -- started (spawn_host_record writes one, once): a command never
        -- typed is a message whose taking is tracked from then on
        -- (spawn_command_message). Read from the log, folded into no table.
        null;
    when 'host.loop_started' then
        -- `spawn loop` started (its boot id and start time): the recovery
        -- reads it to tell an execution whose end this loop found after a
        -- host restart from one it watched fail (spawn_host_record).
        null;
    when 'execution.interrupted' then
        -- One interruption of one execution: how it ended (or how a turn
        -- failed) with its cause, its evidence and the path back. Read from
        -- the log by the next pass, this one and after a restart, folded
        -- into no table (spawn_host_record).
        null;
    when 'execution.cleared' then
        -- The wait an interruption opened is over: what showed the cause
        -- gone and how long it held. Read from the log, folded into no
        -- table (spawn_host_record).
        null;
    when 'task.restarted' then
        -- A delivered task's worker is given a fresh execution of its own
        -- native session (spawn_task_restart): the dispatcher stops the
        -- running one and resumes the session, reading the record from the
        -- log. The task stays delivered, so nothing is folded.
        null;
    when 'task.report_unfinished' then
        -- A report still a draft, not taken (spawn_task_report_unfinished):
        -- the task stays delivered, so nothing is folded.
        null;
    when 'task.fork_failed' then
        -- The dispatcher could not fork an objective task's workspace from
        -- its predecessor's work (spawn_task_fork_failed): read from the
        -- log, folded into no table.
        null;
    when 'source.push_requested' then
        -- The owner asked for a commit on a source's main (`spawn mission
        -- push`): a request the integrator applies between its steps, read
        -- from the log, folded into no table. Its outcome names it: a
        -- `source.moved` (which moves the baselines) or a
        -- `source.push_refused`.
        null;
    when 'source.push_refused' then
        -- The integrator could not apply an owner's request (a conflict, a
        -- commit not in the source, main moving under it twice): main and
        -- every baseline stay where they were.
        null;
    when 'source.push_no_verdict' then
        -- An owner judging of a request ended with no verdict (the host's
        -- fault, an abort, a base that disagreed with itself, ...): the
        -- request stays pending, judged again after its backoff. It names
        -- the request, the reason and where the gate's log is kept
        -- (spawn-cli integrate/retained.rs). No outcome: folded into no table.
        null;
    when 'integrator.draining', 'integrator.drained', 'integrator.drain_expired' then
        -- The integrator's drain (spawn_integrator_record): read from the
        -- log, folded into no table.
        null;
    when 'integrator.started' then
        -- Who an integrator start that took the lock is (objective 234,
        -- spawn_integrator_record): read from the log, folded into no table.
        null;
    when 'objective.solved' then
        -- The objective's scenario passes at a base commit main already
        -- holds, so no task of it can change anything: the assignment rule
        -- reads this record as a landing (OBJECTIVE_LANDINGS), and the task
        -- it ends is cancelled on it. Folded into no table.
        null;
    when 'objective.retired' then
        -- An objective retired by hand (spawn_objective_retire, objective
        -- 210): closed whatever its kind. The first record wins.
        insert into mission_retired_objectives (mission_id, objective, by, reason, caller,
                                                event, at_ms)
        values (v_id, (p_record ->> 'objective')::integer, p_record ->> 'by',
                p_record ->> 'reason', p_record ->> 'caller', p_event, p_at)
        on conflict (mission_id, objective) do nothing;
    when 'task.shadow_gated' then
        -- A gate runner's judging of a copy of what the primary judged
        -- (spawn-cli integrate/shadow.rs), beside the primary's verdict: it
        -- decides nothing, so it changes no task, landing, halt or count.
        -- Read from the log (the supervisor's digest), folded into no table.
        null;
    when 'legacy.imported' then
        -- A row from before the control stream, as it was.
        case p_record ->> 'table'
        when 'mission_missions' then
            -- Columns added after the import take their defaults.
            insert into mission_missions
            select * from jsonb_populate_record(null::mission_missions,
                jsonb_build_object('accept', 'review', 'scenario_floor', 0,
                                   'gate_rejections', 0, 'gate_aborts', 0, 'gate_room_waits', 0,
                                   'gate_room_escalated', false, 'gate_host_faults', 0)
                || (p_record -> 'row'));
        when 'mission_residents' then
            insert into mission_residents
            select * from jsonb_populate_record(null::mission_residents, p_record -> 'row');
        when 'mission_tasks' then
            insert into mission_tasks
            select * from jsonb_populate_record(null::mission_tasks,
                jsonb_build_object('model', 'default', 'pinned', false, 'difficulty', 2,
                                   'quality_rejections', 0)
                || (p_record -> 'row'));
        else
            raise exception 'legacy record of unknown table %', p_record ->> 'table';
        end case;
    else
        raise exception 'unknown control record %', v_type;
    end case;
end $$;

-- Append one record to the control stream and fold it into the tables.
create or replace function spawn_control_record(p_record jsonb)
returns bigint language plpgsql as $$
declare
    v_id bigint;
    v_at bigint;
begin
    select a.out_id, a.out_at into v_id, v_at
      from spawn_append_trusted('agent_control', 'session_control', null, 'control', null,
                                jsonb_build_object('name', 'control.recorded',
                                                   'detail', jsonb_build_object('record', p_record))) a;
    -- A host fault is judged again `backoff_ms` after its own record: its
    -- `due_ms` is the record's time plus that, which only the append knows.
    -- It is written into the record in the transaction that appends it, so
    -- no reader ever sees the record without it.
    if p_record ->> 'type' = 'task.gated' and p_record ->> 'verdict' = 'host_fault'
       and jsonb_typeof(p_record -> 'backoff_ms') = 'number' then
        p_record := p_record || jsonb_build_object(
            'due_ms', v_at + (p_record ->> 'backoff_ms')::numeric::bigint);
        update spawn_events
           set kind = jsonb_set(kind, '{detail,record}', p_record)
         where id = v_id;
    end if;
    -- An owner's hold expires `bound_s` after its own record, the same way.
    if p_record ->> 'type' = 'source.held' and jsonb_typeof(p_record -> 'bound_s') = 'number' then
        p_record := p_record || jsonb_build_object(
            'expires_ms', v_at + (p_record ->> 'bound_s')::numeric::bigint * 1000);
        update spawn_events
           set kind = jsonb_set(kind, '{detail,record}', p_record)
         where id = v_id;
    end if;
    perform spawn_control_apply(p_record, v_at, v_id);
    return v_id;
end $$;

-- Rebuild the tables from the log. Ids come from the records, so the
-- identity sequences stay ahead of every row.
create or replace function spawn_control_refold()
returns void language plpgsql as $$
declare
    v_event record;
begin
    perform pg_advisory_xact_lock(1399957335);
    delete from mission_source_holds;
    delete from mission_retired_objectives;
    delete from mission_source_reds;
    delete from spawn_alerts;
    delete from mission_tasks;
    delete from mission_residents;
    delete from mission_missions;
    for v_event in
        select e.id, e.kind -> 'detail' -> 'record' as record, e.recorded_at_ms
          from spawn_events e
         where e.session_id = 'session_control' and e.event_name = 'control.recorded'
         order by e.session_seq
    loop
        perform spawn_control_apply(v_event.record, v_event.recorded_at_ms, v_event.id);
    end loop;
end $$;

-- Whether `p_source` is a mission source Spawn hands to git: an absolute
-- path, an https:// or ssh:// URL, or ssh's `user@host:path`. Nothing that
-- names another transport (`ext::`, `fd::`, `file://`), nothing relative,
-- nothing that begins like an option, no whitespace or control character in
-- a URL. The controller's git also allows only file, https and ssh
-- (GIT_ALLOW_PROTOCOL), so a source stored before this check still reaches
-- no other transport. Mirrors `MissionSource::parse` in spawn-cli.
create or replace function spawn_source_allowed(p_source text)
returns boolean language sql immutable as $$
    select p_source is not null
       and length(p_source) <= 4096
       and (p_source ~ '^/[^[:cntrl:]]*$'
            or p_source ~ '^(https|ssh)://[^-/[:space:][:cntrl:]][^[:space:][:cntrl:]]*$'
            or p_source ~ '^[A-Za-z0-9_][A-Za-z0-9._-]*@[A-Za-z0-9][A-Za-z0-9.-]*:[^-:[:space:][:cntrl:]][^[:space:][:cntrl:]]*$')
$$;

create or replace function spawn_mission_add(p_text text, p_sources jsonb, p_origin text)
returns bigint language plpgsql security definer as $$
declare
    v_caller text := spawn_mission_caller();
    v_id bigint;
    v_source jsonb;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if v_caller is null then
        raise exception '% may not add missions', session_user using errcode = '42501';
    end if;
    if coalesce(trim(p_text), '') = '' then
        raise exception 'a mission needs text';
    end if;
    if jsonb_typeof(coalesce(p_sources, '[]'::jsonb)) <> 'array' then
        raise exception 'a mission''s sources are a list' using errcode = '22023';
    end if;
    -- Every source is one git runs as the owner: a checked shape, and from
    -- the supervisor only one a human already gave a mission. The supervisor
    -- reads text other agents write; it never introduces a repository.
    for v_source in select value from jsonb_array_elements(coalesce(p_sources, '[]'::jsonb)) loop
        if jsonb_typeof(v_source) <> 'string' or not spawn_source_allowed(v_source #>> '{}') then
            raise exception 'a source is an absolute path or an https:// or ssh:// URL, not %',
                v_source using errcode = '22023';
        end if;
        if v_caller = 'spawn_supervisor' and not exists (
            select 1 from mission_missions
             where origin <> 'spawn_supervisor' and sources @> jsonb_build_array(v_source)) then
            raise exception 'the supervisor names only a source a human gave a mission, not %',
                v_source using errcode = '42501';
        end if;
    end loop;
    v_id := nextval(pg_get_serial_sequence('mission_missions', 'id'));
    perform spawn_control_record(jsonb_build_object(
        'type', 'mission.added', 'id', v_id, 'text', p_text,
        'origin', case when v_caller = 'spawn_supervisor' then 'spawn_supervisor'
                       else coalesce(p_origin, 'human') end,
        'sources', coalesce(p_sources, '[]'::jsonb)));
    return v_id;
end $$;

-- Who cancels, as a `task.cancelled` record names it (`by`): the caller of
-- a checked function, `spawn_supervisor` for the supervisor's login and
-- `human` for the owner's (the CLI; Spawn's loops record their own
-- cancellations under their names: `spawn-integrate`, `spawn-dispatch`).
-- The scorecard tells a person's cancellation from Spawn's by it
-- (docs/design.md §15); a record from before it names none, and counts as
-- a person's.
create or replace function spawn_task_cancel_by() returns text
language sql stable as $$
    select case spawn_mission_caller() when 'spawn_supervisor' then 'spawn_supervisor'
                                       else 'human' end
$$;

-- A close or a retirement cancels, in its fold, the work the closure rule
-- does not let go on. Its writer then gives each task of `p_open` (the ones
-- open before the close) that the fold cancelled its own `task.cancelled`
-- record, so the task's stages end with `cancelled`. The record repeats what
-- the fold did; the fold itself never appends, so replaying the log gives
-- the same tables and adds nothing. Called under the append lock.
-- The record names `by`, the caller (spawn_task_cancel_by).
create or replace function spawn_task_record_cancelled(p_open bigint[])
returns void language plpgsql as $$
declare
    v_task bigint;
begin
    for v_task in
        select id from mission_tasks where id = any(p_open) and state = 'cancelled' order by id
    loop
        perform spawn_control_record(jsonb_build_object('type', 'task.cancelled', 'id', v_task,
                                                        'by', spawn_task_cancel_by()));
    end loop;
end $$;

create or replace function spawn_mission_close(p_mission bigint, p_state text, p_summary text)
returns void language plpgsql security definer as $$
declare
    v_open bigint[];
begin
    -- A drop waits for a landing push in flight (spawn_landing_hold), so
    -- the push cannot land work of a mission dropped meanwhile.
    if p_state = 'dropped' then
        perform pg_advisory_xact_lock(1399957337);
    end if;
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is null then
        raise exception '% may not close missions', session_user using errcode = '42501';
    end if;
    if p_state not in ('done', 'dropped') then
        raise exception 'a mission closes as done or dropped';
    end if;
    if not exists (select 1 from mission_missions where id = p_mission and state in ('open', 'active')) then
        raise exception 'mission % is not open', p_mission;
    end if;
    select coalesce(array_agg(id), '{}') into v_open
      from mission_tasks where mission_id = p_mission and state <> 'cancelled';
    perform spawn_control_record(jsonb_build_object(
        'type', 'mission.closed', 'id', p_mission, 'state', p_state, 'summary', p_summary));
    perform spawn_task_record_cancelled(v_open);
end $$;

-- Assign one task. A resident must be approved; an ephemeral worker gets a
-- new agent named after the label and the task, used for this task only.
-- `p_model` is the profile the worker runs the task on.
--
-- A duplicate (objective 212, GitHub #63): a task of the same mission in
-- flight whose brief equals this one, both trimmed of space, tab, CR and LF
-- (exact, never "looks alike"; the lowest such id). In flight: assigned,
-- delivered, reported, revise or landing, or accepted in a mission with a
-- gate (it still waits for its gate), as the board counts it. The
-- supervisor's duplicate is refused, naming that task, unless `p_again`
-- (`spawn task assign --again`); the owner's (a person or a script giving
-- several workers one brief means it) is assigned. Whenever there is one,
-- the `task.assigned` record names it (`duplicate_of`).
drop function if exists spawn_task_assign(bigint, text, text, text);
drop function if exists spawn_task_assign(bigint, text, text, text, text);
drop function if exists spawn_task_assign(bigint, text, text, text, text, boolean);
drop function if exists spawn_task_assign(bigint, text, text, text, text, boolean, boolean);
drop function if exists spawn_task_assign(bigint, text, text, text, text, boolean, boolean,
                                          integer, text);
drop function if exists spawn_task_assign(bigint, text, text, text, text, boolean, boolean,
                                          integer, text, jsonb);
-- `p_pin` (objective 239, `--pin`): the task stays with its worker, never
-- stolen; the record names `pinned` true, and nothing otherwise.
-- Agent grading (docs/agent-grading.md): `p_difficulty` (1 to 3, `l1` to
-- `l3`; 2 by default) and `p_preset`, the graded preset the CLI routed the
-- task to (`spawn_core::grading::route_preset`), or null. A named preset
-- must be in the grading catalog, routable (active or demoted), graded at
-- least `p_difficulty` (its locked grade, else its calibrated one), and
-- `p_model` its model profile. The record names `difficulty` (`l1` to
-- `l3`) and `preset_id` only when a preset is named or the difficulty is
-- not the default, so an assignment without the catalog records what it
-- did before. Phase 2: `p_classification`, the difficulty classifier's
-- decision and its rationale (`spawn_core::grading::classify_difficulty`,
-- an object naming `difficulty`, `score`, `rules` and `signals`) for an
-- unflagged assignment, recorded as `classification` so the record says
-- why it was routed where it was; and a named preset's
-- `execution_profile`, recorded when it has one. Without either the
-- record is as before.
create or replace function spawn_task_assign(p_mission bigint, p_kind text, p_worker text,
                                             p_brief text, p_model text default 'default',
                                             p_again boolean default false,
                                             p_pin boolean default false,
                                             p_difficulty integer default 2,
                                             p_preset text default null,
                                             p_classification jsonb default null,
                                             p_engine text default null,
                                             p_model_label text default null)
returns bigint language plpgsql security definer as $$
declare
    v_caller text := spawn_mission_caller();
    v_id bigint;
    v_agent text;
    v_session text;
    v_label text;
    v_duplicate bigint;
    v_duplicate_state text;
    v_preset grading_presets%rowtype;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if v_caller is null then
        raise exception '% may not assign tasks', session_user using errcode = '42501';
    end if;
    if not exists (select 1 from mission_missions where id = p_mission and state in ('open', 'active')) then
        raise exception 'mission % is not open', p_mission;
    end if;
    if coalesce(trim(p_brief), '') = '' then
        raise exception 'a task needs a brief';
    end if;
    if p_model is null or p_model not in ('default', 'cheap') then
        raise exception 'a task runs on the default or cheap model profile, not %', p_model;
    end if;
    if p_difficulty is null or p_difficulty not in (1, 2, 3) then
        raise exception 'a task''s difficulty is 1, 2 or 3 (l1, l2 or l3), not %', p_difficulty;
    end if;
    if p_classification is not null
       and (jsonb_typeof(p_classification) <> 'object'
            or spawn_grade_wire(p_classification -> 'difficulty') is null
            or jsonb_typeof(p_classification -> 'signals') is distinct from 'array') then
        raise exception 'a classification is an object naming its difficulty and signals, not %',
            p_classification;
    end if;
    if p_engine is not null and (p_engine !~ '^[a-z][a-z0-9_-]*$') then
        raise exception 'an engine is a registered lowercase driver name, not %', p_engine;
    end if;
    if p_model_label is not null and coalesce(trim(p_model_label), '') = '' then
        raise exception 'a model label cannot be blank';
    end if;
    if p_model_label is not null and p_engine = 'claude' then
        raise exception 'claude takes no direct --model-label (%)', p_model_label;
    end if;
    if p_preset is not null then
        select * into v_preset from grading_presets where preset_id = p_preset;
        if v_preset.preset_id is null then
            raise exception 'preset % is not in the grading catalog', p_preset;
        end if;
        if v_preset.state not in ('active', 'demoted') then
            raise exception 'preset % is %: only an active or demoted preset is routed',
                p_preset, v_preset.state;
        end if;
        if coalesce(v_preset.locked_grade, v_preset.calibrated_grade, 0) < p_difficulty then
            raise exception 'preset % is graded %, below the l% task it is assigned', p_preset,
                coalesce('l' || coalesce(v_preset.locked_grade, v_preset.calibrated_grade),
                         'nothing'),
                p_difficulty;
        end if;
        if v_preset.model_profile <> p_model then
            raise exception 'preset % runs on the % model profile, not %', p_preset,
                v_preset.model_profile, p_model;
        end if;
    end if;
    if p_kind = 'resident' then
        select agent_id, session_id into v_agent, v_session
          from mission_residents where name = p_worker and state = 'approved';
        if v_agent is null then
            raise exception 'resident % is not approved', p_worker;
        end if;
        v_id := nextval(pg_get_serial_sequence('mission_tasks', 'id'));
    elsif p_kind = 'ephemeral' then
        v_id := nextval(pg_get_serial_sequence('mission_tasks', 'id'));
        v_label := left(regexp_replace(lower(coalesce(p_worker, 'task')), '[^a-z0-9]+', '_', 'g'), 20);
        v_label := trim(both '_' from v_label);
        if v_label = '' then v_label := 'task'; end if;
        v_agent := format('agent_worker_%s_%s', v_label, v_id);
        v_session := format('session_worker_%s_%s', v_label, v_id);
    else
        raise exception 'a task is resident or ephemeral, not %', p_kind;
    end if;
    select k.id, k.state into v_duplicate, v_duplicate_state
      from mission_tasks k
      join mission_missions m on m.id = k.mission_id
     where k.mission_id = p_mission
       and btrim(k.brief, E' \t\r\n') = btrim(p_brief, E' \t\r\n')
       and (k.state in ('assigned', 'delivered', 'reported', 'revise', 'landing')
            or (k.state = 'accepted' and m.gate is not null))
     order by k.id
     limit 1;
    if v_duplicate is not null and v_caller = 'spawn_supervisor' and p_again is not true then
        raise exception 'task % of mission % has the same brief and is %: a duplicate is not assigned (cancel it first, or assign again on purpose with --again)',
            v_duplicate, p_mission, v_duplicate_state;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.assigned', 'id', v_id, 'mission_id', p_mission, 'kind', p_kind,
        'agent_id', v_agent, 'session_id', v_session, 'brief', p_brief, 'model', p_model,
        'created_by', case when v_caller = 'owner' then 'human' else v_caller end)
        || case when v_duplicate is not null
                then jsonb_build_object('duplicate_of', v_duplicate) else '{}'::jsonb end
        || case when p_pin then jsonb_build_object('pinned', true) else '{}'::jsonb end
        || case when p_preset is not null or p_difficulty <> 2
                then jsonb_strip_nulls(jsonb_build_object('difficulty', 'l' || p_difficulty,
                                                          'preset_id', p_preset))
                else '{}'::jsonb end
        || case when v_preset.execution_profile is not null
                then jsonb_build_object('execution_profile', v_preset.execution_profile)
                else '{}'::jsonb end
        || case when p_classification is not null
                then jsonb_build_object('classification', p_classification)
                else '{}'::jsonb end
        || case when p_engine is not null or p_model_label is not null
                then jsonb_strip_nulls(jsonb_build_object('engine', p_engine,
                                                          'model_label', nullif(trim(p_model_label), '')))
                else '{}'::jsonb end);
    return v_id;
end $$;

-- The dispatcher's bookkeeping, owner only: a task's delivery command was
-- submitted; a delivered task's report arrived. False when the task is not
-- in the state the step needs, and then nothing is recorded.
create or replace function spawn_task_delivered(p_task bigint, p_command bigint)
returns boolean language plpgsql security definer as $$
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record deliveries', session_user using errcode = '42501';
    end if;
    -- A task of a closed mission, or of a retired resident, is not
    -- delivered (the closure rule).
    if not exists (select 1 from mission_tasks where id = p_task and state in ('assigned', 'revise'))
       or not spawn_task_may_move(p_task, 'delivered') then
        return false;
    end if;
    -- A delivery planned before a move (objective 239, task.stolen) is
    -- never recorded for the old worker: the command's session must be the
    -- task's worker's now. Only a moved task is checked: a task never moved
    -- keeps the session it was assigned to.
    if exists (select 1 from spawn_commands c join mission_tasks k on k.id = p_task
                where c.id = p_command and k.stolen_at_ms is not null
                  and c.session_id is distinct from k.session_id) then
        return false;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.delivered', 'id', p_task, 'command_id', p_command));
    return true;
end $$;

-- Record a report. `p_commit` names the agent's checkpoint the report's
-- turn ended with (its latest `artifact.committed` when the turn's end was
-- recorded): the integrator judges the report against it, never against an
-- older checkpoint. Null only when the agent has no checkpoint at all; the
-- first version took none, and still records a null commit.
create or replace function spawn_task_reported(p_task bigint, p_report text, p_commit text)
returns boolean language plpgsql security definer as $$
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record reports', session_user using errcode = '42501';
    end if;
    -- A report of work the closure rule dropped is not taken.
    if not exists (select 1 from mission_tasks where id = p_task and state = 'delivered')
       or not spawn_task_may_move(p_task, 'reported') then
        return false;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.reported', 'id', p_task, 'report', p_report, 'commit', p_commit));
    return true;
end $$;

create or replace function spawn_task_reported(p_task bigint, p_report text)
returns boolean language plpgsql security definer as $$
begin
    return spawn_task_reported(p_task, p_report, null);
end $$;

-- Whether a report of `p_task` whose content has digest `p_digest` was
-- already found unfinished for the task's current revision (its
-- `task.report_unfinished` record): its worker was told, once, for that
-- content.
create or replace function spawn_task_report_unfinished_recorded(p_task bigint, p_digest text)
returns boolean language sql stable security definer as $$
    select exists (
        select 1
          from spawn_events e
          join mission_tasks k on k.id = p_task
         where e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and e.kind -> 'detail' -> 'record' ->> 'type' = 'task.report_unfinished'
           and e.kind -> 'detail' -> 'record' ->> 'id' = p_task::text
           and e.kind -> 'detail' -> 'record' ->> 'digest' = p_digest
           and (e.kind -> 'detail' -> 'record' ->> 'revision')::integer = k.revisions)
$$;

-- Record that a delivered task's report was read and not taken: it is still
-- a draft (crates/spawn-cli/src/deliver/unfinished.rs). The record names the
-- task's revision, the content's `digest`, the `markers` found (each with
-- its line) and the note that tells the worker (`note`, its idempotency key,
-- and `command_id`). Once per revision and content: false, and nothing
-- recorded, when that content was recorded already, or the task is not
-- delivered. The task stays delivered.
create or replace function spawn_task_report_unfinished(p_task bigint, p_digest text,
                                                        p_markers jsonb, p_note text,
                                                        p_command bigint)
returns boolean language plpgsql security definer as $$
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record reports', session_user using errcode = '42501';
    end if;
    if not exists (select 1 from mission_tasks where id = p_task and state = 'delivered')
       or spawn_task_report_unfinished_recorded(p_task, p_digest) then
        return false;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.report_unfinished', 'id', p_task,
        'revision', (select revisions from mission_tasks where id = p_task),
        'digest', p_digest, 'markers', p_markers, 'note', p_note, 'command_id', p_command));
    return true;
end $$;

-- The dispatcher's fork of an assigned objective task's workspace from its
-- predecessor's work failed (crates/spawn-cli/src/main_merge.rs
-- `fork_from_prior`). Recorded once per task, the first failure's error,
-- the predecessor and its commit; returns how long ago that first failure
-- was recorded (ms, the database's clock), from which the dispatcher stops
-- holding the task's Start and starts it without the fork. A task that is
-- not assigned records nothing (null).
create or replace function spawn_task_fork_failed(p_task bigint, p_from bigint, p_commit text,
                                                  p_error text)
returns bigint language plpgsql security definer as $$
declare
    v_first bigint;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record forks', session_user using errcode = '42501';
    end if;
    if not exists (select 1 from mission_tasks where id = p_task and state = 'assigned') then
        return null;
    end if;
    select min(e.recorded_at_ms) into v_first
      from spawn_events e
     where e.session_id = 'session_control' and e.event_name = 'control.recorded'
       and e.kind -> 'detail' -> 'record' ->> 'id' = p_task::text
       and e.kind -> 'detail' -> 'record' ->> 'type' = 'task.fork_failed';
    if v_first is null then
        perform spawn_control_record(jsonb_build_object(
            'type', 'task.fork_failed', 'id', p_task, 'from', p_from, 'commit', p_commit,
            'error', p_error));
        return 0;
    end if;
    return spawn_now_ms() - v_first;
end $$;

-- Review a report: accept, or send it back with a note. `p_revision` names
-- the revision of the report the reviewer read (`revisions` in the news and
-- the board); a review of another revision is refused, so a decision on an
-- old report never lands on a newer one. Without it, the report as it is
-- now (a human at the command line); the record names that revision either
-- way. A mission whose gate alone accepts takes no review: its gate is
-- judging the report, and a review would send back the revision it judges.
-- The first version named no revision.
drop function if exists spawn_task_review(bigint, boolean, text);
create or replace function spawn_task_review(p_task bigint, p_accept boolean, p_note text,
                                             p_revision integer default null)
returns void language plpgsql security definer as $$
declare
    v_revision integer;
    v_state text;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is null then
        raise exception '% may not review tasks', session_user using errcode = '42501';
    end if;
    if not p_accept and coalesce(trim(p_note), '') = '' then
        raise exception 'sending a task back needs a note';
    end if;
    -- A task that is not `reported` is refused naming its state (an
    -- accept on a task its gate already accepted reads "task N is
    -- accepted", one sent back "task N is sent back for revision"), and a
    -- task that does not exist says so (GitHub #63, part 3).
    select state, revisions into v_state, v_revision from mission_tasks where id = p_task;
    if v_state is null then
        raise exception 'task % does not exist: it has no report to review', p_task;
    end if;
    if v_state <> 'reported' then
        raise exception 'task % is %: it has no report to review', p_task,
                        case v_state when 'revise' then 'sent back for revision'
                                     else v_state end;
    end if;
    if p_revision is not null and p_revision <> v_revision then
        raise exception 'task % is at revision %, not %: read its report again', p_task,
                        v_revision, p_revision;
    end if;
    if exists (select 1 from mission_tasks k join mission_missions m on m.id = k.mission_id
                where k.id = p_task and m.gate is not null and m.accept = 'gate') then
        raise exception 'task % belongs to a mission its gate alone accepts: it is not reviewed',
                        p_task;
    end if;
    -- A closed mission, or a retired resident, takes no new work: the
    -- report is accepted (when its mission still lands work) or cancelled.
    if not spawn_task_may_move(p_task, case when p_accept then 'accepted' else 'revise' end) then
        raise exception 'task % belongs to a closed mission or a retired resident: it may not %',
                        p_task, case when p_accept then 'be accepted' else 'be sent back' end;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.reviewed', 'id', p_task, 'accepted', p_accept, 'note', p_note,
        'revision', v_revision));
end $$;

-- A grading record's grade: its rank when it is a wire name (`l1` to
-- `l3`), else null. The checked writers take nothing else; the folds also
-- read a bare rank (spawn_grade_rank).
create or replace function spawn_grade_wire(p_grade jsonb) returns smallint
language sql immutable as $$
    select case when jsonb_typeof(p_grade) = 'string'
                then case p_grade #>> '{}' when 'l1' then 1 when 'l2' then 2 when 'l3' then 3 end
           end::smallint
$$;
revoke execute on function spawn_grade_wire(jsonb) from public;

-- Agent grading's rework step-up (docs/agent-grading.md): a task sent back
-- for its quality runs its next revision on a stronger graded preset. The
-- CLI routes it (`route_preset`, at `TaskDifficulty::for_rework` of the
-- task's quality rejections, the review that sent it back counted) and
-- names the preset; this checks and records `task.rerouted` {id,
-- preset_id, model, from_preset_id, revision, routed_difficulty}, the
-- model the preset's own and the difficulty a wire name (`l1` to `l3`).
-- Refused, recording nothing, for a task that is not sent back, at another
-- revision, assigned without the catalog, routed at another difficulty
-- than its quality rejections step it up to, or to its own preset, or to
-- a preset not in the catalog, not routable, or graded below it. Returns
-- the record.
create or replace function spawn_task_reroute(p_task bigint, p_preset text, p_revision integer,
                                              p_routed_difficulty integer)
returns jsonb language plpgsql security definer as $$
declare
    v_task mission_tasks%rowtype;
    v_preset grading_presets%rowtype;
    v_needed integer;
    v_record jsonb;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is null then
        raise exception '% may not reroute tasks', session_user using errcode = '42501';
    end if;
    select * into v_task from mission_tasks where id = p_task;
    if v_task.id is null then
        raise exception 'task % does not exist: there is nothing to reroute', p_task;
    end if;
    if v_task.state <> 'revise' then
        raise exception 'task % is %, not sent back: only a task sent back is rerouted',
            p_task, v_task.state;
    end if;
    if v_task.revisions is distinct from p_revision then
        raise exception 'task % is at revision %, not %: route it again', p_task,
            v_task.revisions, p_revision;
    end if;
    if v_task.preset_id is null then
        raise exception 'task % was assigned without the grading catalog: it is not rerouted',
            p_task;
    end if;
    -- `TaskDifficulty::for_rework`, the same thresholds.
    v_needed := case when v_task.difficulty = 1 and v_task.quality_rejections >= 3 then 3
                     when v_task.difficulty = 1 and v_task.quality_rejections >= 1 then 2
                     when v_task.difficulty = 2 and v_task.quality_rejections >= 2 then 3
                     else v_task.difficulty end;
    if p_routed_difficulty is distinct from v_needed then
        raise exception 'task % of difficulty l% after % quality rejections is routed at l%, not %',
            p_task, v_task.difficulty, v_task.quality_rejections, v_needed,
            coalesce('l' || p_routed_difficulty, 'nothing');
    end if;
    if p_preset is not distinct from v_task.preset_id then
        raise exception 'task % runs on preset % already: a reroute names another', p_task,
            p_preset;
    end if;
    select * into v_preset from grading_presets where preset_id = p_preset;
    if v_preset.preset_id is null then
        raise exception 'preset % is not in the grading catalog', p_preset;
    end if;
    if v_preset.state not in ('active', 'demoted') then
        raise exception 'preset % is %: only an active or demoted preset is routed',
            p_preset, v_preset.state;
    end if;
    if coalesce(v_preset.locked_grade, v_preset.calibrated_grade, 0) < p_routed_difficulty then
        raise exception 'preset % is graded below the l% task % is routed at', p_preset,
            p_routed_difficulty, p_task;
    end if;
    v_record := jsonb_build_object(
        'type', 'task.rerouted', 'id', p_task, 'preset_id', p_preset,
        'model', v_preset.model_profile, 'from_preset_id', v_task.preset_id,
        'revision', p_revision, 'routed_difficulty', 'l' || p_routed_difficulty)
        -- Phase 2: the preset's named execution profile, when it has one.
        || case when v_preset.execution_profile is not null
                then jsonb_build_object('execution_profile', v_preset.execution_profile)
                else '{}'::jsonb end;
    perform spawn_control_record(v_record);
    return v_record;
end $$;

-- The grading catalog's log: every change is one `grading.recorded` event
-- of the control session (agent `agent_control`, source `control`), as the
-- nodes' `node.recorded` are, and outside the control fold: no
-- spawn_control_refold reads them, and `grading_presets` is their fold
-- alone. Applying a record never validates: the log is the truth, and
-- replaying it (`spawn_grading_refold`) gives the same table. Grades are
-- wire names (`l1` to `l3`, null for none). Records:
--   preset.registered    {preset_id, engine_label, model_label, model_profile, cost_rank,
--                         execution_profile (phase 2, optional: a named profile)}
--   preset.onboarded     {preset_id, from_state, to_state, to_grade (null: failed l1),
--                         passed, total, failed_cases, suite}
--   preset.regraded      {preset_id, decision, from_grade, to_grade, from_state, to_state,
--                         first_pass, total}                      (calibration)
--   preset.grade_locked  {preset_id, from_grade, to_grade (null: unlocked), from_state,
--                         to_state}
--   preset.state_changed {preset_id, from_state, to_state}
create or replace function spawn_grading_apply(p_record jsonb, p_at bigint, p_event bigint)
returns void language plpgsql as $$
declare
    v_id text := p_record ->> 'preset_id';
begin
    case p_record ->> 'type'
    when 'preset.registered' then
        insert into grading_presets (preset_id, engine_label, model_label, model_profile,
                                     cost_rank, state, window_start_ms, created_at_ms,
                                     updated_at_ms, last_event, execution_profile)
        values (v_id, p_record ->> 'engine_label', p_record ->> 'model_label',
                p_record ->> 'model_profile', (p_record ->> 'cost_rank')::integer,
                'unexamined', p_at, p_at, p_at, p_event, p_record ->> 'execution_profile');
    when 'preset.onboarded' then
        update grading_presets
           set onboarded_grade = spawn_grade_rank(p_record ->> 'to_grade'),
               calibrated_grade = spawn_grade_rank(p_record ->> 'to_grade'),
               state = p_record ->> 'to_state', window_start_ms = p_at, updated_at_ms = p_at,
               last_event = p_event
         where preset_id = v_id;
    when 'preset.regraded' then
        update grading_presets
           set calibrated_grade = spawn_grade_rank(p_record ->> 'to_grade'),
               state = p_record ->> 'to_state', window_start_ms = p_at, updated_at_ms = p_at,
               last_event = p_event
         where preset_id = v_id;
    when 'preset.grade_locked' then
        update grading_presets
           set locked_grade = spawn_grade_rank(p_record ->> 'to_grade'),
               state = p_record ->> 'to_state', window_start_ms = p_at, updated_at_ms = p_at,
               last_event = p_event
         where preset_id = v_id;
    when 'preset.state_changed' then
        -- A preset enabled again starts its calibration window afresh.
        update grading_presets
           set state = p_record ->> 'to_state',
               window_start_ms = case when p_record ->> 'to_state' = 'disabled'
                                      then window_start_ms else p_at end,
               updated_at_ms = p_at, last_event = p_event
         where preset_id = v_id;
    else
        raise exception 'unknown grading record %', p_record ->> 'type';
    end case;
end $$;

-- Check one grading record against the catalog and append it (owner only:
-- the people and scripts that run `spawn grade`). Refused, recording
-- nothing, naming the first rule that fails. Every record but a
-- registration names the state it moves the preset from, which must be its
-- state now, and the state it moves it to, which must be the one the rule
-- gives; none moves a preset to the state it is in. Returns its event's id.
create or replace function spawn_grading_record(p_record jsonb)
returns bigint language plpgsql security definer as $$
declare
    v_type text := p_record ->> 'type';
    v_id text := p_record ->> 'preset_id';
    v_preset grading_presets%rowtype;
    v_keys text[];
    v_from smallint;
    v_to smallint;
    v_state text;
    v_event bigint;
    v_at bigint;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record grading', session_user using errcode = '42501';
    end if;
    v_keys := case v_type
        when 'preset.registered' then
            array['type', 'preset_id', 'engine_label', 'model_label', 'model_profile', 'cost_rank']
        when 'preset.onboarded' then
            array['type', 'preset_id', 'from_state', 'to_state', 'to_grade', 'passed', 'total',
                  'failed_cases', 'suite']
        when 'preset.regraded' then
            array['type', 'preset_id', 'decision', 'from_grade', 'to_grade', 'from_state',
                  'to_state', 'first_pass', 'total']
        when 'preset.grade_locked' then
            array['type', 'preset_id', 'from_grade', 'to_grade', 'from_state', 'to_state']
        when 'preset.state_changed' then array['type', 'preset_id', 'from_state', 'to_state']
        end;
    if v_keys is null then
        raise exception 'not a grading record: %', v_type;
    end if;
    -- Phase 2: a registration may name its execution profile.
    if v_type = 'preset.registered' and p_record ? 'execution_profile' then
        v_keys := array_append(v_keys, 'execution_profile');
    end if;
    if exists (select 1 from jsonb_object_keys(p_record) k where k <> all(v_keys))
       or exists (select 1 from unnest(v_keys) k where not p_record ? k) then
        raise exception 'a % record has %, and nothing else', v_type, array_to_string(v_keys, ', ');
    end if;
    if jsonb_typeof(p_record -> 'preset_id') is distinct from 'string'
       or v_id !~ '^[a-z0-9][a-z0-9_-]{0,63}$' then
        raise exception 'a preset id is [a-z0-9][a-z0-9_-]{0,63}, not %', p_record -> 'preset_id';
    end if;
    select * into v_preset from grading_presets where preset_id = v_id;
    if v_type = 'preset.registered' then
        if v_preset.preset_id is not null then
            raise exception 'preset % is already in the grading catalog', v_id;
        end if;
        if exists (select 1 from unnest(array['engine_label', 'model_label']) f
                    where jsonb_typeof(p_record -> f) is distinct from 'string'
                       or char_length(p_record ->> f) not between 1 and 200
                       or p_record ->> f ~ '^[[:space:]]*$') then
            raise exception 'a preset''s engine and model labels are 1 to 200 characters, not blank';
        end if;
        if p_record ->> 'model_profile' is null
           or p_record ->> 'model_profile' not in ('default', 'cheap') then
            raise exception 'a preset runs on the default or cheap model profile, not %',
                p_record -> 'model_profile';
        end if;
        if p_record ? 'execution_profile'
           and (jsonb_typeof(p_record -> 'execution_profile') is distinct from 'string'
                or p_record ->> 'execution_profile' !~ '^[a-z0-9][a-z0-9_-]{0,63}$'
                or p_record ->> 'execution_profile' in ('default', 'cheap')) then
            raise exception 'a preset''s execution profile is a name [a-z0-9][a-z0-9_-]{0,63} other than default and cheap (those are model_profile), not %',
                p_record -> 'execution_profile';
        end if;
        if (case when jsonb_typeof(p_record -> 'cost_rank') = 'number'
                 then (p_record ->> 'cost_rank')::numeric
                          <> trunc((p_record ->> 'cost_rank')::numeric)
                      or (p_record ->> 'cost_rank')::numeric not between 0 and 1000000
                 else true end) then
            raise exception 'a preset''s cost rank is a whole number from 0 to 1000000, not %',
                p_record -> 'cost_rank';
        end if;
    else
        if v_preset.preset_id is null then
            raise exception 'preset % is not in the grading catalog', v_id;
        end if;
        if p_record ->> 'from_state' is distinct from v_preset.state then
            raise exception 'preset % is %, not %', v_id, v_preset.state, p_record -> 'from_state';
        end if;
        case v_type
        when 'preset.onboarded' then
            if not (jsonb_typeof(p_record -> 'to_grade') = 'null'
                    or spawn_grade_wire(p_record -> 'to_grade') is not null) then
                raise exception 'an onboarding grade is l1, l2, l3 or null, not %',
                    p_record -> 'to_grade';
            end if;
            -- A person's disable stands until a person enables it: only a
            -- preset that has never had a grade (it failed l1) is examined
            -- again while disabled.
            if v_preset.state = 'disabled'
               and coalesce(v_preset.onboarded_grade, v_preset.calibrated_grade,
                            v_preset.locked_grade) is not null then
                raise exception 'preset % is disabled: enable it (spawn grade enable %) before onboarding it again',
                    v_id, v_id;
            end if;
            v_state := case when p_record ->> 'to_grade' is null then 'disabled' else 'active' end;
            if p_record ->> 'to_state' is distinct from v_state then
                raise exception 'an onboarding with grade % leaves the preset %, not %',
                    coalesce(p_record ->> 'to_grade', 'none'), v_state, p_record -> 'to_state';
            end if;
            if jsonb_typeof(p_record -> 'passed') is distinct from 'number'
               or jsonb_typeof(p_record -> 'total') is distinct from 'number'
               or jsonb_typeof(p_record -> 'failed_cases') is distinct from 'array'
               or jsonb_typeof(p_record -> 'suite') is distinct from 'string' then
                raise exception 'an onboarding names passed and total (numbers), failed_cases (a list) and suite';
            end if;
        when 'preset.regraded' then
            v_from := spawn_grade_wire(p_record -> 'from_grade');
            v_to := spawn_grade_wire(p_record -> 'to_grade');
            if v_preset.locked_grade is not null then
                raise exception 'preset % has a locked grade: calibration leaves it alone', v_id;
            end if;
            if v_preset.state not in ('active', 'demoted') then
                raise exception 'preset % is %: calibration grades only a routed preset', v_id,
                    v_preset.state;
            end if;
            if v_from is null or v_from is distinct from v_preset.calibrated_grade then
                raise exception 'preset % is graded l%, not %', v_id, v_preset.calibrated_grade,
                    p_record -> 'from_grade';
            end if;
            if not coalesce(case p_record ->> 'decision'
                   when 'demote' then v_to = v_from - 1 and p_record ->> 'to_state' = 'demoted'
                   when 'restore' then v_to = v_from + 1 and v_to <= v_preset.onboarded_grade
                                       and p_record ->> 'to_state'
                                           = case when v_to = v_preset.onboarded_grade
                                                  then 'active' else 'demoted' end
                   when 'disable' then v_from = 1 and v_to = 1
                                       and p_record ->> 'to_state' = 'disabled'
                   else false end, false) then
                raise exception 'a calibration of preset % from % to % as % is not one step it takes',
                    v_id, p_record -> 'from_grade', p_record -> 'to_grade', p_record -> 'to_state';
            end if;
            if jsonb_typeof(p_record -> 'first_pass') is distinct from 'number'
               or jsonb_typeof(p_record -> 'total') is distinct from 'number' then
                raise exception 'a calibration names first_pass and total, numbers';
            end if;
        when 'preset.grade_locked' then
            if not (jsonb_typeof(p_record -> 'to_grade') = 'null'
                    or spawn_grade_wire(p_record -> 'to_grade') is not null) then
                raise exception 'a locked grade is l1, l2, l3 or null, not %', p_record -> 'to_grade';
            end if;
            if spawn_grade_wire(p_record -> 'from_grade') is distinct from v_preset.locked_grade
               or (jsonb_typeof(p_record -> 'from_grade') <> 'null'
                   and spawn_grade_wire(p_record -> 'from_grade') is null) then
                raise exception 'preset % has locked grade %, not %', v_id,
                    coalesce('l' || v_preset.locked_grade, 'none'), p_record -> 'from_grade';
            end if;
            v_to := spawn_grade_wire(p_record -> 'to_grade');
            if v_to is not distinct from v_preset.locked_grade then
                raise exception 'preset % has locked grade % already', v_id,
                    coalesce('l' || v_preset.locked_grade, 'none');
            end if;
            -- Unlocking the only grade of a routed preset leaves it
            -- ungraded: unexamined again, never routed on nothing.
            v_state := case when v_to is null and v_preset.calibrated_grade is null
                                 and v_preset.state in ('active', 'demoted')
                            then 'unexamined' else v_preset.state end;
            if p_record ->> 'to_state' is distinct from v_state then
                raise exception 'preset % with locked grade % is %, not %', v_id,
                    coalesce(p_record ->> 'to_grade', 'none'), v_state, p_record -> 'to_state';
            end if;
        when 'preset.state_changed' then
            if p_record ->> 'to_state' = p_record ->> 'from_state' then
                raise exception 'preset % is % already', v_id, v_preset.state;
            end if;
            if p_record ->> 'to_state' = 'disabled' then
                null;
            elsif coalesce(v_preset.locked_grade, v_preset.calibrated_grade) is null then
                raise exception 'preset % has no grade: onboard it or lock its grade before enabling it',
                    v_id;
            else
                v_state := case when v_preset.calibrated_grade is null
                                     or v_preset.calibrated_grade = v_preset.onboarded_grade
                                then 'active' else 'demoted' end;
                if p_record ->> 'to_state' is distinct from v_state then
                    raise exception 'preset % enabled is %, not %', v_id, v_state,
                        p_record -> 'to_state';
                end if;
            end if;
        end case;
    end if;
    select a.out_id, a.out_at into v_event, v_at
      from spawn_append_trusted('agent_control', 'session_control', null, 'control', null,
                                jsonb_build_object('name', 'grading.recorded',
                                                   'detail', jsonb_build_object('record', p_record))) a;
    perform spawn_grading_apply(p_record, v_at, v_event);
    return v_event;
end $$;

-- Rebuild the grading catalog from its log. Idempotent: it starts from an
-- empty table every time.
create or replace function spawn_grading_refold()
returns void language plpgsql as $$
declare
    v_event record;
begin
    perform pg_advisory_xact_lock(1399957335);
    delete from grading_presets;
    for v_event in
        select e.id, e.kind -> 'detail' -> 'record' as record, e.recorded_at_ms
          from spawn_events e
         where e.session_id = 'session_control' and e.event_name = 'grading.recorded'
         order by e.session_seq
    loop
        perform spawn_grading_apply(v_event.record, v_event.recorded_at_ms, v_event.id);
    end loop;
end $$;

create or replace function spawn_task_cancel(p_task bigint)
returns void language plpgsql security definer as $$
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is null then
        raise exception '% may not cancel tasks', session_user using errcode = '42501';
    end if;
    if not exists (
        select 1
          from mission_tasks k
          join mission_missions m on m.id = k.mission_id
         where k.id = p_task
           and (
               k.state in ('assigned', 'delivered', 'reported', 'revise')
               or (k.state = 'accepted' and m.gate is not null)
           )
    ) then
        raise exception 'task % is already closed', p_task;
    end if;
    perform spawn_control_record(jsonb_build_object('type', 'task.cancelled', 'id', p_task,
                                                    'by', spawn_task_cancel_by()));
end $$;

-- The dispatcher's re-issue, owner only (docs/fleet-architecture.md §3,
-- "Deliveries"): a task waiting for its first delivery, whose retries are
-- spent and none of whose attempts may have typed, is cancelled and
-- assigned again, in this one transaction, so its objective (if any) has a
-- task in flight throughout. `p_attempts` is every attempt of the spent
-- delivery, in order (`command`, `key`, `error`), as the dispatcher read
-- them from the queue: the `task.cancelled` record keeps them, names `by`
-- `spawn-dispatch` and `reissued_as` the new task, whose `task.assigned`
-- names `reissue_of` and copies the old task's mission, kind, worker (a
-- resident's; an ephemeral task gets a new worker with the same label, as
-- `spawn_task_assign` names it), brief, model, objective, scenario and
-- `created_by`. Refused for a task that is not `assigned` at revision 0,
-- one that is itself a re-issue, or one the closure rule holds. Returns the
-- new task's id.
create or replace function spawn_task_reissue(p_task bigint, p_attempts jsonb)
returns bigint language plpgsql security definer as $$
declare
    v_old mission_tasks%rowtype;
    v_id bigint;
    v_agent text;
    v_session text;
    v_label text;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not re-issue tasks', session_user using errcode = '42501';
    end if;
    select * into v_old from mission_tasks where id = p_task;
    if v_old.id is null then
        raise exception 'task % does not exist', p_task;
    end if;
    if v_old.state <> 'assigned' or v_old.revisions <> 0 then
        raise exception 'task % is %, not waiting for its first delivery: it is not re-issued',
            p_task, v_old.state;
    end if;
    if v_old.reissue_of is not null then
        raise exception 'task % re-issues task % already: it is not re-issued again',
            p_task, v_old.reissue_of;
    end if;
    if jsonb_typeof(p_attempts) is distinct from 'array' or jsonb_array_length(p_attempts) = 0 then
        raise exception 'the re-issue of task % names no attempts of its delivery', p_task;
    end if;
    if not exists (select 1 from mission_missions
                    where id = v_old.mission_id and state in ('open', 'active'))
       or not spawn_task_may_move(p_task, 'cancelled') then
        raise exception 'task % may not be assigned again (its mission or worker is closed)',
            p_task;
    end if;
    v_id := nextval(pg_get_serial_sequence('mission_tasks', 'id'));
    if v_old.kind = 'ephemeral' then
        v_label := coalesce(substring(v_old.agent_id from '^agent_worker_(.+)_[0-9]+$'), 'task');
        v_agent := format('agent_worker_%s_%s', v_label, v_id);
        v_session := format('session_worker_%s_%s', v_label, v_id);
    else
        v_agent := v_old.agent_id;
        v_session := v_old.session_id;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.cancelled', 'id', p_task, 'by', 'spawn-dispatch', 'reissued_as', v_id,
        'attempts', p_attempts));
    perform spawn_control_record(jsonb_strip_nulls(jsonb_build_object(
        'type', 'task.assigned', 'id', v_id, 'mission_id', v_old.mission_id,
        'kind', v_old.kind, 'agent_id', v_agent, 'session_id', v_session,
        'brief', v_old.brief, 'model', v_old.model, 'created_by', v_old.created_by,
        'objective', v_old.objective, 'scenario', v_old.scenario, 'reissue_of', p_task,
        'difficulty', case when v_old.difficulty <> 2 then 'l' || v_old.difficulty end,
        'preset_id', v_old.preset_id,
        'first_preset_id', nullif(v_old.first_preset_id, v_old.preset_id),
        'quality_rejections', nullif(v_old.quality_rejections, 0))));
    return v_id;
end $$;

-- Restart and reassign (docs/fleet-architecture.md §9, "Restart and
-- reassign"): a delivered task's worker that stalled is given a fresh
-- execution, or its task a fresh worker, keeping what it did. Both take a
-- `delivered` task only; any other (or an unknown one) is refused with its
-- state named (SQLSTATE 55000), and nothing is recorded. `p_by` is who asks,
-- as a `task.cancelled` names it (spawn_task_cancel_by; `human` for the page,
-- spawn_human_restart). Each returns `{task, session_id, agent_id}`: the
-- task and the worker that now carry the work. The `_as` functions are
-- called by the checked ones below, never granted to a login.
--
-- A restart records `task.restarted` {task, session_id, agent_id,
-- execution_id (the running one, else null), by, reason, n (from 1, per
-- task)}; the dispatcher stops that execution (`restart-<task>-<n>-stop`, a
-- Stop: its final checkpoint kept) and, once its end is recorded, resumes
-- the same native session (`restart-<task>-<n>`). The recovery records that
-- end `restarted`, `final`.
create or replace function spawn_task_restart_as(p_task bigint, p_reason text, p_by text)
returns jsonb language plpgsql security definer as $$
declare
    v_task mission_tasks%rowtype;
    v_execution text;
    v_n bigint;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    select * into v_task from mission_tasks where id = p_task;
    if v_task.id is null then
        raise exception 'task % does not exist: there is nothing to restart', p_task
            using errcode = '55000';
    end if;
    if v_task.state <> 'delivered' then
        raise exception 'task % is %, not delivered: only a delivered task''s worker is restarted',
            p_task, v_task.state using errcode = '55000';
    end if;
    select s.execution_id into v_execution
      from agent_status s where s.session_id = v_task.session_id and s.live;
    select count(*) + 1 into v_n
      from spawn_events e
     where e.session_id = 'session_control' and e.event_name = 'control.recorded'
       and e.kind -> 'detail' -> 'record' ->> 'type' = 'task.restarted'
       and e.kind -> 'detail' -> 'record' ->> 'task' = p_task::text;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.restarted', 'task', p_task, 'session_id', v_task.session_id,
        'agent_id', v_task.agent_id, 'execution_id', v_execution, 'by', p_by,
        'reason', nullif(btrim(coalesce(p_reason, '')), ''), 'n', v_n));
    return jsonb_build_object('task', p_task, 'session_id', v_task.session_id,
                              'agent_id', v_task.agent_id);
end $$;

-- A reassign, in one transaction as the re-issue does (spawn_task_reissue):
-- the old task's `task.cancelled` names `by`, `reason` and `reassigned_as`
-- (the new task); the new task's `task.assigned` names `reassign_of` (the
-- old) and copies its mission, brief, model, objective, scenario and
-- `created_by`, kind `ephemeral`, with a fresh worker named after the old
-- one's label (`agent_worker_<label>_<new id>`; a resident's name is its
-- label). The dispatcher stops the old worker (`reassign-<task>-stop`, its
-- final checkpoint kept), delivers the new task once it has ended, and its
-- branch starts from the old worker's last checkpoint (OBJECTIVE_FORK).
create or replace function spawn_task_reassign_as(p_task bigint, p_reason text, p_by text)
returns jsonb language plpgsql security definer as $$
declare
    v_old mission_tasks%rowtype;
    v_id bigint;
    v_agent text;
    v_session text;
    v_label text;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    select * into v_old from mission_tasks where id = p_task;
    if v_old.id is null then
        raise exception 'task % does not exist: there is nothing to reassign', p_task
            using errcode = '55000';
    end if;
    if v_old.state <> 'delivered' then
        raise exception 'task % is %, not delivered: only a delivered task is reassigned',
            p_task, v_old.state using errcode = '55000';
    end if;
    if not exists (select 1 from mission_missions
                    where id = v_old.mission_id and state in ('open', 'active'))
       or not spawn_task_may_move(p_task, 'cancelled') then
        raise exception 'task % may not be assigned again (its mission or worker is closed)',
            p_task using errcode = '55000';
    end if;
    v_id := nextval(pg_get_serial_sequence('mission_tasks', 'id'));
    v_label := coalesce(substring(v_old.agent_id from '^agent_worker_(.+)_[0-9]+$'),
                        (select r.name from mission_residents r where r.agent_id = v_old.agent_id),
                        'task');
    v_label := trim(both '_' from left(regexp_replace(lower(v_label), '[^a-z0-9]+', '_', 'g'), 20));
    if v_label = '' then v_label := 'task'; end if;
    v_agent := format('agent_worker_%s_%s', v_label, v_id);
    v_session := format('session_worker_%s_%s', v_label, v_id);
    perform spawn_control_record(jsonb_strip_nulls(jsonb_build_object(
        'type', 'task.cancelled', 'id', p_task, 'by', p_by,
        'reason', nullif(btrim(coalesce(p_reason, '')), ''), 'reassigned_as', v_id)));
    perform spawn_control_record(jsonb_strip_nulls(jsonb_build_object(
        'type', 'task.assigned', 'id', v_id, 'mission_id', v_old.mission_id,
        'kind', 'ephemeral', 'agent_id', v_agent, 'session_id', v_session,
        'brief', v_old.brief, 'model', v_old.model, 'created_by', v_old.created_by,
        'objective', v_old.objective, 'scenario', v_old.scenario, 'reassign_of', p_task,
        'difficulty', case when v_old.difficulty <> 2 then 'l' || v_old.difficulty end,
        'preset_id', v_old.preset_id,
        'first_preset_id', nullif(v_old.first_preset_id, v_old.preset_id),
        'quality_rejections', nullif(v_old.quality_rejections, 0))));
    return jsonb_build_object('task', v_id, 'session_id', v_session, 'agent_id', v_agent);
end $$;

-- The checked restart and reassign of the owner (the CLI) and the
-- supervisor's login: `by` as spawn_task_cancel_by names the caller.
create or replace function spawn_task_restart(p_task bigint, p_reason text)
returns jsonb language plpgsql security definer as $$
begin
    if spawn_mission_caller() is null then
        raise exception '% may not restart tasks', session_user using errcode = '42501';
    end if;
    return spawn_task_restart_as(p_task, p_reason, spawn_task_cancel_by());
end $$;

create or replace function spawn_task_reassign(p_task bigint, p_reason text)
returns jsonb language plpgsql security definer as $$
begin
    if spawn_mission_caller() is null then
        raise exception '% may not reassign tasks', session_user using errcode = '42501';
    end if;
    return spawn_task_reassign_as(p_task, p_reason, spawn_task_cancel_by());
end $$;

-- A person's restart or reassign from the agent page (`spawn serve`, `POST
-- /api/session/<id>/restart` and `/reassign`): the delivered task of
-- session `p_session` (its latest), restarted or reassigned with `by`
-- `human`. A session that holds no delivered task is refused (SQLSTATE
-- 55000, which the page answers 409) and nothing is recorded. Only the
-- `spawn_human` login may call it, beside `spawn_human_input` and
-- `spawn_human_key`; it may call no other mission function. `p_action` is
-- `restart` or `reassign`; the reason is at most 2000 bytes.
create or replace function spawn_human_task(p_session text, p_action text, p_reason text)
returns jsonb language plpgsql security definer as $$
declare
    v_task bigint;
begin
    if spawn_principal() is distinct from 'human' then
        raise exception '% may not restart or reassign as a person (only the spawn_human login does)',
            session_user using errcode = '42501';
    end if;
    if p_action is null or p_action not in ('restart', 'reassign') then
        raise exception 'a person restarts or reassigns, not %', coalesce(p_action, 'null')
            using errcode = '22023';
    end if;
    if octet_length(coalesce(p_reason, '')) > 2000 then
        raise exception 'a reason is at most 2000 bytes, not %', octet_length(p_reason)
            using errcode = '22023';
    end if;
    select k.id into v_task from mission_tasks k
     where k.session_id = p_session and k.state = 'delivered'
     order by k.id desc limit 1;
    if v_task is null then
        raise exception '% holds no delivered task: there is nothing to %', p_session, p_action
            using errcode = '55000';
    end if;
    if p_action = 'restart' then
        return spawn_task_restart_as(v_task, p_reason, 'human');
    end if;
    return spawn_task_reassign_as(v_task, p_reason, 'human');
end $$;

do $$
begin
    execute format('alter function spawn_human_task(text, text, text) set search_path = %I, pg_temp',
                   current_schema());
    execute 'revoke execute on function spawn_human_task(text, text, text) from public';
    execute format('grant execute on function spawn_human_task(text, text, text) to %I',
                   spawn_login_role('spawn_human'));
end
$$;

-- A resident starts only after a human approves it.
-- Whether `p_session`'s resident has a cancel notice not yet told: its
-- latest delivered task is cancelled, and no `cancel-notice-<task>-<n>`
-- command of the dispatcher is recorded (deliver::Work::blocked, as
-- CANCELLED_DELIVERIES reads it). The command's outcome does not block it.
create or replace function spawn_cancel_notice_untold(p_session text)
returns boolean language sql stable as $$
    select exists (
        select 1
          from mission_tasks k
          join mission_residents r on r.agent_id = k.agent_id and r.state <> 'retired'
         where k.session_id = p_session and k.state = 'cancelled' and k.kind = 'resident'
           and k.delivered_at_ms is not null
           and not exists (select 1 from mission_tasks later
                            where later.session_id = k.session_id and later.id <> k.id
                              and later.delivered_at_ms is not null
                              and (later.delivered_at_ms, later.id) > (k.delivered_at_ms, k.id))
           and not exists (select 1 from spawn_commands c
                            where c.session_id = k.session_id and c.principal = 'spawn-dispatch'
                              and c.idempotency_key like 'cancel-notice-' || k.id || '-%'))
$$;

-- Work stealing (objective 239, docs/fleet-architecture.md §3.2 "Work
-- stealing"): move `p_task`, queued and unstarted, to the idle resident
-- `p_to` of its worker's pool, `p_by` (`spawn-dispatch`, or `human` for
-- the owner's `spawn task steal`) naming who and `p_reason` why. Owner only
-- (the dispatcher's login and the owner's are the owner). Under the append
-- lock it checks, in this order, and refuses with the first rule that
-- fails, recording nothing: the task is queued (resident, assigned, never
-- revised, no `deliver-<task>-` command); not pinned; its mission open, not
-- paused, not halted; the taker an approved resident, not its worker; both
-- in one pool; the taker idle (no open task of its own, no cancel notice
-- not yet told); the task in its worker's queue, never the one delivery
-- gives its worker now. Then one `task.stolen`, folded onto the task's
-- session and agent. Returns {task, from_session, to_session, agent_id}.
create or replace function spawn_task_steal(p_task bigint, p_to text, p_by text,
                                            p_reason text default null)
returns jsonb language plpgsql security definer as $$
declare
    v_task mission_tasks;
    v_mission mission_missions;
    v_worker mission_residents;
    v_taker mission_residents;
    v_open record;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not move tasks', session_user using errcode = '42501';
    end if;
    if coalesce(trim(p_by), '') = '' then
        raise exception 'a move names who moves it';
    end if;
    select * into v_task from mission_tasks where id = p_task;
    if not found then
        raise exception 'task % is not queued (no such task)', p_task;
    end if;
    if v_task.kind <> 'resident' then
        raise exception 'task % is not queued (not a resident task)', p_task;
    end if;
    if v_task.state <> 'assigned' then
        raise exception 'task % is not queued (%)', p_task, v_task.state;
    end if;
    if v_task.revisions <> 0 then
        raise exception 'task % is not queued (revised)', p_task;
    end if;
    if exists (select 1 from spawn_commands
                where idempotency_key like 'deliver-' || p_task || '-%') then
        raise exception 'task % is not queued (a delivery command exists)', p_task;
    end if;
    select * into v_worker from mission_residents where agent_id = v_task.agent_id;
    if v_task.pinned then
        raise exception 'task % is pinned to %', p_task, coalesce(v_worker.name, v_task.agent_id);
    end if;
    select * into v_mission from mission_missions where id = v_task.mission_id;
    if v_mission.state not in ('open', 'active') then
        raise exception 'task % waits for its mission % (closed)', p_task, v_task.mission_id;
    end if;
    if v_mission.pause_event is not null then
        raise exception 'task % waits for its mission % (paused)', p_task, v_task.mission_id;
    end if;
    if v_mission.halted is not null then
        raise exception 'task % waits for its mission % (halted)', p_task, v_task.mission_id;
    end if;
    select * into v_taker from mission_residents where name = p_to;
    if not found then
        raise exception 'task % cannot go to % (no such resident)', p_task, p_to;
    end if;
    if v_taker.state = 'proposed' then
        raise exception 'task % cannot go to % (not approved)', p_task, p_to;
    end if;
    if v_taker.state = 'retired' then
        raise exception 'task % cannot go to % (retired)', p_task, p_to;
    end if;
    if v_taker.agent_id = v_task.agent_id then
        raise exception 'task % cannot go to % (already its worker)', p_task, p_to;
    end if;
    if v_worker.pool is null or v_taker.pool is null then
        raise exception 'task % cannot go to % (no pool)', p_task, p_to;
    end if;
    if v_worker.pool <> v_taker.pool then
        raise exception 'task % cannot go to % (pool % is not %)', p_task, p_to,
            v_worker.pool, v_taker.pool;
    end if;
    select k.id, k.state into v_open
      from mission_tasks k join mission_missions m on m.id = k.mission_id
     where k.session_id = v_taker.session_id
       and (k.state in ('assigned', 'delivered', 'reported', 'revise', 'landing')
            or (k.state = 'accepted' and m.gate is not null))
     order by k.id limit 1;
    if found then
        raise exception 'task % cannot go to % (not idle: task % %)', p_task, p_to,
            v_open.id, v_open.state;
    end if;
    if spawn_cancel_notice_untold(v_taker.session_id) then
        raise exception 'task % cannot go to % (not idle: a cancel notice is not told)',
            p_task, p_to;
    end if;
    -- In its worker's queue: the worker holds an open task delivery waits
    -- on, a cancel notice not yet told, or an older task of its own. A
    -- worker's own assigned tasks do not make it busy: an idle worker's
    -- oldest task is the one delivery gives it now.
    if not exists (select 1 from mission_tasks k join mission_missions m on m.id = k.mission_id
                    where k.session_id = v_task.session_id and k.id <> p_task
                      and (k.state in ('delivered', 'reported', 'revise', 'landing')
                           or (k.state = 'accepted' and m.gate is not null)
                           or (k.state = 'assigned' and k.id < p_task)))
       and not spawn_cancel_notice_untold(v_task.session_id) then
        raise exception 'task % is its worker''s next (its worker is idle)', p_task;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.stolen', 'id', p_task,
        'from_session', v_task.session_id, 'from_agent', v_task.agent_id,
        'to_session', v_taker.session_id, 'to_agent', v_taker.agent_id,
        'pool', v_taker.pool, 'by', p_by, 'reason', nullif(trim(coalesce(p_reason, '')), ''),
        'queued_since_ms', v_task.created_at_ms));
    return jsonb_build_object('task', p_task, 'from_session', v_task.session_id,
                              'to_session', v_taker.session_id, 'agent_id', v_taker.agent_id);
end $$;

drop function if exists spawn_resident_propose(text, text);
-- `p_pool` (objective 239): the resident's pool, whose members may take
-- each other's queued tasks once approved; null, none.
create or replace function spawn_resident_propose(p_name text, p_charter text,
                                                  p_pool text default null)
returns void language plpgsql security definer as $$
declare
    v_caller text := spawn_mission_caller();
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if v_caller is null then
        raise exception '% may not propose residents', session_user using errcode = '42501';
    end if;
    if coalesce(trim(p_charter), '') = '' then
        raise exception 'a resident needs a charter';
    end if;
    if coalesce(p_name, '') !~ '^[a-z][a-z0-9_]{0,30}$' then
        raise exception 'resident name % is not [a-z][a-z0-9_]{0,30}', p_name;
    end if;
    if p_pool is not null and p_pool !~ '^[a-z][a-z0-9_]{0,30}$' then
        raise exception 'pool % is not [a-z][a-z0-9_]{0,30}', p_pool;
    end if;
    if exists (select 1 from mission_residents where name = p_name and state <> 'proposed') then
        raise exception 'resident % exists and is not a proposal', p_name;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'resident.proposed', 'name', p_name, 'charter', p_charter,
        'proposed_by', case when v_caller = 'owner' then 'human' else v_caller end)
        || case when p_pool is not null then jsonb_build_object('pool', p_pool)
                else '{}'::jsonb end);
end $$;

create or replace function spawn_resident_approve(p_name text)
returns void language plpgsql security definer as $$
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only a human approves a resident' using errcode = '42501';
    end if;
    if not exists (select 1 from mission_residents where name = p_name and state = 'proposed') then
        raise exception 'resident % is not a proposal', p_name;
    end if;
    perform spawn_control_record(jsonb_build_object('type', 'resident.approved', 'name', p_name));
end $$;

create or replace function spawn_resident_retire(p_name text)
returns void language plpgsql security definer as $$
declare
    v_open bigint[];
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is null then
        raise exception '% may not retire residents', session_user using errcode = '42501';
    end if;
    if not exists (select 1 from mission_residents where name = p_name and state <> 'retired') then
        raise exception 'resident % is already retired', p_name;
    end if;
    select coalesce(array_agg(k.id), '{}') into v_open
      from mission_tasks k join mission_residents r on r.agent_id = k.agent_id
     where r.name = p_name and k.state <> 'cancelled';
    perform spawn_control_record(jsonb_build_object('type', 'resident.retired', 'name', p_name));
    perform spawn_task_record_cancelled(v_open);
end $$;

-- Landing settings and halts are a human's (§10.3): the owner's login only.
-- The first version took no objectives.
drop function if exists spawn_mission_configure(bigint, text, text, jsonb);
create or replace function spawn_mission_configure(p_mission bigint, p_gate text, p_accept text,
                                                   p_budget jsonb, p_objectives jsonb)
returns void language plpgsql security definer as $$
declare
    v_landing bigint;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only a human sets a mission''s gate' using errcode = '42501';
    end if;
    if p_gate is not null and left(p_gate, 1) <> '/' then
        raise exception 'a gate is an absolute path, not %', p_gate;
    end if;
    if coalesce(p_accept, 'review') not in ('review', 'gate') then
        raise exception 'a mission accepts by review or gate, not %', p_accept;
    end if;
    if not exists (select 1 from mission_missions where id = p_mission and state in ('open', 'active')) then
        raise exception 'mission % is not open', p_mission;
    end if;
    if p_objectives is not null and (left(coalesce(p_objectives ->> 'backlog', ''), 1) <> '/'
                                     or coalesce(p_objectives ->> 'resident', '') = '') then
        raise exception 'objectives need an absolute backlog and a resident';
    end if;
    -- The feature map's mapping is an identity file the page reads
    -- (crates/spawn-cli/src/serve/feature_map.rs): an absolute path, never
    -- a status.
    if p_objectives ? 'features'
       and (jsonb_typeof(p_objectives -> 'features') is distinct from 'string'
            or left(p_objectives ->> 'features', 1) <> '/') then
        raise exception 'a mission''s features is the absolute path of its feature map, not %',
            p_objectives -> 'features';
    end if;
    if p_objectives is not null and p_gate is null then
        raise exception 'objectives need a gate to land on';
    end if;
    -- A daily budget in money (objective 041): US dollars, above zero.
    if p_budget ? 'daily_usd'
       and (jsonb_typeof(p_budget -> 'daily_usd') is distinct from 'number'
            or (p_budget ->> 'daily_usd')::numeric <= 0) then
        raise exception 'a mission''s daily_usd is an amount of US dollars above zero, not %',
            p_budget -> 'daily_usd';
    end if;
    -- The worker limit: how many objective tasks may be in flight at once.
    if p_objectives ? 'workers'
       and (jsonb_typeof(p_objectives -> 'workers') is distinct from 'number'
            or (p_objectives ->> 'workers')::numeric < 1
            or (p_objectives ->> 'workers')::numeric > 128
            or (p_objectives ->> 'workers')::numeric <> trunc((p_objectives ->> 'workers')::numeric)) then
        raise exception 'an objective mission''s workers is a whole number from 1 to 128, not %',
            p_objectives -> 'workers';
    end if;
    -- Agents' branches reach only a directory on this host (the pusher's
    -- one producer since the cross-host cut): a gate on a URL would wait
    -- for a push nobody makes. A source the integrator cannot find is
    -- halted by it.
    if p_gate is not null and exists (
        select 1 from mission_missions
         where id = p_mission and sources ->> 0 is not null and left(sources ->> 0, 1) <> '/') then
        raise exception 'mission % has a remote source: a gate lands only on a directory on this host',
                        p_mission;
    end if;
    -- GitHub issue #9: a task in `landing` (accepted, not yet landed) is
    -- landed by the integrator only while its mission has a gate it accepts
    -- by; clearing the gate, or moving accept away from gate, would leave the
    -- task where nothing lands it and `spawn task cancel` refuses it. So
    -- neither goes through while a task of the mission is landing.
    select k.id into v_landing
      from mission_tasks k join mission_missions m on m.id = k.mission_id
     where k.mission_id = p_mission and k.state = 'landing'
       and ((m.gate is not null and p_gate is null)
            or (m.accept = 'gate' and coalesce(p_accept, 'review') <> 'gate'))
     order by k.id limit 1;
    if v_landing is not null then
        raise exception 'mission %: task % is landing; clearing the gate or moving accept away from gate waits until nothing lands',
            p_mission, v_landing;
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'mission.configured', 'id', p_mission, 'gate', p_gate,
        'accept', coalesce(p_accept, 'review'), 'budget', p_budget, 'objectives', p_objectives));
end $$;

-- Change some of a mission's settings and keep the rest (owner only;
-- `spawn mission configure`, objective 027). `p_change` names only what
-- changes: `gate` and `accept` replace theirs when present (a JSON null
-- gate clears it); `budget` and `objectives` merge key by key into the
-- current ones (a key set to null is removed, so `workers` falls back to
-- its default 1; the whole setting set to null is cleared; one left empty
-- is cleared). The result is computed from the mission's row read under
-- the append lock that records it, so a concurrent change is never lost and
-- no caller stores a configuration it did not read; `spawn_mission_configure`
-- checks it and records it whole: `mission.configured` always carries every
-- setting. A change that leaves the settings as they were records nothing.
-- Returns `{mission, before, after}`, each `{gate, accept, budget,
-- objectives}`.
create or replace function spawn_mission_reconfigure(p_mission bigint, p_change jsonb)
returns jsonb language plpgsql security definer as $$
declare
    v_gate text;
    v_accept text;
    v_budget jsonb;
    v_objectives jsonb;
    v_before jsonb;
    v_after jsonb;
    v_key text;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only a human sets a mission''s gate' using errcode = '42501';
    end if;
    if jsonb_typeof(p_change) is distinct from 'object' then
        raise exception 'a mission''s change is a JSON object, not %', p_change;
    end if;
    for v_key in select jsonb_object_keys(p_change) loop
        if v_key not in ('gate', 'accept', 'budget', 'objectives') then
            raise exception 'a mission has no setting %', v_key;
        end if;
    end loop;
    select gate, accept, budget, objectives into v_gate, v_accept, v_budget, v_objectives
      from mission_missions where id = p_mission and state in ('open', 'active');
    if not found then
        raise exception 'mission % is not open', p_mission;
    end if;
    -- The fold stores a setting recorded as null as JSON null: no setting.
    v_budget := nullif(v_budget, 'null'::jsonb);
    v_objectives := nullif(v_objectives, 'null'::jsonb);
    v_before := jsonb_build_object('gate', v_gate, 'accept', v_accept, 'budget', v_budget,
                                   'objectives', v_objectives);
    if p_change ? 'gate' then
        v_gate := p_change ->> 'gate';
    end if;
    if p_change ? 'accept' then
        v_accept := p_change ->> 'accept';
    end if;
    v_budget := spawn_settings_merge(v_budget, p_change, 'budget');
    v_objectives := spawn_settings_merge(v_objectives, p_change, 'objectives');
    v_after := jsonb_build_object('gate', v_gate, 'accept', coalesce(v_accept, 'review'),
                                  'budget', v_budget, 'objectives', v_objectives);
    if v_after is distinct from v_before then
        perform spawn_mission_configure(p_mission, v_gate, v_accept, v_budget, v_objectives);
    end if;
    return jsonb_build_object('mission', p_mission, 'before', v_before, 'after', v_after);
end $$;

-- One setting of `spawn_mission_reconfigure`: `p_current` with
-- `p_change -> p_name` merged into it key by key. Absent from `p_change`:
-- unchanged. A JSON null: cleared. A key set to null: removed. Empty after
-- the merge: cleared (null).
create or replace function spawn_settings_merge(p_current jsonb, p_change jsonb, p_name text)
returns jsonb language plpgsql immutable as $$
declare
    v_change jsonb := p_change -> p_name;
    v_merged jsonb;
begin
    if not p_change ? p_name then
        return p_current;
    end if;
    if jsonb_typeof(v_change) = 'null' then
        return null;
    end if;
    if jsonb_typeof(v_change) is distinct from 'object' then
        raise exception 'a mission''s % is a JSON object, not %', p_name, v_change;
    end if;
    -- Only this level's nulls are removed (jsonb_strip_nulls is deep).
    select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_merged
      from jsonb_each(coalesce(p_current, '{}'::jsonb) || v_change)
     where jsonb_typeof(value) <> 'null';
    return case when v_merged = '{}'::jsonb then null else v_merged end;
end $$;

-- The integrator assigns one of an objective mission's open objectives
-- (owner only). At most `objectives ->> 'workers'` (default 1) of the
-- mission's tasks are in flight at once (assigned until landed or
-- cancelled), and never two for one objective: both checked here, under the
-- append lock, so a second integrator or a stale read cannot oversubscribe.
-- The mission's resident, which must be approved, takes the task when it has
-- none open in the mission; otherwise a new per-task worker does (kind
-- ephemeral, agent `agent_worker_objective_<task>`), as `spawn_task_assign`
-- makes one: no approval, a fresh workspace from the source's main, stopped
-- by the dispatcher once its task lands or is cancelled.
drop function if exists spawn_objective_assign(bigint, integer, text, text);

drop function if exists spawn_objective_assign(bigint, integer, text, text, bigint);

-- An objective's task, assigned by the integrator (owner only). `p_continues`
-- names the overrun task whose work this one keeps (`task.over_budget`): the
-- record says so, and the task's workspace starts from that work
-- (`OBJECTIVE_FORK`). Returns the task's id.
-- Agent grading (docs/agent-grading.md), as `spawn_task_assign` takes it:
-- `p_model` (`default` or `cheap`), `p_difficulty` (1 to 3, `l2` by
-- default), `p_preset`, the graded preset the integrator routed the task to
-- (`spawn_core::grading::route_with_reprobe`), or null, and
-- `p_classification`, the difficulty classifier's decision on the
-- objective's own text. Checked as `spawn_task_assign` checks them. The
-- record names `model` when it is not `default`, `difficulty` and
-- `preset_id` when a preset is named or the difficulty is not the default,
-- the preset's `execution_profile` when it has one and `classification`
-- when there is one: called with the defaults (the five arguments the
-- scenarios give), the record is exactly what it was.
-- A continuation (`p_continues`) of a task routed through the catalog
-- keeps its grading, as a re-issue or reassign does: its difficulty, its
-- first preset (the one calibration counts it for) and its quality
-- rejections, on `p_preset` when the integrator names one, else on the
-- continued task's preset, with that preset's model and execution profile;
-- never the caller's difficulty, model or classification, which are a
-- fresh route's. The preset must still be routable and graded for the
-- continued task's rework difficulty (`TaskDifficulty::for_rework`, as
-- `spawn_task_reroute` steps it up): a named one that is not is refused;
-- when none is named and the continued task's own no longer is (disabled
-- or demoted since), the continuation is assigned as the caller's
-- arguments say, the old grading not carried. A continuation of a task
-- assigned without the catalog is as before.
create or replace function spawn_objective_assign(p_mission bigint, p_objective integer,
                                                  p_scenario text, p_brief text,
                                                  p_continues bigint default null,
                                                  p_model text default 'default',
                                                  p_difficulty integer default 2,
                                                  p_preset text default null,
                                                  p_classification jsonb default null)
returns bigint language plpgsql security definer as $$
declare
    v_id bigint;
    v_agent text;
    v_session text;
    v_kind text := 'resident';
    v_workers integer;
    v_open integer;
    v_preset grading_presets%rowtype;
    v_old mission_tasks%rowtype;
    v_model text := p_model;
    v_difficulty integer := p_difficulty;
    v_preset_id text := p_preset;
    v_classification jsonb := p_classification;
    v_first text;
    v_rejections integer;
    v_needed integer;
    v_carried boolean := false;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not assign objectives', session_user using errcode = '42501';
    end if;
    if p_model is null or p_model not in ('default', 'cheap') then
        raise exception 'a task runs on the default or cheap model profile, not %', p_model;
    end if;
    if p_difficulty is null or p_difficulty not in (1, 2, 3) then
        raise exception 'a task''s difficulty is 1, 2 or 3 (l1, l2 or l3), not %', p_difficulty;
    end if;
    if p_classification is not null
       and (jsonb_typeof(p_classification) <> 'object'
            or spawn_grade_wire(p_classification -> 'difficulty') is null
            or jsonb_typeof(p_classification -> 'signals') is distinct from 'array') then
        raise exception 'a classification is an object naming its difficulty and signals, not %',
            p_classification;
    end if;
    if p_continues is not null then
        select * into v_old from mission_tasks where id = p_continues;
    end if;
    if v_old.preset_id is not null then
        -- `TaskDifficulty::for_rework`, the same thresholds.
        v_needed := case when v_old.difficulty = 1 and v_old.quality_rejections >= 3 then 3
                         when v_old.difficulty = 1 and v_old.quality_rejections >= 1 then 2
                         when v_old.difficulty = 2 and v_old.quality_rejections >= 2 then 3
                         else v_old.difficulty end;
        select * into v_preset from grading_presets
         where preset_id = coalesce(p_preset, v_old.preset_id);
        if v_preset.preset_id is not null and v_preset.state in ('active', 'demoted')
           and coalesce(v_preset.locked_grade, v_preset.calibrated_grade, 0) >= v_needed then
            v_carried := true;
            v_preset_id := v_preset.preset_id;
            v_model := v_preset.model_profile;
            v_difficulty := v_old.difficulty;
            v_first := coalesce(v_old.first_preset_id, v_old.preset_id);
            v_rejections := v_old.quality_rejections;
            v_classification := null;
        elsif p_preset is not null then
            raise exception 'preset % does not take the continuation of task % (l% after % quality rejections, needing l%): only an active or demoted preset graded for it does',
                p_preset, p_continues, v_old.difficulty, v_old.quality_rejections, v_needed;
        else
            v_preset := null;
        end if;
    end if;
    if p_preset is not null and not v_carried then
        select * into v_preset from grading_presets where preset_id = p_preset;
        if v_preset.preset_id is null then
            raise exception 'preset % is not in the grading catalog', p_preset;
        end if;
        if v_preset.state not in ('active', 'demoted') then
            raise exception 'preset % is %: only an active or demoted preset is routed',
                p_preset, v_preset.state;
        end if;
        if coalesce(v_preset.locked_grade, v_preset.calibrated_grade, 0) < p_difficulty then
            raise exception 'preset % is graded %, below the l% task it is assigned', p_preset,
                coalesce('l' || coalesce(v_preset.locked_grade, v_preset.calibrated_grade),
                         'nothing'),
                p_difficulty;
        end if;
        if v_preset.model_profile <> p_model then
            raise exception 'preset % runs on the % model profile, not %', p_preset,
                v_preset.model_profile, p_model;
        end if;
    end if;
    select r.agent_id, r.session_id, coalesce((m.objectives ->> 'workers')::numeric::integer, 1)
      into v_agent, v_session, v_workers
      from mission_missions m join mission_residents r on r.name = m.objectives ->> 'resident'
     where m.id = p_mission and m.state in ('open', 'active') and r.state = 'approved';
    if v_agent is null then
        raise exception 'mission % has no open objectives with an approved resident', p_mission;
    end if;
    -- A paused mission gets no work until the owner resumes it.
    if exists (select 1 from mission_missions where id = p_mission and pause_event is not null) then
        raise exception 'mission % is paused by the owner: no objective is assigned until it is resumed',
            p_mission using errcode = '55000';
    end if;
    if exists (select 1 from mission_tasks
                where mission_id = p_mission and objective = p_objective
                  and state not in ('landed', 'cancelled')) then
        raise exception 'objective % of mission % already has a task in flight',
            p_objective, p_mission;
    end if;
    select count(*) into v_open from mission_tasks
     where mission_id = p_mission and state not in ('landed', 'cancelled');
    if v_open >= v_workers then
        raise exception 'mission % already has % tasks in flight (its workers: %)',
            p_mission, v_open, v_workers;
    end if;
    v_id := nextval(pg_get_serial_sequence('mission_tasks', 'id'));
    -- A continuation of an overrun always starts on a per-task worker: its
    -- workspace is made from the overrun's work (OBJECTIVE_FORK), which a
    -- resident's own branch no longer holds (its cancel set the work aside).
    if p_continues is not null
       or exists (select 1 from mission_tasks
                   where mission_id = p_mission and agent_id = v_agent
                     and state not in ('landed', 'cancelled')) then
        v_kind := 'ephemeral';
        v_agent := format('agent_worker_objective_%s', v_id);
        v_session := format('session_worker_objective_%s', v_id);
    end if;
    perform spawn_control_record(jsonb_build_object(
        'type', 'task.assigned', 'id', v_id, 'mission_id', p_mission, 'kind', v_kind,
        'agent_id', v_agent, 'session_id', v_session, 'brief', p_brief,
        'created_by', 'spawn-integrate', 'objective', p_objective, 'scenario', p_scenario)
        || jsonb_strip_nulls(jsonb_build_object('continues', p_continues))
        || case when v_model <> 'default'
                then jsonb_build_object('model', v_model) else '{}'::jsonb end
        || case when v_preset_id is not null or v_difficulty <> 2
                then jsonb_strip_nulls(jsonb_build_object('difficulty', 'l' || v_difficulty,
                                                          'preset_id', v_preset_id))
                else '{}'::jsonb end
        || case when v_carried
                then jsonb_strip_nulls(jsonb_build_object(
                         'first_preset_id', nullif(v_first, v_preset_id),
                         'quality_rejections', nullif(v_rejections, 0)))
                else '{}'::jsonb end
        || case when v_preset.execution_profile is not null
                then jsonb_build_object('execution_profile', v_preset.execution_profile)
                else '{}'::jsonb end
        || case when v_classification is not null
                then jsonb_build_object('classification', v_classification)
                else '{}'::jsonb end);
    return v_id;
end $$;

-- The one-time import of the retired RSI controller's attempts has run.
drop function if exists spawn_objective_import(bigint, integer, text, text, bigint);

-- The owner's resume (`spawn mission resume`, owner only). A paused
-- mission is unpaused, and only that: `mission.unpaused` {id, pause_event}
-- (a halt stays, for a second resume). A halted mission that is not paused
-- is resumed as before (`mission.resumed`). Anything else is refused and
-- records nothing.
create or replace function spawn_mission_resume(p_mission bigint)
returns void language plpgsql security definer as $$
declare
    v_pause bigint;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only a human resumes a halted or paused mission' using errcode = '42501';
    end if;
    select pause_event into v_pause from mission_missions where id = p_mission;
    if v_pause is not null then
        perform spawn_control_record(jsonb_build_object(
            'type', 'mission.unpaused', 'id', p_mission, 'pause_event', v_pause));
        return;
    end if;
    if not exists (select 1 from mission_missions where id = p_mission and halted is not null) then
        raise exception 'mission % is neither halted nor paused', p_mission;
    end if;
    perform spawn_control_record(jsonb_build_object('type', 'mission.resumed', 'id', p_mission));
end $$;

-- The owner holds a mission (`spawn mission pause`, objective 099; a human
-- only: an agent's login is refused). Records `mission.paused` {id, reason}
-- and returns its event id. While it is paused no objective is assigned to
-- it (`spawn_objective_assign`), nothing is delivered to its workers and
-- its resident is stopped by the dispatcher; `spawn_mission_resume`
-- unpauses it. A mission that does not exist, is closed or is already
-- paused is refused and nothing is recorded. A halted mission may be
-- paused: its halt stays as it is.
create or replace function spawn_mission_pause(p_mission bigint, p_reason text)
returns bigint language plpgsql security definer as $$
declare
    v_state text;
    v_pause bigint;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner (a human) pauses a mission; % may not', session_user
            using errcode = '42501';
    end if;
    if p_reason is not null and char_length(p_reason) > 500 then
        raise exception 'a pause''s reason is at most 500 characters' using errcode = '22023';
    end if;
    select state, pause_event into v_state, v_pause from mission_missions where id = p_mission;
    if not found then
        raise exception 'mission % does not exist', p_mission using errcode = 'P0002';
    end if;
    if v_state not in ('open', 'active') then
        raise exception 'mission % is closed (%): there is nothing to pause', p_mission, v_state
            using errcode = '55000';
    end if;
    if v_pause is not null then
        raise exception 'mission % is already paused (record %)', p_mission, v_pause
            using errcode = '55000';
    end if;
    return spawn_control_record(jsonb_build_object('type', 'mission.paused', 'id', p_mission,
                                                   'reason', nullif(p_reason, '')));
end $$;

-- A person's resume of a halted mission from the web page (`spawn serve`,
-- `POST /api/mission/<id>/resume`, objective 051): the `mission.resumed`
-- the owner's `spawn mission resume` records, folded alike, naming who
-- (`by`, the caller's principal: `human`), the halt it resumes (`halt`, the
-- `mission.halted` event the page showed) and its idempotency key (`key`).
-- Only the halt the mission is in now is resumed: a mission that is not
-- halted, or is halted on another halt (a page not refreshed since), is
-- refused with the reason (SQLSTATE 55000, which the page answers 409) and
-- nothing is recorded. A repeated key returns its first record, for the
-- same mission and halt only (another is refused, SQLSTATE 23505). No such
-- mission is SQLSTATE P0002 (404). Returns the record's event id. Only the
-- `spawn_human` login may call it, beside `spawn_human_input`,
-- `spawn_human_key`, `spawn_human_task` and `spawn_human_master_message`:
-- it resumes and does nothing else.
create or replace function spawn_human_resume(p_mission bigint, p_halt bigint, p_key text)
returns bigint language plpgsql security definer as $$
declare
    v_first record;
    v_halted text;
    v_halt bigint;
begin
    if spawn_principal() is distinct from 'human' then
        raise exception '% may not resume as a person (only the spawn_human login does)',
            session_user using errcode = '42501';
    end if;
    if coalesce(p_key, '') = '' or octet_length(p_key) > 256 or p_key ~ '[[:cntrl:]]' then
        raise exception 'a resume needs an idempotency key of 1 to 256 bytes, no control character'
            using errcode = '22023';
    end if;
    if p_mission is null or p_halt is null then
        raise exception 'a resume names its mission and the halt it resumes' using errcode = '22023';
    end if;
    -- Check and record under the append lock, so no other change interleaves
    -- (two first uses of one key that race are one resume).
    perform pg_advisory_xact_lock(1399957335);
    select e.id, e.kind -> 'detail' -> 'record' as r into v_first
      from spawn_events e
     where e.session_id = 'session_control' and e.event_name = 'control.recorded'
       and e.kind -> 'detail' -> 'record' ->> 'type' = 'mission.resumed'
       and e.kind -> 'detail' -> 'record' ->> 'by' = 'human'
       and e.kind -> 'detail' -> 'record' ->> 'key' = p_key
     order by e.id limit 1;
    if v_first.id is not null then
        if v_first.r ->> 'id' is distinct from p_mission::text
           or v_first.r ->> 'halt' is distinct from p_halt::text then
            raise exception 'idempotency key % was already used for another resume: send this one with a new key',
                quote_literal(p_key) using errcode = '23505';
        end if;
        return v_first.id;
    end if;
    select m.halted, m.halt_event into v_halted, v_halt
      from mission_missions m where m.id = p_mission;
    if not found then
        raise exception 'mission % does not exist', p_mission using errcode = 'P0002';
    end if;
    if v_halted is null then
        raise exception 'mission % is not halted: there is nothing to resume', p_mission
            using errcode = '55000';
    end if;
    if v_halt is distinct from p_halt then
        raise exception 'mission % is halted on %, not on %: reload the page to see its halt',
            p_mission, coalesce(v_halt::text, 'an earlier halt'), p_halt using errcode = '55000';
    end if;
    return spawn_control_record(jsonb_build_object(
        'type', 'mission.resumed', 'id', p_mission, 'by', spawn_principal(), 'halt', p_halt,
        'key', p_key));
end $$;

do $$
begin
    execute format('alter function spawn_human_resume(bigint, bigint, text) set search_path = %I, pg_temp',
                   current_schema());
    execute 'revoke execute on function spawn_human_resume(bigint, bigint, text) from public';
    execute format('grant execute on function spawn_human_resume(bigint, bigint, text) to %I',
                   spawn_login_role('spawn_human'));
end
$$;

-- The owner moved a source's main forward outside the gate (a deploy): the
-- missions whose baseline is `p_from` take `p_to` instead of halting. The
-- caller checks that `p_to` descends from `p_from`; returns how many missions
-- moved. A mission without a baseline yet, or halted, is left alone. The
-- move is recorded for every deploy, also when it moves no mission
-- (`missions` empty: the fold moves nothing then): a deploy is when a host
-- fault may have gone, and the dispatcher tries every spent delivery once
-- more after each `source.moved` record.
create or replace function spawn_source_moved(p_source text, p_from text, p_to text)
returns integer language plpgsql security definer as $$
declare
    v_count integer;
    v_missions jsonb;
    v_cleared jsonb;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner moves a source outside the gate' using errcode = '42501';
    end if;
    -- A halted mission keeps its baseline: the human who resumes it sees
    -- the source as it is, and the resume re-anchors it. One halt is not
    -- that: the integrator's `mission.halted` whose evidence is this very
    -- move (`cause` main_moved, this source, this from and to). The owner's
    -- record is the explanation the halt was waiting for, so the mission
    -- moves and the halt is cleared, as if the push had been recorded
    -- before the pass that saw it.
    select coalesce(jsonb_agg(m.id order by m.id) filter (where m.halted is null), '[]'::jsonb),
           coalesce(jsonb_agg(m.id order by m.id) filter (where m.halted is not null), '[]'::jsonb)
      into v_missions, v_cleared
      from mission_missions m
      left join lateral (
        select e.kind -> 'detail' -> 'record' as r
          from spawn_events e
         where e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and e.kind -> 'detail' -> 'record' ->> 'type' = 'mission.halted'
           and e.kind -> 'detail' -> 'record' ->> 'id' = m.id::text
         order by e.id desc limit 1) halt on true
     where m.sources ->> 0 = p_source
       -- Through the commit map (objective 173): a baseline or a halt
       -- recorded before a history rewrite names the commit it is now.
       and spawn_commit_now(m.baseline) = spawn_commit_now(p_from)
       and (m.halted is null
            or (halt.r ->> 'cause' = 'main_moved' and halt.r ->> 'source' = p_source
                and spawn_commit_now(halt.r ->> 'from') = spawn_commit_now(p_from)
                and spawn_commit_now(halt.r ->> 'to') = spawn_commit_now(p_to)));
    v_count := jsonb_array_length(v_missions) + jsonb_array_length(v_cleared);
    perform spawn_control_record(jsonb_build_object(
        'type', 'source.moved', 'source', p_source, 'from', p_from, 'to', p_to,
        'missions', (select coalesce(jsonb_agg(id order by id), '[]'::jsonb)
                       from jsonb_array_elements_text(v_missions || v_cleared) m(id)),
        'clear', v_cleared));
    return v_count;
end $$;

-- The owner asks for `p_commit` on a mission source's main (`spawn mission
-- push`, owner only): the commit already waits in the source at `p_ref`
-- (`refs/spawn-owner/<commit>`), and the integrator applies the request
-- between its own steps, under the landing hold, and records its outcome
-- (`source.moved` naming it, or `source.push_refused`). Nothing else moves:
-- no branch, no baseline, no gate. Returns the request's event id. The
-- source is one a gate lands on: a directory on this host with a mission.
-- `p_gated`: the integrator judges the landing with the source's gate
-- first, as a judging of its own between the source's gates; `p_urgent`: it
-- goes first and stops the judging in flight on the source
-- (design-owner-push-between-gates.md); `p_reason`: the owner's words, on
-- the record. Each is on the record only when given.
drop function if exists spawn_source_push_request(text, text, text);
create or replace function spawn_source_push_request(p_source text, p_commit text, p_ref text,
                                                     p_gated boolean default false,
                                                     p_urgent boolean default false,
                                                     p_reason text default null)
returns bigint language plpgsql security definer as $$
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner lands on a source' using errcode = '42501';
    end if;
    if not spawn_source_allowed(p_source) then
        raise exception 'not a mission source: %', p_source;
    end if;
    if left(p_source, 1) <> '/' then
        raise exception 'the source % is remote: agents'' branches reach only a directory on '
                        'this host, so nothing lands on it', p_source;
    end if;
    if not exists (select 1 from mission_missions where sources ->> 0 = p_source) then
        raise exception 'no mission is on the source %', p_source;
    end if;
    if p_commit is null or p_commit !~ '^[0-9a-f]{40}([0-9a-f]{24})?$' then
        raise exception 'a commit is named by its full hash, not %', p_commit;
    end if;
    if p_ref is distinct from 'refs/spawn-owner/' || p_commit then
        raise exception 'the owner''s commit waits at refs/spawn-owner/%, not %', p_commit, p_ref;
    end if;
    if length(coalesce(p_reason, '')) > 2000 then
        raise exception 'the reason is at most 2000 characters';
    end if;
    return spawn_control_record(jsonb_build_object(
        'type', 'source.push_requested', 'source', p_source, 'commit', p_commit,
        'ref', p_ref, 'by', 'human')
        || case when coalesce(p_gated, false) then jsonb_build_object('gated', true)
                else '{}'::jsonb end
        || case when coalesce(p_urgent, false) then jsonb_build_object('urgent', true)
                else '{}'::jsonb end
        || case when coalesce(p_reason, '') <> '' then jsonb_build_object('reason', p_reason)
                else '{}'::jsonb end);
end $$;

-- The integrator's hold on an owner's landing (owner only): the landing
-- hold's lock (spawn_landing_hold), so no task landing's push and its
-- record are ever split by an owner landing, and dropping a mission waits
-- for it. Released by spawn_landing_release.
create or replace function spawn_source_push_hold()
returns void language plpgsql security definer as $$
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not land work', session_user using errcode = '42501';
    end if;
    perform pg_advisory_lock(1399957337);
end $$;

-- The integrator's records (`spawn integrate`, owner only): gate verdicts,
-- landings, aborts over budget, halts, the landings an owner's hold keeps
-- waiting (`task.held`), the holds past their bound (`source.hold_expired`),
-- and the outcomes of the owner's landing requests (`source.moved` naming its
-- `request`, `source.push_refused`). Returns the record's event id; null for
-- a `task.held` already recorded for the task and hold (it records nothing).
create or replace function spawn_integrator_record(p_record jsonb)
returns bigint language plpgsql security definer as $$
declare
    v_mission bigint;
    v_stale bigint;
    v_recorded bigint;
    v_subject text;
    v_other text;
    v_request jsonb;
    v_hold mission_source_holds;
begin
    -- Check and record under the append lock, so no other change interleaves.
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record landings', session_user using errcode = '42501';
    end if;
    if p_record ->> 'type' is null
       or p_record ->> 'type' not in ('task.gated', 'task.landed', 'task.aborted', 'mission.halted',
                                      'task.held', 'source.hold_expired', 'task.cancelled',
                                      'source.moved', 'source.push_refused',
                                      'source.push_no_verdict',
                                      'task.over_budget', 'objective.solved',
                                      'source.main_red', 'source.main_probe',
                                      'source.main_green', 'task.shadow_gated',
                                      'integrator.draining', 'integrator.drained',
                                      'integrator.drain_expired', 'task.released',
                                      'integrator.started') then
        raise exception 'the integrator does not record %', p_record ->> 'type';
    end if;
    -- A release of a task the load-sensitive bound parked: by a person or
    -- the integrator (owner only, as every record here), naming who and
    -- why, of a task that is parked: a task that is not is refused, never
    -- a silent no-op.
    if p_record ->> 'type' = 'task.released'
       and (jsonb_typeof(p_record -> 'id') is distinct from 'number'
            or coalesce(p_record ->> 'by', '') = ''
            or coalesce(p_record ->> 'reason', '') = ''
            or not exists (select 1 from mission_tasks
                            where id = (p_record ->> 'id')::bigint
                              and gate_parked_pushed is not null)) then
        raise exception 'task.released names a parked task, its by and its reason: %',
            p_record using errcode = '22023';
    end if;
    -- A shadow verdict (spawn-cli integrate/shadow.rs): a gate runner judged
    -- a copy of what the primary judged, on the inputs it names. It is
    -- beside the verdict, never part of it: whatever the task's state now
    -- (it has usually landed), it moves nothing. It names its task, its
    -- runner, its inputs and the fields unlike the primary's, and compares
    -- the two verdicts (`agrees`) only on equal inputs.
    if p_record ->> 'type' = 'task.shadow_gated' then
        if jsonb_typeof(p_record -> 'id') is distinct from 'number'
           or not exists (select 1 from mission_tasks where id = (p_record ->> 'id')::bigint)
           or coalesce(p_record ->> 'runner', '') = ''
           or jsonb_typeof(p_record -> 'inputs') is distinct from 'object'
           or jsonb_typeof(p_record -> 'unequal') is distinct from 'array'
           or coalesce(jsonb_typeof(p_record -> 'agrees'), 'absent') not in ('boolean', 'null')
           or (jsonb_typeof(p_record -> 'agrees') = 'boolean'
               and jsonb_array_length(p_record -> 'unequal') > 0) then
            raise exception 'a task.shadow_gated names its task, runner, inputs and unequal, and agrees only on equal inputs: %',
                            p_record;
        end if;
        return spawn_control_record(p_record);
    end if;
    -- Who an integrator start that took the lock is (objective 234): its
    -- process, parent, ancestors, working directory, cgroup, gate, root and
    -- once, so a stray is named from the store. Each field's shape is
    -- checked alone, never its value; what /proc could not say is null.
    if p_record ->> 'type' = 'integrator.started' then
        if exists (select 1 from jsonb_object_keys(p_record) k
                    where k not in ('type', 'pid', 'ppid', 'parent_comm', 'ancestors', 'cwd',
                                    'cgroup', 'gate', 'gate_from_env', 'root', 'once')) then
            raise exception 'an integrator.started has type, pid, ppid, parent_comm, ancestors, cwd, cgroup, gate, gate_from_env, root and once, and nothing else: %',
                p_record using errcode = '22023';
        end if;
        if jsonb_typeof(p_record -> 'pid') is distinct from 'number'
           or (p_record ->> 'pid')::numeric < 1 then
            raise exception 'an integrator.started''s pid is a number from 1: %', p_record -> 'pid'
                using errcode = '22023';
        end if;
        if jsonb_typeof(p_record -> 'ppid') is distinct from 'number'
           or (p_record ->> 'ppid')::numeric < 0 then
            raise exception 'an integrator.started''s ppid is a number from 0: %', p_record -> 'ppid'
                using errcode = '22023';
        end if;
        if exists (select 1 from unnest(array['gate', 'root']) f
                    where jsonb_typeof(p_record -> f) is distinct from 'string'
                       or p_record ->> f = '') then
            raise exception 'an integrator.started''s gate and root are non-empty strings: %',
                p_record using errcode = '22023';
        end if;
        if exists (select 1 from unnest(array['gate_from_env', 'once']) f
                    where jsonb_typeof(p_record -> f) is distinct from 'boolean') then
            raise exception 'an integrator.started''s gate_from_env and once are booleans: %',
                p_record using errcode = '22023';
        end if;
        if exists (select 1 from unnest(array['parent_comm', 'cwd', 'cgroup']) f
                    where coalesce(jsonb_typeof(p_record -> f), 'absent') not in ('string', 'null')) then
            raise exception 'an integrator.started''s parent_comm, cwd and cgroup are strings or null: %',
                p_record using errcode = '22023';
        end if;
        if jsonb_typeof(p_record -> 'ancestors') is distinct from 'array'
           or exists (select 1 from jsonb_array_elements(p_record -> 'ancestors') a
                       where jsonb_typeof(a) is distinct from 'object'
                          or jsonb_typeof(a -> 'pid') is distinct from 'number'
                          or jsonb_typeof(a -> 'comm') is distinct from 'string') then
            raise exception 'an integrator.started''s ancestors are [{pid, comm}]: %',
                p_record -> 'ancestors' using errcode = '22023';
        end if;
        return spawn_control_record(p_record);
    end if;
    -- The integrator's own drain (`spawn integrate --drain`, SIGUSR1): its
    -- start names the tasks whose gates run and its bound; its end, drained
    -- (every gate recorded and landed) or expired at the bound (naming the
    -- tasks whose gates it stopped, which record nothing). Folded into no
    -- table: the dispatcher tells the supervisor of an expired drain.
    if p_record ->> 'type' like 'integrator.%' then
        if jsonb_typeof(p_record -> 'bound_s') is distinct from 'number'
           or (p_record ->> 'bound_s')::numeric not between 1 and 86400
           or (p_record ->> 'type' <> 'integrator.drained'
               and (jsonb_typeof(p_record -> 'gates') is distinct from 'array'
                    or exists (select 1 from jsonb_array_elements(p_record -> 'gates') g
                                where jsonb_typeof(g) is distinct from 'number'))) then
            raise exception 'an % names its bound_s (1 to 86400) and, but drained, its gates (task numbers): %',
                            p_record ->> 'type', p_record;
        end if;
        return spawn_control_record(p_record);
    end if;
    -- A judging's outcome names its judging (gate v2, design-gate-survives-
    -- restart.md D4): the id of the directory its gate writes into. A gate
    -- may outlive the integrator that started it, and a later one reaps it;
    -- a reap after a crash between record and cleanup may decide anew, and
    -- differently (the host-fault cap counts the judging's own host fault,
    -- main may have moved, a deploy may read the gate's exit otherwise). So
    -- the first outcome stands, and is returned to any later one before any
    -- other check, nothing more recorded:
    -- - one verdict (`task.gated`) per judging, whatever the verdict; the one
    --   second is the `stale` of a landing that found main moved after the
    --   judging's `accepted` (the `task.aborted` the done-mission rule below
    --   makes of a `stale` is that `stale`);
    -- - one `task.landed`;
    -- - one owner's outcome, `source.moved` or `source.push_refused`;
    -- - one owner's `source.push_no_verdict` (no outcome: the request stays
    --   pending), and none after that judging's outcome.
    -- A judging is about one task or one owner's request: an outcome naming
    -- another under a judging already recorded is refused, never swallowed.
    if p_record ? 'judging' then
        if p_record ->> 'type' not in ('task.gated', 'task.landed', 'source.moved',
                                       'source.push_refused', 'source.push_no_verdict')
           or jsonb_typeof(p_record -> 'judging') is distinct from 'string'
           or p_record ->> 'judging' !~ '^[0-9a-f]{16,64}$' then
            raise exception 'a judging names a gate''s outcome by 16 to 64 hex digits: %', p_record;
        end if;
        v_subject := case when p_record ->> 'type' like 'source.%'
                          then 'request ' || coalesce(p_record ->> 'request', '?')
                          else 'task ' || coalesce(p_record ->> 'id', '?') end;
        select r.subject into v_other
          from spawn_events e
         cross join lateral (
             select case when e.kind #>> '{detail,record,type}' like 'source.%'
                         then 'request ' || coalesce(e.kind #>> '{detail,record,request}', '?')
                         else 'task ' || coalesce(e.kind #>> '{detail,record,id}', '?') end
                    as subject) r
         where e.session_id = 'session_control'
           and e.kind #>> '{detail,record,judging}' = p_record ->> 'judging'
           and r.subject <> v_subject
         order by e.id
         limit 1;
        if v_other is not null then
            raise exception 'judging % is about % already, not %: %', p_record ->> 'judging',
                            v_other, v_subject, p_record;
        end if;
        select e.id into v_recorded
          from spawn_events e
         where e.session_id = 'session_control'
           and e.kind #>> '{detail,record,judging}' = p_record ->> 'judging'
           and case p_record ->> 'type'
               when 'task.gated' then
                   e.kind #>> '{detail,record,type}' in ('task.gated', 'task.aborted')
                   and (p_record ->> 'verdict' is distinct from 'stale'
                        or e.kind #>> '{detail,record,verdict}' is distinct from 'accepted')
               when 'task.landed' then e.kind #>> '{detail,record,type}' = 'task.landed'
               when 'source.push_no_verdict' then
                   e.kind #>> '{detail,record,type}'
                       in ('source.moved', 'source.push_refused', 'source.push_no_verdict')
               else e.kind #>> '{detail,record,type}' in ('source.moved', 'source.push_refused')
               end
         order by coalesce(e.kind #>> '{detail,record,verdict}', '')
                      = coalesce(p_record ->> 'verdict', '') desc,
                  e.id
         limit 1;
        if v_recorded is not null then
            return v_recorded;
        end if;
    end if;
    -- Main of a source red on a check (docs/fleet-architecture.md §10.3,
    -- "Main is red"): a red names its source, main, check and the shared
    -- failures, and says whether it is the first (`alert`, the store's: the
    -- owner is told once a red); a probe is due only an interval after the
    -- last red or probe on that main (`probe_ms`), so two missions on one
    -- source never probe at once; a green names the check that was red, and
    -- carries the red's `since_ms`.
    if p_record ->> 'type' = 'source.main_red' then
        if coalesce(p_record ->> 'source', '') = '' or coalesce(p_record ->> 'main', '') = ''
           or coalesce(p_record ->> 'scenario', '') !~ '^check-[^/[:space:]]+\.sh$'
           or jsonb_typeof(p_record -> 'failures') is distinct from 'array'
           or jsonb_array_length(p_record -> 'failures') = 0
           or jsonb_typeof(p_record -> 'task') is distinct from 'number' then
            raise exception 'a source.main_red names its source, main, check, failures and task: %',
                            p_record;
        end if;
        p_record := p_record || jsonb_build_object('alert', not exists (
            select 1 from mission_source_reds r where r.source = p_record ->> 'source'));
    end if;
    if p_record ->> 'type' = 'source.main_probe' then
        if jsonb_typeof(p_record -> 'probe_ms') is distinct from 'number'
           or (p_record ->> 'probe_ms')::numeric < 1
           or jsonb_typeof(p_record -> 'task') is distinct from 'number' then
            raise exception 'a source.main_probe names its task and probe_ms: %', p_record;
        end if;
        if not exists (
            select 1 from mission_source_reds r
             where r.source = p_record ->> 'source'
               -- Both through the commit map (objective 177): a red main
               -- recorded before a history rewrite is its new commit.
               and coalesce(spawn_commit_now(r.main), r.main)
                   = coalesce(spawn_commit_now(p_record ->> 'main'), p_record ->> 'main')
               and spawn_now_ms() - greatest(r.red_ms, coalesce(r.probed_ms, r.red_ms))
                   >= (p_record ->> 'probe_ms')::numeric) then
            raise exception 'no probe of % is due', p_record ->> 'source';
        end if;
    end if;
    if p_record ->> 'type' = 'source.main_green' then
        if not exists (select 1 from mission_source_reds r
                        where r.source = p_record ->> 'source'
                          and r.scenario = p_record ->> 'scenario') then
            raise exception '% is not red on %', p_record ->> 'source', p_record ->> 'scenario';
        end if;
        p_record := p_record || (select jsonb_build_object('since_ms', r.since_ms, 'red_main', r.main)
                                   from mission_source_reds r
                                  where r.source = p_record ->> 'source');
    end if;
    -- The integrator cancels one kind of task: an objective's task in flight
    -- whose objective ran out of attempts, which yields its slot
    -- (spawn-cli objectives.rs). The cancel's fold sets its work aside and
    -- counts toward no halt.
    if p_record ->> 'type' = 'task.cancelled' then
        -- In flight: for a yield, a task being worked again (not one whose
        -- gate runs now); for an objective solved on the base, the task
        -- whose gate just said so, `reported` too.
        if not exists (
            select 1 from mission_tasks
             where id = (p_record ->> 'id')::bigint and objective is not null
               and (state in ('assigned', 'delivered', 'revise')
                    or (state = 'reported' and p_record ->> 'yielded' is distinct from 'true'
                        and jsonb_typeof(p_record -> 'solved') = 'number'))) then
            raise exception 'the integrator cancels only an objective''s task in flight, not task %',
                            p_record ->> 'id';
        end if;
        -- Two kinds: the yield of a slot (out of attempts), and an
        -- objective already solved on the base (its scenario passes at the
        -- base commit), which ends the task and counts nothing against it.
        if p_record ->> 'yielded' is distinct from 'true' then
            if jsonb_typeof(p_record -> 'solved') is distinct from 'number' or not exists (
                select 1 from spawn_events e
                 where e.id = (p_record ->> 'solved')::bigint
                   and e.session_id = 'session_control'
                   and e.event_name = 'control.recorded'
                   and e.kind -> 'detail' -> 'record' ->> 'type' = 'objective.solved'
                   and e.kind -> 'detail' -> 'record' ->> 'task' = p_record ->> 'id') then
                raise exception 'the integrator cancels task % only as a yield or as an objective solved on the base',
                                p_record ->> 'id';
            end if;
        end if;
        p_record := p_record || jsonb_build_object('by', 'spawn-integrate');
    end if;
    -- A halt that says what moved it names the source and both commits, so
    -- `spawn mission moved` can tell this halt from any other and clear it
    -- when the owner records that very move (spawn_source_moved).
    if p_record ->> 'type' = 'mission.halted' and p_record ? 'cause' then
        if p_record ->> 'cause' is distinct from 'main_moved'
           or coalesce(p_record ->> 'source', '') = ''
           or coalesce(p_record ->> 'from', '') = ''
           or coalesce(p_record ->> 'to', '') = '' then
            raise exception 'a halt on a moved main names cause main_moved, the source and both commits: %',
                            p_record;
        end if;
    end if;
    -- An objective solved on the base: its scenario passes at the base
    -- commit, so the work could not change anything and the objective needs
    -- no task. Names the mission, the objective, the task it ends, the
    -- scenario, the base commit and the gate's log.
    if p_record ->> 'type' = 'objective.solved' then
        if coalesce(p_record ->> 'objective', '') !~ '^[0-9]{1,6}$'
           or coalesce(p_record ->> 'scenario', '') = ''
           or coalesce(p_record ->> 'base', '') = '' then
            raise exception 'an objective.solved names its objective, scenario and base: %',
                            p_record;
        end if;
    end if;
    -- An overrun names what it measured: its reason, its tool calls and the
    -- budget it ran past (the mission's, as it was). Its branch, commit and
    -- diff stat say what work the objective's next task continues.
    if p_record ->> 'type' = 'task.over_budget'
       and (coalesce(p_record ->> 'reason', '') = ''
            or jsonb_typeof(p_record -> 'tool_calls') is distinct from 'number'
            or jsonb_typeof(p_record -> 'budget') is distinct from 'object') then
        raise exception 'a task.over_budget names its reason, tool_calls and budget: %', p_record;
    end if;
    -- The outcome of an owner's landing names its request: a
    -- `source.push_requested` that has no outcome yet, so every request has
    -- at most one. A move names the request's source, where main went from
    -- and to, and is the owner's (`by`); the missions it moves are those on
    -- the source whose baseline was its `from` and that are not halted, as
    -- spawn_source_moved names them (`missions`), and those with no
    -- baseline yet, not halted (`without_baseline`).
    if p_record ->> 'type' in ('source.moved', 'source.push_refused') then
        if coalesce(p_record ->> 'request', '') !~ '^[0-9]{1,18}$' then
            raise exception 'an owner landing''s outcome names its request: %', p_record;
        end if;
        select e.kind -> 'detail' -> 'record' into v_request
          from spawn_events e
         where e.id = (p_record ->> 'request')::bigint
           and e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and e.kind -> 'detail' -> 'record' ->> 'type' = 'source.push_requested';
        if v_request is null then
            raise exception 'no owner landing request %', p_record ->> 'request';
        end if;
        if exists (
            select 1 from spawn_events o
             where o.session_id = 'session_control' and o.event_name = 'control.recorded'
               and o.kind -> 'detail' -> 'record' ->> 'type'
                   in ('source.push_requested', 'source.push_refused', 'source.moved')
               and o.kind -> 'detail' -> 'record' ->> 'request' = p_record ->> 'request') then
            raise exception 'the owner landing request % has its outcome already',
                            p_record ->> 'request';
        end if;
        if p_record ->> 'type' = 'source.moved' then
            if p_record ->> 'source' is distinct from v_request ->> 'source'
               or p_record ->> 'from' is null or p_record ->> 'to' is null then
                raise exception 'a source.moved names the request''s source %, from and to: %',
                                v_request ->> 'source', p_record;
            end if;
            p_record := p_record || jsonb_build_object('by', 'human', 'missions', (
                select coalesce(jsonb_agg(m.id order by m.id), '[]'::jsonb)
                  from mission_missions m
                 where m.sources ->> 0 = p_record ->> 'source'
                   and spawn_commit_now(m.baseline) = spawn_commit_now(p_record ->> 'from')
                   and m.halted is null),
                -- No baseline yet: a gate of theirs judging against the old
                -- main would make it their first one, and halt them at the
                -- next pass. They take the new main instead.
                'without_baseline', (
                select coalesce(jsonb_agg(m.id order by m.id), '[]'::jsonb)
                  from mission_missions m
                 where m.sources ->> 0 = p_record ->> 'source'
                   and m.baseline is null and m.halted is null));
        else
            if coalesce(p_record ->> 'reason', '') = '' then
                raise exception 'a source.push_refused names its reason: %', p_record;
            end if;
            p_record := p_record || jsonb_build_object('source', v_request ->> 'source',
                                                       'commit', v_request ->> 'commit');
        end if;
        return spawn_control_record(p_record);
    end if;
    -- A hold past its bound ends by this record alone, and only the active
    -- hold of its source, once the database's clock has reached its
    -- `expires_ms`: a release or a renewal recorded first wins. The store
    -- names the bound and the tasks waiting behind it, oldest first.
    if p_record ->> 'type' = 'source.hold_expired' then
        select * into v_hold from mission_source_holds where source = p_record ->> 'source';
        if v_hold.hold is null or v_hold.hold::text is distinct from p_record ->> 'hold' then
            raise exception 'hold % is not the active hold of %', p_record ->> 'hold',
                            p_record ->> 'source';
        end if;
        if spawn_now_ms() < v_hold.expires_ms then
            raise exception 'hold % on % expires at %, not before', v_hold.hold, v_hold.source,
                            v_hold.expires_ms;
        end if;
        return spawn_control_record(p_record || jsonb_build_object(
            'expires_ms', v_hold.expires_ms,
            'waiting', (select coalesce(jsonb_agg(k.id order by k.id), '[]'::jsonb)
                          from mission_tasks k
                         where k.state = 'landing' and k.held_by = v_hold.hold)));
    end if;
    if p_record ->> 'type' = 'task.gated'
       and p_record ->> 'verdict' not in ('accepted', 'rejected', 'conflict', 'incompatible',
                                          'aborted', 'stale', 'no_room', 'host_fault') then
        raise exception 'unknown gate verdict %', p_record ->> 'verdict';
    end if;
    -- A verdict says what it is about (objective 035): `code` for one on the
    -- work, `infrastructure` for one the host could not judge, `superseded`
    -- for `stale`. A record from before this change names none; one that
    -- names a class names its verdict's, never another.
    if p_record ->> 'type' = 'task.gated' and p_record ? 'class'
       and p_record ->> 'class' is distinct from (
           case when p_record ->> 'verdict' in ('accepted', 'rejected', 'conflict', 'incompatible')
                     then 'code'
                when p_record ->> 'verdict' in ('aborted', 'host_fault', 'no_room')
                     then 'infrastructure'
                when p_record ->> 'verdict' = 'stale' then 'superseded' end) then
        raise exception 'a % verdict is not of class %', p_record ->> 'verdict',
                        p_record ->> 'class';
    end if;
    -- A host fault names its evidence (§14): the failures the gate printed,
    -- each the host's, and, when the test database's log decided it, the
    -- crash lines stamped inside the gate's window (`failures`,
    -- `server_log`); the base's own disagreement (objective 033's
    -- `base_disagrees`, with its scenario, both exits and its run); or the
    -- gate's own fact (`gate`: a scenario's harness error on the base, or a
    -- check failing on the candidate and the base, naming the scenario and
    -- where); a sandbox that never started its command
    -- (`sandbox_never_started`: on `sandbox`, runs `never started`, what was
    -- to run, which may hold spaces, and the tree: `candidate`, `base` or
    -- `gate`); the gate's own test server that did not start
    -- (`test_server_never_started`: on `test server`, runs `never started`,
    -- scenario `test server`, and which start as its tree: `gate` or
    -- `candidate`); a validator's defect (`validator_defect`: on `candidate
    -- and base`, a scenario, and `validator_defects` naming at least one
    -- script, `<name>.sh`: a regression failing on the candidate and on the
    -- base, run again now, gate.sh's "Three classes of a failing
    -- regression"); a gate whose runner ended without its status
    -- (`abandoned`: on `runner`, runs `no status`; gate v2 step 2, D6); and
    -- its backoff.
    if p_record ->> 'type' = 'task.gated' and p_record ->> 'verdict' = 'host_fault'
       and (coalesce(p_record ->> 'evidence', '') not in ('failures', 'server_log',
                                                          'base_disagrees', 'gate',
                                                          'cannot_judge',
                                                          'sandbox_never_started', 'main_red',
                                                          'test_server_never_started',
                                                          'validator_defect', 'abandoned',
                                                          'load_sensitive',
                                                          'load_sensitive_parked')
            or jsonb_typeof(p_record -> 'backoff_ms') is distinct from 'number'
            or (p_record ->> 'evidence' in ('failures', 'server_log')
                and (case when jsonb_typeof(p_record -> 'failures') = 'array'
                          then jsonb_array_length(p_record -> 'failures') else 0 end = 0
                     or (p_record ->> 'evidence' = 'server_log'
                         and case when jsonb_typeof(p_record -> 'crash') = 'array'
                                  then jsonb_array_length(p_record -> 'crash') else 0 end = 0)))
            or (p_record ->> 'evidence' = 'base_disagrees'
                and (coalesce(p_record ->> 'scenario', '') !~ '^[^[:space:]|]+$'
                     or jsonb_typeof(p_record -> 'exits') is distinct from 'array'
                     or jsonb_array_length(p_record -> 'exits') <> 2
                     or p_record -> 'exits' ->> 0 is distinct from '1'
                     or p_record -> 'exits' ->> 1 is distinct from '0'
                     or jsonb_typeof(p_record -> 'base_disagrees') is distinct from 'number'
                     or jsonb_typeof(p_record -> 'alert') is distinct from 'boolean'
                     or p_record ->> 'escalate' is distinct from 'false'
                     or (p_record ? 'setup_s'
                         and jsonb_typeof(p_record -> 'setup_s') is distinct from 'number')))
            or (p_record ->> 'evidence' = 'gate'
                and (coalesce(p_record -> 'fact' ->> 'scenario', '') !~ '^[^[:space:]|]+$'
                     or coalesce(p_record -> 'fact' ->> 'on', '') not in ('base', 'candidate and base')))
            or (p_record ->> 'evidence' = 'validator_defect'
                and (coalesce(p_record -> 'fact' ->> 'scenario', '') !~ '^[^[:space:]|]+$'
                     or p_record -> 'fact' ->> 'on' is distinct from 'candidate and base'
                     or jsonb_typeof(p_record -> 'validator_defects') is distinct from 'array'
                     or jsonb_array_length(p_record -> 'validator_defects') = 0
                     or exists (select 1
                                  from jsonb_array_elements(p_record -> 'validator_defects') d
                                 where jsonb_typeof(d) <> 'string'
                                    or d #>> '{}' !~ '^[^/[:space:]]+\.sh$')))
            or (p_record ->> 'evidence' = 'cannot_judge'
                and (coalesce(p_record ->> 'scenario', '') !~ '^[^[:space:]|]+$'
                     or jsonb_typeof(p_record -> 'escalate') is distinct from 'boolean'))
            -- A regression gate.sh found load-sensitive (like for like), and
            -- the bound's second one for the same pushed commit (parked):
            -- the commit, and the scenarios named (`sensitive`, not the gate's
            -- `scenarios` count), each a `<name>.sh`.
            or (p_record ->> 'evidence' in ('load_sensitive', 'load_sensitive_parked')
                and (coalesce(p_record ->> 'scenario', '') !~ '^[^[:space:]|]+$'
                     or coalesce(p_record ->> 'pushed', '') !~ '^[0-9a-f]{7,64}$'
                     or jsonb_typeof(p_record -> 'escalate') is distinct from 'boolean'
                     or jsonb_typeof(p_record -> 'sensitive') is distinct from 'array'
                     or jsonb_array_length(p_record -> 'sensitive') = 0
                     or exists (select 1
                                  from jsonb_array_elements(p_record -> 'sensitive') d
                                 where jsonb_typeof(d) <> 'string'
                                    or d #>> '{}' !~ '^[^/[:space:]]+\.sh$')
                     or (p_record ->> 'evidence' = 'load_sensitive_parked'
                         and (p_record ->> 'parked' is distinct from 'true'
                              or p_record ->> 'escalate' is distinct from 'true'))))
            or (p_record ->> 'evidence' = 'sandbox_never_started'
                and (coalesce(p_record -> 'fact' ->> 'scenario', '') = ''
                     or p_record -> 'fact' ->> 'on' is distinct from 'sandbox'
                     or p_record -> 'fact' ->> 'runs' is distinct from 'never started'
                     or coalesce(p_record -> 'fact' ->> 'tree', '') not in
                        ('candidate', 'base', 'gate')))
            or (p_record ->> 'evidence' = 'test_server_never_started'
                and (p_record -> 'fact' ->> 'scenario' is distinct from 'test server'
                     or p_record -> 'fact' ->> 'on' is distinct from 'test server'
                     or p_record -> 'fact' ->> 'runs' is distinct from 'never started'
                     or coalesce(p_record -> 'fact' ->> 'tree', '') not in ('gate', 'candidate')))
            or (p_record ->> 'evidence' = 'abandoned'
                and (p_record -> 'fact' ->> 'on' is distinct from 'runner'
                     or p_record -> 'fact' ->> 'runs' is distinct from 'no status'))
            or (p_record ->> 'evidence' = 'main_red'
                and (coalesce(p_record -> 'fact' ->> 'scenario', '') !~ '^check-[^/[:space:]]+\.sh$'
                     or p_record -> 'fact' ->> 'on' is distinct from 'main'
                     or jsonb_typeof(p_record -> 'fact' -> 'failures') is distinct from 'array'
                     or jsonb_array_length(p_record -> 'fact' -> 'failures') = 0))) then
        raise exception 'a host_fault verdict names its evidence, its facts and backoff_ms: %',
                        p_record;
    end if;
    -- No room to judge names what it measured: the check that fell short
    -- (`disk`, `memory` or `database`), its `measured` and its `threshold`
    -- (the integrator's checks before a gate, docs/fleet-architecture.md
    -- §10.3); a disk one, or one that names no check (the gate's own fact,
    -- and records from before the checks), the free space and the directory.
    if p_record ->> 'type' = 'task.gated' and p_record ->> 'verdict' = 'no_room'
       and ((p_record ? 'check'
             and (coalesce(p_record ->> 'check', '') not in ('disk', 'memory', 'database')
                  or coalesce(p_record ->> 'measured', '') = ''
                  or coalesce(p_record ->> 'threshold', '') = ''))
            or (coalesce(p_record ->> 'check', 'disk') = 'disk'
                and (jsonb_typeof(p_record -> 'free_kb') is distinct from 'number'
                     or p_record ->> 'tmpdir' is null))) then
        raise exception 'a no_room verdict names its check, measured and threshold, and a disk one free_kb and tmpdir: %',
                        p_record;
    end if;
    -- The gate runs for minutes: the task may have been closed meanwhile.
    -- A verdict only moves work that is still waiting for it.
    if p_record ->> 'type' like 'task.%' and not exists (
        select 1 from mission_tasks
         where id = (p_record ->> 'id')::bigint
           and state = any (case p_record ->> 'type'
                              when 'task.landed' then array['landing']
                              when 'task.held' then array['landing']
                              when 'task.aborted' then array['delivered']
                              when 'task.over_budget' then array['delivered']
                              when 'task.cancelled' then
                                  case when jsonb_typeof(p_record -> 'solved') = 'number'
                                       then array['assigned', 'delivered', 'revise', 'reported']
                                       else array['assigned', 'delivered', 'revise'] end
                              else array['reported', 'accepted', 'landing'] end)) then
        raise exception 'task % is not waiting for %', p_record ->> 'id', p_record ->> 'type';
    end if;
    -- A landing that waits behind the active hold of its mission's source
    -- (the integrator read it under the landing lock and pushed nothing),
    -- recorded once per task and hold: a second records nothing.
    if p_record ->> 'type' = 'task.held' then
        select h.* into v_hold
          from mission_tasks k
          join mission_missions m on m.id = k.mission_id
          join mission_source_holds h on h.source = m.sources ->> 0
         where k.id = (p_record ->> 'id')::bigint;
        if v_hold.hold is null or v_hold.hold::text is distinct from p_record ->> 'hold'
           or v_hold.source is distinct from p_record ->> 'source' then
            raise exception 'hold % is not the active hold on task %''s source %',
                            p_record ->> 'hold', p_record ->> 'id', p_record ->> 'source';
        end if;
    end if;
    if p_record ->> 'type' = 'task.held' and exists (
        select 1 from spawn_events e
         where e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and e.kind -> 'detail' -> 'record' ->> 'id' = p_record ->> 'id'
           and e.kind -> 'detail' -> 'record' ->> 'type' = 'task.held'
           and e.kind -> 'detail' -> 'record' ->> 'hold' = p_record ->> 'hold') then
        return null;
    end if;
    -- A verdict names the revision of the report it judged (the task's
    -- `revisions` when the gate began). The gate runs for minutes: one on a
    -- revision the task has left would land, or send back, work it never
    -- judged.
    if p_record ->> 'type' = 'task.gated' and not exists (
        select 1 from mission_tasks
         where id = (p_record ->> 'id')::bigint
           and revisions::text = p_record ->> 'revision') then
        raise exception 'task % is not at the revision the verdict judged (%)',
                        p_record ->> 'id', coalesce(p_record ->> 'revision', 'none named');
    end if;
    -- A landing moves the baseline of the other missions on its source
    -- whose baseline was its `from` (they saw the same main), never a halted
    -- one's: the record names them, as `source.moved` does.
    if p_record ->> 'type' = 'task.landed' then
        p_record := p_record || jsonb_build_object('missions', (
            select coalesce(jsonb_agg(m.id order by m.id), '[]'::jsonb)
              from mission_missions m
              join mission_missions own on m.sources ->> 0 = own.sources ->> 0 and m.id <> own.id
              join mission_tasks k on k.mission_id = own.id
             where k.id = (p_record ->> 'id')::bigint
               and spawn_commit_now(m.baseline) = spawn_commit_now(p_record ->> 'from')
               and m.halted is null));
    end if;
    -- A done mission's work still lands, but nothing new comes for it: a
    -- landing that keeps going stale (its worker never pushes again, main
    -- moved past its base) would be judged again on every pass, forever.
    -- The third stale verdict since the mission closed aborts it instead.
    select k.mission_id into v_mission
      from mission_tasks k join mission_missions m on m.id = k.mission_id
     where k.id = (p_record ->> 'id')::bigint and m.state = 'done'
       and p_record ->> 'type' = 'task.gated' and p_record ->> 'verdict' = 'stale';
    if v_mission is not null then
        select count(*) into v_stale
          from spawn_events e
         cross join lateral (select e.kind -> 'detail' -> 'record' as r) x
         where e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and x.r ->> 'id' = p_record ->> 'id' and x.r ->> 'type' = 'task.gated'
           and x.r ->> 'verdict' = 'stale'
           and e.session_seq > (
               select max(c.session_seq) from spawn_events c
                where c.session_id = 'session_control' and c.event_name = 'control.recorded'
                  and c.kind -> 'detail' -> 'record' ->> 'id' = v_mission::text
                  and c.kind -> 'detail' -> 'record' ->> 'type' = 'mission.closed');
        if v_stale >= 2 then
            return spawn_control_record(jsonb_build_object(
                'type', 'task.aborted', 'id', (p_record ->> 'id')::bigint,
                'reason', format('the landing went stale %s times after mission %s was done',
                                 v_stale + 1, v_mission))
                || jsonb_strip_nulls(jsonb_build_object('judging', p_record -> 'judging')));
        end if;
    end if;
    v_recorded := spawn_control_record(p_record);
    -- A verdict that sends work back to a task the closure rule does not
    -- let take new work (a closed mission's, a retired resident's) ends it.
    if p_record ->> 'type' = 'task.gated' and not exists (
        select 1 from mission_tasks k
          join mission_missions m on m.id = k.mission_id
          left join mission_residents r on r.agent_id = k.agent_id
         where k.id = (p_record ->> 'id')::bigint
           and spawn_task_may_continue(k.state, m.state, m.gate is not null, r.state)) then
        perform spawn_control_record(jsonb_build_object(
            'type', 'task.cancelled', 'id', (p_record ->> 'id')::bigint, 'by', 'spawn-integrate'));
    end if;
    return v_recorded;
end $$;

-- The integrator's hold on one landing (owner only): taken right before its
-- compare-and-swap push and released after it records what the push did
-- (spawn_landing_release). Dropping a mission waits for the hold, so a push
-- never lands work of a mission dropped meanwhile. True when the task is
-- still landing and the closure rule lets it (its mission is not dropped).
-- A landing task the rule dropped (a fold from before drops cancelled
-- landings) is recorded cancelled instead.
create or replace function spawn_landing_hold(p_task bigint)
returns boolean language plpgsql security definer as $$
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not land work', session_user using errcode = '42501';
    end if;
    perform pg_advisory_lock(1399957337);
    if exists (select 1 from mission_tasks k where k.id = p_task and k.state = 'landing')
       and spawn_task_may_move(p_task, 'landing') then
        return true;
    end if;
    perform pg_advisory_xact_lock(1399957335);
    if exists (select 1 from mission_tasks k where k.id = p_task and k.state = 'landing')
       and not spawn_task_may_move(p_task, 'landing') then
        perform spawn_control_record(jsonb_build_object('type', 'task.cancelled', 'id', p_task,
                                                        'by', 'spawn-integrate'));
    end if;
    perform pg_advisory_unlock(1399957337);
    return false;
end $$;

create or replace function spawn_landing_release()
returns void language plpgsql security definer as $$
begin
    perform pg_advisory_unlock(1399957337);
end $$;

-- The owner's hold on a mission source (docs/fleet-architecture.md §10.3,
-- "Landing: the owner's hold"): while a source is held no task lands on it
-- (its gates still run, its accepted tasks wait), and everything else goes
-- on. The hold and its end are records: `source.held`, then
-- `source.released` (the owner) or `source.hold_expired` (the integrator,
-- once the database's clock reached its `expires_ms`).
--
-- A source the owner may hold: one a mission names as its first source,
-- whatever the mission's state, of a checked shape, and a directory on this
-- host (nothing lands on a remote one). Raises otherwise, so a mistyped path
-- never looks like a hold.
create or replace function spawn_source_holdable(p_source text)
returns void language plpgsql as $$
begin
    if not spawn_source_allowed(p_source) then
        raise exception 'a source is an absolute path or an https:// or ssh:// URL, not %',
            coalesce(p_source, 'null') using errcode = '22023';
    end if;
    if not exists (select 1 from mission_missions where sources ->> 0 = p_source) then
        raise exception 'no mission names % as its source: nothing lands there to hold',
            p_source using errcode = '22023';
    end if;
    if p_source not like '/%' then
        raise exception '% is remote: nothing lands there to hold', p_source
            using errcode = '22023';
    end if;
end $$;

-- Take the integrator's landing lock (spawn_landing_hold's) for an owner's
-- hold on `p_source` (owner only): a landing whose compare-and-swap push has
-- begun records its outcome first, so the main the caller reads next is the
-- one that landing left, and none starts until the hold is recorded. Released
-- by spawn_landing_release (or with the connection).
create or replace function spawn_source_hold_lock(p_source text)
returns void language plpgsql security definer as $$
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner holds a source' using errcode = '42501';
    end if;
    perform spawn_source_holdable(p_source);
    perform pg_advisory_lock(1399957337);
end $$;

-- Record the owner's hold on `p_source` (owner only, under the landing lock
-- taken by spawn_source_hold_lock): `source.held` naming the source's main
-- `p_main` as the caller read it under that lock, `by` human, `bound_s` and
-- the `reason` when given (at most 500 characters); the store writes its
-- `expires_ms` (its own time + `bound_s` x 1000). A hold on a source already
-- held renews it: `renews` names the active hold, which ends with this
-- record. Returns `{hold, source, main, expires_ms, renews}`.
create or replace function spawn_source_hold(p_source text, p_main text, p_bound_s integer,
                                             p_reason text)
returns jsonb language plpgsql security definer as $$
declare
    v_renews bigint;
    v_id bigint;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner holds a source' using errcode = '42501';
    end if;
    perform spawn_source_holdable(p_source);
    if not exists (select 1 from pg_locks
                    where locktype = 'advisory' and pid = pg_backend_pid() and granted
                      and classid = 0 and objid = 1399957337 and objsubid = 1) then
        raise exception 'a hold is recorded under the landing lock (spawn_source_hold_lock)';
    end if;
    if coalesce(p_main, '') !~ '^[0-9a-f]{40}([0-9a-f]{24})?$' then
        raise exception 'a hold names the source''s main as a full commit id, not %',
            coalesce(p_main, 'null') using errcode = '22023';
    end if;
    if p_bound_s is null or p_bound_s < 1 or p_bound_s > 86400 then
        raise exception 'SPAWN_SOURCE_HOLD_SECS is a whole number of seconds from 1 to 86400, not %',
            coalesce(p_bound_s::text, 'null') using errcode = '22023';
    end if;
    if length(p_reason) > 500 then
        raise exception 'a hold''s reason is at most 500 characters, not %', length(p_reason)
            using errcode = '22023';
    end if;
    select hold into v_renews from mission_source_holds where source = p_source;
    v_id := spawn_control_record(jsonb_build_object(
        'type', 'source.held', 'source', p_source, 'main', p_main, 'by', 'human',
        'bound_s', p_bound_s, 'renews', v_renews)
        || case when p_reason is null then '{}'::jsonb
                else jsonb_build_object('reason', p_reason) end);
    return (select jsonb_build_object('hold', h.hold, 'source', h.source, 'main', h.main,
                                      'expires_ms', h.expires_ms, 'renews', v_renews)
              from mission_source_holds h where h.source = p_source and h.hold = v_id);
end $$;

-- The owner releases the active hold on `p_source` (owner only): records
-- `source.released` naming it and returns `{source, released, waiting}`, the
-- tasks waiting behind it, oldest first; they land at the integrator's next
-- pass by the existing rules. With no active hold (never held, released or
-- expired) it records nothing and returns `released` null, so a deploy that
-- releases on every exit path never fails on it.
create or replace function spawn_source_release(p_source text)
returns jsonb language plpgsql security definer as $$
declare
    v_hold bigint;
    v_waiting jsonb;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner releases a source' using errcode = '42501';
    end if;
    select hold into v_hold from mission_source_holds where source = p_source;
    if v_hold is null then
        return jsonb_build_object('source', p_source, 'released', null, 'waiting', '[]'::jsonb);
    end if;
    select coalesce(jsonb_agg(k.id order by k.id), '[]'::jsonb) into v_waiting
      from mission_tasks k where k.state = 'landing' and k.held_by = v_hold;
    perform spawn_control_record(jsonb_build_object(
        'type', 'source.released', 'source', p_source, 'hold', v_hold, 'by', 'human'));
    return jsonb_build_object('source', p_source, 'released', v_hold, 'waiting', v_waiting);
end $$;

-- The records that end a hold, by source, found without reading the rest of
-- the stream: a landing's stall is measured from the latest one on its
-- source (dispatch/stall.rs).
create index if not exists spawn_events_hold_end
    on spawn_events ((kind -> 'detail' -> 'record' ->> 'source'), session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' in ('source.released', 'source.hold_expired');

-- A task's (or a mission's) records in the control stream, found without
-- reading the rest: its stages, and the dispatcher's stall facts (`STALL_FACTS`).
create index if not exists spawn_events_control_record
    on spawn_events ((kind -> 'detail' -> 'record' ->> 'id'), session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded';

-- The owner's landing requests and the records that can be their outcome,
-- found without reading the rest of the stream: the integrator reads the
-- pending ones on every pass.
create index if not exists spawn_events_source_push
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type'
          in ('source.push_requested', 'source.push_refused', 'source.moved');

-- The objectives that closed solved on the base, found without reading the
-- rest of the stream: the supervisor's digest reads the ones it has not told
-- yet on every dispatch pass. Measured on the live stream today: 1,442
-- `control.recorded` records, 1 of them `objective.solved`, and the read
-- without this index (`spawn_events_control_record`, whose key is the record
-- id) examined all 1,442 to find it — 1,441 removed by the type filter, 3,261
-- buffers, 12 ms. This index holds that 1 entry.
create index if not exists spawn_events_objective_solved
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'objective.solved';

-- The loop's own records, owner only, folded into no table: what this host
-- saw and what it did about it (docs/fleet-architecture.md §3.1, "the
-- recovery"). One function, so a restricted login can write none of them.
--
-- - `host.disk`: free space on a path the fleet writes to fell under the
--   warning threshold (`low`) or came back (`recovered`). One record per
--   crossing; the loop reads the latest per path back from the log after a
--   restart.
-- - `host.judge`: the model judge (`judge`, its name) failed two calls in
--   a row after its last answer (`down`, with the latest call's `error` and
--   `first_failed_ms`, when the first failed) or answered after that (`up`,
--   with `failed_calls`, the failures its watcher counted since the `down`,
--   or since the watcher's restart if it restarted while down). One record
--   per crossing; the judge's watcher reads the latest per judge back after
--   a restart, and the alert step fires `judge_down` on a `down` with no
--   `up` after it SPAWN_ALERT_JUDGE_DOWN_SECS after its first failure.
-- - `host.messages_marked`: the first `spawn loop` whose Bridge types each
--   message's marker started (`started_at_ms`). Written once: a later
--   start writes nothing and gets the first record's id back. A command
--   never typed is a tracked message from then on (spawn_command_message).
-- - `host.loop_started`: one `spawn loop` started, with its `boot_id` and
--   `started_at_ms`. A restarted loop tells an execution whose end it found
--   from one it watched fail by the records of the loops before it.
-- - `execution.interrupted`: one interruption of one execution, recorded
--   once, whatever an earlier loop recorded and whether or not it was
--   revived. Its `attempt` counts the interruptions of that execution, so
--   `recover-<execution_id>-<attempt>` names this one and no other; `path`
--   is the way back (`resume`, `handoff`, `wait`, `final`) and `due_ms`
--   when it is due (null on `final`). The required fields, and the cause
--   and path vocabulary, are checked here: a record the recovery could not
--   act on is refused, never written and re-read.
-- - `execution.cleared`: the wait an interruption opened is over, with what
--   showed it and `waited_ms` from the first interruption of the wait. Its
--   `execution_id` and `cause` are those of the interruption it answers.
create or replace function spawn_host_record(p_record jsonb)
returns bigint language plpgsql security definer as $$
declare
    v_type text := p_record ->> 'type';
    v_cause text := p_record ->> 'cause';
    v_path text := p_record ->> 'path';
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record host facts', session_user using errcode = '42501';
    end if;
    if v_type is null then
        raise exception 'a host record has a type';
    end if;
    if v_type = 'host.disk' then
        if p_record ->> 'state' not in ('low', 'recovered') or p_record ->> 'path' is null
           or jsonb_typeof(p_record -> 'free_bytes') is distinct from 'number' then
            raise exception 'a host.disk record has a path, free_bytes and state low or recovered: %', p_record;
        end if;
    elsif v_type = 'host.storage' then
        -- What the transcript archive and Claude Code's own transcripts
        -- hold, sampled by the loop at its start and hourly
        -- (docs/storage.md, "What uses the disk").
        if jsonb_typeof(p_record -> 'archive_bytes') is distinct from 'number'
           or jsonb_typeof(p_record -> 'archive_files') is distinct from 'number'
           or jsonb_typeof(p_record -> 'projects_bytes') is distinct from 'number'
           or jsonb_typeof(p_record -> 'projects_files') is distinct from 'number' then
            raise exception 'a host.storage record has archive_bytes, archive_files, projects_bytes and projects_files: %', p_record;
        end if;
    elsif v_type = 'host.core_lines' then
        -- The Core lines figures' values, sampled by the loop at its start
        -- and hourly (objective 090): {<figure key>: <value>}.
        if jsonb_typeof(p_record -> 'values') is distinct from 'object' then
            raise exception 'a host.core_lines record has values, an object: %', p_record;
        end if;
    elsif v_type = 'host.storage_bytes' then
        -- The real bytes on disk of each storage source, read daily by the
        -- loop outside every owner hold (objective 180): {"sources": {<name>:
        -- {"bytes": <n>, ...} | {"not_measured": <why>}}}, at least one.
        if jsonb_typeof(p_record -> 'sources') is distinct from 'object'
           or not exists (select 1 from jsonb_each(p_record -> 'sources'))
           or exists (
               select 1 from jsonb_each(p_record -> 'sources') s(name, source)
                where s.name = ''
                   or jsonb_typeof(s.source) is distinct from 'object'
                   or not coalesce(
                          jsonb_typeof(s.source -> 'bytes') is not distinct from 'number'
                              and (s.source ->> 'bytes')::numeric >= 0
                              and s.source -> 'not_measured' is null
                          or jsonb_typeof(s.source -> 'not_measured') is not distinct from 'string'
                              and s.source -> 'bytes' is null, false)) then
            raise exception 'a host.storage_bytes record has sources, each with bytes (a number from 0) or not_measured (why): %', p_record;
        end if;
    elsif v_type = 'host.judge' then
        if p_record ->> 'judge' is null or p_record ->> 'state' is null
           or p_record ->> 'state' not in ('down', 'up') then
            raise exception 'a host.judge record names its judge and a state down or up: %', p_record;
        end if;
        if p_record ->> 'state' = 'down'
           and (jsonb_typeof(p_record -> 'error') is distinct from 'string'
                or jsonb_typeof(p_record -> 'first_failed_ms') is distinct from 'number') then
            raise exception 'a host.judge down record says the call''s error and first_failed_ms: %', p_record;
        end if;
        if p_record ->> 'state' = 'up'
           and jsonb_typeof(p_record -> 'failed_calls') is distinct from 'number' then
            raise exception 'a host.judge up record counts failed_calls: %', p_record;
        end if;
    elsif v_type = 'host.messages_marked' then
        if jsonb_typeof(p_record -> 'started_at_ms') is distinct from 'number' then
            raise exception 'a host.messages_marked record has started_at_ms: %', p_record;
        end if;
        -- The first such loop is what it says: a later start records
        -- nothing and answers the first record.
        if exists (select 1 from spawn_events
                    where session_id = 'session_control' and event_name = 'control.recorded'
                      and kind -> 'detail' -> 'record' ->> 'type' = 'host.messages_marked') then
            return (select min(id) from spawn_events
                     where session_id = 'session_control' and event_name = 'control.recorded'
                       and kind -> 'detail' -> 'record' ->> 'type' = 'host.messages_marked');
        end if;
    elsif v_type = 'host.loop_started' then
        if p_record ->> 'boot_id' is null
           or jsonb_typeof(p_record -> 'started_at_ms') is distinct from 'number' then
            raise exception 'a host.loop_started record has a boot_id and started_at_ms: %', p_record;
        end if;
    elsif v_type = 'execution.interrupted' then
        if p_record ->> 'agent_id' is null or p_record ->> 'session_id' is null
           or p_record ->> 'execution_id' is null then
            raise exception 'an execution.interrupted record names its agent, session and execution: %', p_record;
        end if;
        -- One vocabulary for every cause and path: a reader that knows
        -- them is the only one that may write them.
        if v_cause is null or v_cause not in (
               'exited', 'crashed', 'memory_limit', 'context_exhausted',
               'model_unavailable', 'model_auth', 'model_error', 'host_restart',
               'database_unavailable', 'disk_full', 'budget', 'stopped', 'restarted',
               'reassigned') then
            raise exception 'not an interruption cause: %', v_cause
                using errcode = '22023';
        end if;
        if v_path is null or v_path not in ('resume', 'handoff', 'wait', 'final') then
            raise exception 'not a recovery path: %', v_path using errcode = '22023';
        end if;
        if jsonb_typeof(p_record -> 'attempt') is distinct from 'number'
           or (p_record ->> 'attempt')::numeric < 1 then
            raise exception 'an interruption has an attempt of 1 or more: %', p_record;
        end if;
        if jsonb_typeof(p_record -> 'evidence') is distinct from 'object' then
            raise exception 'an interruption names its evidence: %', p_record;
        end if;
        if v_path = 'final' then
            if p_record -> 'due_ms' is not null and jsonb_typeof(p_record -> 'due_ms') = 'number' then
                raise exception 'a final interruption is due never (due_ms null): %', p_record;
            end if;
        elsif jsonb_typeof(p_record -> 'due_ms') is distinct from 'number' then
            raise exception 'a revival is due at due_ms: %', p_record;
        end if;
    elsif v_type = 'execution.cleared' then
        if p_record ->> 'execution_id' is null or p_record ->> 'session_id' is null
           or v_cause is null then
            raise exception 'an execution.cleared record names its execution, session and cause: %', p_record;
        end if;
        if jsonb_typeof(p_record -> 'waited_ms') is distinct from 'number' then
            raise exception 'an execution.cleared record names waited_ms: %', p_record;
        end if;
    else
        raise exception 'not a host record: %', v_type;
    end if;
    return spawn_control_record(p_record);
end $$;

-- The recovery's records of one execution, found without reading the rest
-- of the stream: every pass of every loop reads the latest back.
create index if not exists spawn_events_recovery
    on spawn_events ((kind -> 'detail' -> 'record' ->> 'execution_id'), session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type'
          in ('execution.interrupted', 'execution.cleared');

-- The `host.disk` records, found without reading the rest of the stream.
create index if not exists spawn_events_host_disk
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'host.disk';

-- The `host.storage` samples, found without reading the rest of the stream.
create index if not exists spawn_events_host_storage
    on spawn_events (recorded_at_ms)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'host.storage';

-- The `host.core_lines` samples (objective 090), found without reading the
-- rest of the stream: `/api/core-lines` reads the last 7 days of them.
create index if not exists spawn_events_host_core_lines
    on spawn_events (recorded_at_ms)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'host.core_lines';

-- The daily `host.storage_bytes` readings (objective 180), found without
-- reading the rest of the stream: the loop reads the newest when one is due.
create index if not exists spawn_events_host_storage_bytes
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'host.storage_bytes';

-- The nodes (multi-host P1; docs/fleet-architecture.md §1.2): the machines
-- Spawn may use and whether they answer. Their records are `node.recorded`
-- events of the control session, outside the fold: no
-- spawn_control_refold, this schema's or an older one's, reads them, so a
-- schema rolled back still refolds a log that holds them.
--   node.joined {name, ssh, note, arch, os, kernel, cores, cpu_max,
--     mem_total, mem_max, disk_free, gpu, exit_country, transport, endpoint,
--     via, mode} (`spawn node add`, or a node's own `spawn node register`
--     taken by `spawn node serve --register-store`). `transport` is ssh
--     (absent: every join before it), tcp or udp; `endpoint` is null for
--     ssh (the destination is `ssh`) and `[tcp://|udp://]host:port` for
--     the others; `via`, absent or a list of at most 8 joined nodes, the
--     hops from the primary to this node in order, none the node itself,
--     none twice, no loop through the hops' own `via`; `mode`, absent or
--     direct, relay or hole_punch (absent reads as relay with hops and
--     direct without). Issue #87: `transport` coord, a node reached
--     through a coordinator (`spawn node connect`), its `endpoint` the
--     coordinator's `ws://`, `wss://` or `tcp://` URL, its mode relay or
--     hole_punch, its hops (if any) tcp, udp or coord nodes; and, on any
--     join, optional `node_id` (64 hex: SHA-256 of its Ed25519 key),
--     `pubkey` (that key, base64), `role` (worker or peer) and `zone`;
--   node.drained, node.undrained, node.removed {name};
--   node.heartbeat {name, join, load1, mem_available, disk_free},
--   and on node.joined and node.heartbeat an optional `power` (issue #91):
--     null or {on_ac, battery_pct, charging, remaining_mins}, on_ac and
--     charging booleans, battery_pct null or a whole number 0 to 100,
--     remaining_mins null or a whole number at least 0 (absent: a node
--     with no battery or AC sensor, and every record before it);
--   node.lost {name, join, last_seen_ms, silent_ms, error},
--   node.back {name, join, down_ms} (`spawn loop`'s heartbeat worker).
-- One index, spawn_events_node on (type, name, session_seq) of these
-- records, finds a node's latest record of a type in one seek, for the
-- writer's checks and the readers alike. It is not made here: this file
-- runs in one transaction under the append lock, and a first build reads
-- all of spawn_events. `PostgresStore::migrate` builds it after that
-- transaction commits, concurrently, so appends never wait for it
-- (spawn-postgres nodes.rs `NODE_INDEX`). Until it is there the node reads
-- are right, only slower.

-- The latest record of type `p_type` of node `p_name` after `p_after` (a
-- session_seq), through spawn_events_node.
create or replace function spawn_node_latest(p_type text, p_name text, p_after bigint)
returns table (id bigint, seq bigint, at_ms bigint, record jsonb)
language sql stable as $$
    select e.id, e.session_seq, e.recorded_at_ms, e.kind -> 'detail' -> 'record'
      from spawn_events e
     where e.session_id = 'session_control' and e.event_name = 'node.recorded'
       and e.kind -> 'detail' -> 'record' ->> 'type' = p_type
       and e.kind -> 'detail' -> 'record' ->> 'name' = p_name
       and e.session_seq > p_after
     order by e.session_seq desc
     limit 1
$$;

-- Whether `p_value` is a JSON number at least 0.
create or replace function spawn_node_count(p_value jsonb)
returns boolean language sql immutable as $$
    select case when jsonb_typeof(p_value) = 'number' then p_value::text::numeric >= 0
                else false end
$$;

-- The reader login (`/api/nodes`) reads through spawn_node_latest, with its
-- own rights; nobody else is handed either helper.
revoke execute on function spawn_node_latest(text, text, bigint) from public;
revoke execute on function spawn_node_count(jsonb) from public;
do $$
begin
    execute format('grant execute on function spawn_node_latest(text, text, bigint) to %I',
                   spawn_login_role('spawn_reader'));
end
$$;

-- The writer of a node's facts (owner only). Under the append lock: a join
-- of a name not joined (a removed name joins again); any other record of
-- a joined name, the loop's heartbeat, lost and back of its current join
-- (`join`, the node.joined event id), so a probe started for an earlier
-- join records nothing; no drain, undrain, lost or back recorded twice.
-- Returns the record's event id.
create or replace function spawn_node_record(p_record jsonb)
returns bigint language plpgsql security definer as $$
declare
    v_type text := p_record ->> 'type';
    v_name text := p_record ->> 'name';
    v_transport text := coalesce(p_record ->> 'transport', 'ssh');
    v_via jsonb := coalesce(p_record -> 'via', 'null'::jsonb);
    v_seen text[];
    v_front text[];
    v_bad text;
    v_join bigint;
    v_seq bigint;
    v_on bigint;
    v_off bigint;
    v_id bigint;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner records a node''s facts; % may not', session_user
            using errcode = '42501';
    end if;
    if v_type is null or v_type not in ('node.joined', 'node.drained', 'node.undrained',
                                        'node.removed', 'node.heartbeat', 'node.lost',
                                        'node.back') then
        raise exception 'not a node record: its type is none of node.joined, node.drained, node.undrained, node.removed, node.heartbeat, node.lost, node.back'
            using errcode = '22023';
    end if;
    if v_name is null or v_name !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$' then
        raise exception 'a node''s name is 1 to 63 letters, digits, dots, dashes or underscores, first a letter or digit'
            using errcode = '22023';
    end if;
    if v_type = 'node.joined' and v_transport not in ('ssh', 'tcp', 'udp', 'coord') then
        raise exception 'a node''s transport is ssh, tcp or udp, or coord (through a coordinator)'
            using errcode = '22023';
    end if;
    -- A coord node (issue #87) is reached through a coordinator: its
    -- endpoint is the coordinator's URL, its mode relay or hole_punch.
    if v_type = 'node.joined' and v_transport = 'coord'
       and (jsonb_typeof(p_record -> 'endpoint') is distinct from 'string'
            or length(p_record ->> 'endpoint') > 255
            or p_record ->> 'endpoint' ~ '[@[:space:][:cntrl:]]'
            or p_record ->> 'endpoint' !~ ('^(ws|wss|tcp)://'
                                           '([A-Za-z0-9][A-Za-z0-9.-]*|\[[0-9A-Fa-f:.]*:[0-9A-Fa-f:.]*\])'
                                           '(:[0-9]{1,5})?'
                                           '(/[A-Za-z0-9._~:/?#\[\]@!$&''()*+,;=%-]*)?$')
            or coalesce(substring(p_record ->> 'endpoint'
                                  from '^[a-z]+://(?:[A-Za-z0-9][A-Za-z0-9.-]*|\[[0-9A-Fa-f:.]*\]):([0-9]{1,5})')::integer
                        between 1 and 65535, true) is not true) then
        raise exception 'a coord node''s endpoint is its coordinator''s ws://, wss:// or tcp://host[:port][/path], the port 1 to 65535'
            using errcode = '22023';
    end if;
    if v_type = 'node.joined' and v_transport = 'coord'
       and coalesce(p_record ->> 'mode', '') not in ('relay', 'hole_punch') then
        raise exception 'a coord node''s mode is relay or hole_punch'
            using errcode = '22023';
    end if;
    if v_type = 'node.joined'
       and ((coalesce(jsonb_typeof(p_record -> 'node_id'), 'null') <> 'null'
             and (jsonb_typeof(p_record -> 'node_id') <> 'string'
                  or p_record ->> 'node_id' !~ '^[0-9a-f]{64}$'))
            or (coalesce(jsonb_typeof(p_record -> 'pubkey'), 'null') <> 'null'
                and (jsonb_typeof(p_record -> 'pubkey') <> 'string'
                     or p_record ->> 'pubkey' !~ '^[A-Za-z0-9+/_-]{43,44}={0,2}$'))) then
        raise exception 'a node''s node_id is 64 lowercase hex digits and its pubkey a base64 Ed25519 key'
            using errcode = '22023';
    end if;
    if v_type = 'node.joined'
       and coalesce(jsonb_typeof(p_record -> 'role'), 'null') <> 'null'
       and (jsonb_typeof(p_record -> 'role') <> 'string'
            or p_record ->> 'role' not in ('worker', 'peer')) then
        raise exception 'a node''s role is worker or peer'
            using errcode = '22023';
    end if;
    if v_type = 'node.joined'
       and coalesce(jsonb_typeof(p_record -> 'zone'), 'null') <> 'null'
       and (jsonb_typeof(p_record -> 'zone') <> 'string'
            or p_record ->> 'zone' !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$') then
        raise exception 'a node''s zone is 1 to 63 letters, digits, dots, dashes or underscores, first a letter or digit'
            using errcode = '22023';
    end if;
    if v_type = 'node.joined'
       and (v_transport = 'ssh' or p_record ->> 'ssh' is not null)
       and (p_record ->> 'ssh' is null or length(p_record ->> 'ssh') > 255
            or p_record ->> 'ssh' !~ ('^(([A-Za-z0-9_][A-Za-z0-9._-]*@)?[A-Za-z0-9][A-Za-z0-9.-]*'
                                      '|ssh://([A-Za-z0-9_][A-Za-z0-9._-]*@)?[A-Za-z0-9][A-Za-z0-9.-]*(:[0-9]{1,5})?)$')
            or coalesce(substring(p_record ->> 'ssh' from ':([0-9]{1,5})$')::integer
                        between 1 and 65535, true) is not true) then
        raise exception 'a node''s ssh destination is [user@]host or ssh://[user@]host[:port], the port 1 to 65535'
            using errcode = '22023';
    end if;
    -- An ssh node's destination is `ssh`, no endpoint; a tcp or udp
    -- node's is `endpoint`, `host:port` with no user, password, option or
    -- space, the scheme (when there) its transport's.
    if v_type = 'node.joined' and v_transport = 'ssh'
       and coalesce(jsonb_typeof(p_record -> 'endpoint'), 'null') <> 'null' then
        raise exception 'an ssh node''s endpoint is null: its destination is ssh'
            using errcode = '22023';
    end if;
    if v_type = 'node.joined' and v_transport in ('tcp', 'udp')
       and (jsonb_typeof(p_record -> 'endpoint') is distinct from 'string'
            or length(p_record ->> 'endpoint') > 255
            or p_record ->> 'endpoint' !~ ('^(' || v_transport || '://)?'
                                           '([A-Za-z0-9][A-Za-z0-9.-]*|\[[0-9A-Fa-f:.]*:[0-9A-Fa-f:.]*\])'
                                           ':[0-9]{1,5}$')
            or substring(p_record ->> 'endpoint' from ':([0-9]{1,5})$')::integer
               not between 1 and 65535) then
        raise exception 'a % node''s endpoint is [%://]host:port (a name, an IPv4 or a bracketed IPv6 address), the port 1 to 65535',
            v_transport, v_transport using errcode = '22023';
    end if;
    if v_type = 'node.joined'
       and coalesce(jsonb_typeof(p_record -> 'mode'), 'null') <> 'null'
       and (jsonb_typeof(p_record -> 'mode') <> 'string'
            or p_record ->> 'mode' not in ('direct', 'relay', 'hole_punch')) then
        raise exception 'a node''s mode is direct, relay or hole_punch'
            using errcode = '22023';
    end if;
    if v_type = 'node.joined' and jsonb_typeof(v_via) <> 'null' then
        if jsonb_typeof(v_via) <> 'array' or jsonb_array_length(v_via) > 8
           or exists (select 1 from jsonb_array_elements(v_via) h
                       where jsonb_typeof(h) <> 'string'
                          or h #>> '{}' !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$') then
            raise exception 'a node''s via is a list of at most 8 node names'
                using errcode = '22023';
        end if;
        if exists (select 1 from jsonb_array_elements_text(v_via) h where h = v_name) then
            raise exception 'node % cannot be a hop of its own via', v_name using errcode = '22023';
        end if;
        if (select count(distinct h) <> count(*) from jsonb_array_elements_text(v_via) h) then
            raise exception 'a node''s via names a hop twice' using errcode = '22023';
        end if;
        select h into v_bad from jsonb_array_elements_text(v_via) with ordinality v(h, o)
         where not exists (select 1 from spawn_node_latest('node.joined', v.h, 0) j
                            where not exists (select 1 from spawn_node_latest('node.removed', v.h, j.seq)))
         order by o limit 1;
        if v_bad is not null then
            raise exception 'hop % of the via is not joined', v_bad using errcode = 'P0002';
        end if;
        -- An ssh node's hops are its jump hosts, ssh nodes; a tcp, udp or
        -- coord node's are relays, tcp, udp or coord nodes.
        select h into v_bad from jsonb_array_elements_text(v_via) with ordinality v(h, o)
         cross join lateral spawn_node_latest('node.joined', v.h, 0) j
         where (coalesce(j.record ->> 'transport', 'ssh') = 'ssh') <> (v_transport = 'ssh')
         order by o limit 1;
        if v_bad is not null then
            raise exception 'hop % is reached over another transport: an ssh node''s hops are ssh nodes, a tcp, udp or coord node''s are tcp, udp or coord nodes',
                v_bad using errcode = '22023';
        end if;
        if p_record ->> 'mode' = 'direct' and jsonb_array_length(v_via) > 0 then
            raise exception 'a direct node has no via (its mode is relay or hole_punch)'
                using errcode = '22023';
        end if;
        -- No loop: walk the hops' own `via` (their current joins), each
        -- name once, and never reach this node.
        v_seen := array(select jsonb_array_elements_text(v_via));
        v_front := v_seen;
        while cardinality(v_front) > 0 loop
            v_front := array(
                select distinct n.hop
                  from unnest(v_front) f(name)
                 cross join lateral spawn_node_latest('node.joined', f.name, 0) j
                 cross join lateral jsonb_array_elements_text(
                     case when jsonb_typeof(j.record -> 'via') = 'array'
                          then j.record -> 'via' else '[]'::jsonb end) n(hop)
                 where not exists (select 1 from spawn_node_latest('node.removed', f.name, j.seq))
                   and n.hop <> all(v_seen));
            if v_name = any(v_front) then
                raise exception 'node % via % makes a loop: a hop is reached through %',
                    v_name, v_via, v_name using errcode = '22023';
            end if;
            v_seen := v_seen || v_front;
        end loop;
        v_bad := null;
    end if;
    -- Each field this record type holds, named when it is wrong; the
    -- record itself is never said back.
    select c.field, c.what into v_bad, v_on
      from (values (1, 'node.joined', 'arch', 0), (2, 'node.joined', 'os', 0),
                   (3, 'node.joined', 'kernel', 0), (4, 'node.joined', 'cores', 1),
                   (5, 'node.joined', 'mem_total', 1), (6, 'node.joined', 'disk_free', 1),
                   (7, 'node.joined', 'cpu_max', 3), (8, 'node.joined', 'mem_max', 3),
                   (9, 'node.joined', 'gpu', 3), (10, 'node.joined', 'exit_country', 3),
                   (11, 'node.joined', 'note', 4),
                   (12, 'node.heartbeat', 'load1', 1), (13, 'node.heartbeat', 'mem_available', 1),
                   (14, 'node.heartbeat', 'disk_free', 1), (15, 'node.lost', 'silent_ms', 1),
                   (16, 'node.lost', 'last_seen_ms', 2), (17, 'node.back', 'down_ms', 2))
           as c(o, type, field, what)
     where c.type = v_type
       and not coalesce(case c.what
               when 0 then jsonb_typeof(p_record -> c.field) = 'string'
               when 1 then spawn_node_count(p_record -> c.field)
               when 2 then coalesce(jsonb_typeof(p_record -> c.field), 'null') = 'null'
                           or spawn_node_count(p_record -> c.field)
               when 3 then p_record ? c.field
               else char_length(coalesce(p_record ->> c.field, '')) <= 500 end, false)
     order by c.o
     limit 1;
    if v_bad is not null then
        raise exception 'a % record''s % is %', v_type, v_bad,
            case v_on when 0 then 'text' when 1 then 'a number at least 0'
                      when 2 then 'null or a number at least 0' when 3 then 'there, null or not'
                      else 'at most 500 characters' end
            using errcode = '22023';
    end if;
    if v_type in ('node.joined', 'node.heartbeat')
       and coalesce(jsonb_typeof(p_record -> 'power'), 'null') <> 'null'
       and (jsonb_typeof(p_record -> 'power') <> 'object'
            or jsonb_typeof(p_record #> '{power,on_ac}') is distinct from 'boolean'
            or jsonb_typeof(p_record #> '{power,charging}') is distinct from 'boolean'
            or (coalesce(jsonb_typeof(p_record #> '{power,battery_pct}'), 'null') <> 'null'
                and (jsonb_typeof(p_record #> '{power,battery_pct}') <> 'number'
                     or (p_record #>> '{power,battery_pct}') !~ '^[0-9]{1,3}$'
                     or (p_record #>> '{power,battery_pct}')::integer > 100))
            or (coalesce(jsonb_typeof(p_record #> '{power,remaining_mins}'), 'null') <> 'null'
                and (jsonb_typeof(p_record #> '{power,remaining_mins}') <> 'number'
                     or (p_record #>> '{power,remaining_mins}') !~ '^[0-9]{1,9}$'))) then
        raise exception 'a % record''s power is null or {on_ac, battery_pct, charging, remaining_mins}: on_ac and charging booleans, battery_pct null or 0 to 100, remaining_mins null or a whole number at least 0',
            v_type using errcode = '22023';
    end if;
    v_on := null;
    select j.id, j.seq into v_join, v_seq from spawn_node_latest('node.joined', v_name, 0) j;
    if v_join is not null and exists (select 1 from spawn_node_latest('node.removed', v_name, v_seq)) then
        v_join := null;
    end if;
    if v_type = 'node.joined' then
        if v_join is not null then
            raise exception 'node % is joined already (spawn node remove first)', v_name
                using errcode = '23505';
        end if;
        -- A spawn-node v1 node's name (spawn_node_state, below) is never a
        -- P1 node's too, revoked or not: spawn_node_enroll_token checks
        -- the other way round.
        if exists (select 1 from spawn_node_state s where s.name = v_name) then
            raise exception 'node % is a spawn-node v1 node (spawn node enroll-token): one name is one node',
                v_name using errcode = '23505';
        end if;
    elsif v_join is null then
        raise exception 'node % is not joined', v_name using errcode = 'P0002';
    elsif v_type in ('node.heartbeat', 'node.lost', 'node.back')
          and (p_record -> 'join') is distinct from to_jsonb(v_join) then
        raise exception 'node % is joined as event %, and this record names another: a stale probe',
            v_name, v_join using errcode = '55000';
    elsif v_type in ('node.drained', 'node.undrained') then
        select d.seq into v_on from spawn_node_latest('node.drained', v_name, v_seq) d;
        select u.seq into v_off from spawn_node_latest('node.undrained', v_name, v_seq) u;
        if (coalesce(v_on, 0) > coalesce(v_off, 0)) = (v_type = 'node.drained') then
            raise exception 'node % is % already', v_name,
                case when v_type = 'node.drained' then 'drained' else 'not drained' end
                using errcode = '55000';
        end if;
    end if;
    if v_type in ('node.lost', 'node.back') then
        select l.seq into v_on from spawn_node_latest('node.lost', v_name, v_seq) l;
        select b.seq into v_off from spawn_node_latest('node.back', v_name, v_seq) b;
        if (coalesce(v_on, 0) > coalesce(v_off, 0)) = (v_type = 'node.lost') then
            raise exception 'node % is % already', v_name,
                case when v_type = 'node.lost' then 'lost' else 'not lost' end
                using errcode = '55000';
        end if;
    end if;
    select a.out_id into v_id
      from spawn_append_trusted('agent_control', 'session_control', null, 'control', null,
                                jsonb_build_object('name', 'node.recorded',
                                                   'detail', jsonb_build_object('record', p_record))) a;
    return v_id;
end $$;

-- spawn-node v1 ledger: begin (PR S1).
-- The nodes' state and the jobs they are leased (issue #96, design
-- "spawn-node v1 and host-adaptive storage" §5). A v1 node's beat is a row
-- update, never an event; only transitions are recorded, as `node.recorded`
-- records of the control session with `"proto":"node-v1"` (outside the fold,
-- like the P1 node records above). A v1 node's name is never a P1 node's:
-- spawn_node_enroll_token refuses a joined name, spawn_node_record a name
-- held here.
-- Lock order in every function below: rows of spawn_node_state (in name
-- order when several), then rows of spawn_remote_jobs, then, last and only
-- on a recorded transition, the append lock (spawn_node_events), after which
-- no row of either table is locked. A beat, the sweep, a result, a fault and
-- an owner's change therefore never wait on each other in a cycle.
-- Remote-job records and rows name a judging `judging_id`, never `judging`
-- (spawn_events_control_judging_outcome keys on `record.judging`).

create table if not exists spawn_node_state (
    name                text primary key
                        check (name ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$'),
    node_id             text unique check (node_id ~ '^[0-9a-f]{64}$'),
    pubkey              bytea check (pubkey is null or octet_length(pubkey) = 32),
    cell_id             text not null default 'c0' check (cell_id ~ '^[a-z0-9][a-z0-9-]{0,15}$'),
    status              text not null default 'pending'
                        check (status in ('pending', 'active', 'revoked')),
    drained             boolean not null default false,
    degraded            boolean not null default false,
    lost_recorded       boolean not null default false,
    host_fault_strikes  integer not null default 0 check (host_fault_strikes >= 0),
    enroll_token_sha256 bytea unique
                        check (enroll_token_sha256 is null or octet_length(enroll_token_sha256) = 32),
    enroll_expires_ms   bigint,
    enrolled_at_ms      bigint,
    boot_id             text check (boot_id is null or boot_id ~ '^[0-9a-f]{32}$'),
    boot_seen_ms        bigint,
    beat_seq            bigint not null default 0,
    seq_hi              bigint not null default 0,   -- v0.2 UDP: highest seq seen
    seq_window          bigint not null default 0,   -- v0.2 UDP: 64-bit sliding bitmap below seq_hi
    last_beat_ms        bigint,
    beat                jsonb,
    warm_bases          text[] not null default '{}',
    spec_sha256         text check (spec_sha256 is null or spec_sha256 ~ '^[0-9a-f]{64}$'),
    spec                jsonb,
    spec_at_ms          bigint,
    revoked_at_ms       bigint,
    check ((node_id is null) = (pubkey is null)),
    check (status <> 'active' or node_id is not null)
) with (fillfactor = 50);

create table if not exists spawn_remote_jobs (
    job_id            text primary key check (job_id ~ '^[a-z0-9][a-z0-9._-]{7,63}$'),
    cell_id           text not null default 'c0' check (cell_id ~ '^[a-z0-9][a-z0-9-]{0,15}$'),
    kind              text not null check (kind in ('gate', 'gate_shadow', 'build', 'de_batch')),
    state             text not null default 'queued'
                      check (state in ('queued', 'leased', 'result_pending', 'completed',
                                       'fallback_local', 'dead_letter', 'cancelled')),
    priority          integer not null default 0,
    judging_id        text,            -- never named `judging`: spawn_events_control_judging_outcome
    mission_id        bigint,
    task_id           bigint,
    spec              jsonb not null
                      check (jsonb_typeof(spec) = 'object' and octet_length(spec::text) <= 65536),
    requires          jsonb not null default '{}' check (jsonb_typeof(requires) = 'object'),
    cost              jsonb not null default '{}' check (jsonb_typeof(cost) = 'object'),
    base_commit       text check (base_commit is null or base_commit ~ '^[0-9a-f]{40}$'),
    excluded_nodes    text[] not null default '{}',
    fault_nodes       text[] not null default '{}',
    node_id           text,
    boot_id           text,
    lease_epoch       bigint not null default 0,
    lease_expires_ms  bigint,
    grace_until_ms    bigint,
    grant_seq         bigint,
    attempts          integer not null default 0,
    max_attempts      integer not null default 2 check (max_attempts >= 1),
    enqueued_at_ms    bigint not null,
    queue_deadline_ms bigint,
    leased_at_ms      bigint,
    finished_at_ms    bigint,
    exit_code         integer,
    result            jsonb check (result is null or octet_length(result::text) <= 262144),
    result_sha256     text,
    log_sha256        text,
    log_bytes         bigint check (log_bytes is null or log_bytes between 0 and 33554432),
    check (state not in ('leased', 'result_pending')
           or (node_id is not null and lease_expires_ms is not null))
) with (fillfactor = 70);

create index if not exists spawn_remote_jobs_queue
    on spawn_remote_jobs (cell_id, priority desc, enqueued_at_ms) where state = 'queued';
create index if not exists spawn_remote_jobs_held
    on spawn_remote_jobs (node_id) where state in ('leased', 'result_pending');
create index if not exists spawn_remote_jobs_judging
    on spawn_remote_jobs (judging_id) where judging_id is not null;

-- One `node.recorded` record of the control session. `p_key` makes a
-- transition recorded once.
create or replace function spawn_node_event(p_name text, p_type text, p_fields jsonb, p_key text)
returns bigint language plpgsql security definer as $$
declare
    v_id bigint;
begin
    select a.out_id into v_id
      from spawn_append_trusted(
               'agent_control', 'session_control', null, 'control', p_key,
               jsonb_build_object('name', 'node.recorded', 'detail', jsonb_build_object(
                   'record', jsonb_build_object('type', p_type, 'name', p_name, 'proto', 'node-v1')
                             || coalesce(p_fields, '{}'::jsonb)))) a;
    return v_id;
end $$;

-- The transitions a function collected, `[{name, type, fields, key}]`,
-- recorded in order: the last step of every function below, after its rows
-- (the append lock is taken here and no row of the two tables after it).
create or replace function spawn_node_events(p_facts jsonb) returns integer
language plpgsql security definer as $$
declare
    v_fact jsonb;
    v_count integer := 0;
begin
    for v_fact in select f from jsonb_array_elements(coalesce(p_facts, '[]'::jsonb)) f loop
        perform spawn_node_event(v_fact ->> 'name', v_fact ->> 'type', v_fact -> 'fields',
                                 v_fact ->> 'key');
        v_count := v_count + 1;
    end loop;
    return v_count;
end $$;

-- Fences every lease of `p_node_id` in `p_states` except the jobs in
-- `p_keep` (and, when `p_only` is given, only those): the epoch moves, so
-- nothing the old holder sends is believed. `p_refund` gives the attempt
-- back (a grant the node never received). Returns the `remote_job.lease_fenced`
-- facts for spawn_node_events; it records nothing itself.
create or replace function spawn_node_fence(
    p_node_id text, p_name text, p_states text[], p_keep text[], p_only text[], p_reason text,
    p_refund boolean
) returns jsonb language plpgsql security definer as $$
declare
    v_facts jsonb;
begin
    with fenced as (
        update spawn_remote_jobs j
           set lease_epoch = j.lease_epoch + 1,
               attempts = j.attempts - case when p_refund then 1 else 0 end,
               state = case
                         when p_refund or j.attempts < j.max_attempts then 'queued'
                         when j.kind = 'gate' then 'fallback_local'
                         when j.kind = 'gate_shadow' then 'cancelled'
                         else 'dead_letter' end,
               node_id = null, boot_id = null, lease_expires_ms = null,
               grace_until_ms = null, grant_seq = null
         where j.node_id = p_node_id and j.state = any(p_states)
           and not (j.job_id = any(coalesce(p_keep, '{}')))
           and (p_only is null or j.job_id = any(p_only))
        returning j.job_id, j.lease_epoch, j.state, j.kind)
    select coalesce(jsonb_agg(jsonb_build_object(
               'name', p_name, 'type', 'remote_job.lease_fenced',
               'fields', jsonb_build_object('job_id', f.job_id, 'lease_epoch', f.lease_epoch,
                                            'reason', p_reason, 'next', f.state, 'kind', f.kind),
               'key', 'remote_job:' || f.job_id || ':' || f.lease_epoch || ':fenced')
               order by f.job_id), '[]'::jsonb)
      into v_facts from fenced f;
    return v_facts;
end $$;

-- 1 of 4. POST /node/v1/enroll: consumes a one-time token, pins the key.
create or replace function spawn_node_gw_enroll(
    p_token_sha256 bytea, p_pubkey bytea, p_boot_id text, p_spec_sha256 text, p_spec jsonb
) returns jsonb language plpgsql security definer as $$
declare
    v_now bigint := spawn_now_ms();
    v_n spawn_node_state;
    v_node_id text;
    v_facts jsonb := '[]'::jsonb;
begin
    if octet_length(p_token_sha256) is distinct from 32 or octet_length(p_pubkey) is distinct from 32
       or p_boot_id is null or p_boot_id !~ '^[0-9a-f]{32}$'
       or p_spec_sha256 is null or p_spec_sha256 !~ '^[0-9a-f]{64}$'
       or jsonb_typeof(p_spec) is distinct from 'object' or octet_length(p_spec::text) > 65536 then
        return jsonb_build_object('ok', false, 'error', 'bad_request', 'server_time_ms', v_now);
    end if;
    select * into v_n from spawn_node_state where enroll_token_sha256 = p_token_sha256 for update;
    if not found or v_n.status = 'revoked' or coalesce(v_n.enroll_expires_ms, 0) < v_now then
        return jsonb_build_object('ok', false, 'error', 'bad_token', 'server_time_ms', v_now);
    end if;
    v_node_id := encode(sha256(p_pubkey), 'hex');
    if exists (select 1 from spawn_node_state o where o.node_id = v_node_id and o.name <> v_n.name) then
        return jsonb_build_object('ok', false, 'error', 'key_in_use', 'server_time_ms', v_now);
    end if;
    update spawn_node_state
       set node_id = v_node_id, pubkey = p_pubkey, status = 'active',
           enroll_token_sha256 = null, enroll_expires_ms = null, enrolled_at_ms = v_now,
           boot_id = p_boot_id, boot_seen_ms = v_now, beat_seq = 0, seq_hi = 0, seq_window = 0,
           last_beat_ms = v_now, beat = null, warm_bases = '{}', lost_recorded = false,
           degraded = false, host_fault_strikes = 0,
           spec_sha256 = p_spec_sha256, spec = p_spec, spec_at_ms = v_now
     where name = v_n.name;
    if v_n.node_id is not null then
        -- A new key for the name: whatever the old key held is fenced.
        v_facts := spawn_node_fence(v_n.node_id, v_n.name, array['leased', 'result_pending'], null,
                                    null, 're_enrolled', false);
    end if;
    perform spawn_node_events(v_facts || jsonb_build_array(jsonb_build_object(
        'name', v_n.name, 'type', 'node.enrolled',
        'fields', jsonb_build_object('node_id', v_node_id, 'cell_id', v_n.cell_id,
                                     'spec_sha256', p_spec_sha256, 'replaced', v_n.node_id),
        'key', 'node:' || v_node_id || ':enrolled:' || v_now)));
    return jsonb_build_object('ok', true, 'name', v_n.name, 'node_id', v_node_id,
                              'cell_id', v_n.cell_id, 'server_time_ms', v_now);
end $$;

-- 2 of 4. POST /node/v1/heartbeat. Returns the node's key with its answer:
-- the gateway verifies the request's signature against it and commits, or
-- rolls the whole call back. No append lock and no event unless a state
-- changes (a new boot, a node back, a lease granted or fenced).
create or replace function spawn_node_gw_beat(
    p_node_id text, p_boot_id text, p_seq bigint, p_beat jsonb
) returns jsonb language plpgsql security definer as $$
declare
    c_ttl_ms constant bigint := 90000;
    c_grace_ms constant bigint := 180000;
    c_max_grants constant integer := 2;
    v_now bigint := spawn_now_ms();
    v_n spawn_node_state;
    v_pub text;
    v_new_boot boolean := false;
    v_held jsonb;
    v_pending jsonb;
    v_keep text[];
    v_renewed jsonb;
    v_fenced jsonb;
    v_acked jsonb;
    v_need_spec boolean;
    v_avail jsonb;
    v_job spawn_remote_jobs;
    v_fits boolean;
    v_grants jsonb := '[]'::jsonb;
    v_granted integer := 0;
    v_need_sync jsonb := '{}'::jsonb;
    v_facts jsonb := '[]'::jsonb;
begin
    select * into v_n from spawn_node_state where node_id = p_node_id for update;
    if not found or v_n.status = 'pending' then
        return jsonb_build_object('ok', false, 'error', 'unknown_node', 'server_time_ms', v_now);
    end if;
    v_pub := encode(v_n.pubkey, 'base64');
    if v_n.status = 'revoked' then
        return jsonb_build_object('ok', false, 'error', 'revoked', 'pubkey', v_pub,
                                  'server_time_ms', v_now);
    end if;
    if p_boot_id is null or p_boot_id !~ '^[0-9a-f]{32}$' or p_seq is null or p_seq < 1
       or jsonb_typeof(p_beat) is distinct from 'object' then
        return jsonb_build_object('ok', false, 'error', 'bad_request', 'pubkey', v_pub,
                                  'server_time_ms', v_now);
    end if;
    -- A boot id's first 16 hex digits are the node's persistent boot counter.
    if v_n.boot_id is null or left(p_boot_id, 16) > left(v_n.boot_id, 16) then
        v_new_boot := true;
    elsif p_boot_id <> v_n.boot_id then
        return jsonb_build_object('ok', false, 'error', 'stale_boot', 'pubkey', v_pub,
                                  'server_time_ms', v_now);
    elsif p_seq <= v_n.beat_seq then
        return jsonb_build_object('ok', false, 'error', 'replay', 'pubkey', v_pub,
                                  'server_time_ms', v_now);
    end if;

    v_held := case when jsonb_typeof(p_beat -> 'leases') = 'array' then p_beat -> 'leases'
                   else '[]'::jsonb end;
    v_pending := case when jsonb_typeof(p_beat -> 'lease_results_pending') = 'array'
                      then p_beat -> 'lease_results_pending' else '[]'::jsonb end;

    -- A finished job whose result waits here: no longer fenced by its lease.
    update spawn_remote_jobs j
       set state = 'result_pending', grace_until_ms = v_now + c_grace_ms
     where j.node_id = p_node_id and j.state = 'leased'
       and exists (select 1 from jsonb_array_elements(v_pending) r
                    where r ->> 'job_id' = j.job_id
                      and r ->> 'lease_epoch' = j.lease_epoch::text);

    if v_new_boot then
        -- The process that held them is gone: fenced at once, no TTL wait.
        v_facts := v_facts || spawn_node_fence(p_node_id, v_n.name, array['leased'], null, null,
                                               'boot_id_changed', false);
    else
        -- A lease granted by an earlier answer that this (later) beat does
        -- not hold, at its epoch: the answer never arrived. Given back, the
        -- attempt too.
        select coalesce(array_agg(j.job_id), '{}') into v_keep
          from spawn_remote_jobs j
         where j.node_id = p_node_id and j.state = 'leased'
           and exists (select 1 from jsonb_array_elements(v_held) r
                        where r ->> 'job_id' = j.job_id
                          and r ->> 'lease_epoch' = j.lease_epoch::text);
        update spawn_remote_jobs j set grant_seq = null
         where j.node_id = p_node_id and j.state = 'leased' and j.job_id = any(v_keep)
           and j.grant_seq is not null;
        if exists (select 1 from spawn_remote_jobs j
                    where j.node_id = p_node_id and j.state = 'leased'
                      and not (j.job_id = any(v_keep))) then
            v_facts := v_facts || spawn_node_fence(p_node_id, v_n.name, array['leased'], v_keep,
                                                   null, 'grant_lost', true);
        end if;
    end if;

    with renewed as (
        update spawn_remote_jobs j
           set lease_expires_ms = v_now + c_ttl_ms
         where j.node_id = p_node_id and j.state = 'leased'
           and exists (select 1 from jsonb_array_elements(v_held) r
                        where r ->> 'job_id' = j.job_id
                          and r ->> 'lease_epoch' = j.lease_epoch::text)
        returning j.job_id, j.lease_epoch)
    select coalesce(jsonb_agg(jsonb_build_object('job_id', job_id, 'lease_epoch', lease_epoch)
                              order by job_id), '[]'::jsonb)
      into v_renewed from renewed;

    -- What the node holds and the ledger does not: it must stop and drop it.
    select coalesce(jsonb_agg(jsonb_build_object('job_id', r ->> 'job_id',
                                                 'lease_epoch', r -> 'lease_epoch',
                                                 'reason', 'not_held')), '[]'::jsonb)
      into v_fenced
      from jsonb_array_elements(v_held || v_pending) r
     where not exists (select 1 from spawn_remote_jobs j
                        where j.job_id = r ->> 'job_id' and j.node_id = p_node_id
                          and j.lease_epoch::text = r ->> 'lease_epoch'
                          and j.state in ('leased', 'result_pending', 'completed'));
    select coalesce(jsonb_agg(jsonb_build_object('job_id', r ->> 'job_id',
                                                 'lease_epoch', r -> 'lease_epoch')), '[]'::jsonb)
      into v_acked
      from jsonb_array_elements(v_pending) r
     where exists (select 1 from spawn_remote_jobs j
                    where j.job_id = r ->> 'job_id' and j.node_id = p_node_id
                      and j.lease_epoch::text = r ->> 'lease_epoch' and j.state = 'completed');

    v_need_spec := v_n.spec_sha256 is distinct from (p_beat ->> 'spec_sha256');

    -- Grants: at most two an answer, each within what the node says is free.
    -- SKIP LOCKED: two nodes beating at once never wait on, nor share, a job.
    if not v_n.drained and not v_n.degraded and not v_need_spec
       and coalesce(p_beat ->> 'state', 'idle') <> 'draining' then
        select coalesce(jsonb_object_agg(c.key, coalesce((c.value ->> 'free')::bigint, 0)),
                        '{}'::jsonb)
               || jsonb_build_object('tmpfs_mb',
                      coalesce((p_beat #>> '{tmpfs_budget_mb,free}')::bigint, 0))
          into v_avail
          from jsonb_each(case when jsonb_typeof(p_beat -> 'capacities') = 'object'
                               then p_beat -> 'capacities' else '{}'::jsonb end) c;
        for v_job in
            select j.* from spawn_remote_jobs j
             where j.state = 'queued' and j.cell_id = v_n.cell_id
               and not (p_node_id = any(j.excluded_nodes))
             order by j.priority desc, j.enqueued_at_ms
             for update skip locked
             limit 16
        loop
            exit when v_granted >= c_max_grants;
            if not (v_job.requires <@ coalesce(v_n.spec -> 'holds', '{}'::jsonb)) then
                -- need_registry_sync and its kin: never leased until held.
                if v_need_sync = '{}'::jsonb then v_need_sync := v_job.requires; end if;
                continue;
            end if;
            select coalesce(bool_and(coalesce((v_avail ->> c.key)::bigint, 0) >= c.value::bigint),
                            true)
              into v_fits from jsonb_each_text(v_job.cost) c;
            continue when not v_fits;
            select coalesce(jsonb_object_agg(a.key,
                       a.value::bigint - coalesce((v_job.cost ->> a.key)::bigint, 0)), '{}'::jsonb)
              into v_avail from jsonb_each_text(v_avail) a;
            update spawn_remote_jobs j
               set state = 'leased', node_id = p_node_id, boot_id = p_boot_id,
                   lease_epoch = j.lease_epoch + 1, lease_expires_ms = v_now + c_ttl_ms,
                   leased_at_ms = v_now, grant_seq = p_seq, attempts = j.attempts + 1,
                   grace_until_ms = null
             where j.job_id = v_job.job_id
            returning j.* into v_job;
            v_granted := v_granted + 1;
            v_grants := v_grants || jsonb_build_object(
                'job_id', v_job.job_id, 'lease_epoch', v_job.lease_epoch, 'kind', v_job.kind,
                'cost', v_job.cost, 'spec', v_job.spec, 'attempt', v_job.attempts,
                'needs_baseline', v_job.base_commit is not null
                    and not (v_job.base_commit = any(
                        coalesce(array(select jsonb_array_elements_text(
                            case when jsonb_typeof(p_beat -> 'warm_bases') = 'array'
                                 then p_beat -> 'warm_bases' else '[]'::jsonb end)), '{}'))));
        end loop;
    end if;

    update spawn_node_state
       set boot_id = p_boot_id,
           boot_seen_ms = case when v_new_boot then v_now else boot_seen_ms end,
           beat_seq = p_seq, seq_hi = greatest(seq_hi, p_seq), last_beat_ms = v_now,
           beat = p_beat, lost_recorded = false,
           warm_bases = coalesce(array(select jsonb_array_elements_text(
               case when jsonb_typeof(p_beat -> 'warm_bases') = 'array'
                    then p_beat -> 'warm_bases' else '[]'::jsonb end)), '{}')
     where name = v_n.name;

    -- Rows are done: the recorded transitions, under the append lock, last.
    if v_n.lost_recorded then
        v_facts := v_facts || jsonb_build_array(jsonb_build_object(
            'name', v_n.name, 'type', 'node.back',
            'fields', jsonb_build_object('node_id', p_node_id, 'down_ms', v_now - v_n.last_beat_ms)));
    end if;
    select v_facts || coalesce(jsonb_agg(jsonb_build_object(
               'name', v_n.name, 'type', 'remote_job.leased',
               'fields', jsonb_build_object('job_id', g ->> 'job_id', 'lease_epoch', g -> 'lease_epoch',
                                            'kind', g ->> 'kind', 'node_id', p_node_id),
               'key', 'remote_job:' || (g ->> 'job_id') || ':' || (g ->> 'lease_epoch') || ':leased')),
               '[]'::jsonb)
      into v_facts from jsonb_array_elements(v_grants) g;
    perform spawn_node_events(v_facts);

    return jsonb_build_object(
        'ok', true, 'pubkey', v_pub, 'name', v_n.name, 'server_time_ms', v_now,
        -- 5 s busy or idle: an idle node must lease newly queued work well
        -- inside the 30 s default queue wait, even with ±20% node jitter.
        'next_beat_ms', 5000,
        'lease_ttl_s', c_ttl_ms / 1000, 'need_spec', v_need_spec, 'need_sync', v_need_sync,
        'renewed', v_renewed, 'fenced', v_fenced, 'acked_results', v_acked,
        'grants', v_grants, 'drain', v_n.drained);
end $$;

-- 3 of 4. POST /node/v1/spec: the node's labels, totals and what it holds.
create or replace function spawn_node_gw_spec(
    p_node_id text, p_boot_id text, p_spec_sha256 text, p_spec jsonb
) returns jsonb language plpgsql security definer as $$
declare
    v_now bigint := spawn_now_ms();
    v_n spawn_node_state;
    v_pub text;
begin
    select * into v_n from spawn_node_state where node_id = p_node_id for update;
    if not found or v_n.status = 'pending' then
        return jsonb_build_object('ok', false, 'error', 'unknown_node', 'server_time_ms', v_now);
    end if;
    v_pub := encode(v_n.pubkey, 'base64');
    if v_n.status = 'revoked' then
        return jsonb_build_object('ok', false, 'error', 'revoked', 'pubkey', v_pub,
                                  'server_time_ms', v_now);
    end if;
    if p_spec_sha256 is null or p_spec_sha256 !~ '^[0-9a-f]{64}$'
       or jsonb_typeof(p_spec) is distinct from 'object' or octet_length(p_spec::text) > 65536 then
        return jsonb_build_object('ok', false, 'error', 'bad_request', 'pubkey', v_pub,
                                  'server_time_ms', v_now);
    end if;
    if v_n.boot_id is distinct from p_boot_id then
        return jsonb_build_object('ok', false, 'error', 'beat_first', 'pubkey', v_pub,
                                  'server_time_ms', v_now);
    end if;
    if v_n.spec_sha256 is not distinct from p_spec_sha256 then
        return jsonb_build_object('ok', true, 'changed', false, 'pubkey', v_pub,
                                  'server_time_ms', v_now);
    end if;
    update spawn_node_state
       set spec_sha256 = p_spec_sha256, spec = p_spec, spec_at_ms = v_now
     where name = v_n.name;
    perform spawn_node_events(jsonb_build_array(jsonb_build_object(
        'name', v_n.name, 'type', 'node.spec_registered',
        'fields', jsonb_build_object('node_id', p_node_id, 'spec_sha256', p_spec_sha256,
                                     'holds', p_spec -> 'holds', 'labels', p_spec -> 'labels'),
        'key', 'node:' || p_node_id || ':spec:' || p_spec_sha256 || ':' || v_n.boot_id)));
    return jsonb_build_object('ok', true, 'changed', true, 'pubkey', v_pub, 'server_time_ms', v_now);
end $$;

-- 4 of 4. POST /node/v1/jobs/<job_id>/result: the fenced completion. True
-- when this call, or an identical earlier one, completed the job. The node
-- row is read FOR SHARE first (the lock order): a result never completes
-- beside a revoke of its node, and waits out a beat of it.
create or replace function spawn_node_gw_result(
    p_node_id text, p_job_id text, p_lease_epoch bigint, p_result jsonb
) returns boolean language plpgsql security definer as $$
declare
    v_now bigint := spawn_now_ms();
    v_done boolean;
    v_name text;
    v_kind text;
begin
    if jsonb_typeof(p_result) is distinct from 'object'
       or coalesce(p_result ->> 'result_sha256', '') !~ '^[0-9a-f]{64}$'
       or coalesce(p_result ->> 'log_sha256', '') !~ '^[0-9a-f]{64}$'
       or coalesce(p_result ->> 'log_bytes', '') !~ '^[0-9]{1,8}$'
       or coalesce(p_result ->> 'exit_code', '0') !~ '^-?[0-9]{1,9}$' then
        return false;
    end if;
    select n.name into v_name from spawn_node_state n
     where n.node_id = p_node_id and n.status = 'active'
       for share;
    if v_name is null then
        return false;
    end if;
    update spawn_remote_jobs
       set state = 'completed', finished_at_ms = v_now,
           exit_code = (p_result ->> 'exit_code')::integer,
           result = p_result, result_sha256 = p_result ->> 'result_sha256',
           log_sha256 = p_result ->> 'log_sha256', log_bytes = (p_result ->> 'log_bytes')::bigint,
           lease_expires_ms = null, grace_until_ms = null
     where job_id = p_job_id and lease_epoch = p_lease_epoch
       and state in ('leased', 'result_pending')
       and node_id = p_node_id
    returning true, kind into v_done, v_kind;
    if v_done then
        perform spawn_node_events(jsonb_build_array(jsonb_build_object(
            'name', v_name, 'type', 'remote_job.completed',
            'fields', jsonb_build_object('job_id', p_job_id, 'lease_epoch', p_lease_epoch,
                                         'kind', v_kind, 'node_id', p_node_id,
                                         'exit_code', p_result -> 'exit_code',
                                         'seconds', p_result -> 'seconds',
                                         'result_sha256', p_result ->> 'result_sha256'),
            'key', 'remote_job:' || p_job_id || ':' || p_lease_epoch || ':completed')));
        return true;
    end if;
    return exists (select 1 from spawn_remote_jobs j
                    where j.job_id = p_job_id and j.lease_epoch = p_lease_epoch
                      and j.node_id = p_node_id and j.state = 'completed'
                      and j.result_sha256 = p_result ->> 'result_sha256');
end $$;

-- Owner side (never granted to the gateway). The level-triggered sweep, run
-- from the integrator's pass: a lease past its time waits `result_pending`
-- for 180 s, then is fenced; a node silent for a lease's time is recorded
-- lost, once. The nodes it acts on are locked first, in name order, as a
-- beat locks its own node before its jobs; their jobs after; the events last.
create or replace function spawn_node_sweep() returns jsonb
language plpgsql security definer as $$
declare
    c_ttl_ms constant bigint := 90000;
    c_grace_ms constant bigint := 180000;
    v_now bigint := spawn_now_ms();
    v_nodes text[];
    v_n record;
    v_waiting integer;
    v_fenced integer := 0;
    v_lost jsonb;
    v_facts jsonb := '[]'::jsonb;
    v_some jsonb;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner sweeps the nodes; % may not', session_user
            using errcode = '42501';
    end if;
    select coalesce(array_agg(x.node_id order by x.name), '{}') into v_nodes
      from (select n.name, n.node_id from spawn_node_state n
             where n.node_id is not null
               and (exists (select 1 from spawn_remote_jobs j
                             where j.node_id = n.node_id
                               and ((j.state = 'leased' and j.lease_expires_ms < v_now)
                                    or (j.state = 'result_pending' and j.grace_until_ms < v_now)))
                    or (n.status = 'active' and not n.lost_recorded
                        and n.last_beat_ms < v_now - c_ttl_ms))
             order by n.name
               for update of n) x;
    update spawn_remote_jobs
       set state = 'result_pending', grace_until_ms = v_now + c_grace_ms
     where state = 'leased' and lease_expires_ms < v_now and node_id = any(v_nodes);
    get diagnostics v_waiting = row_count;
    for v_n in
        select n.name, n.node_id,
               array(select j.job_id from spawn_remote_jobs j
                      where j.node_id = n.node_id and j.state = 'result_pending'
                        and j.grace_until_ms < v_now) as late
          from spawn_node_state n
         where n.node_id = any(v_nodes)
         order by n.name
    loop
        continue when cardinality(v_n.late) = 0;
        v_some := spawn_node_fence(v_n.node_id, v_n.name, array['result_pending'], null, v_n.late,
                                   'lease_expired', false);
        v_fenced := v_fenced + jsonb_array_length(v_some);
        v_facts := v_facts || v_some;
    end loop;
    with lost as (
        update spawn_node_state n set lost_recorded = true
         where n.node_id = any(v_nodes) and n.status = 'active' and not n.lost_recorded
           and n.last_beat_ms < v_now - c_ttl_ms
        returning n.name, n.node_id, n.last_beat_ms)
    select coalesce(jsonb_agg(jsonb_build_object(
               'name', l.name, 'type', 'node.lost',
               'fields', jsonb_build_object('node_id', l.node_id, 'last_seen_ms', l.last_beat_ms,
                                            'silent_ms', v_now - l.last_beat_ms))
               order by l.name), '[]'::jsonb)
      into v_lost from lost l;
    perform spawn_node_events(v_facts || v_lost);
    return jsonb_build_object('waiting', v_waiting, 'fenced', v_fenced,
                              'lost', jsonb_array_length(v_lost));
end $$;

-- `spawn node enroll-token <name>`: a one-time token's digest, good at most
-- 10 minutes. Returns when it expires.
create or replace function spawn_node_enroll_token(
    p_name text, p_cell text, p_token_sha256 bytea, p_ttl_ms bigint
) returns bigint language plpgsql security definer as $$
declare
    v_now bigint := spawn_now_ms();
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner enrolls a node; % may not', session_user
            using errcode = '42501';
    end if;
    if octet_length(p_token_sha256) is distinct from 32
       or p_ttl_ms is null or p_ttl_ms not between 1000 and 600000 then
        raise exception 'an enrollment token is 32 bytes of SHA-256, good for at most 10 minutes'
            using errcode = '22023';
    end if;
    -- A name the P1 records hold joined is another node's (spawn_node_record).
    if exists (select 1 from spawn_node_latest('node.joined', p_name, 0) j
                where not exists (select 1 from spawn_node_latest('node.removed', p_name, j.seq))) then
        raise exception 'node % is joined by `spawn node add` (spawn node remove first)', p_name
            using errcode = '23505';
    end if;
    insert into spawn_node_state (name, cell_id, enroll_token_sha256, enroll_expires_ms)
    values (p_name, coalesce(p_cell, 'c0'), p_token_sha256, v_now + p_ttl_ms)
    on conflict (name) do update
       set enroll_token_sha256 = excluded.enroll_token_sha256,
           enroll_expires_ms = excluded.enroll_expires_ms,
           cell_id = excluded.cell_id
     where spawn_node_state.status <> 'revoked';
    if not found then
        raise exception 'node % is revoked: enroll it under another name', p_name
            using errcode = '55000';
    end if;
    return v_now + p_ttl_ms;
end $$;

-- `spawn node drain|undrain|revoke <name>` of a v1 node. An undrain also
-- clears `degraded` and its strikes: the owner looked.
create or replace function spawn_node_admin(p_name text, p_action text) returns boolean
language plpgsql security definer as $$
declare
    v_now bigint := spawn_now_ms();
    v_n spawn_node_state;
    v_facts jsonb := '[]'::jsonb;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner changes a node; % may not', session_user
            using errcode = '42501';
    end if;
    if p_action is null or p_action not in ('drain', 'undrain', 'revoke') then
        raise exception 'a node is drained, undrained or revoked, not %', p_action
            using errcode = '22023';
    end if;
    select * into v_n from spawn_node_state where name = p_name for update;
    if not found then
        raise exception 'no node is named %', p_name using errcode = 'P0002';
    end if;
    if p_action = 'drain' then
        if v_n.drained then return false; end if;
        update spawn_node_state set drained = true where name = p_name;
    elsif p_action = 'undrain' then
        if not v_n.drained and not v_n.degraded then return false; end if;
        update spawn_node_state set drained = false, degraded = false, host_fault_strikes = 0
         where name = p_name;
    else
        if v_n.status = 'revoked' then return false; end if;
        update spawn_node_state
           set status = 'revoked', revoked_at_ms = v_now, enroll_token_sha256 = null,
               enroll_expires_ms = null
         where name = p_name;
        if v_n.node_id is not null then
            v_facts := spawn_node_fence(v_n.node_id, p_name, array['leased', 'result_pending'],
                                        null, null, 'revoked', false);
        end if;
    end if;
    perform spawn_node_events(v_facts || jsonb_build_array(jsonb_build_object(
        'name', p_name,
        'type', case p_action when 'drain' then 'node.drained' when 'undrain' then 'node.undrained'
                              else 'node.revoked' end,
        'fields', jsonb_build_object('node_id', v_n.node_id))));
    return true;
end $$;

-- The integrator's enqueue. `p_job`: {job_id, kind, cell_id?, priority?,
-- judging_id?, mission_id?, task_id?, spec, requires, cost, base_commit?,
-- max_attempts?, queue_wait_ms?}. Returns the job's id.
create or replace function spawn_remote_job_enqueue(p_job jsonb) returns text
language plpgsql security definer as $$
declare
    v_now bigint := spawn_now_ms();
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner queues a remote job; % may not', session_user
            using errcode = '42501';
    end if;
    insert into spawn_remote_jobs (job_id, kind, cell_id, priority, judging_id, mission_id, task_id,
                                   spec, requires, cost, base_commit, max_attempts,
                                   enqueued_at_ms, queue_deadline_ms)
    values (p_job ->> 'job_id', p_job ->> 'kind', coalesce(p_job ->> 'cell_id', 'c0'),
            coalesce((p_job ->> 'priority')::integer, 0), p_job ->> 'judging_id',
            (p_job ->> 'mission_id')::bigint, (p_job ->> 'task_id')::bigint,
            p_job -> 'spec', coalesce(p_job -> 'requires', '{}'::jsonb),
            coalesce(p_job -> 'cost', '{}'::jsonb), p_job ->> 'base_commit',
            coalesce((p_job ->> 'max_attempts')::integer, 2), v_now,
            v_now + coalesce((p_job ->> 'queue_wait_ms')::bigint, 30000));
    return p_job ->> 'job_id';
end $$;

-- FALLBACK_LOCAL: the integrator takes back a job no node holds, at the
-- epoch it read. The same fenced compare-and-set as a node's result: one of
-- the two wins, never both.
create or replace function spawn_remote_job_take_local(p_job_id text, p_lease_epoch bigint)
returns boolean language plpgsql security definer as $$
declare
    v_done boolean;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner takes a remote job back; % may not', session_user
            using errcode = '42501';
    end if;
    update spawn_remote_jobs
       set state = 'fallback_local', lease_epoch = lease_epoch + 1, finished_at_ms = spawn_now_ms()
     where job_id = p_job_id and lease_epoch = p_lease_epoch and state = 'queued'
    returning true into v_done;
    return coalesce(v_done, false);
end $$;

-- The integrator's reading of a completed job (spawn-cli gate.rs `decide`)
-- when it is the node's fault: a strike, three make it degraded (no grants
-- until `spawn node undrain`). `p_next`: 'queued' (another node, this one
-- excluded), 'fallback_local', 'dead_letter' or 'keep' (the row stays
-- completed). A job that faulted on two nodes is the poison, not they: the
-- earlier nodes' strikes from it are given back and the job goes local
-- (gate), stays (gate_shadow) or is dead-lettered. A completion is judged
-- once: a second call for it answers ok false.
create or replace function spawn_remote_job_fault(
    p_job_id text, p_lease_epoch bigint, p_evidence text, p_strike boolean, p_next text
) returns jsonb language plpgsql security definer as $$
declare
    v_j spawn_remote_jobs;
    v_n spawn_node_state;
    v_poison boolean;
    v_strikes integer;
    v_next text := p_next;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner judges a remote job; % may not', session_user
            using errcode = '42501';
    end if;
    if p_next is null or p_next not in ('queued', 'fallback_local', 'dead_letter', 'keep') then
        raise exception 'a faulted job is queued, fallback_local, dead_letter or kept, not %', p_next
            using errcode = '22023';
    end if;
    select j.* into v_j from spawn_remote_jobs j
     where j.job_id = p_job_id and j.lease_epoch = p_lease_epoch and j.state = 'completed';
    if not found then
        return jsonb_build_object('ok', false);
    end if;
    -- Every node the judging may change, first, in name order.
    perform 1 from spawn_node_state n
     where n.node_id = v_j.node_id or n.node_id = any(v_j.fault_nodes)
     order by n.name
       for update;
    select * into v_n from spawn_node_state where node_id = v_j.node_id;
    select * into v_j from spawn_remote_jobs
     where job_id = p_job_id and lease_epoch = p_lease_epoch and state = 'completed' for update;
    if not found or v_j.node_id = any(v_j.excluded_nodes) then
        return jsonb_build_object('ok', false);
    end if;
    v_poison := coalesce(p_strike, false) and cardinality(v_j.fault_nodes) >= 1
                and not (v_j.node_id = any(v_j.fault_nodes));
    if v_poison then
        update spawn_node_state n
           set host_fault_strikes = greatest(n.host_fault_strikes - 1, 0)
         where n.node_id = any(v_j.fault_nodes) and n.node_id <> v_j.node_id;
        v_next := case when v_j.kind = 'gate' then 'fallback_local'
                       when v_j.kind = 'gate_shadow' then 'keep' else 'dead_letter' end;
    elsif coalesce(p_strike, false) and v_n.name is not null then
        update spawn_node_state
           set host_fault_strikes = host_fault_strikes + 1,
               degraded = degraded or host_fault_strikes + 1 >= 3
         where name = v_n.name
        returning host_fault_strikes into v_strikes;
    end if;
    if v_next = 'queued' and v_j.attempts >= v_j.max_attempts then
        v_next := case when v_j.kind = 'gate' then 'fallback_local'
                       when v_j.kind = 'gate_shadow' then 'keep' else 'dead_letter' end;
    end if;
    update spawn_remote_jobs
       set fault_nodes = case when coalesce(p_strike, false)
                              then array_append(fault_nodes, v_j.node_id) else fault_nodes end,
           excluded_nodes = array_append(excluded_nodes, v_j.node_id),
           state = case when v_next = 'keep' then state else v_next end,
           lease_epoch = case when v_next = 'keep' then lease_epoch else lease_epoch + 1 end,
           node_id = case when v_next = 'queued' then null else node_id end,
           boot_id = case when v_next = 'queued' then null else boot_id end,
           grant_seq = null
     where job_id = p_job_id;
    perform spawn_node_events(jsonb_build_array(jsonb_build_object(
        'name', coalesce(v_n.name, 'unknown'), 'type', 'remote_job.host_fault',
        'fields', jsonb_build_object('job_id', p_job_id, 'lease_epoch', p_lease_epoch,
                                     'kind', v_j.kind, 'node_id', v_j.node_id,
                                     'evidence', p_evidence, 'exit_code', v_j.exit_code,
                                     'strike', coalesce(p_strike, false) and not v_poison,
                                     'strikes', v_strikes,
                                     'degraded', coalesce(v_strikes, 0) >= 3, 'poison', v_poison,
                                     'next', v_next),
        'key', 'remote_job:' || p_job_id || ':' || p_lease_epoch || ':host_fault')));
    return jsonb_build_object('ok', true, 'next', v_next, 'poison', v_poison,
                              'strikes', v_strikes, 'degraded', coalesce(v_strikes, 0) >= 3);
end $$;

-- The integrator's reading of a completed job whose node gave a verdict on
-- the job's own inputs, believed or not (spawn-cli integrate/remote.rs
-- `settle`; never a rejection naming only test-database errors): the run
-- was valid, so the node's strikes go back to 0. `degraded` stays as it is
-- (only `spawn node undrain` clears it). Same lock order as
-- spawn_remote_job_fault (nodes in name order, then the job); the row stays
-- completed and its epoch moves, so a completion is judged once: a second
-- call, or a fault judging at the old epoch, answers ok false.
create or replace function spawn_remote_job_valid(p_job_id text, p_lease_epoch bigint)
returns jsonb language plpgsql security definer as $$
declare
    v_j spawn_remote_jobs;
    v_n spawn_node_state;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner judges a remote job; % may not', session_user
            using errcode = '42501';
    end if;
    select j.* into v_j from spawn_remote_jobs j
     where j.job_id = p_job_id and j.lease_epoch = p_lease_epoch and j.state = 'completed';
    if not found then
        return jsonb_build_object('ok', false);
    end if;
    perform 1 from spawn_node_state n
     where n.node_id = v_j.node_id
     order by n.name
       for update;
    select * into v_n from spawn_node_state where node_id = v_j.node_id;
    select * into v_j from spawn_remote_jobs
     where job_id = p_job_id and lease_epoch = p_lease_epoch and state = 'completed' for update;
    if not found or v_j.node_id = any(v_j.excluded_nodes) then
        return jsonb_build_object('ok', false);
    end if;
    update spawn_remote_jobs
       set lease_epoch = lease_epoch + 1,
           finished_at_ms = coalesce(finished_at_ms, spawn_now_ms())
     where job_id = p_job_id;
    if v_n.name is not null then
        update spawn_node_state set host_fault_strikes = 0 where name = v_n.name;
    end if;
    return jsonb_build_object('ok', true, 'prior_strikes', coalesce(v_n.host_fault_strikes, 0),
                              'strikes', 0);
end $$;

-- The gateway's login (`spawn-node-gateway`): this database's
-- `spawn_node_gateway_<db>`, made without login like the others
-- (PostgresStore::migrate gives it one, and its timeouts: statement 5 s,
-- lock 2 s, idle in a transaction 5 s). It may connect, see the schema and
-- execute the four spawn_node_gw_* functions; it holds no table privilege
-- and no row of spawn_grants, and spawn_mission_caller names it nobody.
-- Every function above is closed to public and pins its search path.
do $$
declare
    v_role text := spawn_login_role('spawn_node_gateway');
    v_function text;
begin
    if not exists (select 1 from pg_roles where rolname = v_role) then
        execute format('create role %I nologin', v_role);
    end if;
    if coalesce(shobj_description((select oid from pg_roles where rolname = v_role),
                                  'pg_authid'), '') !~ '^spawn login salt [0-9a-f]{64}$' then
        execute format('comment on role %I is %L', v_role,
                       'spawn login salt '
                       || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''));
    end if;
    if not exists (select 1 from pg_database d cross join lateral aclexplode(d.datacl) a
                    where d.datname = current_database() and a.privilege_type = 'CONNECT'
                      and a.grantee = (select oid from pg_roles where rolname = v_role)) then
        execute format('grant connect on database %I to %I', current_database(), v_role);
    end if;
    execute format('grant usage on schema %I to %I', current_schema(), v_role);
    foreach v_function in array array[
        'spawn_node_event(text, text, jsonb, text)', 'spawn_node_events(jsonb)',
        'spawn_node_fence(text, text, text[], text[], text[], text, boolean)',
        'spawn_node_gw_enroll(bytea, bytea, text, text, jsonb)',
        'spawn_node_gw_beat(text, text, bigint, jsonb)',
        'spawn_node_gw_spec(text, text, text, jsonb)',
        'spawn_node_gw_result(text, text, bigint, jsonb)',
        'spawn_node_sweep()', 'spawn_node_enroll_token(text, text, bytea, bigint)',
        'spawn_node_admin(text, text)', 'spawn_remote_job_enqueue(jsonb)',
        'spawn_remote_job_take_local(text, bigint)',
        'spawn_remote_job_fault(text, bigint, text, boolean, text)',
        'spawn_remote_job_valid(text, bigint)'] loop
        execute format('alter function %s set search_path = %I, pg_temp', v_function, current_schema());
        execute format('revoke execute on function %s from public', v_function);
    end loop;
    foreach v_function in array array[
        'spawn_node_gw_enroll(bytea, bytea, text, text, jsonb)',
        'spawn_node_gw_beat(text, text, bigint, jsonb)',
        'spawn_node_gw_spec(text, text, text, jsonb)',
        'spawn_node_gw_result(text, text, bigint, jsonb)'] loop
        execute format('grant execute on function %s to %I', v_function, v_role);
    end loop;
    revoke all on spawn_node_state, spawn_remote_jobs from public;
    execute format('revoke all on spawn_node_state, spawn_remote_jobs from %I', v_role);
end
$$;
-- spawn-node v1 ledger: end (PR S1).


-- The alert transitions: the loop's `alert.fired` and `alert.cleared`
-- records (`spawn_alert_record`, owner only), each once per occurrence
-- (docs/fleet-architecture.md, "Alerts"). The checked writer refuses a
-- second `fired` for a key, a `cleared` without its `fired`, and a second
-- `cleared`; the fold does the same, so the log and the table agree.
create or replace function spawn_alert_record(p_record jsonb)
returns bigint language plpgsql security definer as $$
declare
    v_type text := p_record ->> 'type';
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record alerts', session_user using errcode = '42501';
    end if;
    if v_type not in ('alert.fired', 'alert.cleared', 'alert.judged', 'alert.updated') then
        raise exception 'not an alert record: %', v_type;
    end if;
    -- The owner's judgement (objective 092): `{type, key, verdict}`, checked
    -- as the fold checks it, before anything is written.
    if v_type = 'alert.judged' then
        if exists (select 1 from jsonb_object_keys(p_record) k
                    where k not in ('type', 'key', 'verdict')) then
            raise exception 'an alert judgement is {type, key, verdict}, nothing else';
        end if;
        if coalesce(p_record ->> 'verdict', '') not in ('right', 'false', 'stale', 'duplicate') then
            raise exception 'an alert verdict is right, false, stale or duplicate, not %',
                            coalesce(p_record ->> 'verdict', 'none');
        end if;
        if not exists (select 1 from spawn_alerts where key = p_record ->> 'key') then
            raise exception 'no alert has the key %', p_record ->> 'key';
        end if;
        if exists (select 1 from spawn_alerts where key = p_record ->> 'key' and notice) then
            raise exception 'alert % is a notice: a notice is not judged', p_record ->> 'key';
        end if;
        if exists (select 1 from spawn_alerts
                    where key = p_record ->> 'key' and verdict is not null) then
            raise exception 'alert % is judged already', p_record ->> 'key';
        end if;
        return spawn_control_record(p_record);
    end if;
    if nullif(p_record ->> 'key', '') is null or nullif(p_record ->> 'kind', '') is null
       or nullif(p_record ->> 'subject', '') is null then
        raise exception 'an alert record names a key, a kind and a subject: %', p_record;
    end if;
    if v_type = 'alert.fired' then
        if exists (select 1 from spawn_alerts where key = p_record ->> 'key') then
            raise exception 'alert % was already fired', p_record ->> 'key';
        end if;
    elsif v_type = 'alert.updated' then
        -- An open alert's current text and evidence (objective 219): the
        -- key's alert open (not a notice, not cleared), of that kind and
        -- subject, and a text.
        if not exists (select 1 from spawn_alerts
                        where key = p_record ->> 'key' and state = 'open' and not notice
                          and kind = p_record ->> 'kind'
                          and subject = p_record ->> 'subject') then
            raise exception 'alert % is not an open % alert of %: nothing to update',
                            p_record ->> 'key', p_record ->> 'kind', p_record ->> 'subject';
        end if;
        if coalesce(btrim(p_record ->> 'text'), '') = '' then
            raise exception 'an alert update names its text: %', p_record ->> 'key';
        end if;
    else
        if not exists (select 1 from spawn_alerts where key = p_record ->> 'key') then
            raise exception 'alert % was not fired', p_record ->> 'key';
        end if;
        if exists (select 1 from spawn_alerts
                    where key = p_record ->> 'key' and state <> 'open') then
            raise exception 'alert % is not open: nothing to clear', p_record ->> 'key';
        end if;
    end if;
    return spawn_control_record(p_record);
end $$;

-- Messages (objective 045; docs/fleet-architecture.md §3.4, "Messages"):
-- what the Bridge types for a command (an input, a start or a resume with a
-- prompt) ends with its marker, `[spawn message #<id>]`, and the transcript
-- line that holds it is the message taken (`message.taken`, detail
-- `command_id`, from the engine's transcript). A command's message is read
-- by its id from the records alone, never by its text or its order.

-- Each `message.taken` by session and command.
create index if not exists spawn_events_message_taken
    on spawn_events (session_id, ((kind -> 'detail' ->> 'command_id')::bigint), id)
    where event_name = 'message.taken';

-- When the first loop that types markers started (`host.messages_marked`),
-- null before any did.
create or replace function spawn_messages_marked_from() returns bigint
language sql stable as $$
    select min(e.recorded_at_ms) from spawn_events e
     where e.session_id = 'session_control' and e.event_name = 'control.recorded'
       and e.kind -> 'detail' -> 'record' ->> 'type' = 'host.messages_marked'
$$;

-- The message of command `p_id` (its session, action, state, creation and
-- finish; null for one that types nothing: a key, a
-- stop, a discard, a start or resume with no prompt), at `p_now`, its bound
-- `p_bound_ms` (SPAWN_MESSAGE_TAKEN_SECS) and the first marking loop's start
-- `p_marked_from`:
-- - `typed_at_ms`: the Bridge's `typed` step; `taken_at_ms`: the first
--   `message.taken` naming it, `taken` how many name it; `answered_at_ms`:
--   the session's first `turn.stopped` or `turn.failed` after that first
--   `message.taken`. `acted` (`{outcome, why}`) and `acted_at_ms`: its
--   answer, `message.acted` (an ack, or the report of the task it
--   delivered; objective 046), null until answered. `state` is `acted`,
--   else `answered`, else `taken`, else `typed`, else `recorded`. Times
--   are the records' (`recorded_at_ms`).
-- - `not_taken`: no `message.taken` names it, it is tracked, and its bound
--   has passed. Tracked: the Bridge recorded `message.typed` for it (the
--   text it typed carried the marker; the bound runs from the command's
--   creation), or nothing of it was ever typed (no `typing` step), it did
--   not finish failed (the Bridge refused it before typing: its sender is
--   told, and a loop's sends it again as a new command), and it was still
--   open, or finished, after the first marking loop started (the bound runs
--   from the later of its creation and that start). A command an
--   older Spawn typed has `typing` and no `message.typed`: never not taken.
--   Nothing is tracked that was sent while its session's transcript had
--   held no marker (no `message.taken` recorded at or before its creation):
--   an engine that does not keep the prompt it is given says nothing by its
--   silence. An input waits for its turn (the Bridge types it once the
--   session is ready): the bound runs from the session's last busy screen
--   (`screen.observed` `busy`, recorded again every `screen_refresh`, 30 s,
--   while a turn runs) or turn end (`turn.stopped`, `turn.failed`) after
--   that start and before the Bridge began typing it (its `typing` or
--   `message` step), or before now if it is not typed yet. So a message held
--   behind a running turn, its session's own or the turn of an input queued
--   ahead of it, is due one bound after that turn ends, not while it runs
--   (a bound longer than `screen_refresh`); one sent to a ready session runs
--   from its creation. A turn that never ends keeps a waiting message from
--   being due: that is the stuck agent's alert, not this one.
-- - `typed`: whether the Bridge recorded it typed; `ended`: the session ended
--   with it (what the alert clears on): the execution it was typed into, or
--   its own start's, ended; or, never typed or started, it finished while no
--   execution that is still live ran.
-- - `later_taken` and `later_taken_at_ms` (objective 138): for a tracked
--   message typed and not taken, the first `message.taken` (by event id) of
--   its session naming a later command (a greater id), its command and
--   time: the agent went on past it, its marker missed. Null otherwise or
--   when there is none: an untyped message is behind nothing the agent
--   took, and another session's taking never counts. Read through
--   spawn_events_message_taken.
create or replace function spawn_command_message(p_id bigint, p_session text, p_action jsonb,
                                                 p_state text, p_succeeded boolean,
                                                 p_created bigint,
                                                 p_finished bigint, p_bound_ms bigint,
                                                 p_marked_from bigint, p_now bigint)
returns jsonb language plpgsql stable as $$
declare
    v_type text := p_action ->> 'type';
    v_typed_at bigint;
    v_typing_exec text;
    v_typing_at bigint;
    v_typing_id bigint;
    v_marked boolean;
    v_taken bigint;
    v_taken_id bigint;
    v_taken_at bigint;
    v_answered_at bigint;
    v_own_exec text;
    v_exec text;
    v_tracked boolean;
    v_from bigint;
    v_ended boolean;
    v_live_since bigint;
    v_acted jsonb;
    v_acted_at bigint;
    v_later_id bigint;
    v_later bigint;
    v_later_at bigint;
begin
    if not (v_type = 'input'
            or (v_type in ('start', 'resume') and coalesce(p_action ->> 'prompt', '') <> '')) then
        return null;
    end if;
    select min(e.recorded_at_ms) into v_typed_at from spawn_events e
     where e.session_id = p_session and e.source = 'bridge'
       and e.source_event_id = 'cmd_' || p_id || ':typed';
    select e.execution_id, e.recorded_at_ms, e.id into v_typing_exec, v_typing_at, v_typing_id
      from spawn_events e
     where e.session_id = p_session and e.source = 'bridge'
       and e.source_event_id in ('cmd_' || p_id || ':typing', 'cmd_' || p_id || ':message')
     order by e.id limit 1;
    v_marked := exists (select 1 from spawn_events e
                         where e.session_id = p_session and e.source = 'bridge'
                           and e.source_event_id = 'cmd_' || p_id || ':message');
    select count(*), min(e.id) into v_taken, v_taken_id from spawn_events e
     where e.session_id = p_session and e.event_name = 'message.taken'
       and (e.kind -> 'detail' ->> 'command_id')::bigint = p_id;
    if v_taken_id is not null then
        select e.recorded_at_ms into v_taken_at from spawn_events e where e.id = v_taken_id;
        select e.recorded_at_ms into v_answered_at from spawn_events e
         where e.session_id = p_session and e.event_name in ('turn.stopped', 'turn.failed')
           and e.id > v_taken_id
         order by e.id limit 1;
    end if;
    if not exists (select 1 from spawn_events e
                    where e.session_id = p_session and e.event_name = 'message.taken'
                      and e.recorded_at_ms <= p_created) then
        -- The session's transcript had held no marker when it was sent:
        -- its engine (or a stand-in) may not keep the prompt it is given,
        -- and its silence says nothing. Fixed when it is sent, so a later
        -- taking changes no earlier message.
        v_tracked := false;
    elsif v_marked then
        v_tracked := true;
        v_from := p_created;
    elsif v_typing_exec is null and p_marked_from is not null
          and not exists (select 1 from spawn_events e
                           where e.session_id = p_session and e.source = 'bridge'
                             and e.source_event_id = 'cmd_' || p_id || ':typing')
          and (p_finished is null or p_finished >= p_marked_from)
          and p_succeeded is not false then
        v_tracked := true;
        v_from := greatest(p_created, p_marked_from);
    else
        v_tracked := false;
    end if;
    -- It waited for its turn: the bound runs from the session's last busy
    -- screen or turn end after its start and before the Bridge began typing
    -- it (or before now). Only an untaken one is read: a taken one is never
    -- not taken. Each kind is the latest row before the typing's (by id,
    -- through spawn_events_session_name, read backwards from the typing or
    -- the end: a long-lived session's older readings are never scanned).
    if v_tracked and v_taken = 0 then
        select greatest(v_from, max(x.at)) into v_from from (
            (select e.recorded_at_ms as at from spawn_events e
              where e.session_id = p_session and e.event_name = 'screen.observed'
                and e.kind -> 'detail' ->> 'state' = 'busy'
                and (v_typing_id is null or e.id < v_typing_id)
              order by e.id desc limit 1)
            union all
            (select e.recorded_at_ms from spawn_events e
              where e.session_id = p_session and e.event_name = 'turn.stopped'
                and (v_typing_id is null or e.id < v_typing_id)
              order by e.id desc limit 1)
            union all
            (select e.recorded_at_ms from spawn_events e
              where e.session_id = p_session and e.event_name = 'turn.failed'
                and (v_typing_id is null or e.id < v_typing_id)
              order by e.id desc limit 1)) x
         where x.at <= coalesce(v_typing_at, p_now);
    end if;
    -- A later message of its session taken (objective 138): the first
    -- taking, by event id, naming a greater command id.
    if v_tracked and v_typed_at is not null and v_taken = 0 then
        select min(e.id) into v_later_id from spawn_events e
         where e.session_id = p_session and e.event_name = 'message.taken'
           and (e.kind -> 'detail' ->> 'command_id')::bigint > p_id;
        if v_later_id is not null then
            select (e.kind -> 'detail' ->> 'command_id')::bigint, e.recorded_at_ms
              into v_later, v_later_at from spawn_events e where e.id = v_later_id;
        end if;
    end if;
    -- The session ended with it: the execution it was typed into, or its
    -- own start's, ended.
    if v_type in ('start', 'resume') then
        select e.execution_id into v_own_exec from spawn_events e
         where e.session_id = p_session and e.event_name = 'execution.started'
           and (e.kind -> 'detail' ->> 'command_id')::bigint = p_id
         order by e.id limit 1;
    end if;
    v_exec := coalesce(v_typing_exec, v_own_exec);
    if v_exec is not null then
        v_ended := exists (select 1 from spawn_events e
                            where e.session_id = p_session and e.event_name = 'execution.ended'
                              and e.source = 'bridge' and e.execution_id = v_exec);
    else
        -- The session's live execution: its latest start, with no end.
        select s.recorded_at_ms into v_live_since from spawn_events s
         where s.session_id = p_session and s.event_name = 'execution.started'
           and not exists (select 1 from spawn_events x
                            where x.session_id = s.session_id and x.event_name = 'execution.ended'
                              and x.source = 'bridge' and x.execution_id = s.execution_id)
         order by s.id desc limit 1;
        -- An unfinished one has not ended: the Bridge finishes it, and a
        -- start or resume before it may give it an execution yet.
        v_ended := p_state = 'finished'
                   and (v_live_since is null or v_live_since > coalesce(p_finished, p_now));
    end if;
    -- Its answer (objective 046): the agent's ack, or the report of the
    -- task it delivered, recorded once (`message.acted`, keyed
    -- `<id>:acted`).
    select e.kind -> 'detail', e.recorded_at_ms into v_acted, v_acted_at from spawn_events e
     where e.session_id = p_session and e.source = 'bridge'
       and e.source_event_id = p_id || ':acted';
    return jsonb_build_object(
        'state', case when v_acted is not null then 'acted'
                      when v_answered_at is not null then 'answered'
                      when v_taken_at is not null then 'taken'
                      when v_typed_at is not null then 'typed'
                      else 'recorded' end,
        'acted', case when v_acted is not null
                      then jsonb_build_object('outcome', v_acted ->> 'outcome',
                                              'why', coalesce(v_acted -> 'why', 'null'::jsonb)) end,
        'acted_at_ms', v_acted_at,
        'typed_at_ms', v_typed_at,
        'taken_at_ms', v_taken_at,
        'answered_at_ms', v_answered_at,
        'taken', v_taken,
        'not_taken', v_taken = 0 and v_tracked and p_now - v_from >= p_bound_ms,
        'tracked', v_tracked,
        'due_ms', case when v_tracked and v_taken = 0 then v_from + p_bound_ms end,
        'typed', v_typed_at is not null,
        'ended', v_ended,
        'later_taken', v_later,
        'later_taken_at_ms', v_later_at);
end $$;

-- The owner (the loop) and `spawn serve`'s reader login read messages;
-- nobody else is handed a function over the log. Each runs with its
-- caller's rights.
revoke execute on function spawn_messages_marked_from() from public;
revoke execute on function spawn_command_message(bigint, text, jsonb, text, boolean, bigint,
                                                 bigint, bigint, bigint, bigint) from public;
do $$
begin
    execute format('grant execute on function spawn_messages_marked_from() to %I',
                   spawn_login_role('spawn_reader'));
    execute format('grant execute on function spawn_command_message(bigint, text, jsonb, text, '
                   'boolean, bigint, bigint, bigint, bigint, bigint) to %I',
                   spawn_login_role('spawn_reader'));
end
$$;

-- The backup records: the loop's `spawn backup dump|bundle|verify` writes
-- them through `spawn_backup_record` (owner only); each names what a copy
-- holds and what the run measured (docs/storage.md, "Where state lives").
-- Folded into no table, like `host.disk`.
create or replace function spawn_backup_record(p_record jsonb)
returns bigint language plpgsql security definer as $$
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record backups', session_user using errcode = '42501';
    end if;
    if p_record ->> 'type' not in ('backup.dumped', 'backup.bundled', 'backup.verified',
                                   'backup.stored', 'backup.drilled.transcripts',
                                   'backup.drilled.missions',
                                   'backup.drilled.controllers', 'backup.drilled.sync') then
        raise exception 'not a backup record: %', p_record ->> 'type';
    end if;
    -- A `spawn store put` run (crate backup/store.rs): its shape is fixed,
    -- every field checked, and nothing else is taken (a record is read by
    -- anyone who reads the log; nothing of a file's content goes in it).
    if p_record ->> 'type' = 'backup.stored' then
        if exists (select 1 from jsonb_object_keys(p_record) k
                    where k not in ('type', 'area', 'host', 'account', 'manifest', 'files',
                                    'unchanged', 'grown', 'whole', 'segments_written',
                                    'segments_found', 'bytes_written', 'sealed_with')) then
            raise exception 'a backup.stored record has type, area, host, account, manifest, files, unchanged, grown, whole, segments_written, segments_found, bytes_written and optionally sealed_with, and nothing else';
        end if;
        -- The key that sealed the run's objects (objective 115): optional
        -- (a record without it is taken as before), and when present only
        -- a key's name, never anything of the key.
        if p_record ? 'sealed_with'
           and (jsonb_typeof(p_record -> 'sealed_with') is distinct from 'string'
                or p_record ->> 'sealed_with' !~ '^k[1-9][0-9]*$') then
            raise exception 'a backup.stored record''s sealed_with, when present, is a key''s name: a string k1, k2, ...';
        end if;
        if p_record ->> 'area' is null or p_record ->> 'area' not in ('transcripts', 'sessions')
           or jsonb_typeof(p_record -> 'host') is distinct from 'string'
           or jsonb_typeof(p_record -> 'account') is distinct from 'string'
           or jsonb_typeof(p_record -> 'manifest') is distinct from 'string'
           or exists (select 1 from unnest(array['files', 'unchanged', 'grown', 'whole',
                                                 'segments_written', 'segments_found',
                                                 'bytes_written']) f
                       where jsonb_typeof(p_record -> f) is distinct from 'number'
                          or (p_record ->> f)::numeric < 0
                          or (p_record ->> f)::numeric <> trunc((p_record ->> f)::numeric)) then
            raise exception 'a backup.stored record: area transcripts or sessions, host, account and manifest strings, the counts whole numbers';
        end if;
    end if;
    -- A restore drill's verdict on one resource (`spawn backup
    -- restore-drill`, objective 104): its shape is fixed, every field
    -- checked, and nothing else is taken.
    -- The notes folder's drill (objective 217, `--only sync`) has the same
    -- shape.
    if p_record ->> 'type' in ('backup.drilled.transcripts', 'backup.drilled.missions',
                               'backup.drilled.sync') then
        if exists (select 1 from jsonb_object_keys(p_record) k
                    where k not in ('type', 'ok', 'reason', 'bundle', 'bundle_event_id',
                                    'mismatches', 'duration_ms')) then
            raise exception 'a drill record has type, ok, reason, bundle, bundle_event_id, mismatches and duration_ms, and nothing else';
        end if;
    end if;
    -- The controllers' drill (objective 198), one record per controller:
    -- the drill record's fields, and the run's start, the controller, its
    -- missions and source, its current tree and its previous one (null when
    -- there is none), what was left out; each of its kind, nothing else.
    -- Each tree may say what the backup holds of it (objective 199): held,
    -- null (no commit of its history) or {commit, lag_commits, lag_hours,
    -- ok, files, differing}. A run that cannot restore the backup records
    -- one failed record of the drill record's fields alone.
    if p_record ->> 'type' = 'backup.drilled.controllers' then
        if exists (select 1 from jsonb_object_keys(p_record) k
                    where k not in ('type', 'ok', 'reason', 'bundle', 'bundle_event_id',
                                    'mismatches', 'duration_ms', 'run', 'controller',
                                    'missions', 'source', 'current', 'prev', 'left_out')) then
            raise exception 'a controllers drill record has type, ok, reason, bundle, bundle_event_id, mismatches, duration_ms, run, controller, missions, source, current, prev and left_out, and nothing else';
        end if;
    end if;
    if p_record ->> 'type' = 'backup.drilled.controllers'
       and (jsonb_typeof(p_record -> 'ok') is distinct from 'boolean'
            or (p_record ->> 'ok')::boolean
            or exists (select 1 from jsonb_object_keys(p_record) k
                        where k in ('run', 'controller', 'missions', 'source', 'current',
                                    'prev', 'left_out'))) then
        if jsonb_typeof(p_record -> 'run') is distinct from 'number'
           or (p_record ->> 'run')::numeric < 0
           or (p_record ->> 'run')::numeric <> trunc((p_record ->> 'run')::numeric)
           or jsonb_typeof(p_record -> 'controller') is distinct from 'string'
           or p_record ->> 'controller' = ''
           or jsonb_typeof(p_record -> 'source') is distinct from 'string'
           or jsonb_typeof(p_record -> 'missions') is distinct from 'array'
           or exists (select 1 from jsonb_array_elements(p_record -> 'missions') m
                       where jsonb_typeof(m) is distinct from 'number'
                          or (m #>> '{}')::numeric <> trunc((m #>> '{}')::numeric))
           or jsonb_typeof(p_record -> 'left_out') is distinct from 'array'
           or exists (select 1 from jsonb_array_elements(p_record -> 'left_out') l
                       where jsonb_typeof(l) is distinct from 'string')
           or jsonb_typeof(p_record -> 'current') is distinct from 'object'
           or coalesce(jsonb_typeof(p_record -> 'prev'), 'absent') not in ('object', 'null')
           or exists (select 1 from (values (p_record -> 'current'), (p_record -> 'prev')) t(tree)
                       where jsonb_typeof(tree) = 'object'
                         and (exists (select 1 from jsonb_object_keys(tree) k
                                       where k not in ('commit', 'live', 'held'))
                              or coalesce(jsonb_typeof(tree -> 'held'), 'null') not in ('object', 'null')
                              or (jsonb_typeof(tree -> 'held') = 'object'
                                  and (exists (select 1 from jsonb_object_keys(tree -> 'held') k
                                                where k not in ('commit', 'lag_commits', 'lag_hours',
                                                                'ok', 'files', 'differing'))
                                       or jsonb_typeof(tree -> 'held' -> 'commit') is distinct from 'string'
                                       or jsonb_typeof(tree -> 'held' -> 'ok') is distinct from 'boolean'
                                       or exists (select 1 from unnest(array['lag_commits', 'lag_hours', 'files']) f
                                                   where jsonb_typeof(tree -> 'held' -> f) is distinct from 'number'
                                                      or (tree -> 'held' ->> f)::numeric < 0
                                                      or (tree -> 'held' ->> f)::numeric
                                                         <> trunc((tree -> 'held' ->> f)::numeric))
                                       or jsonb_typeof(tree -> 'held' -> 'differing') is distinct from 'array'
                                       or jsonb_array_length(tree -> 'held' -> 'differing') > 20
                                       or exists (select 1 from jsonb_array_elements(tree -> 'held' -> 'differing') d
                                                   where jsonb_typeof(d) is distinct from 'string')))
                              or jsonb_typeof(tree -> 'commit') is distinct from 'string'
                              or jsonb_typeof(tree -> 'live') is distinct from 'object'
                              or exists (select 1 from jsonb_object_keys(tree -> 'live') k
                                          where k not in ('ok', 'files', 'differing'))
                              or jsonb_typeof(tree -> 'live' -> 'ok') is distinct from 'boolean'
                              or jsonb_typeof(tree -> 'live' -> 'files') is distinct from 'number'
                              or (tree -> 'live' ->> 'files')::numeric < 0
                              or (tree -> 'live' ->> 'files')::numeric
                                 <> trunc((tree -> 'live' ->> 'files')::numeric)
                              or jsonb_typeof(tree -> 'live' -> 'differing') is distinct from 'array'
                              or jsonb_array_length(tree -> 'live' -> 'differing') > 20
                              or exists (select 1 from jsonb_array_elements(tree -> 'live' -> 'differing') d
                                          where jsonb_typeof(d) is distinct from 'string'))) then
            raise exception 'a controllers drill record is {run: a whole number, controller: a name, source: a string, missions: mission ids, left_out: strings, current: {commit: a string, live: {ok: boolean, files: a whole number, differing: at most 20 strings}, held (optional): null or {commit: a string, ok: boolean, lag_commits, lag_hours and files whole numbers, differing: at most 20 strings}}, prev: the same or null}';
        end if;
    end if;
    if p_record ->> 'type' in ('backup.drilled.transcripts', 'backup.drilled.missions',
                               'backup.drilled.controllers', 'backup.drilled.sync') then
        if jsonb_typeof(p_record -> 'ok') is distinct from 'boolean'
           or jsonb_typeof(p_record -> 'reason') is distinct from 'string'
           or length(p_record ->> 'reason') > 500
           or (p_record ->> 'ok')::boolean is distinct from (p_record ->> 'reason' = '')
           or jsonb_typeof(p_record -> 'bundle') is distinct from 'string'
           or exists (select 1 from unnest(array['bundle_event_id', 'mismatches', 'duration_ms']) f
                       where jsonb_typeof(p_record -> f) is distinct from 'number'
                          or (p_record ->> f)::numeric < 0
                          or (p_record ->> f)::numeric <> trunc((p_record ->> f)::numeric)) then
            raise exception 'a drill record is {ok: boolean, true exactly when reason is empty, reason: at most 500 characters, bundle: a string, bundle_event_id, mismatches and duration_ms whole numbers}';
        end if;
    end if;
    return spawn_control_record(p_record);
end $$;

-- How a deploy ended (#54): deploy/deploy.sh writes one `deploy.finished`
-- through `spawn mission deployed` once it holds the deploy lock, for every
-- kind of deploy (`by`: `landing` for deploy/on-landing.sh, `owner` for a
-- hand deploy), `ok` false with the reason the deploy said, true once the
-- services restarted on the new build. The alert step raises
-- `deploy_failed` on a failure and clears it at the next success. Its shape
-- is fixed, every field checked, and nothing else is taken: a record is
-- read by anyone who reads alerts, so nothing in it may come from the
-- deploy's environment but the reason's text, which deploy.sh writes.
create or replace function spawn_deploy_record(p_record jsonb)
returns bigint language plpgsql security definer as $$
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record deploys', session_user using errcode = '42501';
    end if;
    if p_record ->> 'type' is distinct from 'deploy.finished' then
        raise exception 'not a deploy record: %', p_record ->> 'type';
    end if;
    if exists (select 1 from jsonb_object_keys(p_record) k
                where k not in ('type', 'ok', 'head', 'by', 'reason')) then
        raise exception 'a deploy record has type, ok, head, by and reason, and nothing else';
    end if;
    if jsonb_typeof(p_record -> 'ok') is distinct from 'boolean'
       or coalesce(p_record ->> 'head', '') !~ '^[0-9a-f]{40}$'
       or coalesce(p_record ->> 'by', '') not in ('landing', 'owner')
       or jsonb_typeof(p_record -> 'reason') is distinct from 'string'
       or length(p_record ->> 'reason') > 500 then
        raise exception 'a deploy record is {ok: boolean, head: a commit, by: landing|owner, '
                        'reason: at most 500 characters}';
    end if;
    return spawn_control_record(p_record);
end $$;

-- An objective's verification after its landing (objective 133): `spawn
-- verify <mission>/<objective>` writes one `objective.verified` through
-- `spawn_verification_record` (owner only): who looked (`by`), how (`how`)
-- and what they saw (`result`, pass or fail). Its shape is fixed, every
-- field checked, and nothing else is taken. Objectives are numbered per
-- mission, so the record names both; an objective that never landed in
-- that mission (no `task.landed` of a task of that mission and objective)
-- is refused. Folded into no table: `spawn verify list` reads the records.
create or replace function spawn_verification_record(p_record jsonb)
returns bigint language plpgsql security definer as $$
declare
    v_mission bigint;
    v_objective integer;
begin
    perform pg_advisory_xact_lock(1399957335);
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception '% may not record verifications', session_user using errcode = '42501';
    end if;
    if p_record ->> 'type' is distinct from 'objective.verified' then
        raise exception 'not a verification record: %', p_record ->> 'type';
    end if;
    if exists (select 1 from jsonb_object_keys(p_record) k
                where k not in ('type', 'mission', 'objective', 'by', 'how', 'result'))
       or exists (select 1 from unnest(array['mission', 'objective', 'by', 'how', 'result']) f
                   where not p_record ? f) then
        raise exception 'a verification record has type, mission, objective, by, how and result, and nothing else';
    end if;
    if exists (select 1 from unnest(array['mission', 'objective']) f
                where case when jsonb_typeof(p_record -> f) = 'number'
                           then (p_record ->> f)::numeric < 1
                                or (p_record ->> f)::numeric > 2147483647
                                or (p_record ->> f)::numeric <> trunc((p_record ->> f)::numeric)
                           else true end) then
        raise exception 'a verification record''s mission and objective are whole numbers from 1';
    end if;
    if jsonb_typeof(p_record -> 'by') is distinct from 'string'
       or char_length(p_record ->> 'by') not between 1 and 80
       or p_record ->> 'by' ~ '^[[:space:]]*$' then
        raise exception 'a verification record''s by is 1 to 80 characters, not blank';
    end if;
    if jsonb_typeof(p_record -> 'how') is distinct from 'string'
       or char_length(p_record ->> 'how') not between 1 and 500
       or p_record ->> 'how' ~ '^[[:space:]]*$' then
        raise exception 'a verification record''s how is 1 to 500 characters, not blank';
    end if;
    if jsonb_typeof(p_record -> 'result') is distinct from 'string'
       or p_record ->> 'result' not in ('pass', 'fail') then
        raise exception 'a verification record''s result is pass or fail';
    end if;
    v_mission := (p_record ->> 'mission')::numeric::bigint;
    v_objective := (p_record ->> 'objective')::numeric::integer;
    if not exists (
        select 1
          from mission_tasks t
          join spawn_events e
            on e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and e.kind -> 'detail' -> 'record' ->> 'type' = 'task.landed'
           and e.kind -> 'detail' -> 'record' -> 'id' = to_jsonb(t.id)
         where t.mission_id = v_mission and t.objective = v_objective) then
        raise exception 'objective %/% never landed', v_mission, v_objective;
    end if;
    return spawn_control_record(p_record);
end $$;

-- An objective retired by hand (objective 210, GitHub #65): `spawn
-- objective retire` writes one `objective.retired` {type, id: mission,
-- objective, kind, by, reason, caller} through `spawn_objective_retire`,
-- for an objective that can never land. Only the owner's and the
-- supervisor's logins may; `caller` is set here from the login, never
-- taken from the input. The input has exactly type, id, objective, kind,
-- by and reason; the mission must exist and have a backlog; the objective
-- need not be in it (retiring a renumbered one is the point). Refused,
-- recording nothing: an objective with a task in flight, or one already
-- closed (a landed task, an objective.solved or an objective.retired).
--
-- The kind (objective 223) is on-main, renumbered or obsolete, named by
-- the caller, never guessed from the reason's words. on-main is a claim
-- the gate's own records must show: an accepted `task.gated` of a task of
-- the same mission, that task now landed, whose `passed` or `reused` names
-- the objective's scenario (`<NNN>.sh`, the number zero-padded to three
-- digits, as objectives.rs names it), with no `task.gated` of the mission
-- recorded after the newest such gate naming it in `main_red_scenarios`
-- (a gate that repairs a red scenario names it in both lists: its own red
-- is not after its pass). A landing's title is not a gate record (9/61 on
-- 2026-11-18: retired "already on main" while 061.sh was red on main).
-- renumbered and obsolete need no record.
--
-- Cost: the gates that may show it are read before the append lock, up to
-- the newest control event when the read began (v_seen: every append
-- takes the lock and numbers its event max + 1, so every event up to it is
-- committed); under the lock only the control events after v_seen are
-- read, and the states of the tasks read, so a landing or a gate recorded
-- meanwhile counts. Only an on-main retire reads them.
create or replace function spawn_objective_retire(p_record jsonb)
returns bigint language plpgsql security definer as $$
declare
    v_caller text := spawn_mission_caller();
    v_mission bigint;
    v_objective integer;
    v_kind text;
    v_scenario text;
    v_seen bigint;
    v_gates jsonb := '[]'::jsonb;
    v_part jsonb;
    v_pass bigint;
    v_red record;
begin
    if v_caller is null then
        raise exception '% may not retire objectives', session_user using errcode = '42501';
    end if;
    if p_record ->> 'type' is distinct from 'objective.retired' then
        raise exception 'not a retirement record: %', p_record ->> 'type';
    end if;
    if exists (select 1 from jsonb_object_keys(p_record) k
                where k not in ('type', 'id', 'objective', 'kind', 'by', 'reason'))
       or exists (select 1 from unnest(array['id', 'objective', 'kind', 'by', 'reason']) f
                   where not p_record ? f) then
        raise exception 'a retirement record has type, id, objective, kind, by and reason, and nothing else';
    end if;
    if exists (select 1 from unnest(array['id', 'objective']) f
                where case when jsonb_typeof(p_record -> f) = 'number'
                           then (p_record ->> f)::numeric < 1
                                or (p_record ->> f)::numeric > 2147483647
                                or (p_record ->> f)::numeric <> trunc((p_record ->> f)::numeric)
                           else true end) then
        raise exception 'a retirement record''s mission and objective are whole numbers from 1';
    end if;
    if jsonb_typeof(p_record -> 'kind') is distinct from 'string'
       or p_record ->> 'kind' not in ('on-main', 'renumbered', 'obsolete') then
        raise exception 'a retirement record''s kind is on-main, renumbered or obsolete, not %',
            coalesce(p_record ->> 'kind', 'null');
    end if;
    if jsonb_typeof(p_record -> 'by') is distinct from 'string'
       or char_length(p_record ->> 'by') not between 1 and 80
       or p_record ->> 'by' ~ '^[[:space:]]*$' then
        raise exception 'a retirement record''s by is 1 to 80 characters, not blank';
    end if;
    if jsonb_typeof(p_record -> 'reason') is distinct from 'string'
       or char_length(p_record ->> 'reason') not between 1 and 500
       or p_record ->> 'reason' ~ '^[[:space:]]*$' then
        raise exception 'a retirement record''s reason is 1 to 500 characters, not blank';
    end if;
    v_mission := (p_record ->> 'id')::numeric::bigint;
    v_objective := (p_record ->> 'objective')::numeric::integer;
    v_kind := p_record ->> 'kind';
    -- At least three digits: lpad alone would cut 1234 to 123.
    v_scenario := lpad(v_objective::text, greatest(3, char_length(v_objective::text)), '0')
                  || '.sh';

    -- on-main, before the lock: the mission's gates that may show it, up
    -- to v_seen.
    if v_kind = 'on-main' then
        select coalesce(max(session_seq), 0) into v_seen
          from spawn_events where session_id = 'session_control';
        select coalesce(jsonb_agg(jsonb_build_object(
                   'seq', e.session_seq, 'task', t.id, 'base', r ->> 'base',
                   'pass', r ->> 'verdict' = 'accepted'
                           and (coalesce(r -> 'passed' ? v_scenario, false)
                                or coalesce(r -> 'reused' ? v_scenario, false)),
                   'red', coalesce(r -> 'main_red_scenarios' ? v_scenario, false))), '[]'::jsonb)
          into v_part
          from spawn_events e
         cross join lateral (select e.kind -> 'detail' -> 'record' as r) x
          join mission_tasks t on to_jsonb(t.id) = r -> 'id' and t.mission_id = v_mission
         where e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and r ->> 'type' = 'task.gated'
           and e.session_seq > 0 and e.session_seq <= v_seen
           and ((r ->> 'verdict' = 'accepted'
                 and (coalesce(r -> 'passed' ? v_scenario, false)
                      or coalesce(r -> 'reused' ? v_scenario, false)))
                or coalesce(r -> 'main_red_scenarios' ? v_scenario, false));
        v_gates := v_part;
    end if;

    perform pg_advisory_xact_lock(1399957335);
    if not exists (select 1 from mission_missions where id = v_mission) then
        raise exception 'mission % does not exist', v_mission;
    end if;
    if not exists (select 1 from mission_missions
                    where id = v_mission and jsonb_typeof(objectives -> 'backlog') = 'string') then
        raise exception 'mission % has no backlog: it is no objective mission', v_mission;
    end if;
    if exists (select 1 from mission_tasks
                where mission_id = v_mission and objective = v_objective
                  and state in ('assigned', 'delivered', 'revise', 'reported', 'accepted',
                                'landing')) then
        raise exception 'objective %/% has a task in flight', v_mission, v_objective;
    end if;
    if exists (select 1 from mission_tasks
                where mission_id = v_mission and objective = v_objective and state = 'landed') then
        raise exception 'objective %/% is closed: a task of it landed', v_mission, v_objective;
    end if;
    if exists (select 1 from spawn_events e
                where e.session_id = 'session_control' and e.event_name = 'control.recorded'
                  and e.kind -> 'detail' -> 'record' ->> 'type' = 'objective.solved'
                  and e.kind -> 'detail' -> 'record' ->> 'id' = v_mission::text
                  and e.kind -> 'detail' -> 'record' ->> 'objective' = v_objective::text) then
        raise exception 'objective %/% is closed: solved on the base', v_mission, v_objective;
    end if;
    if exists (select 1 from mission_retired_objectives
                where mission_id = v_mission and objective = v_objective) then
        raise exception 'objective %/% is closed: already retired', v_mission, v_objective;
    end if;

    if v_kind = 'on-main' then
        -- Under the lock: the control events after v_seen, and the tasks'
        -- states now.
        select coalesce(jsonb_agg(jsonb_build_object(
                   'seq', e.session_seq, 'task', t.id, 'base', r ->> 'base',
                   'pass', r ->> 'verdict' = 'accepted'
                           and (coalesce(r -> 'passed' ? v_scenario, false)
                                or coalesce(r -> 'reused' ? v_scenario, false)),
                   'red', coalesce(r -> 'main_red_scenarios' ? v_scenario, false))), '[]'::jsonb)
          into v_part
          from spawn_events e
         cross join lateral (select e.kind -> 'detail' -> 'record' as r) x
          join mission_tasks t on to_jsonb(t.id) = r -> 'id' and t.mission_id = v_mission
         where e.session_id = 'session_control' and e.event_name = 'control.recorded'
           and r ->> 'type' = 'task.gated'
           and e.session_seq > v_seen
           and ((r ->> 'verdict' = 'accepted'
                 and (coalesce(r -> 'passed' ? v_scenario, false)
                      or coalesce(r -> 'reused' ? v_scenario, false)))
                or coalesce(r -> 'main_red_scenarios' ? v_scenario, false));
        v_gates := v_gates || v_part;
        select max((g ->> 'seq')::bigint) into v_pass
          from jsonb_array_elements(v_gates) g
          join mission_tasks t on t.id = (g ->> 'task')::bigint
         where (g ->> 'pass')::boolean and t.state = 'landed';
        if v_pass is null then
            raise exception 'objective %/% is not shown on main: no accepted gate of a landed task of mission % lists % as passed (a landing''s title is not a gate record); run its scenario through a gate, or retire it as renumbered or obsolete',
                v_mission, v_objective, v_mission, v_scenario;
        end if;
        select (g ->> 'task')::bigint as task, g ->> 'base' as base into v_red
          from jsonb_array_elements(v_gates) g
         where (g ->> 'red')::boolean and (g ->> 'seq')::bigint > v_pass
         order by (g ->> 'seq')::bigint
         limit 1;
        if found then
            raise exception 'objective %/% is not shown on main: % is red on main since task #%''s gate (%); run its scenario through a gate, or retire it as renumbered or obsolete',
                v_mission, v_objective, v_scenario, v_red.task, coalesce(v_red.base, 'no base');
        end if;
    end if;
    return spawn_control_record(jsonb_build_object(
        'type', 'objective.retired', 'id', v_mission, 'objective', v_objective,
        'kind', v_kind, 'by', p_record ->> 'by', 'reason', p_record ->> 'reason',
        'caller', v_caller));
end $$;

-- The landings and the deploy records, found without reading the rest of
-- the stream: deploy/on-landing.sh reads main's landing and the last deploy
-- every minute (`MAIN_LANDING`).
create index if not exists spawn_events_landing
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' in ('task.landed', 'source.moved',
                                                      'deploy.finished');

-- The backup records, found without reading the rest of the stream: a run
-- reads the ones before it to decide its tiers and its bundle's base.
create index if not exists spawn_events_backup
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type'
          in ('backup.dumped', 'backup.bundled', 'backup.verified');

-- The alert transitions, found without reading the rest of the stream.
create index if not exists spawn_events_alert
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' in ('alert.fired', 'alert.cleared');

-- The `source.moved` records (deploys), found without reading the rest of
-- the stream: the dispatcher reads the latest on every step
-- (`LATEST_SOURCE_MOVED`).
create index if not exists spawn_events_source_moved
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'source.moved';

-- The `no_room` gate records that escalate, found without reading the rest
-- of the stream (the dispatcher reads them on every step).
create index if not exists spawn_events_gate_room
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'task.gated'
      and kind -> 'detail' -> 'record' ->> 'verdict' = 'no_room'
      and kind -> 'detail' -> 'record' ->> 'escalate' = 'true';

-- The `host_fault` gate records that escalate (the second host fault in a
-- row), found the same way.
create index if not exists spawn_events_gate_host_fault
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'task.gated'
      and kind -> 'detail' -> 'record' ->> 'verdict' = 'host_fault'
      and kind -> 'detail' -> 'record' ->> 'escalate' = 'true';

-- The `host_fault` gate records whose base disagreed with itself and that
-- carry `alert` (the mission's third in a row, objective 033), found the
-- same way: the dispatcher's digest takes each to the supervisor once.
create index if not exists spawn_events_gate_base_disagrees
    on spawn_events (session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and kind -> 'detail' -> 'record' ->> 'type' = 'task.gated'
      and kind -> 'detail' -> 'record' ->> 'verdict' = 'host_fault'
      and kind -> 'detail' -> 'record' ->> 'evidence' = 'base_disagrees'
      and kind -> 'detail' -> 'record' ->> 'alert' = 'true';

-- A task's stages, oldest first: `[{stage, verdict?, at_ms, took_ms?}]`.
-- `stage` is the record type without `task.`; `verdict` is a gate's verdict
-- or a review's (`accepted`, `rejected`); `took_ms` is the time since the
-- task's previous record (none on the first). Runs as the owner, so the
-- supervisor's login, which may not read `spawn_events`, reads it too.
create or replace function spawn_task_stages(p_task bigint)
returns jsonb language sql stable security definer as $$
    -- A verdict's `class`, `inputs` and `env` (objective 035) as recorded,
    -- their nulls kept (a controller that was unknown, a run that printed
    -- no toolchain); a record from before them shows none.
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'stage', substr(s.type, 6), 'verdict', s.verdict, 'at_ms', s.at_ms,
               'took_ms', s.at_ms - s.previous_ms))
               || s.binding order by s.seq), '[]'::jsonb)
      from (select e.session_seq as seq, r.record ->> 'type' as type,
                   case when r.record ->> 'type' = 'task.gated' then
                     r.record - array(select k from jsonb_object_keys(r.record) k
                                       where k not in ('class', 'inputs', 'env', 'head_inputs'))
                   -- A move (objective 239): from and to whose session, by whom.
                   when r.record ->> 'type' = 'task.stolen' then
                     jsonb_build_object('from', r.record ->> 'from_session',
                                        'to', r.record ->> 'to_session',
                                        'by', r.record ->> 'by')
                   else '{}'::jsonb end as binding,
                   case r.record ->> 'type'
                     when 'task.gated' then r.record ->> 'verdict'
                     when 'task.reviewed' then
                       case when (r.record ->> 'accepted')::boolean then 'accepted'
                            else 'rejected' end
                   end as verdict,
                   e.recorded_at_ms as at_ms,
                   lag(e.recorded_at_ms) over (order by e.session_seq) as previous_ms
              from spawn_events e
             cross join lateral (select e.kind -> 'detail' -> 'record' as record) r
             where e.session_id = 'session_control' and e.event_name = 'control.recorded'
               and (e.kind -> 'detail' -> 'record' ->> 'id') = p_task::text
               and r.record ->> 'type' like 'task.%') s
$$;

-- A database from before the control stream has rows and no records. Each
-- row becomes one `legacy.imported` record, once.
do $$
declare
    v_row record;
begin
    perform pg_advisory_xact_lock(1399957335);
    if exists (select 1 from spawn_events where session_id = 'session_control')
       or not exists (select 1 from mission_missions union all select 1 from mission_residents) then
        return;
    end if;
    create temporary table spawn_legacy_rows on commit drop as
        select 1 as part, 'mission_missions' as name, to_jsonb(m) as row, lpad(m.id::text, 20, '0') as ord
          from mission_missions m
        union all
        select 2, 'mission_residents', to_jsonb(r), lpad(r.created_at_ms::text, 20, '0') || r.name
          from mission_residents r
        union all
        select 3, 'mission_tasks', to_jsonb(t), lpad(t.id::text, 20, '0')
          from mission_tasks t;
    delete from mission_tasks;
    delete from mission_residents;
    delete from mission_missions;
    for v_row in
        select name, row from spawn_legacy_rows
         order by part, ord
    loop
        perform spawn_control_record(jsonb_build_object(
            'type', 'legacy.imported', 'table', v_row.name, 'row', v_row.row));
    end loop;
end
$$;

-- The closure rule's functions: search_path pinned, closed to public.
do $$
declare
    v_function text;
begin
    foreach v_function in array array[
        'spawn_task_may_continue(text, text, boolean, text)',
        'spawn_task_may_move(bigint, text)',
        'spawn_task_record_cancelled(bigint[])', 'spawn_task_cancel_by()'] loop
        execute format('alter function %s set search_path = %I, pg_temp', v_function, current_schema());
        execute format('revoke execute on function %s from public', v_function);
    end loop;
end
$$;

-- Closes and retirements from before the closure rule left work open that
-- the rule drops (a dropped mission's delivered task, a retired resident's
-- report): each such task is recorded cancelled, once.
do $$
declare
    v_task bigint;
begin
    perform pg_advisory_xact_lock(1399957335);
    for v_task in
        select k.id from mission_tasks k
          join mission_missions m on m.id = k.mission_id
          left join mission_residents r on r.agent_id = k.agent_id
         where not spawn_task_may_continue(k.state, m.state, m.gate is not null, r.state)
         order by k.id
    loop
        perform spawn_control_record(jsonb_build_object('type', 'task.cancelled', 'id', v_task,
                                                        'by', 'spawn-migrate'));
    end loop;
end
$$;

-- Closes and retirements from before their writers recorded what they
-- cancelled (spawn_task_record_cancelled) left tasks the fold cancelled with
-- no record of it: their stages end at `assigned`, `delivered` or
-- `reported`. Each cancelled task whose last `task.%` record closes nothing
-- is recorded cancelled, once: a task that ends with `task.cancelled`,
-- `task.aborted` or `task.over_budget` (cancelled over budget, its work
-- kept) gets none, and neither does a row
-- from before the control stream (`legacy.imported`, no `task.%` records).
do $$
declare
    v_task bigint;
begin
    perform pg_advisory_xact_lock(1399957335);
    for v_task in
        select k.id
          from mission_tasks k
          join (select distinct on (r.record ->> 'id') r.record ->> 'id' as id,
                       r.record ->> 'type' as type
                  from spawn_events e
                 cross join lateral (select e.kind -> 'detail' -> 'record' as record) r
                 where e.session_id = 'session_control' and e.event_name = 'control.recorded'
                   and r.record ->> 'type' like 'task.%'
                 order by r.record ->> 'id', e.session_seq desc) last on last.id = k.id::text
         where k.state = 'cancelled'
           and last.type not in ('task.cancelled', 'task.aborted', 'task.over_budget')
         order by k.id
    loop
        perform spawn_control_record(jsonb_build_object('type', 'task.cancelled', 'id', v_task,
                                                        'by', 'spawn-migrate'));
    end loop;
end
$$;

-- Experience (objective 043; docs/fleet-architecture.md §4): decisions,
-- interventions, outcomes and escalations, one row per item with `at_ms`
-- (when it counts), derived from the log alone, so every reader (the
-- scorecard's "How the fleet decides", `/api/fleet`'s ladder, RSI) counts
-- the same rows. Views read with their owner's rights: the reader selects
-- them with every table, the supervisor by the grant below. The helper
-- views (`spawn_experience_*`, `spawn_task_spans`, `spawn_mission_spans`)
-- fold the control stream as the scorecard does (docs/design.md §15):
-- a task's interval runs from each assignment to its first closing record,
-- a review accepted closes only on a mission without a gate as of that
-- review, and a record that names a closed task changes nothing.

-- A JSON number, or a number written as text, as a bigint; null otherwise.
create or replace function spawn_experience_int(p_value jsonb) returns bigint
language sql immutable parallel safe as $$
    select case
             when jsonb_typeof(p_value) = 'number' and (p_value #>> '{}') ~ '^-?[0-9]{1,18}$'
               then (p_value #>> '{}')::bigint
             when jsonb_typeof(p_value) = 'string' and btrim(p_value #>> '{}') ~ '^-?[0-9]{1,18}$'
               then btrim(p_value #>> '{}')::bigint
           end $$;

-- The control records by the ids the experience views look them up by,
-- each lookup "the first or latest record of this task (mission) after a
-- seq": spawn_task_spans' closing record (`record -> 'id'`), and
-- spawn_experience_settings' and spawn_experience_assignments' (`id`, or a
-- legacy row's `row -> 'id'`). Without them each lookup decoded the whole
-- control stream, once per assignment: /api/interventions took 12 s and the
-- scorecard's window 61 s on a copy of the live log of 2026-11-11 (2736
-- control records), 0.5 s and 1.1 s with them.
create index if not exists spawn_events_control_record_int_id
    on spawn_events (spawn_experience_int(kind -> 'detail' -> 'record' -> 'id'), session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded';
create index if not exists spawn_events_control_record_row_id
    on spawn_events (spawn_experience_int(coalesce(kind -> 'detail' -> 'record' -> 'id',
                                                   kind -> 'detail' -> 'record' -> 'row' -> 'id')),
                     session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded';

-- The control records, in stream order.
create or replace view spawn_experience_records as
select e.session_seq as seq,
       e.recorded_at_ms as at_ms,
       e.kind -> 'detail' -> 'record' ->> 'type' as type,
       e.kind -> 'detail' -> 'record' as record
from spawn_events e
where e.session_id = 'session_control' and e.event_name = 'control.recorded';

-- Each record that sets a mission's settings: `mission.added` (no gate,
-- accepted by review), `mission.configured` and a legacy mission row.
create or replace view spawn_experience_settings as
select r.seq,
       spawn_experience_int(coalesce(r.record -> 'id', r.record -> 'row' -> 'id')) as mission_id,
       case when r.type = 'mission.added' then false
            else coalesce(jsonb_typeof(coalesce(r.record -> 'gate', r.record -> 'row' -> 'gate')), 'null')
                 <> 'null' end as gated,
       case when r.type = 'mission.added' then true
            else case when jsonb_typeof(coalesce(r.record -> 'accept', r.record -> 'row' -> 'accept'))
                               = 'string'
                      then coalesce(r.record -> 'accept', r.record -> 'row' -> 'accept') #>> '{}' = 'review'
                      else true end end as review
from spawn_experience_records r
where r.type in ('mission.added', 'mission.configured')
   or (r.type = 'legacy.imported' and r.record ->> 'table' = 'mission_missions');

-- Every assignment of a task (a `task.assigned`, or a legacy task row at its
-- row's creation), with the next assignment of the same task after it.
create or replace view spawn_experience_assignments as
select a.*, lead(a.seq) over (partition by a.task_id order by a.seq) as next_seq
from (
    select r.seq,
           r.type,
           spawn_experience_int(coalesce(r.record -> 'id', r.record -> 'row' -> 'id')) as task_id,
           spawn_experience_int(coalesce(r.record -> 'mission_id', r.record -> 'row' -> 'mission_id'))
               as mission_id,
           case when r.type = 'task.assigned' then r.at_ms
                else coalesce(spawn_experience_int(r.record -> 'row' -> 'created_at_ms'), r.at_ms)
           end as assigned_at_ms,
           coalesce(r.record ->> 'created_by', r.record -> 'row' ->> 'created_by') as created_by,
           spawn_experience_int(coalesce(r.record -> 'objective', r.record -> 'row' -> 'objective'))
               as objective,
           coalesce(r.record ->> 'brief', r.record -> 'row' ->> 'brief') as brief,
           r.record
      from spawn_experience_records r
     where r.type = 'task.assigned'
        or (r.type = 'legacy.imported' and r.record ->> 'table' = 'mission_tasks')
) a
where a.task_id is not null and a.mission_id is not null;

-- Each assignment's interval: from the assignment to its first closing
-- record before the task's next assignment (`closed_at_ms` null while
-- open), with that record's outcome; a legacy row closed as its row says
-- (at its `updated_at_ms`, no outcome: no record of one).
create or replace view spawn_task_spans as
select a.task_id,
       a.mission_id,
       a.seq as assigned_seq,
       a.assigned_at_ms,
       coalesce(c.at_ms, l.closed_at_ms) as closed_at_ms,
       c.seq as closed_seq,
       c.outcome,
       c.by,
       a.created_by,
       a.objective,
       a.brief
from spawn_experience_assignments a
left join lateral (
    select case when a.type = 'legacy.imported'
                     and (a.record -> 'row' ->> 'state' in ('cancelled', 'landed')
                          or (a.record -> 'row' ->> 'state' = 'accepted'
                              and not coalesce((select s.gated from spawn_experience_settings s
                                                 where s.mission_id = a.mission_id and s.seq < a.seq
                                                 order by s.seq desc limit 1), false)))
                then coalesce(spawn_experience_int(a.record -> 'row' -> 'updated_at_ms'),
                              (select r.at_ms from spawn_experience_records r where r.seq = a.seq))
           end as closed_at_ms
) l on true
left join lateral (
    select r.seq,
           r.at_ms,
           case r.type when 'task.landed' then 'landed'
                       when 'task.reviewed' then 'accepted'
                       when 'task.cancelled' then 'cancelled'
                       when 'task.aborted' then 'aborted'
                       when 'task.over_budget' then 'over_budget' end as outcome,
           r.record ->> 'by' as by
      from spawn_experience_records r
     where l.closed_at_ms is null
       and r.seq > a.seq and (a.next_seq is null or r.seq < a.next_seq)
       and spawn_experience_int(r.record -> 'id') = a.task_id
       and (r.type in ('task.landed', 'task.cancelled', 'task.aborted', 'task.over_budget')
            or (r.type = 'task.reviewed'
                and lower(r.record ->> 'accepted') in ('true', 't')
                and not coalesce((select s.gated from spawn_experience_settings s
                                   where s.mission_id = a.mission_id and s.seq < r.seq
                                   order by s.seq desc limit 1), false)))
     order by r.seq
     limit 1
) c on true;

-- Each mission's open span: from its `mission.added` to its first
-- `mission.closed` after (null while open); a legacy mission row from its
-- row's creation to its update when the row is closed.
create or replace view spawn_mission_spans as
select m.mission_id, m.text, m.opened_at_ms, m.closed_at_ms
from (
    select spawn_experience_int(r.record -> 'id') as mission_id,
           r.record ->> 'text' as text,
           r.at_ms as opened_at_ms,
           (select c.at_ms from spawn_experience_records c
             where c.type = 'mission.closed' and c.seq > r.seq
               and spawn_experience_int(c.record -> 'id') = spawn_experience_int(r.record -> 'id')
             order by c.seq limit 1) as closed_at_ms
      from spawn_experience_records r
     where r.type = 'mission.added'
    union all
    select spawn_experience_int(r.record -> 'row' -> 'id'),
           r.record -> 'row' ->> 'text',
           coalesce(spawn_experience_int(r.record -> 'row' -> 'created_at_ms'), r.at_ms),
           case when coalesce(r.record -> 'row' ->> 'state', 'open') not in ('open', 'active')
                then coalesce(spawn_experience_int(r.record -> 'row' -> 'updated_at_ms'), r.at_ms) end
      from spawn_experience_records r
     where r.type = 'legacy.imported' and r.record ->> 'table' = 'mission_missions'
) m
where m.mission_id is not null;

-- A person's intents (objective 049; docs/fleet-architecture.md §0): a
-- command of the board or the CLI (principal `human` or `spawn`) continues
-- the intent of the latest earlier command of the same principal, session
-- and action (the whole JSON, as jsonb) when that one finished failed at or
-- before this one was created, at most 60 minutes before it; otherwise it
-- starts one. From the records alone, never the text's meaning. One row per
-- intent: its time (its first command's creation), its first command's id,
-- its commands in order and their count, and its outcome, its last
-- command's (`taken`, `failed`, `pending` while unfinished). The arrays
-- after give each command's creation, finish and result in the same order,
-- so a reader can take the intent as it stood at an earlier time (the
-- commands created before it, the last one's result if it finished before).
create or replace view spawn_human_intents as
with person as (
    select c.id, c.principal, c.agent_id, c.session_id, c.action, c.created_at_ms,
           c.finished_at_ms, c.succeeded,
           lag(c.succeeded) over k as prev_succeeded,
           lag(c.finished_at_ms) over k as prev_finished_at_ms
      from spawn_commands c
     where c.principal in ('human', 'spawn')
    window k as (partition by c.principal, c.session_id, c.action order by c.id)
), marked as (
    select p.*,
           not coalesce(p.prev_succeeded is false
                        and p.prev_finished_at_ms <= p.created_at_ms
                        and p.created_at_ms - p.prev_finished_at_ms <= 3600000, false) as starts
      from person p
), chained as (
    select m.*,
           sum(case when m.starts then 1 else 0 end)
               over (partition by m.principal, m.session_id, m.action order by m.id) as chain
      from marked m
), intents as (
    select min(c.created_at_ms) as at_ms,
           min(c.id) as intent,
           c.principal,
           (array_agg(c.agent_id order by c.id))[1] as agent_id,
           c.session_id,
           array_agg(c.id order by c.id) as commands,
           count(*) as attempts,
           (array_agg(c.finished_at_ms order by c.id desc))[1] as last_finished_at_ms,
           (array_agg(c.succeeded order by c.id desc))[1] as last_succeeded,
           array_agg(c.created_at_ms order by c.id) as created_at_ms,
           array_agg(c.finished_at_ms order by c.id) as finished_at_ms,
           array_agg(c.succeeded order by c.id) as succeeded,
           (array_agg(c.action order by c.id))[1] as action
      from chained c
     group by c.principal, c.session_id, c.action, c.chain
)
select i.at_ms, i.intent, i.principal, i.agent_id, i.session_id, i.commands, i.attempts,
       case when i.last_finished_at_ms is null then 'pending'
            when i.last_succeeded then 'taken'
            else 'failed' end as outcome,
       i.created_at_ms, i.finished_at_ms, i.succeeded, i.action
from intents i;

-- Every decision: each judgement at its time (tier `rules` when the rules
-- judged, else `model`), each command at its creation, by its principal's
-- tier (`dispatcher`, `supervisor`, `liveness`, any other principal as its
-- own tier), and each intent of a person (the board's and the CLI's
-- commands, `spawn_human_intents`: a refused command sent again is one) at
-- its time, tier `human`. `source`: the judge or the principal.
create or replace view spawn_decisions as
select j.recorded_at_ms as at_ms,
       case when j.observation ->> 'judge' = 'rules' then 'rules' else 'model' end as tier,
       j.session_id,
       j.agent_id,
       coalesce(j.observation ->> 'judge', 'model') as source
from agent_judgements j
union all
select c.created_at_ms,
       case c.principal when 'spawn-dispatch' then 'dispatcher'
                        when 'spawn_supervisor' then 'supervisor'
                        when 'spawn-liveness' then 'liveness'
                        else c.principal end,
       c.session_id,
       c.agent_id,
       c.principal
from spawn_commands c
where c.principal not in ('human', 'spawn')
union all
select i.at_ms, 'human', i.session_id, i.agent_id, i.principal
from spawn_human_intents i;

-- The assignment records (a `task.assigned`, a legacy task row) by mission
-- and objective, and by mission and brief: spawn_interventions finds a
-- cancelled task's attempts of the same work and the next assignment of it
-- by these, never by reading the rest of the control stream.
create index if not exists spawn_events_control_assignment_objective
    on spawn_events (spawn_experience_int(coalesce(kind -> 'detail' -> 'record' -> 'mission_id',
                                                   kind -> 'detail' -> 'record' -> 'row' -> 'mission_id')),
                     spawn_experience_int(coalesce(kind -> 'detail' -> 'record' -> 'objective',
                                                   kind -> 'detail' -> 'record' -> 'row' -> 'objective')),
                     session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and (kind -> 'detail' -> 'record' ->> 'type' = 'task.assigned'
           or (kind -> 'detail' -> 'record' ->> 'type' = 'legacy.imported'
               and kind -> 'detail' -> 'record' ->> 'table' = 'mission_tasks'));
create index if not exists spawn_events_control_assignment_brief
    on spawn_events (spawn_experience_int(coalesce(kind -> 'detail' -> 'record' -> 'mission_id',
                                                   kind -> 'detail' -> 'record' -> 'row' -> 'mission_id')),
                     md5(coalesce(kind -> 'detail' -> 'record' ->> 'brief',
                                  kind -> 'detail' -> 'record' -> 'row' ->> 'brief')),
                     session_seq)
    where session_id = 'session_control' and event_name = 'control.recorded'
      and (kind -> 'detail' -> 'record' ->> 'type' = 'task.assigned'
           or (kind -> 'detail' -> 'record' ->> 'type' = 'legacy.imported'
               and kind -> 'detail' -> 'record' ->> 'table' = 'mission_tasks'));

-- The control records of a type, by time: a window's records of a type
-- (spawn_interventions' assignments and resumptions of `[$1, $2)`) and the
-- newest record of a type (host.rs's NEWEST_PASSED, spelled as it spells
-- the type) are read without reading the stream, under a generic plan too
-- (the window and the type parameters).
create index if not exists spawn_events_control_record_type
    on spawn_events ((kind -> 'detail' -> 'record' ->> 'type'), recorded_at_ms, id)
    where session_id = 'session_control' and event_name = 'control.recorded';

-- Every intervention, exactly the scorecard's (docs/design.md §15, autonomy
-- (a)-(d)): `command`, a person's intent (`spawn_human_intents`: a refused
-- command sent again is one), at its time, `command_id` its first command;
-- `resume`, a `mission.resumed` or the owner's release of a pause
-- (`mission.unpaused`); `pause`, the owner's `mission.paused`; `owner_task`, a task a person assigned on
-- a mission accepted by review; `cancel_reassign`, a person's cancellation
-- of an open task followed by the same work (the same objective, or without
-- one the same brief) assigned again in the mission, at that assignment
-- (`task_id` the new task, `cancelled_task_id` the one cancelled).
--
-- Each kind's time is a column of its base scan, so a reader's window
-- (`at_ms >= $1 and at_ms < $2`, under a generic plan too, or bounds that
-- are values such as `(select ms from now)`; never a join with another
-- relation, which is applied after the whole history) reaches the scan
-- and the read grows with the window, not the log (the view before worked
-- the whole history out and bounded it last: 1.1 s on the live log of
-- 2026-11-13). A reassignment starts from the assignment (`task.assigned`,
-- in the window by spawn_events_control_record_type): the earlier assignments of the
-- same work in its mission (its objective, or without one its brief:
-- spawn_events_control_assignment_objective, _brief), each one's span closed
-- as spawn_task_spans closes it (its next assignment and first closing
-- record by the task's id; a legacy row its row closed has no closing
-- record), kept when a person cancelled it and no assignment of that work
-- came between: this assignment is its reassignment. The view before is
-- the tests' oracle (tests/experience.rs). A further kind is one more
-- branch whose time is its base scan's.
create or replace view spawn_interventions as
select i.at_ms, 'command'::text as kind, null::bigint as mission_id,
       null::bigint as task_id, i.intent as command_id, null::bigint as cancelled_task_id
from spawn_human_intents i
union all
select r.at_ms, case r.type when 'mission.paused' then 'pause' else 'resume' end,
       spawn_experience_int(r.record -> 'id'), null, null, null
from spawn_experience_records r
where r.type in ('mission.resumed', 'mission.paused', 'mission.unpaused')
  and spawn_experience_int(r.record -> 'id') is not null
union all
select r.at_ms, 'owner_task', a.mission_id, a.task_id, null, null
  from spawn_experience_records r
 cross join lateral (
       select spawn_experience_int(coalesce(r.record -> 'id', r.record -> 'row' -> 'id')) as task_id,
              spawn_experience_int(coalesce(r.record -> 'mission_id', r.record -> 'row' -> 'mission_id'))
                  as mission_id) a
 where r.type = 'task.assigned'
   and a.task_id is not null and a.mission_id is not null
   and coalesce(r.record ->> 'created_by', r.record -> 'row' ->> 'created_by') = 'human'
   and coalesce((select s.review from spawn_experience_settings s
                  where s.mission_id = a.mission_id and s.seq < r.seq
                  order by s.seq desc limit 1), true)
union all
select w.at_ms, 'cancel_reassign', n.mission_id, n.task_id, null, p.task_id
  from spawn_experience_records w
 cross join lateral (
       select w.seq,
              spawn_experience_int(coalesce(w.record -> 'id', w.record -> 'row' -> 'id')) as task_id,
              spawn_experience_int(coalesce(w.record -> 'mission_id', w.record -> 'row' -> 'mission_id'))
                  as mission_id,
              spawn_experience_int(coalesce(w.record -> 'objective', w.record -> 'row' -> 'objective'))
                  as objective,
              coalesce(w.record ->> 'brief', w.record -> 'row' ->> 'brief') as brief) n
 cross join lateral (
       -- The earlier assignments of n's work in its mission: of its
       -- objective, or (one without an objective) of its brief.
       select r.seq, r.type, r.record,
              spawn_experience_int(coalesce(r.record -> 'id', r.record -> 'row' -> 'id')) as task_id,
              spawn_experience_int(coalesce(r.record -> 'objective', r.record -> 'row' -> 'objective'))
                  as objective,
              coalesce(r.record ->> 'brief', r.record -> 'row' ->> 'brief') as brief
         from spawn_experience_records r
        where (r.type = 'task.assigned'
               or (r.type = 'legacy.imported' and r.record ->> 'table' = 'mission_tasks'))
          and spawn_experience_int(coalesce(r.record -> 'mission_id', r.record -> 'row' -> 'mission_id'))
              = n.mission_id
          and spawn_experience_int(coalesce(r.record -> 'objective', r.record -> 'row' -> 'objective'))
              = n.objective
          and r.seq < n.seq
       union all
       select r.seq, r.type, r.record,
              spawn_experience_int(coalesce(r.record -> 'id', r.record -> 'row' -> 'id')),
              null::bigint,
              coalesce(r.record ->> 'brief', r.record -> 'row' ->> 'brief')
         from spawn_experience_records r
        where (r.type = 'task.assigned'
               or (r.type = 'legacy.imported' and r.record ->> 'table' = 'mission_tasks'))
          and spawn_experience_int(coalesce(r.record -> 'mission_id', r.record -> 'row' -> 'mission_id'))
              = n.mission_id
          and md5(coalesce(r.record ->> 'brief', r.record -> 'row' ->> 'brief')) = md5(n.brief)
          and coalesce(r.record ->> 'brief', r.record -> 'row' ->> 'brief') = n.brief
          and spawn_experience_int(coalesce(r.record -> 'objective', r.record -> 'row' -> 'objective'))
              is null
          and r.seq < n.seq
     ) p
 -- Its span, as spawn_task_spans closes it: up to the task's next
 -- assignment; a legacy row its row closed has no closing record. Found
 -- among the task's own records (spawn_events_control_record_row_id, by
 -- its id and seq), the first that is an assignment. The type test is
 -- spelled so that no assignment index (_objective, _brief: their
 -- predicate) applies: by one of them this lookup walked every later
 -- assignment of the log for each cancelled attempt (a 7-day window 1.4 s
 -- on the live log of 2026-11-13, more as history followed it).
 left join lateral (
       select r.seq as next_seq
         from spawn_experience_records r
        where spawn_experience_int(coalesce(r.record -> 'id', r.record -> 'row' -> 'id')) = p.task_id
          and r.seq > p.seq
          and r.type in ('task.assigned', 'legacy.imported')
          and (r.type = 'task.assigned' or r.record ->> 'table' = 'mission_tasks')
          and spawn_experience_int(coalesce(r.record -> 'mission_id', r.record -> 'row' -> 'mission_id'))
              is not null
        order by r.seq
        limit 1) x on true
 cross join lateral (
       select r.seq, r.type, r.record
         from spawn_experience_records r
        where r.seq > p.seq and (x.next_seq is null or r.seq < x.next_seq)
          and spawn_experience_int(r.record -> 'id') = p.task_id
          and (r.type in ('task.landed', 'task.cancelled', 'task.aborted', 'task.over_budget')
               or (r.type = 'task.reviewed'
                   and lower(r.record ->> 'accepted') in ('true', 't')
                   and not coalesce((select s.gated from spawn_experience_settings s
                                      where s.mission_id = n.mission_id and s.seq < r.seq
                                      order by s.seq desc limit 1), false)))
        order by r.seq
        limit 1) c
 where w.type = 'task.assigned'
   and n.task_id is not null and n.mission_id is not null and p.task_id is not null
   and not (p.type = 'legacy.imported'
            and (p.record -> 'row' ->> 'state' in ('cancelled', 'landed')
                 or (p.record -> 'row' ->> 'state' = 'accepted'
                     and not coalesce((select s.gated from spawn_experience_settings s
                                        where s.mission_id = n.mission_id and s.seq < p.seq
                                        order by s.seq desc limit 1), false))))
   and c.type = 'task.cancelled' and c.seq < n.seq
   and (jsonb_typeof(c.record -> 'by') is distinct from 'string' or c.record ->> 'by' = 'human')
   -- No assignment of the cancelled task's work came between: n is the
   -- first after the cancellation (of its objective; without one, of its
   -- brief, whatever objective that assignment has).
   and (p.objective is null or not exists (
       select 1 from spawn_experience_records r
        where r.type = 'task.assigned' and r.seq > c.seq and r.seq < n.seq
          and spawn_experience_int(coalesce(r.record -> 'mission_id', r.record -> 'row' -> 'mission_id'))
              = n.mission_id
          and spawn_experience_int(coalesce(r.record -> 'objective', r.record -> 'row' -> 'objective'))
              = p.objective
          and spawn_experience_int(coalesce(r.record -> 'id', r.record -> 'row' -> 'id')) is not null))
   and (p.objective is not null or not exists (
       select 1 from spawn_experience_records r
        where r.type = 'task.assigned' and r.seq > c.seq and r.seq < n.seq
          and spawn_experience_int(coalesce(r.record -> 'mission_id', r.record -> 'row' -> 'mission_id'))
              = n.mission_id
          and md5(coalesce(r.record ->> 'brief', r.record -> 'row' ->> 'brief')) = md5(p.brief)
          and coalesce(r.record ->> 'brief', r.record -> 'row' ->> 'brief') = p.brief
          and spawn_experience_int(coalesce(r.record -> 'id', r.record -> 'row' -> 'id')) is not null));

-- Each task's closing record: `landed`, `accepted` (a review that closes it),
-- `cancelled`, `aborted` or `over_budget`; `by`, the record's own.
create or replace view spawn_outcomes as
select t.closed_at_ms as at_ms, t.outcome, t.task_id, t.mission_id, t.by
from spawn_task_spans t
where t.outcome is not null;

-- Every escalation: each distinct tag of the dispatcher's inputs into the
-- supervisor (`Escalation::tag`, `<session> <id>`; a charter's tag is not
-- one), once, at the first command that carried it.
create or replace view spawn_escalations as
select distinct on (g.tag) c.created_at_ms as at_ms, g.tag, c.id as command_id
from spawn_commands c
cross join lateral jsonb_array_elements_text(
    case when jsonb_typeof(c.action -> 'tags') = 'array' then c.action -> 'tags'
         else '[]'::jsonb end) g(tag)
where c.principal = 'spawn-dispatch' and c.session_id = 'session_supervisor'
  and c.action ->> 'type' = 'input' and g.tag like '% %' and g.tag not like 'charter %'
order by g.tag, c.id;

revoke all on mission_missions, mission_residents, mission_tasks, mission_source_holds,
               mission_source_reds, spawn_alerts, mission_retired_objectives,
               grading_presets from public;
-- Every mission function: search_path pinned, closed to public. The
-- supervisor may call the ones it decides with; the rest are the owner's
-- (humans, the dispatcher, the integrator).
do $$
declare
    v_function text;
begin
    foreach v_function in array array[
        'spawn_mission_add(text, jsonb, text)', 'spawn_mission_close(bigint, text, text)',
        'spawn_task_assign(bigint, text, text, text, text, boolean, boolean, integer, text, jsonb, text, text)',
        'spawn_task_review(bigint, boolean, text, integer)',
        'spawn_task_cancel(bigint)', 'spawn_task_reissue(bigint, jsonb)',
        'spawn_task_restart(bigint, text)', 'spawn_task_reassign(bigint, text)',
        'spawn_task_restart_as(bigint, text, text)', 'spawn_task_reassign_as(bigint, text, text)',
        'spawn_resident_propose(text, text, text)',
        'spawn_resident_retire(text)', 'spawn_resident_approve(text)',
        'spawn_task_steal(bigint, text, text, text)', 'spawn_cancel_notice_untold(text)',
        'spawn_task_delivered(bigint, bigint)', 'spawn_task_reported(bigint, text)',
        'spawn_task_reported(bigint, text, text)',
        'spawn_task_report_unfinished(bigint, text, jsonb, text, bigint)',
        'spawn_task_report_unfinished_recorded(bigint, text)',
        'spawn_task_fork_failed(bigint, bigint, text, text)',
        'spawn_control_apply(jsonb, bigint, bigint)', 'spawn_control_record(jsonb)',
        'spawn_control_refold()', 'spawn_mission_configure(bigint, text, text, jsonb, jsonb)',
        'spawn_mission_reconfigure(bigint, jsonb)', 'spawn_settings_merge(jsonb, jsonb, text)',
        'spawn_mission_resume(bigint)', 'spawn_mission_pause(bigint, text)',
        'spawn_integrator_record(jsonb)',
        'spawn_source_moved(text, text, text)', 'spawn_host_record(jsonb)',
        'spawn_node_record(jsonb)',
        'spawn_alert_record(jsonb)', 'spawn_backup_record(jsonb)',
        'spawn_deploy_record(jsonb)', 'spawn_verification_record(jsonb)',
        'spawn_objective_retire(jsonb)', 'spawn_cost_record(jsonb)',
        'spawn_cost_usd(jsonb, bigint, bigint, bigint, bigint)',
        'spawn_cost_archive_record(jsonb, jsonb)',
        'spawn_cost_session_record(jsonb, jsonb, jsonb)',
        'spawn_objective_assign(bigint, integer, text, text, bigint, text, integer, text, jsonb)',
        'spawn_task_stages(bigint)',
        'spawn_landing_hold(bigint)', 'spawn_landing_release()',
        'spawn_source_holdable(text)', 'spawn_source_hold_lock(text)',
        'spawn_source_hold(text, text, integer, text)', 'spawn_source_release(text)',
        'spawn_source_push_request(text, text, text, boolean, boolean, text)',
        'spawn_source_push_hold()',
        'spawn_task_reroute(bigint, text, integer, integer)',
        'spawn_grading_apply(jsonb, bigint, bigint)', 'spawn_grading_record(jsonb)',
        'spawn_grading_refold()'] loop
        execute format('alter function %s set search_path = %I, pg_temp', v_function, current_schema());
        execute format('revoke execute on function %s from public', v_function);
    end loop;
    foreach v_function in array array[
        'spawn_mission_add(text, jsonb, text)', 'spawn_mission_close(bigint, text, text)',
        'spawn_task_assign(bigint, text, text, text, text, boolean, boolean, integer, text, jsonb, text, text)',
        'spawn_task_review(bigint, boolean, text, integer)',
        'spawn_task_cancel(bigint)', 'spawn_task_restart(bigint, text)',
        'spawn_task_reassign(bigint, text)', 'spawn_resident_propose(text, text, text)',
        'spawn_resident_retire(text)', 'spawn_task_stages(bigint)',
        'spawn_objective_retire(jsonb)', 'spawn_task_reroute(bigint, text, integer, integer)'] loop
        execute format('grant execute on function %s to %I', v_function,
                       spawn_login_role('spawn_supervisor'));
    end loop;
    execute format('grant select on mission_missions, mission_residents, mission_tasks, '
                   'mission_source_holds, mission_source_reds, spawn_alerts, '
                   'mission_retired_objectives, grading_presets, '
                   'spawn_alert_scores, spawn_decisions, spawn_interventions, spawn_outcomes, '
                   'spawn_escalations, spawn_human_intents to %I',
                   spawn_login_role('spawn_supervisor'));
end
$$;

-- The supervisor commands residents too (stop, steer).
insert into spawn_grants (principal, agent_id, scope) values
    ('spawn_supervisor', 'agent_resident_*', 'all')
on conflict (principal, agent_id) do nothing;

-- `spawn serve` connects with this login. It reads every table and writes
-- nothing, so the dashboard cannot change the log or the queue even if it is
-- tricked into running a query. Its password is set like the supervisor's.
-- The board it serves carries every task's stages.
do $$
begin
    execute format('grant select on all tables in schema %I to %I', current_schema(),
                   spawn_login_role('spawn_reader'));
    execute format('grant execute on function spawn_task_stages(bigint) to %I',
                   spawn_login_role('spawn_reader'));
end
$$;

-- `spawn_append` is now SECURITY DEFINER, so it must not resolve names
-- through the caller's `search_path`.
do $$
begin
    execute format(
        'alter function spawn_append(text, text, text, text, text, jsonb)
             set search_path = %I, pg_temp',
        current_schema()
    );
    execute format(
        'alter function spawn_append_trusted(text, text, text, text, text, jsonb)
             set search_path = %I, pg_temp',
        current_schema()
    );
end
$$;


-- Universal file provenance (PV1): which change made each file as it is,
-- who made it (agent, execution, task, preset, model) and what it used.
-- Three append-only tables:
-- - `prov_changes`: one row per recorded change, keyed by its
--   `(change_id, rev)`; `base` and `result` are the tree digests before and
--   after it, `boundary` the point at which it was recorded.
-- - `prov_entries`: the paths a change touched, each with its content digest
--   before and after (null: absent), and `origin` the earlier change its
--   content came from (a revert, a cherry-pick, an import).
-- - `prov_edges`: what a change used, included, superseded or redacted;
--   `dst` names a change by its `change_id`, a tree digest (`result`) or a
--   content digest (`prov_entries.after`).
-- Every value is checked once, as it is written (rows are never changed):
-- non-empty ids, digests, domain and path, a revision from 1, a size of 0 or
-- more and an edge's detail a JSON object.
-- Only `spawn_prov_record_change` (owner only) writes them; every update,
-- delete and truncate is refused by trigger. The reader selects them.
create table if not exists prov_changes (
    id bigint generated always as identity primary key,
    change_id text collate "C" not null check (char_length(change_id) > 0),
    rev integer not null check (rev >= 1),
    kind text not null check (kind in ('edit', 'derive', 'land', 'revert', 'import')),
    domain text not null check (char_length(domain) > 0),
    agent_id text not null check (char_length(agent_id) > 0),
    execution_id text,
    task_id bigint,
    preset_id text,
    model_label text,
    transcript_ref text,
    attributed text not null default 'host' check (attributed in ('host', 'inferred', 'imported')),
    base text collate "C" not null check (char_length(base) > 0),
    result text collate "C" not null check (char_length(result) > 0),
    boundary text not null check (boundary in ('checkpoint', 'submit', 'land', 'job', 'backfill')),
    at_ms bigint not null,
    unique (change_id, rev)
);
create index if not exists prov_changes_agent on prov_changes (agent_id, at_ms);
create index if not exists prov_changes_execution on prov_changes (execution_id, at_ms)
    where execution_id is not null;
create index if not exists prov_changes_result on prov_changes (result);

create table if not exists prov_entries (
    change bigint not null references prov_changes (id),
    path text collate "C" not null check (char_length(path) > 0),
    before text collate "C",
    after text collate "C",
    size bigint check (size is null or size >= 0),
    class text not null default 'content' check (class in ('content', 'mechanical', 'generated', 'tree')),
    origin bigint references prov_changes (id),
    primary key (change, path)
);
-- Which changes produced a content digest, and one path's history.
create index if not exists prov_entries_after on prov_entries (after) where after is not null;
create index if not exists prov_entries_path on prov_entries (path, change);
create index if not exists prov_entries_origin on prov_entries (origin) where origin is not null;

create table if not exists prov_edges (
    id bigint generated always as identity primary key,
    kind text not null check (kind in ('used', 'includes', 'supersedes', 'redacts')),
    src bigint not null references prov_changes (id),
    dst text collate "C" not null,
    detail jsonb not null default '{}'::jsonb check (jsonb_typeof(detail) = 'object'),
    at_ms bigint not null
);
create index if not exists prov_edges_dst on prov_edges (dst);
create index if not exists prov_edges_src on prov_edges (src);

revoke all on prov_changes, prov_entries, prov_edges from public;

-- Provenance is never changed: what was recorded stays as recorded.
create or replace function spawn_prov_unchanged() returns trigger
language plpgsql as $$
begin
    raise exception 'provenance is append-only: % on % refused', lower(tg_op), tg_table_name
        using errcode = '42501';
end $$;
revoke execute on function spawn_prov_unchanged() from public;
drop trigger if exists prov_changes_unchanged on prov_changes;
create trigger prov_changes_unchanged before update or delete on prov_changes
    for each row execute function spawn_prov_unchanged();
drop trigger if exists prov_changes_untruncated on prov_changes;
create trigger prov_changes_untruncated before truncate on prov_changes
    for each statement execute function spawn_prov_unchanged();
drop trigger if exists prov_entries_unchanged on prov_entries;
create trigger prov_entries_unchanged before update or delete on prov_entries
    for each row execute function spawn_prov_unchanged();
drop trigger if exists prov_entries_untruncated on prov_entries;
create trigger prov_entries_untruncated before truncate on prov_entries
    for each statement execute function spawn_prov_unchanged();
drop trigger if exists prov_edges_unchanged on prov_edges;
create trigger prov_edges_unchanged before update or delete on prov_edges
    for each row execute function spawn_prov_unchanged();
drop trigger if exists prov_edges_untruncated on prov_edges;
create trigger prov_edges_untruncated before truncate on prov_edges
    for each statement execute function spawn_prov_unchanged();

-- A recorded change as `spawn_prov_record_change` compares it: the change's
-- columns but its id, its entries by path (without `change`) and its edges
-- in a fixed order (without `id` and `src`).
create or replace function spawn_prov_canonical(p_id bigint) returns jsonb
language sql stable as $$
    select jsonb_build_object(
        'change', (select to_jsonb(c) - 'id' from prov_changes c where c.id = p_id),
        'entries', (select coalesce(jsonb_agg(to_jsonb(n) - 'change' order by n.path), '[]'::jsonb)
                      from prov_entries n where n.change = p_id),
        'edges', (select coalesce(jsonb_agg(to_jsonb(e) - 'id' - 'src'
                                            order by e.kind, e.dst, e.at_ms, e.detail::text),
                                  '[]'::jsonb)
                    from prov_edges e where e.src = p_id))
$$;

-- Record one change (owner only), atomically: its `prov_changes` row from
-- `p_change` (an object of its columns but `id`; `attributed` defaults to
-- host), its `prov_entries` from `p_entries` (an array of objects of their
-- columns but `change`; `class` defaults to content) and its `prov_edges`
-- from `p_edges` (null or an array of objects of `kind`, `dst`, `detail`
-- (default {}) and `at_ms` (default the change's); `src` is the change).
-- Returns the change's id.
--
-- Idempotent: recording a `(change_id, rev)` already recorded with exactly
-- the same change, entries and edges returns the recorded id and writes
-- nothing; with anything different it is refused (23505, "recorded already
-- with different content") and nothing is written. An unknown key, a value
-- of the wrong type, a missing required column, a check's violation, a
-- path twice and an origin that names no change are refused likewise.
create or replace function spawn_prov_record_change(p_change jsonb, p_entries jsonb, p_edges jsonb)
returns bigint
language plpgsql security definer as $$
declare
    v_change prov_changes;
    v_given jsonb;
    v_edges jsonb;
    v_id bigint;
    v_unknown text;
begin
    if spawn_mission_caller() is distinct from 'owner' then
        raise exception 'only the owner records provenance' using errcode = '42501';
    end if;
    if jsonb_typeof(p_change) is distinct from 'object' then
        raise exception 'a provenance change is a JSON object of its columns' using errcode = '22023';
    end if;
    if jsonb_typeof(p_entries) is distinct from 'array'
       or exists (select 1 from jsonb_array_elements(p_entries) n where jsonb_typeof(n) <> 'object') then
        raise exception 'provenance entries are a JSON array of objects' using errcode = '22023';
    end if;
    if p_edges is not null and jsonb_typeof(p_edges) <> 'null'
       and (jsonb_typeof(p_edges) <> 'array'
            or exists (select 1 from jsonb_array_elements(p_edges) e where jsonb_typeof(e) <> 'object')) then
        raise exception 'provenance edges are null or a JSON array of objects' using errcode = '22023';
    end if;
    select string_agg(k, ', ' order by k) into v_unknown
      from (select k from jsonb_object_keys(p_change) k
             where k not in ('change_id', 'rev', 'kind', 'domain', 'agent_id', 'execution_id',
                             'task_id', 'preset_id', 'model_label', 'transcript_ref',
                             'attributed', 'base', 'result', 'boundary', 'at_ms')
            union
            select k from jsonb_array_elements(p_entries) n, jsonb_object_keys(n) k
             where k not in ('path', 'before', 'after', 'size', 'class', 'origin')
            union
            select k from jsonb_array_elements(case jsonb_typeof(p_edges) when 'array' then p_edges
                                                                         else '[]'::jsonb end) e,
                          jsonb_object_keys(e) k
             where k not in ('kind', 'dst', 'detail', 'at_ms')) u;
    if v_unknown is not null then
        raise exception 'unknown provenance keys: %', v_unknown using errcode = '22023';
    end if;

    v_change := jsonb_populate_record(null::prov_changes, p_change);
    v_change.id := null;
    v_change.attributed := coalesce(v_change.attributed, 'host');
    v_given := jsonb_build_object(
        'change', to_jsonb(v_change) - 'id',
        'entries', (select coalesce(jsonb_agg(to_jsonb(n) - 'change' order by n.path), '[]'::jsonb)
                      from (select null::bigint as change, r.path, r.before, r.after, r.size,
                                   coalesce(r.class, 'content') as class, r.origin
                              from jsonb_populate_recordset(null::prov_entries, p_entries) r) n),
        'edges', '[]'::jsonb);
    -- The edges as given (their order is their ids'), with their defaults.
    select coalesce(jsonb_agg(jsonb_build_object('kind', r.kind, 'dst', r.dst,
                                                 'detail', coalesce(r.detail, '{}'::jsonb),
                                                 'at_ms', coalesce(r.at_ms, v_change.at_ms))
                              order by x.at),
                    '[]'::jsonb)
      into v_edges
      from jsonb_array_elements(case jsonb_typeof(p_edges) when 'array' then p_edges
                                                           else '[]'::jsonb end)
           with ordinality x(edge, at),
           jsonb_populate_record(null::prov_edges, x.edge) r;
    v_given := jsonb_set(v_given, '{edges}',
                         (select coalesce(jsonb_agg(e order by e ->> 'kind', (e ->> 'dst') collate "C",
                                                    (e ->> 'at_ms')::bigint, (e -> 'detail')::text),
                                          '[]'::jsonb)
                            from jsonb_array_elements(v_edges) e));

    insert into prov_changes (change_id, rev, kind, domain, agent_id, execution_id, task_id,
                              preset_id, model_label, transcript_ref, attributed, base, result,
                              boundary, at_ms)
    values (v_change.change_id, v_change.rev, v_change.kind, v_change.domain, v_change.agent_id,
            v_change.execution_id, v_change.task_id, v_change.preset_id, v_change.model_label,
            v_change.transcript_ref, v_change.attributed, v_change.base, v_change.result,
            v_change.boundary, v_change.at_ms)
    on conflict (change_id, rev) do nothing
    returning id into v_id;

    if v_id is null then
        -- Recorded already (by an earlier call, or one that committed while
        -- this one waited on the key): the same content is this one.
        select c.id into v_id from prov_changes c
         where c.change_id = v_change.change_id and c.rev = v_change.rev;
        if spawn_prov_canonical(v_id) is distinct from v_given then
            raise exception 'provenance change (%, %) is recorded already with different content',
                            v_change.change_id, v_change.rev
                using errcode = '23505';
        end if;
        return v_id;
    end if;

    insert into prov_entries (change, path, before, after, size, class, origin)
    select v_id, r.path, r.before, r.after, r.size, r.class, r.origin
      from jsonb_populate_recordset(null::prov_entries, v_given -> 'entries') r;
    insert into prov_edges (kind, src, dst, detail, at_ms)
    select r.kind, v_id, r.dst, r.detail, r.at_ms
      from jsonb_array_elements(v_edges) with ordinality x(edge, at),
           jsonb_populate_record(null::prov_edges, x.edge) r
     order by x.at;
    return v_id;
end $$;
do $$
begin
    execute format('alter function spawn_prov_canonical(bigint) set search_path = %I, pg_temp',
                   current_schema());
    execute format('alter function spawn_prov_record_change(jsonb, jsonb, jsonb) set search_path = %I, pg_temp',
                   current_schema());
    execute 'revoke execute on function spawn_prov_canonical(bigint) from public';
    execute 'revoke execute on function spawn_prov_record_change(jsonb, jsonb, jsonb) from public';
    -- The reader selects every relation (its parity with the rest of the
    -- schema); only the owner records.
    execute format('grant select on prov_changes, prov_entries, prov_edges to %I',
                   spawn_login_role('spawn_reader'));
end
$$;
